window.__LIB__={"reading/career_aux":{"version":"0.1","source":"《图解道教天文历算学·紫微斗数（下·推理卷）》第拾叁章 六吉/六煞/四化坐事业宫（摘编）","groups":[{"name":"辅弼","stars":["左辅","右弼"],"note":"适合协助、辅导、劝导这类不抢风头的事，讲合作、重协调的环境最自在。"},{"name":"魁钺","stars":["天魁","天钺"],"note":"适合能让人看见本事和上进心的岗位，周围也容易遇到有分量的人。"},{"name":"昌曲","stars":["文昌","文曲"],"note":"文化艺术、氛围营造、分析表达都很对路，讲气质和美感的环境更能发挥。"},{"name":"空劫","stars":["地空","地劫"],"note":"研究实验、化学光学、医护、设计改良这类要动脑求突破的事挺合适。"},{"name":"火铃","stars":["火星","铃星"],"note":"适合主动出击、阶段性强的事，开拓、技艺，甚至带点挑战的岗位都接得住。"},{"name":"擎羊","stars":["擎羊"],"note":"喜欢冲在前面，前瞻、金属器械、军警司法、整顿改革这类事最能使上劲。"},{"name":"陀罗","stars":["陀罗"],"note":"适合需要耐心反复打磨的事，制造、精修这类慢工最见功夫。"}],"hua":{"禄":"容易把人和事都带得顺，钱与机会也跟着流动起来。","权":"既能拿主意也能落地，要紧的事交到你手里就稳了。","科":"才华容易被看见，文艺、展示、口碑这类事都很合拍。","忌":"容易先碰到卡住的地方，把死角理顺、难题啃下来，反而长本事。"}},"reading/career_notes":{"version":"0.1","source":"《图解道教天文历算学·紫微斗数（下·推理卷）》第拾叁章 主星坐事业宫（摘编）","notes":{"紫微":"适合能代表一个方向、需要拿主意的事，比如个人品牌、珠宝首饰、团体牵头，也容易接触到层级更高的环境。","武曲":"和钱物、手上功夫、把项目推起来有关，贸易开发、工厂管理、金融实业、技术类工作都很合适。","廉贞":"装饰设计、文艺演艺、公共关系、公职这类事都对路。人际稍复杂时，你居中协调反而最自在。","七杀":"习惯负责到底、自己站第一线，企划和带队一起扛。需要担点风险、内外都要顾的岗位，反而合你的性子。","破军":"适合打头阵、从零开创、要动起来的事，开发、表演、高强度行业都能发挥。事成之后换个新舞台，也很自然。","贪狼":"文艺、餐饮娱乐旅游、设计美学这类热闹又好看的事最对味，跟人打交道多的场合也能应付。","天府":"喜欢从头到尾自己把事做完，工作室、独立小单位、专业手作和定制都很合适。","天相":"擅长企划协调、把各方沟通顺，秘书、公关、专业服务这类要替人负责的岗位很合适。","太阳":"适合和很多人有关、需要一点热心的事，教育、文化、传播都很对路。","天机":"偏重推演、策划、当参谋，动脑比动手多，规划、研究、技术顾问都很顺手。","天同":"适合氛围轻松、能让人舒服点的工作，文化、教育、餐饮、娱乐、观光都不错。","太阴":"适合配合他人、需要细心的事，轮班或作息不规律也能稳稳接住，慢工出细活最合拍。","巨门":"擅长把信息说清楚、把意见讲明白，也会居中疏通，传播、法律、教育、销售都用得上。","天梁":"愿意照顾人、替大家谋点福利，做事讲公平，医疗、教育、公职、监察都很合适。"}},"reading/daily_copy":{"version":"1.0","note":"每日一句：12 宫骨架 + 28 星性件 + 12 动作件。空宫借对宫星。零术语、少用『你』、≤35 字。","variants":["{scene}，{self}，可{opp}。{action}。","{scene}，{self}；其实{opp}。{action}。","{scene}，{self}，又{opp}。{action}。","{scene}，{self}，可{opp}——{action}。"],"fallback":"{scene}，{self}。{action}。","palace_scaffolds":{"命宫":{"scene":"关于自己","action":"先挑一件小事动手就好"},"兄弟":{"scene":"一起做事的人","action":"先想想，再慢慢决定"},"夫妻":{"scene":"两个人的事","action":"先轻轻说一句在意的"},"子女":{"scene":"晚辈和手上的新事","action":"先想想是帮他，还是替他做"},"财帛":{"scene":"钱的事","action":"先看看是买需要，还是买安心"},"疾厄":{"scene":"身体的事","action":"早半小时收工就好"},"迁移":{"scene":"在外面","action":"不用急着定死，留点余地"},"交友":{"scene":"朋友之间","action":"听完不急着答应，回头再说"},"官禄":{"scene":"工作上的事","action":"先把一句话说清楚"},"田宅":{"scene":"家里的事","action":"先看看是缺了什么，还是想换个心情"},"福德":{"scene":"心里的事","action":"给自己十分钟发发呆"},"父母":{"scene":"跟长辈或上级","action":"先听完，再轻轻回一句"}},"star_qualities":{"紫微":"想自己拿主意","天机":"想法多","太阳":"先照亮别人","武曲":"想算清楚","天同":"想舒服","廉贞":"爱憎分明","天府":"想稳","太阴":"想得细","贪狼":"想试试","巨门":"爱问为什么","天相":"会打圆场","天梁":"会操心","七杀":"想自己冲","破军":"想换个做法","左辅":"愿意帮人","右弼":"会顺着人","文昌":"爱琢磨","文曲":"会说","天魁":"容易遇贵人","天钺":"容易遇提点","禄存":"想攒","天马":"闲不住","擎羊":"话容易说重","陀罗":"容易慢半拍","火星":"性子急","铃星":"心里容易急","地空":"想得多、落得少","地劫":"容易落空"},"opposite_pairs":{"命宫":"迁移","迁移":"命宫","兄弟":"交友","交友":"兄弟","夫妻":"官禄","官禄":"夫妻","子女":"田宅","田宅":"子女","财帛":"福德","福德":"财帛","疾厄":"父母","父母":"疾厄"},"trait_palaces":["命宫","福德","官禄","财帛","迁移"],"relation_lines":{"兄弟":["一起做事的人，和身边的朋友，是一对。","同辈之间，面和心不一定一样近。","一起做事的人，先商量按谁的来。"],"交友":["身边的朋友，和一起做事的人，是一对。","朋友的话，听听就好。","朋友之间，话说得好听，事不一定落地。"],"夫妻":["两个人的关系，和外面的角色，是一对。","关系里的样子，和工作上的样子，是一对。","两个人的事，不用让对方猜。"],"官禄":["在外面的样子，和家里的样子，是一对。","工作上的样子，和关系里的样子，是一对。","工作上的事，写清楚比说得多省心。"],"子女":["手上的新事，和家里的底子，是一对。","对晚辈和手上的事，急也急不来。","手上的新事，不用急着定。"],"田宅":["家里的底子，和手上的新事，是一对。","家里的事，慢慢来比大改舒服。","家里想大改，也不用急着跟。"],"疾厄":["身体先累，常常是因为一直在扛。","身体的事，硬撑着最容易累。","身体的事，自己最清楚，累了就先停。"],"父母":["跟长辈或上级相处，也照见自己扛了多少。","跟长辈或上级说话，有时一句就累了。","跟长辈或上级，话说慢一点。"]}},"reading/down_notes":{"version":"0.1","source":"《图解道教天文历算学·紫微斗数（下·推理卷）》第玖/拾章 主星坐身命宫参断（摘编）","notes":{"紫微":"看着沉稳，心里其实很在意被尊重，也容易把重要的人和事握得紧。天生能拿主意，有人帮衬时这份底气最显出来，偶尔听听旁人的想法会更顺。","天机":"点子多、反应快，策划和分析都很拿手。想得细也容易想得久，认准一件事慢慢做深，比频繁换方向更踏实。","太阳":"坦荡又热心，敢把话说清楚，也愿意照顾别人。直脾气偶尔会让人接不住，留点余地、别把自己烧太干就好。","武曲":"说干就干，重情义也扛得住事。决定下得快时容易一条道走到底，多听一句别人的意见，反而少绕路。","天同":"随和、好相处，心里还留着一点孩子气。不太爱催自己，给自己定个小小的目标，慢慢就能动起来。","廉贞":"爱憎分明，说话直，身上有股不服输的劲。情绪上来时给自己一点缓冲，守住自己的边界，日子会清爽很多。","天府":"稳当、能干，也把体面看得很重。细碎繁琐的事容易磨耐心，找个合拍的伙伴一起补上，会轻松不少。","太阴":"细腻、会照顾人，很多小细节都看在眼里。心里容易多想，把在意的事轻轻说开，比闷着舒服。","贪狼":"兴趣广、会来事，什么都想试一试。挑一样真正喜欢的认真深耕，比处处浅尝更尽兴。","巨门":"会问、会辩，心思也细。话赶话时容易起误会，慢半拍再开口，重要的事随手记一笔就稳妥了。","天相":"温和周全，最会替人圆场。心软时容易跟着别人走，留一句自己的主张，再找个能拍板的搭档就刚好。","天梁":"老成、有原则，天生爱照拂人。操心多了会累，把别人的课题还给别人，自己也能松口气。","七杀":"独立、果断，遇事敢自己扛。急起来情绪都写在脸上，学着收一收，冲劲就更用得上了。","破军":"敢推倒重来，很有自己的主意。动手前先把新路铺一小段、留好退路，这份开创的劲头就落得住了。"}},"reading/health_notes":{"version":"0.1","source":"《图解道教天文历算学·紫微斗数（下·推理卷）》第拾贰章 主星病理特征（摘编）","notes":{"紫微":"多关照头、脑和胃。操心重的时候容易头紧、胃口乱，吃得更规律一点会舒服些。","天机":"四肢和神经系统比较敏感。想得多、睡得浅时容易紧绷，手脚也别一直硬撑，记得松一松。","太阳":"眼睛、循环和肠胃容易先喊累。用眼久了歇一歇，火气上来时给自己降点温。","武曲":"鼻子、气管、肺和牙齿比较需要照顾。换季时多留意呼吸，动作急了也容易磕碰，慢半拍更稳妥。","天同":"代谢和水分这一块比较敏感，作息一乱容易浮肿。少熬夜、动一动，身体就轻快不少。","廉贞":"肠胃和皮肤比较敏感，也别忽略私密处的小信号。不舒服早点看看，比硬扛省心。","天府":"脾胃是重点。三餐别太赶、少点刺激，定期体检就够安心了。","太阴":"内分泌、皮肤和眼睛容易先有反应。睡够、少盯屏幕，身体会慢慢回稳。","贪狼":"扁桃腺和泌尿生殖这一块比较敏感。作息规律、别太放纵，换季时多留意自己就好。","巨门":"口腔、咽喉和肠胃容易有反应。补品别一股脑地吃，听得懂身体的信号比什么都强。","天相":"皮肤和泌尿这一块偏敏感，偶尔也会胸闷。换季留意过敏，累了就先躺一会儿。","天梁":"手脚、骨头和脾胃需要多关照。好在你也最肯早点看医生，小毛病不拖就是福气。","七杀":"呼吸和筋骨是重点。动作快的场合多做点防护，别跟身体较劲。","破军":"泌尿、牙齿和代谢这几处容易突然闹点小状况。定期看看牙、别硬撑，就稳当了。"}},"reading/pairs_v01":{"version":"0.1","note":"双星同宫的合参衔接句；键为主星对，顺序无关。","pairs":[{"stars":["紫微","天相"],"text":"一个能拿主意、一个能把事办周全，挺合拍；只是都看重体面，偶尔谁都不好意思先开口。"},{"stars":["紫微","天府"],"text":"一个敢定、一个能守，像掌舵的和管家的搭在一起；稳不等于保守，机会来了也能稳稳接住。"},{"stars":["紫微","贪狼"],"text":"规矩遇上好奇，既想体面又想尝鲜；想要的坦白说出来，比藏着轻松。"},{"stars":["紫微","破军"],"text":"一边想有章法、一边想推倒重来，常在守和变之间来回；心里留一条不轻易动的底线就好。"},{"stars":["紫微","七杀"],"text":"气场足、决断快，也容易让人有压力；把这份劲用在拿主意上，比用在脾气上更好。"},{"stars":["天机","太阴"],"text":"脑子细、心也细，会想是本事；只是别把想得多，变成一次次否定自己。"},{"stars":["天机","巨门"],"text":"脑子和嘴都利落；聪明用在看清事情上最好，话到嘴边留半句更稳。"},{"stars":["天机","天梁"],"text":"一个出主意、一个稳得住，很互补；容易替人操心过头，先看看哪些是自己的事。"},{"stars":["太阳","太阴"],"text":"一个外放、一个内收，热和静都在身上；对外大方，也记得给自己留点安静。"},{"stars":["太阳","巨门"],"text":"爱表达，也爱把话说清楚；真话很好，说的时候留一点温柔就更顺。"},{"stars":["太阳","天梁"],"text":"一个愿担、一个愿护，容易成了大家的靠山；把自己也照顾进去，才撑得久。"},{"stars":["武曲","天府"],"text":"能挣也能守，钱上很稳；数字之外，给人和人情也留一点位置。"},{"stars":["武曲","贪狼"],"text":"一个会算、一个会找机会，很互补；敢闯很好，冲动前留半秒就更稳。"},{"stars":["武曲","七杀"],"text":"两个都利落，执行力很足，也容易硬碰硬；事做好了，关系也留着更值。"},{"stars":["武曲","破军"],"text":"一个求稳、一个想变，常在「要不要换」上拉扯；先看清楚退路，动起来更安心。"},{"stars":["天同","太阴"],"text":"随和又细腻，待人有温柔，也容易把委屈咽下去；想说的时候轻轻说一句就好。"},{"stars":["天同","巨门"],"text":"一个软、一个锐，话听着利落，心里其实怕起冲突；有意见早点讲，就不必攒着了。"},{"stars":["天同","天梁"],"text":"想轻松又放心不下，一边想歇一边还在操心；把该管的和不必管的轻轻分开就好。"},{"stars":["廉贞","天府"],"text":"有锋芒也有分寸，在讲规矩的地方挺自在；规矩用来把事理顺，不用来为难人。"},{"stars":["廉贞","贪狼"],"text":"有张力也有兴致，很容易被看见；把劲用在做成一件事上，比急着证明自己更尽兴。"},{"stars":["廉贞","七杀"],"text":"敢碰硬也敢担事；脾气上来时停三秒，很多小麻烦就化开了。"},{"stars":["廉贞","破军"],"text":"一边守着线、一边想试试边界；心里留一条自己不越的线，反而更自在。"}]},"reading/pan144":{"version":"0.1","source":"《图解道教天文历算学·紫微斗数（上·命理卷）》第捌章 144种命盘论断（OCR 整理，136/144 收录）","charts":{"子":{"子":{"names":["紫府朝垣格"],"page":305},"丑":{"names":["同巨阴阳格","命无正曜格"],"page":306},"寅":{"names":["杀破狼格"],"page":307},"卯":{"names":["同巨阳梁格","命无正曜格"],"page":308},"辰":{"names":["天府朝垣格","紫府朝垣格"],"page":309},"巳":{"names":["机月阳梁格"],"page":310},"午":{"names":["杀破狼格"],"page":311},"未":{"names":["同巨同宫格"],"page":312},"申":{"names":["紫府武相格"],"page":313},"酉":{"names":["日月天梁格"],"page":314},"戌":{"names":["杀破狼格"],"page":315},"亥":{"names":["机阴同巨格"],"page":316}},"丑":{"子":{"names":["机月同梁格"],"page":317},"丑":{"names":["杀破狼格"],"page":318},"寅":{"names":["巨日格"],"page":319},"卯":{"names":["府相朝垣格"],"page":320},"辰":{"names":["日月反背格"],"page":321},"巳":{"names":["杀破狼格"],"page":322},"午":{"names":["石中隐玉格"],"page":323},"未":{"names":["紫武廉相格","杀破狼格","府相朝垣格"],"page":324},"申":{"names":["机月同梁格"],"page":325},"酉":{"names":["杀破狼格"],"page":326},"戌":{"names":["日月反背格"],"page":327},"亥":{"names":["命无正曜格"],"page":328}},"寅":{"子":{"names":["英星人庙格"],"page":329},"丑":{"names":["机梁同巨格"],"page":330},"寅":{"names":["紫府同宫格"],"page":331},"卯":{"names":["日月同梁格"],"page":332},"辰":{"names":["杀破狼格"],"page":333},"巳":{"names":["巨日格"],"page":334},"午":{"names":["紫府武廉相格"],"page":335},"未":{"names":["机月阳梁格"],"page":336},"申":{"names":["七杀朝斗格"],"page":337},"酉":{"names":["机月同阴格"],"page":338},"戌":{"names":["将星得地格"],"page":339},"亥":{"names":["巨日格"],"page":340}},"卯":{"子":{"names":["巨日格"],"page":341},"丑":{"names":["日月夹命格"],"page":342},"寅":{"names":["机月同梁格"],"page":343},"卯":{"names":["杀破狼格"],"page":344},"辰":{"names":["同巨格"],"page":345},"巳":{"names":["府相朝垣格"],"page":346},"午":{"names":["寿星人庙格"],"page":347},"未":{"names":["雄宿朝元格"],"page":348},"申":{"names":["机阴格"],"page":349},"酉":{"names":["命无正曜格"],"page":350},"亥":{"names":["杀破狼格"],"page":352}},"辰":{"子":{"names":["紫府武廉相格"],"page":353},"丑":{"names":["日月同临格"],"page":354},"寅":{"names":["杀破狼格"],"page":355},"卯":{"names":["巨机同临格"],"page":356},"辰":{"names":["府相朝垣格"],"page":357},"巳":{"names":["日月同梁格"],"page":358},"午":{"names":["七杀朝斗格"],"page":359},"未":{"names":["命无正曜格"],"page":360},"申":{"names":["雄宿朝元格"],"page":361},"酉":{"names":["命无正曜格"],"page":362},"戌":{"names":["日月照壁格"],"page":363},"亥":{"names":["机巨同梁格"],"page":364}},"巳":{"子":{"names":["月生沧海格","水澄桂萼格"],"page":365},"丑":{"names":["贪武同行格","日月夹命格"],"page":366},"寅":{"names":["巨日同宫格"],"page":367},"卯":{"names":["府相朝垣格"],"page":368},"辰":{"names":["善荫朝纲格","机月同梁格"],"page":369},"巳":{"names":["紫府武廉格","杀破狼格"],"page":370},"午":{"names":["命无正曜格"],"page":371},"未":{"names":["命无正曜格","武曲贪狼格"],"page":372},"申":{"names":["命无正曜格"],"page":373},"酉":{"names":["杀破狼格"],"page":374}},"午":{"子":{"names":["杀破狼格"],"page":377},"丑":{"names":["同巨机格"],"page":378},"寅":{"names":["府相朝垣格"],"page":379},"卯":{"names":["日出扶桑格","日照雷门格"],"page":380},"辰":{"names":["杀破狼格"],"page":381},"巳":{"names":["机阴同巨格"],"page":382},"午":{"names":["极向离明格"],"page":383},"未":{"names":["日月并明格","明珠出海格"],"page":384},"申":{"names":["杀破狼格"],"page":385},"酉":{"names":["命无正曜格"],"page":386},"戌":{"names":["天府朝垣格","紫府武廉相格"],"page":387},"亥":{"names":["月朗天门格"],"page":388}},"未":{"子":{"names":["石中隐玉格"],"page":389},"丑":{"names":["紫府天相格"],"page":390},"寅":{"names":["机月同梁格"],"page":391},"卯":{"names":["杀破狼格"],"page":392},"辰":{"names":["巨日格"],"page":393},"巳":{"names":["命无正曜格"],"page":394},"午":{"names":["机月同梁格"],"page":395},"未":{"names":["杀破狼格","日月照壁格"],"page":396},"申":{"names":["命无正曜格"],"page":397},"戌":{"names":["机月同梁格"],"page":398},"酉":{"names":["府相武杀格"],"page":399}},"申":{"子":{"names":["紫府武廉相格"],"page":401},"丑":{"names":["丹桂格","日月并明格"],"page":402},"寅":{"names":["七杀朝斗格"],"page":403},"卯":{"names":["机月同巨格"],"page":404},"辰":{"names":["将星得地格"],"page":405},"巳":{"names":["巨日格"],"page":406},"午":{"names":["英星人庙格"],"page":407},"未":{"names":["机月同梁格"],"page":408},"申":{"names":["紫府同宫格"],"page":409},"酉":{"names":["日月同梁格"],"page":410},"戌":{"names":["杀破狼格"],"page":411},"亥":{"names":["巨日格"],"page":412}},"酉":{"子":{"names":["寿星人庙格"],"page":413},"丑":{"names":["杀破狼格"],"page":414},"寅":{"names":["命无正曜格"],"page":415},"卯":{"names":["命无正曜格"],"page":416},"辰":{"names":["机月同梁格"],"page":417},"巳":{"names":["杀破狼格"],"page":418},"午":{"names":["日丽中天格","金灿光辉格"],"page":419},"未":{"names":["日月夹命格"],"page":420},"申":{"names":["机月同梁格"],"page":421},"酉":{"names":["杀破狼格"],"page":422},"亥":{"names":["武破府相格"],"page":424}},"戌":{"丑":{"names":["命无正曜格"],"page":426},"寅":{"names":["紫府武廉相格"],"page":427},"卯":{"names":["命无正曜格"],"page":428},"辰":{"names":["日月照壁格"],"page":429},"巳":{"names":["机巨同梁格"],"page":430},"午":{"names":["紫府武廉相格"],"page":431},"申":{"names":["杀破狼格"],"page":433},"酉":{"names":["巨机同临格"],"page":434},"亥":{"names":["日月同梁格"],"page":436}},"亥":{"子":{"names":["命无正曜格"],"page":437},"丑":{"names":["命无正曜格"],"page":438},"寅":{"names":["命无正曜格"],"page":439},"卯":{"names":["杀破狼格"],"page":440},"辰":{"names":["善荫朝纲格","命无正曜格"],"page":441},"巳":{"names":["紫府武廉相格"],"page":442},"午":{"names":["机月同梁格"],"page":443},"未":{"names":["将星得地格","贪武同行格"],"page":444},"申":{"names":["巨日同宫格"],"page":445},"酉":{"names":["府相朝垣格"],"page":446},"戌":{"names":["善荫朝纲格","机月同梁格"],"page":447},"亥":{"names":["紫府武廉相格"],"page":448}}}},"reading/patterns":{"version":"0.5","source":"《图解道教天文历算学·紫微斗数（上）》第柒章 命格解析（摘编）","patterns":{"紫府同宫":{"rule":"紫微、天府同宫守命（寅或申）","note":"两颗主星同坐，日子宽裕有福气。心里偶尔会有点孤单，感情慢慢来更自在。"},"府相朝垣":{"rule":"天府、天相会照命宫三方四正","note":"稳当、有人帮衬，在成体系的路上一步步往上走最顺。"},"机月同梁":{"rule":"天机、太阴、天同、天梁齐会命宫三方四正","note":"公教、文教、大众传播都很合拍，稳稳往前就很好。"},"巨机同临":{"rule":"天机、巨门同宫守命（卯或酉）","note":"脑子快、嘴也利，高科技或一门专业深耕下去最见长。"},"月朗天门":{"rule":"太阴在亥守命","note":"清秀内敛，喜欢慢慢积累，文教和幕后都很自在。"},"日照雷门":{"rule":"太阳在卯守命","note":"明朗外向，敢把想法说出来，公职、传播、教育都很合适。"},"石中隐玉":{"rule":"巨门在子或午守命","note":"会说话，也容易卷进闲话，靠一门专业立身最稳，话到嘴边留半句。"},"七杀朝斗":{"rule":"七杀在寅、申、子、午守命","note":"适合自己开路和武职这类事，主动一点很好，锋芒收一收更稳。"},"极向离明":{"rule":"紫微在午守命","note":"格局清贵，有人帮衬时最出彩，别什么都自己扛。"},"贪武同行":{"rule":"武曲、贪狼同宫守命（丑或未）","note":"钱和想法一起来，踏实做实业、稳稳经营最合适，太大的一步不必冒。"},"日月并明":{"rule":"太阳、太阴同宫守命（丑或未）","note":"身上同时有热和静两面，把作息和情绪调匀就顺了。"},"君臣庆会":{"rule":"紫微守命，三方四正会左辅右弼、文昌文曲、天魁天钺","note":"格局好、也常有人帮，借团队把事做成，比一个人拍板更顺。"},"巨日同宫":{"rule":"太阳、巨门同宫守命（寅或申）","note":"会表达也坦荡，传播、教育、法律都很对路，少卷进闲气更省心。"},"机梁加会":{"rule":"天机、天梁同宫或三方会照命宫","note":"会谋划又稳得住，策划、研究、公益这类事很合拍。"},"文梁振纪":{"rule":"文昌、天梁会照命宫","note":"有文采也有原则，文教、法务、公职都能发挥。"},"阳梁昌禄":{"rule":"太阳、天梁、文昌、禄存齐会命宫三方四正","note":"考试和稳定收入上都更容易顺，公职、文教是顺路。"},"三奇加会":{"rule":"化禄、化权、化科三奇会照命宫三方四正","note":"三颗吉化齐来，格局亮眼，顺着势头走、别端着就更好。"},"左右同宫":{"rule":"左辅、右弼同宫守命","note":"帮手多、人缘好，跟团队一起做事最省力。"},"文桂文华":{"rule":"文昌、文曲同宫守命","note":"聪明多才，文书和考试都容易出彩，肯落到实处就更亮。"},"将星得地":{"rule":"武曲守命且庙旺","note":"执行力足，财经、实业都很合适，语气软一点路更宽。"},"月生沧海":{"rule":"太阴在子守命","note":"清贵内敛，文教、财务、幕后谋划都自在。"},"寿星入庙":{"rule":"天梁在午守命","note":"自带庇荫，专业和公益都合适，别把别人的事都揽上身。"},"英星入庙":{"rule":"破军在子或午守命","note":"敢破敢立、气势足，很适合开创，收尾时多撑一会儿就好。"},"马头带箭":{"rule":"擎羊在午宫守命","note":"性子烈、冲劲足，军警、竞技都能发挥，动手前留半秒更稳妥。"},"紫府朝垣":{"rule":"紫微或天府庙旺守命","note":"主星得地坐命，再有吉星相伴，格局清贵。"},"天府朝垣":{"rule":"天府在辰或戌守命","note":"主星坐守财库，福气厚，稳稳守住就很舒服。"},"金灿光辉":{"rule":"太阳在午守命","note":"如日当中，格局亮眼，起伏来时把节奏放慢就好。"},"明珠出海":{"rule":"命宫在未无主星，卯宫太阳天梁、亥宫太阴合照","note":"三星连成一线，容易在名声和事业上被看见。"},"天乙拱命":{"rule":"天魁、天钺夹命宫","note":"贵人从旁拱着，常有人愿意拉你一把。"},"权禄巡逢":{"rule":"化禄与化权同守命宫","note":"权与禄一起到，格局亮眼，星曜得地时更出彩。"},"科权禄夹":{"rule":"化科、化权、化禄中有二居命宫两侧","note":"三吉化从旁夹着，格局清贵。"},"双禄夹命":{"rule":"禄存与化禄夹命宫","note":"两禄夹着，钱财上比较宽裕。"},"三合火贪":{"rule":"火星与贪狼同宫或三合","note":"火与贪狼相遇，容易一阵子突然发光，状态足时最明显。"},"贪铃朝垣":{"rule":"铃星与贪狼同宫","note":"铃星与贪狼同度，气场足、能服众，状态稳时更好。"},"贵星夹命":{"rule":"紫微天府夹命，或太阳太阴夹命","note":"贵星从旁夹着，格局好也常有人帮。"},"廉贞文武":{"rule":"廉贞在寅或申，文昌文曲三方拱照","note":"文武都拿得起，政法、军警、艺术都能发挥。"},"辅拱文星":{"rule":"文昌守命，左辅三方拱照","note":"才华有人帮衬，文教、策划很顺手。"},"禄文拱命":{"rule":"禄存守命，三方得昌曲拱照","note":"财与名都来得顺，节奏别被外界打乱就好。"},"禄合鸳鸯":{"rule":"禄存与化禄同守命宫","note":"两禄同宫，进账宽裕。"},"双禄朝垣":{"rule":"三方四正有禄存与化禄","note":"两禄会来，财与格局都不错，遇到起伏慢一点就好。"},"禄马交驰":{"rule":"三方四正有禄存或化禄，又有天马","note":"常在外奔波，也容易在异地把钱挣出来。"},"二曜同临":{"rule":"命在丑日月在未，或命在未日月在丑","note":"日月相互照着，格局清亮，节奏稳住就更顺。"},"丹桂":{"rule":"太阳在辰或巳守命，或太阴在酉或戌守命","note":"两颗主星都得地，年轻时就容易崭露头角。"},"甲第登庸":{"rule":"化科守命，化权在三方","note":"科与权相朝，考试、管理都更容易顺。"},"科名会禄":{"rule":"化科守命，化禄在三方","note":"科与禄相会，名声和收入都容易慢慢起来。"},"明禄暗禄":{"rule":"命宫有化禄或禄存，暗合宫有另一个","note":"明暗两禄都在，财路接得比较顺。"},"权星朝垣":{"rule":"化权守命宫","note":"权星坐命，肯扛事、有担当，有人帮衬时更容易成。"},"禄马佩印":{"rule":"禄存或化禄与天马、天相同宫守命","note":"禄马带印，进账稳，也容易有个说得出的位置。"},"财禄夹马":{"rule":"天马守命，邻宫有武曲与化禄相夹","note":"财禄夹着天马，早年紧一点，往后慢慢宽裕。"},"日月照壁":{"rule":"破军在辰或戌守命，太阳太阴在丑或未（田宅）","note":"容易攒下家业，三方再有吉星相助就更稳。"},"化星返贵":{"rule":"天同在戌守命逢丁年，或巨门在辰守命逢辛年","note":"平宫遇化忌反而转出贵气，是比较特别的一格。"},"科明禄暗":{"rule":"化科守命，暗合宫有禄存或化禄","note":"科在明、禄在暗，名声一起来，收入也跟着来。"},"羊陀夹煞":{"rule":"煞星坐宫被两邻宫擎羊、陀罗夹制","note":"两颗煞星从旁夹着，脾气容易被引起来，走到这段运时给自己多一点缓冲。"},"火铃夹煞":{"rule":"煞星坐宫被两邻宫火星、铃星夹制","note":"火铃夹着，容易有说来就来的小状况，留点余地就不慌。"},"空劫夹煞":{"rule":"煞星坐宫被两邻宫地空、地劫夹制","note":"空劫夹着，想法和现实容易来回拉扯，把眼前的事做实就好。"},"双忌夹煞":{"rule":"生年忌与大限忌夹制煞星坐宫","note":"两忌夹着，事情容易反复，慢一点、多给自己一点时间。"},"三方皆煞":{"rule":"命宫、财帛、官禄、迁移皆坐煞星","note":"三方都带煞，路上卡点会多一些，一件件来反而走得稳。"},"七杀羊陀迭并":{"rule":"七杀守命，羊陀同宫或会照","note":"性子急、容易硬碰，往武职这类有章法的地方使力，反而更顺。"},"刑囚夹印":{"rule":"廉贞、天相、擎羊（或陀罗）三合会照","note":"容易碰上规则与是非，法务、军警这类讲规矩的路子很合适。"},"路上埋尸":{"rule":"廉贞、七杀、擎羊（或陀罗）会照","note":"奔走多、也容易磕碰，武职这类有节奏的岗位更稳妥。"},"巨火羊":{"rule":"巨门、火星、擎羊会照","note":"话和脾气都容易抢先一步，慢半拍再开口就好。"},"巨铃羊":{"rule":"巨门、铃星、擎羊会照","note":"容易被闲话惊到，动手前先稳一稳。"},"铃昌陀武":{"rule":"铃星、文昌、陀罗、武曲会照","note":"事情容易卡一下又重来，守住节奏比抢快更有效。"},"天机天梁擎羊会":{"rule":"天机、天梁、擎羊会照","note":"起伏里带点硬碰，往技术专业里扎根，反而能把劲用对。"},"权杀化禄":{"rule":"羊陀火铃坐命入庙，三方有化禄化权","note":"气场足、敢冲，武职或带挑战的事很合适，身边有吉星帮衬更稳。"}}},"reading/star_notes":{"version":"0.1","source":"《图解道教天文历算学·紫微斗数（上·命理卷）》第伍章 星曜特性（摘编）","notes":{"紫微":"像一位天生想做主的人，遇事有主见，也常被大家托付。有人帮衬时最自在；什么都自己扛久了，会有点孤单，记得把身边的人拉进来一起商量。","天机":"脑子转得快，爱琢磨、爱规划，做参谋和策划特别合适。想法一多就容易反复，拿不准的事慢一点决定，给自己留点余地就好。","太阳":"热心又坦荡，愿意把光分给别人，也在意自己被怎么看。付出多的时候容易累，别忘了顺手照一照自己。","武曲":"做事干脆、说干就干，对钱和数字很有感觉，适合踏实经营的路子。性子急时容易把话说硬，缓一缓反而更顺。","天同":"温和好相处，懂得享受当下，人缘也顺。不太爱逼自己，在稳定的节奏里反而最能发光。","廉贞":"爱憎分明，有棱角也有吸引力，适合需要判断力、表现力的事。情绪起伏时留一点空间给自己，有边界会更自在。","天府":"稳重、会攒资源，像把家打理得妥帖的管家。守成是你的拿手好戏，遇上大变化慢慢来就好。","太阴":"细腻、慢热，喜欢一点点积累，也很会照顾人。想得多时容易内耗，把心里话说出来，会轻松不少。","贪狼":"兴趣广、会来事，才艺和人缘都不缺，热闹里最如鱼得水。想要的东西多，挑一两样认真深耕，会比样样浅尝更尽兴。","巨门":"会问、会辩，眼睛里揉不得沙子，研究、法律、讲台都很合适。话说直了容易起误会，慢半拍再开口，反而更有分量。","天相":"体面又周全，最会替人圆场、把事协调好。心软时容易替别人扛，记得也留一句给自己的主张。","天梁":"老成、有原则，天生爱照拂人，像身边那位靠谱的长辈。操心多了会累，把别人的课题还给别人就好。","七杀":"独立、果决，敢自己开路，从零开始的事最合你的性子。冲劲很足，偶尔收一收锋芒，路会走得更稳。","破军":"敢破敢立，不怕重来，身上有股开创的劲头。开头很猛，收尾时多撑一会儿，成果就落得住了。","禄存":"踏实、会存，日子讲究一个稳字。守得住是长处，偶尔给自己松一点，反而更安心。","左辅":"愿意搭把手，也容得下不同意见，是很好的同行者。和主星一起出现时，助力最明显。","右弼":"圆融、会协调，擅长把人凑到一起。和左辅一同出现，配合起来尤其顺手。","文昌":"爱读书、爱琢磨，文字和条理都是强项。状态被打断时容易卡住，给自己留一段安静时间就好。","文曲":"有才气，也会表达，审美和口才都在行。周遭太杂容易分心，挑个合拍的圈子更能发挥。","天魁":"像白天递来的那只手，容易遇到愿意提携你的人。机会来的时候，大方接住就好。","天钺":"像夜里的一盏灯，常有人在不动声色处帮你一把。别人给的建议，值得认真听一听。","擎羊":"性子直、冲劲足，该出手时绝不犹豫。力道用得急容易碰疼人，慢半拍会更利落。","陀罗":"容易在同一件事上打转，反复斟酌才肯往前。别怪自己慢，想清楚了再走，反而走得稳。","火星":"来得快、也热烈，说燃就燃。和贪狼相遇时容易擦出火花；急着下决定前，先给自己数三秒。","铃星":"心里那团火闷着烧，反应比看上去快。给它一个出口，别让急劲儿攒成压力。","地空":"想法天马行空，不太爱被框住，创作和研究都很合适。守着死规矩会闷，留点空白反而有灵感。","地劫":"不太恋旧，敢推倒重来，来去看得开。起伏大的时候照顾好手边的日常，先稳住，再出发。","天马":"闲不住，喜欢走动和变化，越动越有精神。和禄存一起出现时，奔忙更容易换来收获；方向定了再跑，会更省力。"},"meta":{"紫微":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"紫微屬土，乃中天之尊星，為帝座，主掌造化樞機，人生主宰","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"021"},"pdf":{"page":11,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"天机":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"天機屬木，南斗第三益算之善星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"023"},"pdf":{"page":12,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"太阳":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"太陽星屬火，日之精也；乃造化之表儀","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"024"},"pdf":{"page":13,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"武曲":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"武曲北斗第六星，屬金乃財帛宮主財","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"026"},"pdf":{"page":14,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"天同":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"天同星屬水，乃南方第四星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"027"},"pdf":{"page":14,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"廉贞":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"廉貞屬木，北斗第五星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"028"},"pdf":{"page":15,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"天府":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"天府屬土，南斗主令第一星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"028"},"pdf":{"page":15,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"太阴":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"太陰乃水之精，為田宅主化富","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"029"},"pdf":{"page":15,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"贪狼":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"貪狼北斗解厄之神，第一星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"030"},"pdf":{"page":16,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"巨门":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"巨門屬水金，北斗第二星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"032"},"pdf":{"page":17,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"天相":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"天相屬水，南斗第五星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"033"},"pdf":{"page":17,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"天梁":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"天梁屬土，南斗第二星也，司壽","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"034"},"pdf":{"page":18,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"七杀":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"七殺南斗第六星也，屬火金","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"035"},"pdf":{"page":18,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"破军":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"破軍屬水，北斗第七星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"036"},"pdf":{"page":19,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"文昌":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"文昌主科甲，守身命，主人幽閑儒雅","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"037"},"pdf":{"page":19,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"文曲":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"文曲屬水，北斗第四星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"038"},"pdf":{"page":20,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"左辅":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"左輔帝極主宰之星，守身命諸宮降福","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"039"},"pdf":{"page":20,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"右弼":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"右弼帝極主之星，守身命文墨精通","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"039"},"pdf":{"page":20,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"禄存":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"祿存北斗第三星，真人之宿","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"041"},"pdf":{"page":21,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"天魁":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"魁鉞斗中司科之星","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"040"},"pdf":{"page":21,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"天钺":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"魁鉞斗中司科之星","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"040"},"pdf":{"page":21,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"天马":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"諸宮各有制化，如身命臨之，謂之驛馬","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"042"},"pdf":{"page":22,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"擎羊":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"擎羊北斗之助星","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"044"},"pdf":{"page":23,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"陀罗":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"陀羅北斗之助星","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"044"},"pdf":{"page":23,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"火星":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"火星乃南斗浮星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"045"},"pdf":{"page":23,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"铃星":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"鈴星乃南斗助星也","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"045"},"pdf":{"page":23,"side":"L"},"checked":"2026-11-12 逐字对图核对"},"地空":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"二星守身命，遇吉則吉，遇凶則凶","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"046"},"pdf":{"page":24,"side":"R"},"checked":"2026-11-12 逐字对图核对"},"地劫":{"ruleset":"zywx.classic.cn@2026.1","source":{"text":"二星守身命，遇吉則吉，遇凶則凶","book":"紫微斗數全書","edition":"陳希夷進源版","juan":"卷之一","page":"046"},"pdf":{"page":24,"side":"R"},"checked":"2026-11-12 逐字对图核对"}}},"reading/templates_v02":{"version":"0.2","note":"短模板 v0.2：14 主星 × 5 维，80–150 字；语气参考 Renhuai123/ziwei-doushu 数据集，健康段只写状态与习惯。","count":70,"templates":[{"id":"ziwei-性格","star":"紫微","dimension":"性格","palace":"命宫","chars":88,"text":"你往人群里一坐，不用开口就有人看过来。乱局里你最先看出主线，也最不服被人指挥。这份天生的上位感是本事，也是坎：被否定时嘴上客气，心里能记很久。要练的不是谦虚，是承认自己也会错。","basis":"紫微（命宫）"},{"id":"ziwei-事业","star":"紫微","dimension":"事业","palace":"官禄","chars":89,"text":"你靠才华和个人风格吃饭，创意、表达、能站在台前的事最对你的路子。你能把一盘散沙盘活，但情绪一上来容易把事搞砸。找个稳重的人管运营和账目，你只管创意和对外。贵人往往和舞台一起出现。","basis":"紫微（官禄）"},{"id":"ziwei-财运","star":"紫微","dimension":"财运","palace":"财帛","chars":81,"text":"钱是本事换来的，越专业、越难被替代，进账越稳。你不为面子乱花钱，存得住，只是有时候省过了头。别碰看不懂的高风险盘子，留一笔备用金，合作借贷一律白纸黑字。慢就是快。","basis":"紫微（财帛）"},{"id":"ziwei-健康","star":"紫微","dimension":"健康","palace":"疾厄","chars":88,"text":"底子不差，真正拖后腿的是生活方式：能坐不站，运动量常年不够。心里有事你不爱说，硬扛久了睡眠和肠胃先报警。把运动做成每天的一件小事，比偶尔练一次狠的管用得多。别拿意志力硬扛身体。","basis":"紫微（疾厄）"},{"id":"ziwei-感情","star":"紫微","dimension":"感情","palace":"夫妻","chars":86,"text":"你要的是被尊重，不是被哄。对方若只会顺着你，你很快失去兴趣；能当面反驳、又说得出道理的人，才留得住。你给的踏实都藏在行动里，别让对方一直靠猜。把姿态放软一点，关系才走得长。","basis":"紫微（夫妻）"},{"id":"tianfu-性格","star":"天府","dimension":"性格","palace":"命宫","chars":80,"text":"你看着普通，其实很稳。不抢风头，账却算得清楚，关键时刻顶得住。年轻时你慢半拍，同龄人在闯，你在攒；中年以后这份稳显出好处，钱稳、家稳、关系也稳。短板是缺爆发力。","basis":"天府（命宫）"},{"id":"tianfu-事业","star":"天府","dimension":"事业","palace":"官禄","chars":81,"text":"你的本事在幕后。在大平台里做核心支撑，比站到最前面更适合你：行政、财务、法务、运营，制度越健全你越顺。功劳容易被别人拿走，记得每年主动提一次升职加薪，拿数字说话。","basis":"天府（官禄）"},{"id":"tianfu-财运","star":"天府","dimension":"财运","palace":"财帛","chars":80,"text":"你的钱跟着位置走，工资和头衔带来的收入稳定，投机暴富不是你的路数。你重面子、爱买好的，攒钱偏慢；又太信自己的判断，拍脑袋的决定一错损失不小。中年以后会明显宽裕。","basis":"天府（财帛）"},{"id":"tianfu-健康","star":"天府","dimension":"健康","palace":"疾厄","chars":80,"text":"你属于神经敏感的体质，脑子转得太久，身体先扛不住。最容易出状况的是睡眠：心里搁着事就睡不踏实，人容易累、容易头疼。把作息固定下来，吃得清淡些，情绪一紧身体就紧。","basis":"天府（疾厄）"},{"id":"tianfu-感情","star":"天府","dimension":"感情","palace":"夫妻","chars":81,"text":"你像靠谱的合伙人，不浪漫，但不会突然消失。你重体面，也看重对方能不能一起把日子过稳。别把心事都攒着，偶尔把在意说出口，关系会松很多。体面给外人看，松弛只留给家里。","basis":"天府（夫妻）"},{"id":"qisha-性格","star":"七杀","dimension":"性格","palace":"命宫","chars":84,"text":"你的存在感很强，不靠嗓门，靠那股不好惹的气场。你果断、不爱绕弯，定了的事不回头；受不了拖泥带水的人，团队配合上常有摩擦。你性子急又刚，还容易多疑。嘴上不说，心里都有数。","basis":"七杀（命宫）"},{"id":"qisha-事业","star":"七杀","dimension":"事业","palace":"官禄","chars":88,"text":"你的事业靠破和变吃饭。开新局、推改革的地方最能发挥，守着老一套天天重复你受不了。适合往外走、跨行、自己干。给自己定条规矩：一件事没做满三年不换赛道。熬过前三年，复利才真正开始。","basis":"七杀（官禄）"},{"id":"qisha-财运","star":"七杀","dimension":"财运","palace":"财帛","chars":86,"text":"你的钱很少是按月稳稳发的那种。大钱多半在计划外，靠人脉、机会一笔一笔来，来得猛也去得快。挣得多、存得难。每次赚到先把本金抽走，放进一个不好动的账户。本金在，机会才轮得到你。","basis":"七杀（财帛）"},{"id":"qisha-健康","star":"七杀","dimension":"健康","palace":"疾厄","chars":90,"text":"你的身体跟心情是连着的。心情顺就有劲，情绪压着就先喊累。你偏敏感，长期憋着，睡眠和精神往往最先出问题。吃温的、按点吃，运动挑舒缓的，出点汗情绪也跟着走掉。每年体检一次，这一项别省。","basis":"七杀（疾厄）"},{"id":"qisha-感情","star":"七杀","dimension":"感情","palace":"夫妻","chars":83,"text":"你直接但不细腻，给的是说到做到的踏实，不是猜心思的温柔。对方要能接住你的急，也得有自己的主意。关心做出来比说出口管用：接一次机、记一个日子，都比沉默强。把在意做出来。","basis":"七杀（夫妻）"},{"id":"wuqu-性格","star":"武曲","dimension":"性格","palace":"命宫","chars":84,"text":"你务实、直接、认结果。不喜欢空谈，事情到你手上就得有交代。缺点是硬，话不留余地，容易把人推远；你其实心软，只是不习惯表达。学会在开口前先放慢半拍。慢半拍，话说得就软了。","basis":"武曲（命宫）"},{"id":"wuqu-事业","star":"武曲","dimension":"事业","palace":"官禄","chars":85,"text":"你适合跟钱、资源、执行打交道：财务、金融、工程、实业。你靠专业和效率立身，不喜欢应酬场。升迁靠的是把事做成，而不是把话说漂亮。找的人要能补你的人际短板。专业越深，路越宽。","basis":"武曲（官禄）"},{"id":"wuqu-财运","star":"武曲","dimension":"财运","palace":"财帛","chars":82,"text":"你对钱敏感，也管得住。收入跟能力和位置挂钩，走的是稳路；敢下手，但别把杠杆压满。你花钱务实，不太为面子买单，长期拿住看得懂的资产就够了。别把全部身家押在一次判断上。","basis":"武曲（财帛）"},{"id":"wuqu-健康","star":"武曲","dimension":"健康","palace":"疾厄","chars":81,"text":"你容易把自己当机器用，累了也硬撑。留意筋骨、牙齿和作息，别等到疼了才休息。运动挑带力量的，比只做有氧更适合你；每年体检别省。把休息也当成一项任务来执行，才跑得长。","basis":"武曲（疾厄）"},{"id":"wuqu-感情","star":"武曲","dimension":"感情","palace":"夫妻","chars":84,"text":"你表达爱的方式是解决问题，不是甜言蜜语。对方若只想要情绪价值，会觉得你冷。把在意说出口一次，胜过替对方做十件事；也要允许对方用自己的方式对你好。两个人都舒服，才走得远。","basis":"武曲（夫妻）"},{"id":"tianji-性格","star":"天机","dimension":"性格","palace":"命宫","chars":97,"text":"你脑子像一台不熄火的机器，别人看你在发呆，里面同时跑着十几条线。上手快、什么都摸得到门道，代价是每样都没挖到底。真正舒服的位置是出主意，不是扛大旗；感情里也容易反复，不是不专一，是总在重新算账。","basis":"天机（命宫）"},{"id":"tianji-事业","star":"天机","dimension":"事业","palace":"官禄","chars":89,"text":"你适合靠脑子和策划吃饭：顾问、技术把关、教育培训、分析研究，环境有温度你效率才高。天天硬碰业绩的地方你待着难受。团队里你常提出新角度，但把事从头推到尾不是强项，最好有人替你落地。","basis":"天机（官禄）"},{"id":"tianji-财运","star":"天机","dimension":"财运","palace":"财帛","chars":94,"text":"你的钱是慢慢攒出来的，早年数目不大，中年以后才见模样。主要靠薪水和专业，真正的赚钱方式是口碑——一件事做到让人信得过，客人会自己带客人来。漏钱的地方很固定：吃喝、旅行、让自己舒服的小开销。","basis":"天机（财帛）"},{"id":"tianji-健康","star":"天机","dimension":"健康","palace":"疾厄","chars":86,"text":"你累的时候不是垮，是空。脑子转太久，最先出事的是睡眠和神经，久坐还会把颈椎、腰椎拖出问题。情绪你习惯往心里咽，表面平和，其实一直扛着。把作息钉死，每天留一段完全不动的空白。","basis":"天机（疾厄）"},{"id":"tianji-感情","star":"天机","dimension":"感情","palace":"夫妻","chars":85,"text":"你想得多，对方一句平常话你能拆出三层意思。不是不信任，是脑子停不下来。你需要一个说得清、也愿意解释的人，把猜的部分填上；否则你会在心里把关系演完，再去问对方为什么不配合。","basis":"天机（夫妻）"},{"id":"taiyang-性格","star":"太阳","dimension":"性格","palace":"命宫","chars":83,"text":"你一进门，房间就亮了。大方、直率、爱表态，陌生人也容易喜欢你。代价是不擅长独处与反省，停下来对你是种煎熬，于是干脆一直忙。你在意被看见，不是虚荣，是这真的是你的燃料。","basis":"太阳（命宫）"},{"id":"taiyang-事业","star":"太阳","dimension":"事业","palace":"官禄","chars":84,"text":"你的事业靠一张嘴和一身正气：教育、媒体、公职、销售、法律，凡是要说服人、替人争权益的岗位都适合。你敢说真话，有时因此得罪人。把话挑私下的场合说，锋芒收三分，路会顺很多。","basis":"太阳（官禄）"},{"id":"taiyang-财运","star":"太阳","dimension":"财运","palace":"财帛","chars":83,"text":"你的钱起伏不小，靠的是名气与表达换来的收入。讲课、咨询、写东西、做方案，把脑子变成钱最自然。你赚钱强过守钱，想法一多就分到好几个方向。早年起伏大，四十岁以后才慢慢稳。","basis":"太阳（财帛）"},{"id":"taiyang-健康","star":"太阳","dimension":"健康","palace":"疾厄","chars":82,"text":"你身上有股火气，情绪一起伏，身体立刻有反应：容易上火、睡不安稳，眼睛和心血管要先留意。喝酒和重口味会把这股火拱得更旺。你的健康和心情基本是一回事，别让生气替你熬夜。","basis":"太阳（疾厄）"},{"id":"taiyang-感情","star":"太阳","dimension":"感情","palace":"夫妻","chars":86,"text":"你付出得大方，也容易被自己的热情带着走。你习惯先给，再等对方回应；对方慢一点，你会怀疑是不是不够爱。学会把需要说出来，别用更多付出去换一个答案，关系反而更稳。把需要讲明白。","basis":"太阳（夫妻）"},{"id":"tiantong-性格","star":"天同","dimension":"性格","palace":"命宫","chars":83,"text":"你最不容易跟人结仇。脾气好、不争抢，跟谁都聊得来，很多事你自己办不成，拉着人一起反倒办成了。麻烦在于缺一股非做成不可的劲，舒服久了会心慌。该主动的时候，别等别人推你。","basis":"天同（命宫）"},{"id":"tiantong-事业","star":"天同","dimension":"事业","palace":"官禄","chars":87,"text":"你靠脑子和应变吃饭，最发光的不是埋头执行，而是出主意、定方向。公职、内勤、咨询、教育培训、策划都合适。领一份固定薪水、把本事用在判断上，比自己扛风险稳得多。别让舒服变成将就。","basis":"天同（官禄）"},{"id":"tiantong-财运","star":"天同","dimension":"财运","palace":"财帛","chars":86,"text":"你的钱来得平稳，靠积累不靠爆发。你不大会为钱焦虑，也容易花在让自己舒服的地方。设一个固定储蓄比例，工资一到账先转走，比指望一笔大进项实在。人缘就是你的财路，别把自己关起来。","basis":"天同（财帛）"},{"id":"tiantong-健康","star":"天同","dimension":"健康","palace":"疾厄","chars":82,"text":"你偏享受型，能躺不坐。体重、血糖、睡眠是三个要盯的点，水肿和消化也常跟着作息走。把运动做成习惯，别等体检报告来提醒你。把散步、早睡这些小事固定下来，身体会安静很多。","basis":"天同（疾厄）"},{"id":"tiantong-感情","star":"天同","dimension":"感情","palace":"夫妻","chars":82,"text":"你怕冲突，小事都咽下去，久了会冷。你要的是被照顾，也愿意照顾人，但别把照顾变成交换。学会在不满还小的时候就说出来，比憋到最后翻旧账有用。把话说在前面，比事后委屈强。","basis":"天同（夫妻）"},{"id":"lianzhen-性格","star":"廉贞","dimension":"性格","palace":"命宫","chars":91,"text":"你心里永远比脸上复杂。不是好脾气，是那团火常压着不发。你爱憎分明，喜欢得深，不喜欢也记得久；聪明常常用错地方——一句话能琢磨三个月。带点锋芒的路你走着反而顺。锋芒要对准事，不是对人。","basis":"廉贞（命宫）"},{"id":"lianzhen-事业","star":"廉贞","dimension":"事业","palace":"官禄","chars":87,"text":"你靠真本事说话，不靠关系也不靠形象。金融财务、工业制造、军警执法、工程管理，或有实权能拍板的位置都合适。你做事不拖，团队推得快，但管人偏硬，下属压力不小。学会把话软下来一点。","basis":"廉贞（官禄）"},{"id":"lianzhen-财运","star":"廉贞","dimension":"财运","palace":"财帛","chars":83,"text":"你的钱跟着位置走。工资、头衔带来的收入稳定；投机和快钱不是你的路数。你重面子，买好的、贵的，攒钱偏慢；又容易太信自己的判断，拍脑袋的决定一错损失不小。中年以后会宽裕。","basis":"廉贞（财帛）"},{"id":"lianzhen-健康","star":"廉贞","dimension":"健康","palace":"疾厄","chars":85,"text":"你神经敏感，脑子转太久身体先扛不住。最容易出问题的是睡眠：心里压着事就睡不踏实，人累、头也疼。情绪一紧身体跟着紧，别把硬扛当成能力。该松的时候真松下来。把休息排进日程里。","basis":"廉贞（疾厄）"},{"id":"lianzhen-感情","star":"廉贞","dimension":"感情","palace":"夫妻","chars":83,"text":"你爱得深，也记得久。对方的冷淡你能忍，敷衍你忍不了。你要的是势均力敌、能接住你锋芒的人；一旦认定，就很少留退路。把话说开，比在心里反复审判对方有用。别用试探代替直说。","basis":"廉贞（夫妻）"},{"id":"taiyin-性格","star":"太阴","dimension":"性格","palace":"命宫","chars":86,"text":"你心思软，体贴得近乎周到。别人忽略的情绪你看得见，随口提过的喜好你记得住。缺点是太软、不爱直来直往，宁可在背后把事默默办完。安静少打扰的时候你状态最好，人多的场合反而耗你。","basis":"太阴（命宫）"},{"id":"taiyin-事业","star":"太阴","dimension":"事业","palace":"官禄","chars":90,"text":"你靠细腻和专业攒口碑，越是做出对别人有用的事越出得来。文化、教育、医疗、咨询、财务都合适。你是稳场面的那个人，乱的时候最清醒；缺点是态度偏冷，别人不太敢靠近。专业做到别人替不了你。","basis":"太阴（官禄）"},{"id":"taiyin-财运","star":"太阴","dimension":"财运","palace":"财帛","chars":85,"text":"你的收入不太能提前算准，机会多来自人脉和曝光，邀约不少但好坏都有，得挑。你花钱大方，请客送礼、维持形象的开销不小。钱通常来得晚，中年以后才真正厚起来。把面子开销设个上限。","basis":"太阴（财帛）"},{"id":"taiyin-健康","star":"太阴","dimension":"健康","palace":"疾厄","chars":84,"text":"你底子偏柔，情绪和睡眠是最先响的两处。心思细的人容易把话咽下去，闷气最后落在身体上，变成说不清的酸痛和疲惫。规律作息、少熬夜，比补品管用。把睡觉当成正事，别总排在最后。","basis":"太阴（疾厄）"},{"id":"taiyin-感情","star":"太阴","dimension":"感情","palace":"夫妻","chars":84,"text":"你细腻，也慢热。你会用记得对方的小事来表达在意，却很少直接说需要什么。遇上大大咧咧的人，容易觉得委屈；把期待说清楚，你的温柔才不会被当成理所当然。你要的，得让对方知道。","basis":"太阴（夫妻）"},{"id":"tanlang-性格","star":"贪狼","dimension":"性格","palace":"命宫","chars":86,"text":"你在哪儿，哪儿就是焦点。嘴上有功夫，人脉天然宽，做生意有别人比不了的起手优势。但热络是面子，里子其实挺硬：认定的事九头牛拉不回。你最大的对手是想要的太多。把劲收在一件事上。","basis":"贪狼（命宫）"},{"id":"tanlang-事业","star":"贪狼","dimension":"事业","palace":"官禄","chars":84,"text":"你适合竞争强、变化快的地方：销售、娱乐、公关、外贸，越是有舞台越有精神。纯文书和行政会把你磨钝。你是团队里的冲锋队长，推得快，但也容易因为不肯妥协树敌。把对手当同行看。","basis":"贪狼（官禄）"},{"id":"tanlang-财运","star":"贪狼","dimension":"财运","palace":"财帛","chars":87,"text":"你的钱大起大落。好的时候来得猛，淡的时候也真淡。固定收入跟着事业走，意外之财常在变动里冒出来，抓时机比埋头苦干管用。你赚钱强、守钱弱，心情一好就大手大脚。先存后花，别反着来。","basis":"贪狼（财帛）"},{"id":"tanlang-健康","star":"贪狼","dimension":"健康","palace":"疾厄","chars":82,"text":"你体力好、精力旺，也最容易透支。忙起来不知道停，情绪一上来火也大。用眼多、屏幕前久，眼睛要额外照顾；应酬排太满，抵抗力会掉。该停的时候真停一天。身体的账，迟早要还。","basis":"贪狼（疾厄）"},{"id":"tanlang-感情","star":"贪狼","dimension":"感情","palace":"夫妻","chars":87,"text":"你多情，也好奇。容易被新鲜感推着走，真正留下来的，往往是能陪你玩、也能按住你的人。你不是不肯安定，是怕日子变成一潭死水。把边界说清楚，比事后解释有用。热闹之外，也要有一个人。","basis":"贪狼（夫妻）"},{"id":"jumen-性格","star":"巨门","dimension":"性格","palace":"命宫","chars":86,"text":"你说话有条理、想得深，一个问题能想到别人想不到的角度。这张嘴既是本事也是负担：说错一句能翻来覆去想三天，一点误会能纠结半年。你不是多疑，是看得太细。想归想，别把结论当事实。","basis":"巨门（命宫）"},{"id":"jumen-事业","star":"巨门","dimension":"事业","palace":"官禄","chars":84,"text":"你靠专业和口才吃饭：法律、教育、传媒、咨询、研究，凡是需要把事情说清楚、辩明白的行当都适合。你能挖出别人漏掉的细节，但要注意别把讨论变成争输赢。把话说清楚，比说赢重要。","basis":"巨门（官禄）"},{"id":"jumen-财运","star":"巨门","dimension":"财运","palace":"财帛","chars":82,"text":"你的钱跟着专业口碑走，稳但不快。真正的收入来自别人信得过你，愿意为你的判断付费。漏财多半在口舌是非和替人担保上，合同和承诺都要落到纸上。别替人做担保，钱和交情分开。","basis":"巨门（财帛）"},{"id":"jumen-健康","star":"巨门","dimension":"健康","palace":"疾厄","chars":88,"text":"身体跟着情绪走。你想得多、说得少，嘴上的克制会变成肠胃和睡眠的负担。作息稳定是你最大的保障，熬夜一次要缓好几天。把想不通的事写下来，比反复在脑子里过强。把心事写下来，比憋着强。","basis":"巨门（疾厄）"},{"id":"jumen-感情","star":"巨门","dimension":"感情","palace":"夫妻","chars":83,"text":"你需要一个能好好说话的人。对方若习惯冷战或含糊，你会自己在心里审半天。把疑问直接问出来，别用试探代替沟通；你要的不是赢，是被听懂。有话直说，别让对方猜你为什么不高兴。","basis":"巨门（夫妻）"},{"id":"tianxiang-性格","star":"天相","dimension":"性格","palace":"命宫","chars":80,"text":"你放在哪儿都让人放心。稳重、配合度高、爱面子但不张扬。给带头的人当左右手，比自己当头儿舒服；凡是你接下的事都办得妥当。那把是非尺很直，看见不地道的事心里就来气。","basis":"天相（命宫）"},{"id":"tianxiang-事业","star":"天相","dimension":"事业","palace":"官禄","chars":81,"text":"你靠位置吃饭。有头衔、说了算的岗位比在底下做执行更能发挥：行政、秘书、公关、管理层幕僚。你擅长定方向，不爱琐碎细节，需要能干的人替你落地。升职比跳槽更能改善收入。","basis":"天相（官禄）"},{"id":"tianxiang-财运","star":"天相","dimension":"财运","palace":"财帛","chars":85,"text":"你的钱是攒出来的，不是搏出来的。收入靠稳定工作和日积月累，花钱有节制，中年以后会相当充实。漏钱有两处：太保守，好机会不敢上；以及感情和家里的大额开销。该花的钱，也要舍得。","basis":"天相（财帛）"},{"id":"tianxiang-健康","star":"天相","dimension":"健康","palace":"疾厄","chars":87,"text":"你底子不错，但容易把事憋在身上。体面惯了，不舒服也先忍着。皮肤、泌尿和睡眠是常被忽略的三处；定期体检，别等小毛病拖成习惯。情绪也要找出口。体检的报告别只收着，该改的习惯要改。","basis":"天相（疾厄）"},{"id":"tianxiang-感情","star":"天相","dimension":"感情","palace":"夫妻","chars":86,"text":"你重体面，也重配合。对方拿得出手、家里说得过去，你才安心。你不擅长表达需求，容易用帮忙代替亲密。偶尔示弱一次，比一直当那个可靠的人更有用。把需要说出口，对方才有机会对你好。","basis":"天相（夫妻）"},{"id":"tianliang-性格","star":"天梁","dimension":"性格","palace":"命宫","chars":87,"text":"你比同龄人显老成，不是长相，是那股沉得住气的劲。为人厚道，原则上的事一点不让。你有天生罩着人的本能，朋友出事第一个想到你；这份好也容易把你拖进去。帮人之前，先看看自己够不够。","basis":"天梁（命宫）"},{"id":"tianliang-事业","star":"天梁","dimension":"事业","palace":"官禄","chars":87,"text":"你吃的是名声这碗饭，被更多人知道，机会才来。医疗、教育、公职、监察、媒体都合适。你天生会带队、会表达，短板在细节和后台执行，需要有人替你收尾。把名声做在专业上，而不是场面上。","basis":"天梁（官禄）"},{"id":"tianliang-财运","star":"天梁","dimension":"财运","palace":"财帛","chars":89,"text":"你的钱是慢慢攒的，来自专业、薪水和跟审美有关的活。房子和不动产是真正的钱袋子，来快去快的投机不是你的路。漏财两处：为家人伴侣的大额付出，和心情一上头做的决定。稳定，比刺激更值钱。","basis":"天梁（财帛）"},{"id":"tianliang-健康","star":"天梁","dimension":"健康","palace":"疾厄","chars":85,"text":"你底子偏结实，但情绪和身体绑得紧。自尊心强的人一受挫，压力全闷在心里，最先扛不住的是睡眠和头部。吃饭按点、七分饱，少酒少油，别一顿撑一顿饿。情绪要有出口，别全往身体里放。","basis":"天梁（疾厄）"},{"id":"tianliang-感情","star":"天梁","dimension":"感情","palace":"夫妻","chars":82,"text":"你容易吸引比你年轻、或更需要照顾的人，也享受被需要。照顾是善意，但别把它变成控制。对方要成长时，松开手比一直扶着更难，也更有用。别用照顾绑住对方，也别用付出换回报。","basis":"天梁（夫妻）"},{"id":"pojun-性格","star":"破军","dimension":"性格","palace":"命宫","chars":88,"text":"你天生爱拆，不是有恶意，是安不下现状。稳定工作做三年就想换，老流程看一眼就想改。开创上少有人比得过你，守摊维持却几乎做不到。脑子跳得快，中间那几步常常是断的。把想法收成一条线。","basis":"破军（命宫）"},{"id":"pojun-事业","star":"破军","dimension":"事业","palace":"官禄","chars":87,"text":"你适合开新局、推改革：创业、技术攻坚、军警、重建类项目。守着一套重复的东西你受不了。给自己定条规矩：一件事做满三到五年再谈换，否则手上攒不下真本事。把开局的劲，分一半给收尾。","basis":"破军（官禄）"},{"id":"pojun-财运","star":"破军","dimension":"财运","palace":"财帛","chars":82,"text":"你的钱来得快去得也快。好的时候一笔大进，差的时候一笔大亏。你敢冒险，所以机会比别人多，也更容易在激进投资上亏掉一大截。强制储蓄，先划走再花。先保住本金，再谈下一把。","basis":"破军（财帛）"},{"id":"pojun-健康","star":"破军","dimension":"健康","palace":"疾厄","chars":87,"text":"你体力好，也最会透支。忙起来不知道停，情绪一上来火气大。消耗型的生活方式会在某天一起找你算账。每年体检，把睡眠和运动当成必须完成的任务，别拿年轻当本钱。把睡眠当成第一项任务。","basis":"破军（疾厄）"},{"id":"pojun-感情","star":"破军","dimension":"感情","palace":"夫妻","chars":82,"text":"你的感情要么很热，要么很烈。你看不上温吞，也受不了被管。真正留住你的是能跟你一起折腾、又稳得住的人。把冲动的话留到第二天再说，能少毁掉很多关系。热的时候留一句余地。","basis":"破军（夫妻）"}]},"reading/templates_v03":{"version":"0.3","note":"短模板 v0.3：14 主星 × 5 维 + 14 条大限/流年主题；80–150 字；健康段只写状态与习惯。","count":84,"templates":[{"id":"ziwei-性格","star":"紫微","dimension":"性格","palace":"命宫","chars":88,"text":"你往人群里一坐，不用开口就有人看过来。乱局里你最先看出主线，也最不服被人指挥。这份天生的上位感是本事，也是坎：被否定时嘴上客气，心里能记很久。偶尔也允许自己看走眼，反而更轻松。","basis":"紫微（命宫）"},{"id":"ziwei-事业","star":"紫微","dimension":"事业","palace":"官禄","chars":94,"text":"你靠才华和个人风格吃饭，创意、表达、能站在台前的事最对你的路子。你能把一盘散沙盘活，情绪上来时容易乱了节奏。有个稳重的人帮你管账目，你专心做创意和对外，会轻松很多。贵人往往和舞台一起出现。","basis":"紫微（官禄）"},{"id":"ziwei-财运","star":"紫微","dimension":"财运","palace":"财帛","chars":83,"text":"钱是本事换来的，越专业、越难被替代，进账越稳。你不为面子乱花钱，存得住，只是有时候省过了头。看不懂的高风险事不必急着碰，留一笔备用金、合作时把话写清楚，慢慢来反而稳。","basis":"紫微（财帛）"},{"id":"ziwei-健康","star":"紫微","dimension":"健康","palace":"疾厄","chars":79,"text":"底子不差，真正拖后腿的是生活方式：能坐不站，运动量常年不够。心里有事你不爱说，闷久了睡眠和肠胃先提醒你。每天动一动，比偶尔狠练一次管用；身体不用靠意志力硬撑。","basis":"紫微（疾厄）"},{"id":"ziwei-感情","star":"紫微","dimension":"感情","palace":"夫妻","chars":93,"text":"你要的是被尊重，不是被哄。对方若只会顺着你，你很快失去兴趣；能当面反驳、又说得出道理的人，才留得住。你给的踏实都藏在行动里，偶尔说一句，对方就不用猜了。姿态偶尔软一点，关系反而走得更久。","basis":"紫微（夫妻）"},{"id":"tianfu-性格","star":"天府","dimension":"性格","palace":"命宫","chars":87,"text":"你看着普通，其实很稳。不抢风头，账却算得清楚，关键时刻顶得住。年轻时你慢半拍，同龄人在闯，你在攒；中年以后这份稳显出好处，钱稳、家稳、关系也稳。只是起步会慢一点，稳稳走就好。","basis":"天府（命宫）"},{"id":"tianfu-事业","star":"天府","dimension":"事业","palace":"官禄","chars":79,"text":"你的本事在幕后。在大平台里做核心支撑，比站到最前面更适合你：行政、财务、法务、运营，制度越健全你越顺。默默做的功劳容易被忽略，偶尔把做过的事说一说，也挺好的。","basis":"天府（官禄）"},{"id":"tianfu-财运","star":"天府","dimension":"财运","palace":"财帛","chars":85,"text":"你的钱跟着位置走，工资和头衔带来的收入稳定，投机暴富不是你的路数。你重面子、爱买好的，攒钱偏慢；又太信自己的判断，一时兴起的决定，偶尔会多花点冤枉钱。中年以后会明显宽裕。","basis":"天府（财帛）"},{"id":"tianfu-健康","star":"天府","dimension":"健康","palace":"疾厄","chars":76,"text":"体质偏敏感，脑子转得太久，身体先扛不住。最容易出状况的是睡眠：心里搁着事就睡不踏实，人容易累、容易头疼。作息稳一点、吃得清淡些，情绪一紧，身体也跟着紧。","basis":"天府（疾厄）"},{"id":"tianfu-感情","star":"天府","dimension":"感情","palace":"夫妻","chars":81,"text":"你像靠谱的合伙人，不浪漫，但不会突然消失。你重体面，也看重对方能不能一起把日子过稳。心事不用都攒着，偶尔把在意说出口，关系会松很多。体面给外人看，松弛只留给家里。","basis":"天府（夫妻）"},{"id":"qisha-性格","star":"七杀","dimension":"性格","palace":"命宫","chars":84,"text":"你的存在感很强，不靠嗓门，靠那股不好惹的气场。你果断、不爱绕弯，定了的事不回头；受不了拖泥带水的人，团队配合上常有摩擦。你性子急又刚，还容易多疑。嘴上不说，心里都有数。","basis":"七杀（命宫）"},{"id":"qisha-事业","star":"七杀","dimension":"事业","palace":"官禄","chars":75,"text":"你的事业靠破和变吃饭。开新局、推改革的地方最能发挥，守着老一套天天重复你受不了。适合往外走、跨行、自己干。一件事多撑一阵，前面的积累才会慢慢显出好处。","basis":"七杀（官禄）"},{"id":"qisha-财运","star":"七杀","dimension":"财运","palace":"财帛","chars":78,"text":"你的钱很少是按月稳稳发的那种。大钱多半在计划外，靠人脉、机会一笔一笔来，来得猛也去得快。挣得多、存得难。进账时先留下一部分本金，本金在，下一次机会才接得住。","basis":"七杀（财帛）"},{"id":"qisha-健康","star":"七杀","dimension":"健康","palace":"疾厄","chars":94,"text":"你的身体跟心情是连着的。心情顺就有劲，情绪压着就先喊累。你偏敏感，长期憋着，睡眠和精神往往最先有反应。吃温的、按点吃，运动挑舒缓的，出点汗情绪也跟着走掉。每年一次体检，就当给身体做个小结。","basis":"七杀（疾厄）"},{"id":"qisha-感情","star":"七杀","dimension":"感情","palace":"夫妻","chars":80,"text":"你直接但不细腻，给的是说到做到的踏实，不是猜心思的温柔。对方要能接住你的急，也得有自己的主意。关心做出来比说出口管用：接一次机、记一个日子，比沉默更让人记得住。","basis":"七杀（夫妻）"},{"id":"wuqu-性格","star":"武曲","dimension":"性格","palace":"命宫","chars":75,"text":"你务实、直接、认结果。不喜欢空谈，事情到你手上就得有交代。说话直了些，偶尔会把人推远一点；你其实心软，只是不习惯表达。开口前慢半拍，话就自然软一点了。","basis":"武曲（命宫）"},{"id":"wuqu-事业","star":"武曲","dimension":"事业","palace":"官禄","chars":91,"text":"你适合跟钱、资源、执行打交道：财务、金融、工程、实业。你靠专业和效率立身，不喜欢应酬场。往上走靠的是把事做成，话说得漂亮倒在其次。有个擅长打交道的人搭把手就更好了。专业越深，路越宽。","basis":"武曲（官禄）"},{"id":"wuqu-财运","star":"武曲","dimension":"财运","palace":"财帛","chars":84,"text":"你对钱敏感，也管得住。收入跟能力和位置挂钩，走的是稳路；敢下手，杠杆不必压得太满。你花钱务实，不太为面子买单，长期拿住看得懂的资产就够了。不必把全部身家押在一次判断上。","basis":"武曲（财帛）"},{"id":"wuqu-健康","star":"武曲","dimension":"健康","palace":"疾厄","chars":81,"text":"你容易把自己当机器用，累了还在硬撑。筋骨、牙齿和作息多留意一点，疼之前就先歇歇。运动挑带力量的，比只做有氧更适合你；每年看看身体。把休息也排进日程，反而跑得更久。","basis":"武曲（疾厄）"},{"id":"wuqu-感情","star":"武曲","dimension":"感情","palace":"夫妻","chars":87,"text":"你表达爱的方式是解决问题，不是甜言蜜语。对方若只想要情绪价值，会觉得你冷。偶尔把在意说出口，比替对方做十件事还让人暖；也要允许对方用自己的方式对你好。两个人都舒服，才走得远。","basis":"武曲（夫妻）"},{"id":"tianji-性格","star":"天机","dimension":"性格","palace":"命宫","chars":97,"text":"你脑子像一台不熄火的机器，别人看你在发呆，里面同时跑着十几条线。上手快、什么都摸得到门道，只是容易样样都浅一点。真正舒服的位置是出主意，不是扛大旗；感情里也容易反复，不是不专一，是总在重新算账。","basis":"天机（命宫）"},{"id":"tianji-事业","star":"天机","dimension":"事业","palace":"官禄","chars":89,"text":"你适合靠脑子和策划吃饭：顾问、技术把关、教育培训、分析研究，环境有温度你效率才高。天天硬碰业绩的地方会有点累。团队里你常提出新角度，但把事从头推到尾不是强项，有人一起落地就更顺。","basis":"天机（官禄）"},{"id":"tianji-财运","star":"天机","dimension":"财运","palace":"财帛","chars":96,"text":"你的钱是慢慢攒出来的，早年数目不大，中年以后才见模样。主要靠薪水和专业，真正的赚钱方式是口碑——一件事做到让人信得过，客人会自己带客人来。钱多半花在让自己舒服的小地方：吃喝、旅行、一点小享受。","basis":"天机（财帛）"},{"id":"tianji-健康","star":"天机","dimension":"健康","palace":"疾厄","chars":93,"text":"你累的时候不是垮，是空。脑子转太久，最先出事的是睡眠和神经，久坐还会把颈椎、腰椎拖出问题。情绪你习惯往心里咽，表面平和，其实一直扛着。作息稳一点，每天留一段什么都不做的空白，会舒服很多。","basis":"天机（疾厄）"},{"id":"tianji-感情","star":"天机","dimension":"感情","palace":"夫妻","chars":83,"text":"你想得多，对方一句平常话你能拆出三层意思。不是不信任，是脑子停不下来。你需要一个说得清、也愿意解释的人，把猜的部分填上；不然容易在心里把整出戏演完，才想起来问问对方。","basis":"天机（夫妻）"},{"id":"taiyang-性格","star":"太阳","dimension":"性格","palace":"命宫","chars":78,"text":"你一进门，房间就亮了。大方、直率、爱表态，陌生人也容易喜欢你。不太习惯一个人待着，一闲下来就想找点事做。被看见会让你更有劲，倒不是爱面子，更像是给自己充电。","basis":"太阳（命宫）"},{"id":"taiyang-事业","star":"太阳","dimension":"事业","palace":"官禄","chars":87,"text":"你的事业靠一张嘴和一身正气：教育、媒体、公职、销售、法律，凡是要说服人、替人争权益的岗位都适合。敢说真话是你的长处，偶尔也会让人接不住。换个私下场合、语气缓一点，路会顺很多。","basis":"太阳（官禄）"},{"id":"taiyang-财运","star":"太阳","dimension":"财运","palace":"财帛","chars":84,"text":"你的钱起伏不小，靠的是名气与表达换来的收入。讲课、咨询、写东西、做方案，把脑子变成钱最自然。赚钱比守钱更拿手，想法一多就分到好几个方向。早年起伏大，四十岁以后才慢慢稳。","basis":"太阳（财帛）"},{"id":"taiyang-健康","star":"太阳","dimension":"健康","palace":"疾厄","chars":89,"text":"你身上有股火气，情绪一起伏，身体立刻有反应：容易上火、睡不安稳，眼睛和心血管要先留意。喝酒和重口味会把这股火拱得更旺。你的健康和心情基本是一回事，心里有气时，早点休息比熬着划算。","basis":"太阳（疾厄）"},{"id":"taiyang-感情","star":"太阳","dimension":"感情","palace":"夫妻","chars":74,"text":"你付出得大方，也容易被自己的热情带着走。你习惯先给，再等对方回应；对方慢一点，你会怀疑是不是不够爱。把需要轻轻说出来，比用更多付出去换一个答案更稳。","basis":"太阳（夫妻）"},{"id":"tiantong-性格","star":"天同","dimension":"性格","palace":"命宫","chars":81,"text":"你最不容易跟人结仇。脾气好、不争抢，跟谁都聊得来，很多事你自己办不成，拉着人一起反倒办成了。少了点非做成不可的劲，舒服久了也会心慌。想主动的时候，不用等别人来推。","basis":"天同（命宫）"},{"id":"tiantong-事业","star":"天同","dimension":"事业","palace":"官禄","chars":96,"text":"你靠脑子和应变吃饭，最发光的不是埋头执行，而是出主意、定方向。公职、内勤、咨询、教育培训、策划都合适。领一份固定薪水、把本事用在判断上，比自己扛风险稳得多。舒服之外，也留一点想往前走的心就好。","basis":"天同（官禄）"},{"id":"tiantong-财运","star":"天同","dimension":"财运","palace":"财帛","chars":79,"text":"你的钱来得平稳，靠积累不靠爆发。你不大会为钱焦虑，也容易花在让自己舒服的地方。工资到账先留一小笔，比等一笔大进项踏实；人缘也是你的财路，多和大家待在一起就好。","basis":"天同（财帛）"},{"id":"tiantong-健康","star":"天同","dimension":"健康","palace":"疾厄","chars":75,"text":"你偏享受型，能躺不坐。体重、血糖、睡眠是三个要盯的点，水肿和消化也常跟着作息走。把散步、早睡这些小事固定下来，身体会安静很多，也不用等体检报告来提醒。","basis":"天同（疾厄）"},{"id":"tiantong-感情","star":"天同","dimension":"感情","palace":"夫妻","chars":82,"text":"你怕冲突，小事都咽下去，久了会冷。你要的是被照顾，也愿意照顾人，但别把照顾变成交换。学会在不满还小的时候就说出来，比憋到最后翻旧账有用。话早点说开，比事后委屈舒服。","basis":"天同（夫妻）"},{"id":"lianzhen-性格","star":"廉贞","dimension":"性格","palace":"命宫","chars":88,"text":"你心里永远比脸上复杂。不是好脾气，是那团火常压着不发。你爱憎分明，喜欢得深，不喜欢也记得久；心思细，一句话能琢磨好久。带点锋芒的路你走着反而顺。把锋芒用在事上，比用在人上更顺。","basis":"廉贞（命宫）"},{"id":"lianzhen-事业","star":"廉贞","dimension":"事业","palace":"官禄","chars":91,"text":"你靠真本事说话，不靠关系也不靠形象。金融财务、工业制造、军警执法、工程管理，或有实权能拍板的位置都合适。你做事不拖，团队推得快，管人时容易偏硬，身边人可能有点压力，话软一点就更顺了。","basis":"廉贞（官禄）"},{"id":"lianzhen-财运","star":"廉贞","dimension":"财运","palace":"财帛","chars":88,"text":"你的钱跟着位置走。工资、头衔带来的收入稳定；投机和快钱不是你的路数。你重面子，买好的、贵的，攒钱偏慢；又容易太信自己的判断，一时兴起的决定，偶尔会多花点冤枉钱。中年以后会宽裕。","basis":"廉贞（财帛）"},{"id":"lianzhen-健康","star":"廉贞","dimension":"健康","palace":"疾厄","chars":82,"text":"你神经敏感，脑子转太久身体先扛不住。最容易出问题的是睡眠：心里压着事就睡不踏实，人累、头也疼。情绪一紧身体跟着紧，硬扛不算本事，该松的时候松下来，把休息也排进日程。","basis":"廉贞（疾厄）"},{"id":"lianzhen-感情","star":"廉贞","dimension":"感情","palace":"夫妻","chars":79,"text":"你爱得深，也记得久。对方的冷淡你能忍，敷衍你忍不了。你要的是势均力敌、能接住你锋芒的人；一旦认定，就很少留退路。把话说开，比在心里反复琢磨舒服；试探不如直说。","basis":"廉贞（夫妻）"},{"id":"taiyin-性格","star":"太阴","dimension":"性格","palace":"命宫","chars":86,"text":"你心思软，体贴得近乎周到。别人忽略的情绪你看得见，随口提过的喜好你记得住。性子偏软，不爱直来直往，更习惯在背后把事默默办完。安静少打扰的时候你状态最好，人多的场合反而耗你。","basis":"太阴（命宫）"},{"id":"taiyin-事业","star":"太阴","dimension":"事业","palace":"官禄","chars":93,"text":"你靠细腻和专业攒口碑，越是做出对别人有用的事越出得来。文化、教育、医疗、咨询、财务都合适。你是稳场面的那个人，乱的时候最清醒；态度偏静，别人不太敢主动靠近；把专业慢慢做深，自然会被看见。","basis":"太阴（官禄）"},{"id":"taiyin-财运","star":"太阴","dimension":"财运","palace":"财帛","chars":90,"text":"你的收入不太能提前算准，机会多来自人脉和曝光，邀约不少但好坏都有，得挑。你花钱大方，请客送礼、维持形象的开销不小。钱通常来得晚，中年以后才真正厚起来。面子上的开销留个度，就更安心。","basis":"太阴（财帛）"},{"id":"taiyin-健康","star":"太阴","dimension":"健康","palace":"疾厄","chars":86,"text":"你底子偏柔，情绪和睡眠是最先响的两处。心思细的人容易把话咽下去，闷气最后落在身体上，变成说不清的酸痛和疲惫。规律作息、少熬夜，比补品管用。把睡觉当成正事，别总排在最后就好。","basis":"太阴（疾厄）"},{"id":"taiyin-感情","star":"太阴","dimension":"感情","palace":"夫妻","chars":86,"text":"你细腻，也慢热。你会用记得对方的小事来表达在意，却很少直接说需要什么。遇上大大咧咧的人，容易觉得委屈；把期待说清楚，你的温柔才不会被当成理所当然。你在意的，让对方知道就好。","basis":"太阴（夫妻）"},{"id":"tanlang-性格","star":"贪狼","dimension":"性格","palace":"命宫","chars":84,"text":"你在哪儿，哪儿就是焦点。嘴上有功夫，人脉天然宽，做生意有别人比不了的起手优势。但热络是面子，里子其实挺硬：认定的事九头牛拉不回。想要的有点多，挑一样认真做，反而更尽兴。","basis":"贪狼（命宫）"},{"id":"tanlang-事业","star":"贪狼","dimension":"事业","palace":"官禄","chars":89,"text":"你适合竞争强、变化快的地方：销售、娱乐、公关、外贸，越是有舞台越有精神。纯文书和行政会把你磨钝。你是团队里的冲锋队长，推得快，不太肯妥协时容易和人较劲，把对方当同行，反而更自在。","basis":"贪狼（官禄）"},{"id":"tanlang-财运","star":"贪狼","dimension":"财运","palace":"财帛","chars":89,"text":"你的钱大起大落。好的时候来得猛，淡的时候也真淡。固定收入跟着事业走，意外之财常在变动里冒出来，抓时机比埋头苦干管用。你赚钱强、守钱弱，心情一好就大手大脚。先留一点再花，会更踏实。","basis":"贪狼（财帛）"},{"id":"tanlang-健康","star":"贪狼","dimension":"健康","palace":"疾厄","chars":82,"text":"你体力好、精力旺，也最容易透支。忙起来不知道停，情绪一上来火也大。用眼多、屏幕前久，眼睛要额外照顾；应酬排太满，抵抗力会掉。该停的时候真的停一天，身体会记得你的好。","basis":"贪狼（疾厄）"},{"id":"tanlang-感情","star":"贪狼","dimension":"感情","palace":"夫妻","chars":92,"text":"你多情，也好奇。容易被新鲜感推着走，真正留下来的，往往是能陪你玩、也能按住你的人。你不是不肯安定，是怕日子变成一潭死水。边界先说清楚，比事后解释轻松；热闹之外，也留一个能说心里话的人。","basis":"贪狼（夫妻）"},{"id":"jumen-性格","star":"巨门","dimension":"性格","palace":"命宫","chars":75,"text":"你说话有条理、想得深，一个问题能想到别人想不到的角度。会问、会想是本事，也容易把一句话在心里放很久。你不是多疑，是看得太细。想过就好，先别急着下结论。","basis":"巨门（命宫）"},{"id":"jumen-事业","star":"巨门","dimension":"事业","palace":"官禄","chars":83,"text":"你靠专业和口才吃饭：法律、教育、传媒、咨询、研究，凡是需要把事情说清楚、辩明白的行当都适合。你能挖出别人漏掉的细节，讨论时不必急着分输赢，把话说清楚，大家反而更服气。","basis":"巨门（官禄）"},{"id":"jumen-财运","star":"巨门","dimension":"财运","palace":"财帛","chars":79,"text":"你的钱跟着专业口碑走，稳但不快。真正的收入来自别人信得过你，愿意为你的判断付费。钱容易在替人担保和闲气上漏掉，合同、承诺写清楚就好；钱和交情分开，彼此都轻松。","basis":"巨门（财帛）"},{"id":"jumen-健康","star":"巨门","dimension":"健康","palace":"疾厄","chars":77,"text":"身体跟着情绪走。你想得多、说得少，嘴上的克制会变成肠胃和睡眠的负担。作息稳定是你最大的保障，熬夜一次要缓好几天。把想不通的事写下来，比在脑子里反复过轻松。","basis":"巨门（疾厄）"},{"id":"jumen-感情","star":"巨门","dimension":"感情","palace":"夫妻","chars":84,"text":"你需要一个能好好说话的人。对方若习惯冷战或含糊，你会自己在心里审半天。把疑问直接问出来，别用试探代替沟通；你要的不是赢，是被听懂。有话直说，对方也不用猜你为什么不高兴。","basis":"巨门（夫妻）"},{"id":"tianxiang-性格","star":"天相","dimension":"性格","palace":"命宫","chars":80,"text":"你放在哪儿都让人放心。稳重、配合度高、爱面子但不张扬。给带头的人当左右手，比自己当头儿舒服；凡是你接下的事都办得妥当。那把是非尺很直，看见不地道的事心里就来气。","basis":"天相（命宫）"},{"id":"tianxiang-事业","star":"天相","dimension":"事业","palace":"官禄","chars":85,"text":"你靠位置吃饭。有头衔、说了算的岗位比在底下做执行更能发挥：行政、秘书、公关、管理层幕僚。你擅长定方向，不爱琐碎细节，需要能干的人替你落地。慢慢往上走，收入也会跟着稳起来。","basis":"天相（官禄）"},{"id":"tianxiang-财运","star":"天相","dimension":"财运","palace":"财帛","chars":89,"text":"你的钱是攒出来的，不是搏出来的。收入靠稳定工作和日积月累，花钱有节制，中年以后会相当充实。漏钱有两处：太保守，好机会不敢上；以及感情和家里的大额开销。该花的时候，也别太为难自己。","basis":"天相（财帛）"},{"id":"tianxiang-健康","star":"天相","dimension":"健康","palace":"疾厄","chars":91,"text":"你底子不错，但容易把事憋在身上。体面惯了，不舒服也先忍着。皮肤、泌尿和睡眠是常被忽略的三处；定期体检，别等小毛病拖成习惯。情绪也要找出口。体检报告看过之后，慢慢改一两个小习惯就够了。","basis":"天相（疾厄）"},{"id":"tianxiang-感情","star":"天相","dimension":"感情","palace":"夫妻","chars":86,"text":"你重体面，也重配合。对方拿得出手、家里说得过去，你才安心。你不擅长表达需求，容易用帮忙代替亲密。偶尔示弱一次，比一直当那个可靠的人更有用。把需要说出口，对方才有机会对你好。","basis":"天相（夫妻）"},{"id":"tianliang-性格","star":"天梁","dimension":"性格","palace":"命宫","chars":88,"text":"你比同龄人显老成，不是长相，是那股沉得住气的劲。为人厚道，心里有一条自己的线，不太愿意将就。天生会照拂人，朋友有事第一个想到你；这份热心偶尔也会让你累，先顾好自己，才帮得长久。","basis":"天梁（命宫）"},{"id":"tianliang-事业","star":"天梁","dimension":"事业","palace":"官禄","chars":89,"text":"你吃的是名声这碗饭，被更多人知道，机会才来。医疗、教育、公职、监察、媒体都合适。你天生会带队、会表达，短板在细节和后台执行，需要有人替你收尾。名声落在专业上，比落在场面上更长久。","basis":"天梁（官禄）"},{"id":"tianliang-财运","star":"天梁","dimension":"财运","palace":"财帛","chars":91,"text":"你的钱是慢慢攒的，来自专业、薪水和跟审美有关的活。房子和不动产是真正的钱袋子，来快去快的投机不是你的路。漏财两处：为家人伴侣的大额付出，和心情一上头做的决定。稳一点，反而更让人安心。","basis":"天梁（财帛）"},{"id":"tianliang-健康","star":"天梁","dimension":"健康","palace":"疾厄","chars":87,"text":"你底子偏结实，但情绪和身体绑得紧。自尊心强的人一受挫，压力全闷在心里，最先扛不住的是睡眠和头部。吃饭按点、七分饱，少酒少油，别一顿撑一顿饿。情绪留个出口，别都往身体里放就好。","basis":"天梁（疾厄）"},{"id":"tianliang-感情","star":"天梁","dimension":"感情","palace":"夫妻","chars":84,"text":"你容易吸引比你年轻、或更需要照顾的人，也享受被需要。照顾是善意，松一点手也还是善意。对方要成长时，松开手比一直扶着更难，也更有用。不用靠照顾绑住谁，也不必拿付出换回报。","basis":"天梁（夫妻）"},{"id":"pojun-性格","star":"破军","dimension":"性格","palace":"命宫","chars":101,"text":"你天生爱拆，不是有恶意，是安不下现状。稳定工作做三年就想换，老流程看一眼就想改。开创上少有人比得过你，守着同一套重复做，会比较难熬。脑子跳得快，中间那几步常常是断的。把想法慢慢收成一条线，就更好落地了。","basis":"破军（命宫）"},{"id":"pojun-事业","star":"破军","dimension":"事业","palace":"官禄","chars":77,"text":"你适合开新局、推改革：创业、技术攻坚、军警、重建类项目。守着一套重复的东西你受不了。一件事做久一点，手上才攒得下真本事；开局的劲，分一点给收尾就更完整了。","basis":"破军（官禄）"},{"id":"pojun-财运","star":"破军","dimension":"财运","palace":"财帛","chars":84,"text":"你的钱来得快去得也快。好的时候一笔大进，差的时候一笔大亏。你敢冒险，所以机会比别人多，也更容易在激进投资上亏掉一大截。先留下一部分再花，本金稳住了，下一次机会才接得住。","basis":"破军（财帛）"},{"id":"pojun-健康","star":"破军","dimension":"健康","palace":"疾厄","chars":79,"text":"你体力好，也最会透支。忙起来不知道停，情绪一上来火气大。消耗型的生活方式会在某天一起找你算账。每年看看身体，把睡眠和运动当成日常里的小约定，身体会陪你久一点。","basis":"破军（疾厄）"},{"id":"pojun-感情","star":"破军","dimension":"感情","palace":"夫妻","chars":82,"text":"你的感情要么很热，要么很烈。你看不上温吞，也受不了被管。真正留住你的是能跟你一起折腾、又稳得住的人。冲动的话留到第二天再说，往往就化开了；热的时候给彼此留一句余地。","basis":"破军（夫妻）"},{"id":"ziwei-大限","star":"紫微","dimension":"大限","palace":"大限","chars":84,"text":"走到紫微的位置，容易被推到台前，责任和曝光一起上来。你容易端着，也容易被期待压住。适合定方向、带团队，不必什么都自己扛，把琐事分出去，这段路会更稳；功劳也让大家一起分。","basis":"紫微（大限）"},{"id":"tianji-大限","star":"天机","dimension":"大限","palace":"大限","chars":87,"text":"走到天机的位置，变动和信息都多，换环境、学新东西的机会会出现。你脑子转得快，容易同时开好几条线；给每件小事留个截止，先做成一件再谈其它；决定下了先跑一阵看看，比反复改更省心。","basis":"天机（大限）"},{"id":"taiyang-大限","star":"太阳","dimension":"大限","palace":"大限","chars":78,"text":"走到太阳的位置，曝光和付出都变多，忙着帮人、忙着证明自己。名声来得快，消耗也快；留一点力气给自己，别让身体和钱包一起透支；该歇就歇，停一下也不会有人忘了你。","basis":"太阳（大限）"},{"id":"wuqu-大限","star":"武曲","dimension":"大限","palace":"大限","chars":75,"text":"走到武曲的位置，跟钱、资源、执行打交道的事会变多，适合把事业做实、把账算清。你容易硬碰硬，赢了事、输了人其实不太划算；账算清，人也留住，比争一口气值。","basis":"武曲（大限）"},{"id":"tiantong-大限","star":"天同","dimension":"大限","palace":"大限","chars":78,"text":"走到天同的位置，节奏会慢下来，适合休整、修复关系、把日子过舒服。舒服过头容易变成拖延；留一件慢慢推进的小事，这段路就不容易空转；舒服是修整，节奏自己定就好。","basis":"天同（大限）"},{"id":"lianzhen-大限","star":"廉贞","dimension":"大限","palace":"大限","chars":77,"text":"走到廉贞的位置，压力和机会一起来的阶段。权力和责任绑在一起，边界不清就容易出事；该拒绝时温和拒绝，要紧的事留个记录；力气用在做事上，比用来证明自己更划算。","basis":"廉贞（大限）"},{"id":"tianfu-大限","star":"天府","dimension":"大限","palace":"大限","chars":73,"text":"走到天府的位置，是守成和积累的阶段，适合扩盘子、稳资产、把家底做厚。太保守容易错过窗口，留一小部分试试新东西就好；家底是拿来做事的，稳着用更安心。","basis":"天府（大限）"},{"id":"taiyin-大限","star":"太阴","dimension":"大限","palace":"大限","chars":75,"text":"走到太阴的位置，是往内收的阶段，适合积累、学习、经营关系。你容易把心事憋着；说出来、写下来，情绪就不用在身体里结账；安静地积累，比热闹地证明更适合你。","basis":"太阴（大限）"},{"id":"tanlang-大限","star":"贪狼","dimension":"大限","palace":"大限","chars":72,"text":"走到贪狼的位置，机会多、应酬多、欲望也多。抓一两件真正想做的做成，比样样都沾一点强；留点边界，热闹就不会变成消耗；挑着去几场，比场场都到更尽兴。","basis":"贪狼（大限）"},{"id":"jumen-大限","star":"巨门","dimension":"大限","palace":"大限","chars":75,"text":"走到巨门的位置，口舌和专业并行的阶段。靠本事立名最稳，靠争辩立威最险；合同、承诺、聊天记录留清楚就稳妥；把话说清楚是本事，说赢不是，力气留给专业更值。","basis":"巨门（大限）"},{"id":"tianxiang-大限","star":"天相","dimension":"大限","palace":"大限","chars":63,"text":"走到天相的位置，是辅佐和稳定的阶段，适合在体系里往上走、把位置坐实。不必只当老好人，该开口时轻轻提一句，做过的事才容易被看见。","basis":"天相（大限）"},{"id":"tianliang-大限","star":"天梁","dimension":"大限","palace":"大限","chars":73,"text":"走到天梁的位置，责任和庇荫一起来，容易被推去担事、当靠山。照顾别人之前先照顾自己，该说不的时候不用硬撑；你不必对所有人负责，放下一些，反而扛得久。","basis":"天梁（大限）"},{"id":"qisha-大限","star":"七杀","dimension":"大限","palace":"大限","chars":74,"text":"走到七杀的位置，是冲刺和变动的阶段，适合开新局、拼命干。冲得太快时别把关系拼没了，留几个能说真话的人；冲时留一分清醒，收时留一分体面，退路自然还在。","basis":"七杀（大限）"},{"id":"pojun-大限","star":"破军","dimension":"大限","palace":"大限","chars":85,"text":"走到破军的位置，是破旧立新的阶段，换工作、换城市、推翻重来都常见。出手前先备好退路，改可以，别把自己也拆了；换之前想想是这里不合适，还是自己待不住，答案不同，走法也不同。","basis":"破军（大限）"}]},"reading/wealth_notes":{"version":"0.1","source":"《图解道教天文历算学·紫微斗数（下·推理卷）》第拾壹章 十四主星坐财帛宫（摘编）","notes":{"紫微":"财路广也稳，常有人帮一把或得家里支持。讲体面、赚得多也花得多，慢慢把收支理顺，信用别撑得太满就好。","天机":"靠脑子和策划挣钱，收入起伏会大一些。把一门技能做深、步子放稳，比追着机会跑更安心。","太阳":"钱来得正、也舍得花，进出都大方。为亲友破费时留个底，靠自己一点点开创，收获最踏实。","武曲":"和钱很有缘，也懂得打理，像矿要慢慢开采才见分量。金融、财政、实业都合适，年岁渐长财路会更稳。","天同":"财路不算紧，偶尔还有意外之喜，花得也随性。文化、教育、餐饮、旅游都合拍，年轻时多攒点，往后就轻省了。","廉贞":"喜欢钱也敢花，机会性的进账有，但不容易留下来。骨子里其实挺稳，不太冒险，拿钱去经营人情反而更值。","天府":"像个小金库，谨慎、会存，日子总能攒下东西。公职或大企业的财经岗位很稳，太大的险不必冒。","太阴":"花钱有分寸、收入也稳，喜欢慢慢置点家业。状态好的时候进账宽裕，费神的时候多给自己留点余地。","贪狼":"机会多、竞争也多，钱来得快去得也快。年轻时起伏大些，往后慢慢稳下来，想要的少一点反而留得住。","巨门":"靠嘴皮子和一门专业吃饭，多半是自食其力、拿稳定薪水。慢慢置点产业会越来越踏实，闲气少生为妙。","天相":"会打理钱，财路不愁，收入多半来自专业服务这类稳妥来源。性子谨慎，一步步自己攒起来的居多。","天梁":"财路不愁，常有长辈照拂，偶尔还有意外进账。心软爱帮人是好事，借钱出去时量力就好。","七杀":"钱要靠自己一关一关挣出来，带点起伏。自己做生意的居多，武职、连锁、制造这类竞争强的行当反而合拍。","破军":"钱跟着开创走，起伏比较大，来去都快。技术创业、不断翻新的路子很适合，守财不是强项就交给稳妥的人搭把手。"}},"reading_bazi/daily_bazi_copy":{"gods":{"比肩":{"shun":"得同道之助，宜结伴同行、合力成事，不宜独力硬扛。","ni":"防同行相争、钱财破耗，与人共事账目宜清。"},"劫财":{"shun":"宜借他人之力成事，与人分利，合则两利。","ni":"防破财与小人劫夺，不轻借贷担保，银钱宜收紧。"},"食神":{"shun":"食禄生香，心气舒泰，宜宴饮、创作、放慢节奏。","ni":"防耽于安逸、拖延误事，先把手头正事办妥。"},"伤官":{"shun":"才思得泄，宜发声、创作、展露所长。","ni":"防口舌是非，出言留三分，莫逞一时之快。"},"正财":{"shun":"正财平稳，宜踏实经营、按部就班求进。","ni":"防无谓破耗，量入为出，银钱之事宜谨慎。"},"偏财":{"shun":"偏财有门，宜随机应变、把握机缘。","ni":"防投机失手，不赌不贪，见好即收。"},"正官":{"shun":"得贵人提携，正途顺遂，宜进取名分地位。","ni":"防压力与是非，恪守规矩，不与上位相抗。"},"七杀":{"shun":"压力可化为动力，宜迎难而上、果断行事。","ni":"防冲突与小人，宜守不宜攻，勿以硬碰硬。"},"正印":{"shun":"得靠山庇护，宜读书求教、静心沉淀。","ni":"防依赖与懈怠，勿坐等他人，凡事亲力亲为。"},"偏印":{"shun":"灵思泉涌，宜钻研、独处，偏门亦可成。","ni":"防思虑过重、疑心自扰，宜放宽心，莫钻牛角尖。"}}},"reading_bazi/geju":{"version":"0.2","note":"白话版：只留判断与理由，不显示出处。","take":{"order":["先看月令。月支里藏着的天干，先看本气；本气没透出来，再看中气、余气里透出来的那一位。","月支被冲坏、又没人救，叫「损坏提纲」，多半不太顺。","月支就是日主的禄，叫建禄格；是日主的帝旺，叫月劫格，这两类另算。"],"note":"日主和财官印的强弱，都先拿月令来衡量。"},"cheng_bai":{"印绶":"印格最怕见财，还偏走财运，再赶上气数走到尽头，容易出大事；有比肩能挡一挡。要是有官星来生印，就是官印两全，是好格局。","正官":"官格怕七杀、怕伤官、怕刑冲破害；这几样再跟岁运一起来，那点贵气就散光了。它要的是身旺、有印护着、有财来生官。","正财":"财格怕比肩来分、怕劫财羊刃；再碰上岁运一冲一合，格局就破了。有官杀护着财，或者用食伤把比劫化掉，能解。","偏财":"偏财怕比劫来分、怕落空亡；有官星护着，比劫就不敢动。财轻的，等旺运再说；财重的，得身强，还得有官杀守着财。","伤官":"伤官格怕财旺而身弱、怕官杀一层层压、怕混杂又冲刃；岁运再来，这一段就不好过。它要的是身旺、有财、有印——也就是伤官配印。","七杀":"七杀要身旺、要有人管得住它、要合得住它、要羊刃相配；怕身弱、怕财来生它、怕一点约束都没有。可管得太死，也不成。","食神":"食神要身旺、要有财；最怕印星来夺食，也怕身弱。食神一个就够，是福气；多了反而不清。","羊刃":"羊刃喜欢配偏财、配七杀；怕伤官，也怕再走刃旺的运，最怕又合又冲。","从格":"从格是顺着势头走：顺着的那一边越旺越好，日主越弱越好。最怕日主忽然有了根，从不成，反倒出事。","建禄":"月支是日主的禄，就不另外取格了；看透出什么、全局怎么配，仍然以月令为主。","月劫":"月支是日主的帝旺，喜欢七杀来制、喜欢偏财；怕伤官，也怕再走刃旺的运。"},"commentary_note":"看命以用神和全局配合为准，不拿神煞断生死。"},"reading_bazi/gods":{"version":"0.2","note":"白话版：只留判断与理由，不显示出处。","gods":{"正官":{"nature":"正官是管着日主、但阴阳相配的那一位，代表名分、规矩和责任。","traits":"命里正官有力，人一般端正、守规矩、有担当，容易走上正式职位。","xi":["身旺","印星护着","财星来生官"],"ji":["被刑冲破害","伤官来伤","官杀混杂","官星太多"],"key":"正官要有身旺、有印护着才容易发福；走到伤官的运上，官星受伤，贵气就掉了。官星太多会杂乱，要清一清才好。"},"七杀":{"nature":"七杀是同类相克、不留情面的那一位，也叫偏官。有东西管住它叫偏官，管不住就叫七杀。","traits":"七杀重的人有压力也有魄力，压得住就成大事，压不住就多险、多劳心。","xi":["身旺","食伤制住它","印星化掉它","羊刃相配"],"ji":["身弱","财星生它","一点制伏都没有","制得太死"],"key":"身强杀轻，走财杀运反而能扬威；身弱杀重，要靠比劫帮身、食伤制杀，用印化杀最稳。制得太狠，杀气全失，也成不了事。"},"正印":{"nature":"正印是生养日主、阴阳相配的那一位，代表庇护、学识和信用。","traits":"印星得地的人多半少病、安稳，容易得到长辈和家里的照应。","xi":["官星来生印","走生旺之地"],"ji":["财星旺来破印","走到死绝之地","印星太多"],"key":"有官无印不算真官，有印无官反倒有福。印怕财，走财运伤了印，容易破家、离乡。印太多也不行，容易把官杀之气泄光，反成拖累。"},"偏印":{"nature":"偏印也是生日的，只是阴阳不配，又叫倒食、枭神。它天生克食神。","traits":"偏印重的人偏门学问、直觉和专注力强，但容易孤僻多虑。","xi":["财星压住枭","官杀化解","身弱得生"],"ji":["用食神时遇到枭","枭和食并见又没有财"],"key":"食神是财的根，枭神一克，财就没了根，所以靠食神吃饭、靠财过日子的人，都怕这一下倒食。不过要是有财星压住枭、护住食神，反倒是好格局。"},"正财":{"nature":"正财是日主克得住、阴阳相配的那一位，代表稳定的收入和持家。","traits":"正财旺的人务实、能守成，财旺还能生官，名利双全的不少。","xi":["身旺能任财","印星生身","食伤生财","官星护财"],"ji":["身弱扛不住财","比肩劫财来夺","偏印夺食","财多没有约束"],"key":"身弱财又旺，钱再多也守不住，反成拖累。身旺、财也旺，才叫称心。用财最怕比劫来抢，有官星护着最好。"},"偏财":{"nature":"偏财是日主克得住、但阴阳不配的那一位，是流动的、大家都能碰的财。","traits":"偏财旺的人大方、会交际，机会多；得地的话容易富。","xi":["官星护财","身强","财轻时走财运"],"ji":["比劫来分","落空亡","身弱财重","财多没有官"],"key":"偏财最怕兄弟姐妹来分，有官星在，比劫就不敢抢。财轻的时候等旺运再发，财重的时候要身强、要官杀护着。"},"食神":{"nature":"食神是日主生出去、阴阳相同的那一位。它泄日主的气，但能生财，是财的根，所以算吉神。","traits":"食神好的人有口福、心宽、有才艺，也主有寿、有子女缘。","xi":["身旺","财星","食神生财"],"ji":["印星夺食","身弱","食神太多"],"key":"食神一个就够，是福气；多了反而不清。它要身旺，怕的是印星来夺食。身旺再用食神去生财，是正路，容易富。"},"伤官":{"nature":"伤官是日主生出去、阴阳相配的那一位，专门伤官星，所以叫伤官。","traits":"伤官旺的人聪明、有才气、爱表现，但也容易傲气、讲话不留情。","xi":["伤尽（局里不见官星）","身旺","财星","印星（伤官佩印）"],"ji":["见官星","没有财","身弱"],"key":"伤官最好伤得彻底；伤不尽又有官星来，麻烦就大。身旺伤旺有财，是富贵路；伤官配印也是大格。见官但有财化解，灾就轻。"},"劫财":{"nature":"劫财是同类相夺的那一位，讲白了就是抢。","traits":"劫财重的人行动力强、会周旋，但容易破财、被人拖累。","xi":["身弱时来帮身","官杀管住它"],"ji":["身旺再遇劫财","财透出来又没人护"],"key":"钱是人人都想要的，兄弟朋友见了容易争。身旺再见劫财，多半要破财，得靠官杀管着、或食伤化解。"},"比肩":{"nature":"比肩是同类同阴阳的那一位，代表自立和同辈。","traits":"比肩旺的人主意正、能自立，但容易固执；弱的时候帮不上什么忙。","xi":["身弱得帮","官杀有制"],"ji":["身旺再加比肩","和财星并见容易夺财"],"key":"比肩和比劫一样是同类，命里多了就是争。身弱靠它帮身，身旺它就是累赘。"},"羊刃":{"nature":"羊刃是月令走到帝旺的那一位，旺到极点就会转衰，像羊站在刀刃上。","traits":"羊刃虽是凶神，但有刃的人不少反而富贵；配上七杀成杀刃格，更不是普通人。","xi":["偏财","七杀","官杀制刃"],"ji":["伤官","再走刃旺的运","被冲被合"],"key":"杀没有刃不显威，刃没有杀不成器。刃强杀轻走官杀运能发，杀强刃轻走刃比运能发；杀刃都强时再走印运，反而坏事。"}}},"reading_bazi/houjue":{"note":"据《子平汇刊》本《渊海子平》卷四「十二月候诗诀」整理，每月数条，诗诀存原句，白话为改写。","yao":"这组诗诀按月令讲用神往哪边走顺、往哪边走滞，要跟下面的调候表配合着看：调候管的是寒暖燥湿，诗诀管的是这个月生的人，往哪个方位、哪一步运上比较顺手。","months":{"寅":[{"ju":"正月寅宫原是木，木生火旺土长生；戊兼午未宫中喜，申酉休囚数莫行","hua":"正月是木管事，木能生火，火一旺土就跟着起来。戊土生在这个月，走午、未这种火土旺的地方顺手；走到申、酉，金气当令，土被泄掉，就有点走不动。"},{"ju":"寅月重逢午戌该，庚辛为主两推排；有根有土偏宜火，身弱休囚怕火来","hua":"正月里又见午、戌，火就合成一片，这时候要拿庚辛金来参照。庚辛有根、又有土生，不怕再走火；本身弱、又没根，火再来就顶不住。"},{"ju":"如有寅宫木火神，南方午未禄财欣；逆行戌亥还当旺，破损忧愁见酉申","hua":"正月生的人，八字里木火成气，走南方午未这一段财路顺；往回走戌亥也不算弱；最怕见酉申，金一来就把木火的路截断了。"},{"ju":"庚辛主弱逢寅月，午戌加临会杀星；日主无根还透土，逆行金水福兴隆","hua":"庚辛金生在正月本来就弱，再见午戌，等于把火杀招来了。日主要是没根、天干却透出土来护，往金水方向走反倒能起来。"},{"ju":"己戊身衰喜见寅，重重官杀必荣身；只求木火相生吉，运到西方怕酉申","hua":"己土戊土身弱的人，生在正月反倒是好事：官杀一层层压过来，压力能变成动力，人容易出头。只要木火能接上就顺；走到西方见酉申，金来克木，就不太妙。"}],"卯":[{"ju":"丙丁二月身逢印，大怕庚辛酉丑伤；水运敛荣木火旺，西方行运定遭殃","hua":"丙丁火生在二月，木来生火，是得印的路子。最怕庚辛和酉丑来伤这个印。走水运是把气收住，走木火是往上旺；一到西方，印被砍断，这一段就容易出岔子。"},{"ju":"甲日卯月重逢丑，格中有火不须嫌；再行火土兴财禄，岁运宜金怕水缠","hua":"甲木生在二月又见丑，只要八字里有火，就不用嫌丑土拖累。再走火土能把财路带起来；岁运上金还可以，水太多就缠住了。"},{"ju":"木正荣于卯月中，若将为用喜生逢；北方亥子成名利，午未行来坐福浓","hua":"二月正是木最旺的时候，木如果对你有用，就喜欢再有人来生它。走北方亥子能成名得利，走午未福气厚。"},{"ju":"卯宫大怕逢金降，火旺根深制伏强；四柱有金嫌巳丑，运来酉上定须伤","hua":"二月这个位置最怕金来压。得火旺、根扎得深，才压得住金。八字里本来就有金，再碰上巳丑合成金局更麻烦；运走到酉，金气最盛，这一段要留神。"},{"ju":"己卯日元二三月，杀生有露火偏奇；只宜木火重迎见，金水行来命必亏","hua":"己卯日生在二三月，杀有东西管着、火又透出来，这种搭配少见但好用。适合再见木火；走金水就一路往下。"},{"ju":"庚辛卯月多逢木，日主无根怕旺财；南北两头防有破，如逢申酉祸难来","hua":"庚辛金生在二月，木太多。日主自己没根，最怕财旺身弱扛不住。南北两头都要防着破口；走到申酉，卯酉一冲，月令被冲开，麻烦就跟着来。"},{"ju":"癸日无根卯月逢，局中有火反成功；如行身旺多财富，若至官乡数必终","hua":"癸水没根却生在二月，八字里有火反而能成事——木火把水泄出去，正好成了财路。走身旺的运，财就多；到了官杀那一段，压力一上来，这条路就走不下去。"}],"辰":[{"ju":"三月辰宫只论土，杀多金水化为祥；提纲若用财官印，金水相临命有伤","hua":"三月辰这个位置，主要按土论。杀多的时候，有金水来化，反而是好事。可要是月令上取的是财官印，金水再压过来，就把这条路伤了。"},{"ju":"戊土无根日坐寅，重重水旺福源深；如行木火宫中吉，金水相逢祸必侵","hua":"戊土自己没根、日支坐寅，水一层层旺起来，福反倒深——土能挡水，成了用处。走木火这一段顺；金水一起来，就顶不住了。"},{"ju":"三月干头只用金，火生土厚福还真；身为壬癸多逢土，火旺提防祸必临","hua":"三月天干上只取金来用，火生土、土又厚，福是实的。可要是日主是壬癸水、八字里土又多，火一旺土更厚，水被克得更狠，这一段要提防。"}],"巳":[{"ju":"甲乙如临四月天，水乡木旺振财源；北方火地多凶破，酉又相逢祸便言","hua":"甲乙木生在四月，木气已经泄得差不多。走水乡把木养回来，财路就能振作；往火旺的地方去，多半是破耗；再碰上酉，金来克木，就更麻烦。"},{"ju":"四月干头水土逢，水乡木旺禄还通；如行金水多成败，更怕提纲物对冲","hua":"四月天干上见水见土，走水乡把木养旺，禄路是通的。走金水这一段成成败败都有；最怕月令被冲着——提纲一破，根基就动。"},{"ju":"金水干头四月胎，土为印绶火为财；身强土厚宜金土，日主轻浮怕水来","hua":"天干是金水、生在四月，这叫「胎」。土在这儿是印，火是财。身强、土又厚的，走金土都合适；日主虚浮没根，就怕水再来漂。"},{"ju":"壬日巳月多火土，无根无印怕财乡；须行申酉是名利，逆走东南寿不长","hua":"壬水生在四月，火土正旺。既没根又没印，最怕再走财旺的地方——财多身弱，扛不住。得走申酉把水养住，名利才起得来；反过来往东南火旺处走，消耗太大，身体先吃不消。"},{"ju":"四月金生火土旺，三般神用要分明；财官印绶藏宫内，运看高低仔细寻","hua":"四月金被生出来，可火土也旺。财、官、印这三样，哪一个真能用，得分清楚。它们藏在哪一柱里，走到哪一步运是帮它还是伤它，得一步步细看。"}],"午":[{"ju":"五月宫中火正荣，高低贵贱两分明；财官印用宜生旺，化杀欣逢要水平","hua":"五月火最旺，格局高低在这一段最容易看出来。财官印这几样拿来做用，都希望它生旺；要用它化杀，就得有水来把火压平。"},{"ju":"五月炎炎则论火，如逢木火自然兴；西方金木多防克，丑土周还怕子迎","hua":"五月天热，主要论火。八字里再有木火，自然就往旺里走。走到西方，金木之间容易相克，要防；碰上丑土绕回来，又怕子水来迎——子丑一合，局面就变了。"},{"ju":"午宫怕子水来冲，用火逢冲数必凶；日主庚辛如会杀，运中逢此反成功","hua":"午这个位置怕子水来冲。拿火当用神的，一冲就散，这一段不好过。可要是日主是庚辛金、八字里又带着杀，走到这儿反倒能成事——冲开了才有转机。"},{"ju":"财官印绶如藏午，西北休临申子辰；木火土乡还富贵，休来水土更嫌金","hua":"财官印藏在午里，往西北申子辰那一片就别去了。走木火土还能富贵；水土不必来，金更不讨巧。"}],"未":[{"ju":"丙丁日坐未宫逢，金水虽凶未必凶；木库水乡应富贵，再行申酉祸灾重","hua":"丙丁火日主坐未，看着金水是凶，其实未必。未是木库，能接上水乡，反倒应富贵；可再走到申酉，金气一起来，麻烦就重了。"},{"ju":"未月支藏木火时，不逢顺逆格高低；南方行去东方旺，酉位休愁戌亥亏","hua":"未月地支里藏着木火，不论顺行逆行，格局都有高低可分。往南、往东都旺；到酉不必发愁，真正吃亏的是戌亥那一段。"}],"申":[{"ju":"印绶财官月建申，北方回喜福还真；火金生旺多清贵，大限行来最怕寅","hua":"月令在申，八字里又见印绶财官，往北方走反倒得福。火金生旺的多半清贵；大限走到寅，寅申一冲，月令被冲，这一段最要小心。"},{"ju":"建禄庚辛旺在申，有官有印有财星；逆行辰巳荣财禄，北地须知富贵成","hua":"庚辛金在申是建禄，本身就旺。再配上官、印、财，逆行到辰巳能把财禄做起来，往北方走富贵可成。"},{"ju":"壬癸生临七八月，火土多厚北方奇；无伤无破休行水，帝旺临官运不宜","hua":"壬癸水生七八月，金气正旺生水。火土厚的人往北方走反而出彩；八字本来就没什么伤破，就不必再往水里走——帝旺、临官那几步，水太过了反而不合适。"}],"酉":[{"ju":"甲乙无根八月逢，庚辛金旺不嫌凶；北方水运财星足，逆走南方得失中","hua":"甲乙木没根却生在八月，金旺本来克身，可只要有水通关，就不算凶。走北方水运财星足；反过来往南方走，得失参半。"},{"ju":"酉月藏金乙日逢，北方亥子水重重；离明午未财权重，巳丑加临寿必终","hua":"乙日生在酉月，金气藏得深。往北方亥子走，水一层层厚起来；到午未火明之处，财的份量重；再到巳丑跟酉合成金局，金太过了，这一段身体上要多留心。"},{"ju":"甲乙酉月多官杀，无根日主一生低；北逢顺走休临丑，逆走南方巳上亏","hua":"甲乙木生在八月，官杀太多。日主自己没根，一生都容易被压着。顺走北方，别到丑；逆走南方，到巳就吃亏——巳酉丑又要合金。"},{"ju":"丁生酉月天干癸，去杀方能可去财；有气保身存印绶，无情行到水中来","hua":"丁火生在酉月、天干见癸，得先把杀处理掉，才谈得上取财。能保住身的是印绶；要是无情，走到水旺的地方就陷进去了。"},{"ju":"秋金酉丑重金旺，除非火炼有声明；东方行去盈财禄，西北来临福必倾","hua":"秋金在酉丑，金重得很。除非有火来炼，才出得了名声。走东方能把财禄做盈；一到西北，金水一起来，福就往下泄。"}],"戌":[{"ju":"九月戌中藏火土，庚辛不忌日无根；格中若有财官印，运到南方福禄亨","hua":"九月戌里藏着火土，庚辛金就算自己没根，也不用太忌讳——土能生金。格局里要是有财官印，走到南方火地，福禄是通的。"},{"ju":"甲乙秋木九月生，木衰金旺怕庚辛；如临水火兴家计，金水才来祸便行","hua":"甲乙木生在九月，木已经衰了、金正旺，最怕庚辛再压。要是有水来通关、有火来制金，家业反倒能兴；可金水一起来，木就没了活路。"},{"ju":"财官印绶九月临，发旺升腾见卯寅；顺去北方行子丑，逆行嫌酉破逢申","hua":"财官印落在九月，见卯寅就能发起来。顺行往北方子丑走；逆行就怕酉来破、申来冲。"},{"ju":"戌月金生藏火土，或行南北或行东；不分顺逆高低格，大运辰逢寿必终","hua":"九月金被生出来、里头又藏着火土，往南往北往东都走得通。不论顺逆、格局高低，大运走到辰，辰戌一冲把月令冲开，这一段身体上要多留意。"},{"ju":"壬日无根戊己多，生于九月忌财过；逆行休用南方午，寅若如逢奈若何","hua":"壬水没根、八字里戊己土又多，生在九月最忌财太重——土多就是财多，身弱扛不住。逆行就别往南方午去；要是再碰上寅，寅午一合火，更难办。"},{"ju":"丙丁无主戌中旬，财透天干作用神；此格伤官杀喜旺，只愁身旺尽伤官","hua":"丙丁火生在九月中旬，天干透出财来当用神。这是伤官格，杀旺一点反倒好；只怕身太旺，把伤官用尽了，气全泄光反倒成空。"}],"亥":[{"ju":"水木生居亥月乾，财官印绶喜相连；用壬运旺西方去，用木须欣寅卯逢","hua":"水木生在十月，财官印连着来是好事。拿壬水当用的，走西方金地能把水养旺；拿木当用的，喜欢见寅卯。"},{"ju":"丙日壬杀喜东南，来至东南发显官；大运愁逢金水地，再行西兑寿难完","hua":"丙火日主拿壬水当杀，喜欢东南——木火之地能化杀。到了东南官就显；大运走到金水地，杀被生得更旺，再往西兑走，身体上就吃力了。"},{"ju":"财官印绶立乾宫，水木相生福禄通；阳水喜金嫌火土，运行最怕巳相冲","hua":"财官印落在亥（乾位），水木相生，福禄是通的。阳水喜欢金，不喜欢火土；运上最怕巳来冲——巳亥一冲，这个位置就动了。"},{"ju":"日主无根干土金，月通亥子土来侵；只宜印绶扶身旺，何怕提纲损用神","hua":"日主没根、天干却是土金，月令又通亥子，土还来侵。这时候只适合用印绶把身扶起来；身一旺，就不怕月令被损、用神被动。"}],"子":[{"ju":"丙丁日主月逢子，支下存申时又辰；火土旺乡成富贵，再行金水祸难禁","hua":"丙丁火生在十一月，地支里又有申、时上带辰，申子辰合成水局。走火土旺的地方能成富贵；再往金水走，水太盛，火就压不住了。"},{"ju":"子宫有水金乡旺，见土休囚忌破支；元有土离逢水贵，午来冲对寿元衰","hua":"子这个位置有水，金在那儿正旺；见土反而被泄得没力，还怕地支被冲破。本来带土的人，离开土去就水，反倒能贵；可午来一冲，这一段身体就往下走。"},{"ju":"庚金遇子多强吉，火土相嫌未必凶；运去元辰翻作贵，再行午运福重重","hua":"庚金遇子，多半是强而吉的；跟火土不对付，但未必就凶。运走过这一段反倒能贵；再走到午，福气一层层叠上来。"},{"ju":"庚日逢寅午戌行，日通火局是提纲；如行金水翻成富，火土重来福怎当","hua":"庚日碰上寅午戌，日支通火局，这就成了提纲。走金水反倒能富；火土再重来一遍，福就顶不住了。"},{"ju":"水归冬旺乐无忧，透用财官富九州；顺逆不分还富贵，提纲刑克事休休","hua":"水到冬天正旺，本来无忧。财官透出来当用，富气能铺得很开。顺逆怎么走都还行；可月令一被刑克，事情就停摆了。"}],"丑":[{"ju":"甲子生居丑月中，无根金水不嫌凶；再行金水声名显，火土相逢破本宗","hua":"甲子日生在十二月，自己没根，见金水也不算凶。再走金水反倒名声显；碰上火土，就把本来的格局破了。"},{"ju":"丙丁坐火财中杀，四柱无根忌水乡；运到火乡加福助，须知显振名利香","hua":"丙丁火坐火上，财里带着杀。四柱没根的最忌水乡；运走到火地，助力一来，名利就能振起来。"},{"ju":"庚辛丑月中藏印，火土来临福禄齐；壬癸天干或透出，如逢戊己言相生","hua":"庚辛金生在丑月，丑里藏着印。火土一来，福禄就齐了。天干要是透出壬癸，再逢戊己，那是相生——土生金、金生水，气是接得上的。"},{"ju":"壬癸生居丑月提，有金有土格中奇；顺行辰巳兴财禄，逆去升腾申酉支","hua":"壬癸水生丑月，八字里又有金又有土，这种格局少见。顺行到辰巳能把财禄做起来，逆行到申酉也能往上走。"},{"ju":"戊土生居十二月，伤官财旺藏时节；水清金白助格中，若逢火土多周折","hua":"戊土生在十二月，伤官和财旺，都藏在时令里。水清金白，是来帮这个格的；碰上火土，就多绕几道弯。"},{"ju":"己干提丑支金局，杀旺身强格局高；金水重来名利厚，水乡火地不坚牢","hua":"己土提丑、地支又成金局，杀旺而身也强，格局就高。金水再来，名利更厚；可水乡火地这两头，根基都不牢。"},{"ju":"丙日多根丑局逢，财官藏在月提中；水乡在旺金乡吉，土困行南总是空","hua":"丙日自己根多、又碰上丑局，财官都藏在月令里。水乡当旺、金乡也吉；要是被土困住，再往南走也是空的。"},{"ju":"戊己生居丑月中，忽逢羊刃在天宫；金多有水方成贵，火土虽嫌比劫同","hua":"戊己土生在丑月，天干上忽然见羊刃。金多、又有水，才成得了贵；火土虽然不太对路，可跟比劫是一路的，算不上坏事。"}]}},"reading_bazi/huotao":{"note":"据《子平汇刊》本《渊海子平》卷六「批命活套」整理（此卷世传诸本多无，据钦天监戈先生校定本补入）。原为七言套语，多科举富贵口气，此处只取结构与断法，改写成白话；原诗见 zphk_ocr.txt p229–268。","yao":"活套是旧时批命的骨架：先相貌、次父母、次兄弟、次婚姻、次子息、次行运、末寿元；同一句式按命换成吉凶两套，故叫「活套」。今日只借它的叙述顺序与分寸，不照搬套语。","jiegou":["起手：赞相貌才器，定一句格局基调","父母：双全、父在母亡、母在父亡、俱亡，四套任选","兄弟：和睦共居或分飞各自","婚姻：贤配、偏正、迟婚、刑妻（丧妻/离异）四类","子息：早得、迟得、过继、损子","行运：先述初运辛苦，再中运发财官，晚运归安","收尾：寿元与五福"],"ge":{"正官":{"ju":"正官之格喜清纯，不带冲伤不带刑；印旺资身为贵取，财多扶本富堪称","hua":"正官格最讲究一个「清」字：不杂、不挨冲刑。印旺能把身扶起来，走的是名声那条路；财多能生官，走的是实惠那条路。旧时批这类命，起手先夸家风清白、诗书传家，收尾落在财印这两步运上。"},"偏官":{"ju":"七杀当权蕴月支，惟宜身旺可胜之；官星不紊纯而贵，印旺扶元是福基","hua":"七杀在月支上管事，得身旺才扛得住。官杀不混，气就纯，格局也清；印旺能把身扶住，是福的根。这种人大多性子刚、敢冲，肯干事。"},"印绶":{"ju":"贵造清纯印绶逢，财藏官露是豪雄","hua":"印绶清纯、财藏着、官露着，旧说这是「豪雄」的路子。人偏温和、守规矩，做事讲老理。"},"杀印":{"ju":"杀印棱棱格局清，日干秉令向春生；蛟龙岂是池中物，一遇风云即奋身","hua":"杀和印互相生，格局就清；日干又当令，底气足。这种人像蛟龙不在池子里待着，时机一到就起来。性子硬，气量也大，肯给人。"},"正财":{"ju":"富造生于乔木家，正财之格实堪夸；比劫不来真空遇，日干兴旺享太华","hua":"正财格怕比劫来抢，日干旺才守得住。家底一般厚实，人守本分；不图做大官，图的是田园日子的安稳。"},"偏财":{"ju":"月令偏财一点清，又逢印绶与官星","hua":"偏财清、又带着印和官，是有本事的人。喜欢跟明白人来往，讲礼、肯帮人；适合读书求名，中晚年能成。"},"伤官":{"ju":"此格伤官杀喜旺，只愁身旺尽伤官","hua":"伤官格喜欢见七杀，怕的是身太旺、把气全泄成伤官。人聪明，藏不住；最好有东西管着、有东西化着。"},"杂气财官":{"ju":"杂气财官格，最要刑冲开库","hua":"杂气财官藏在辰戌丑未这四个库里，得靠刑冲把库打开才发得出来；库不开，财官就闷在里头。"}},"gui":[{"name":"批殿元显宦","yong":"状元之命，榜首题名"},{"name":"批宦相斯文","yong":"二品之贵，文臣"},{"name":"批天资国器","yong":"三品之贵，栋梁之材"},{"name":"批及第登高","yong":"进士及第"},{"name":"批月窟重光","yong":"大夫之贵"},{"name":"批浪起春雷","yong":"秀才之命"},{"name":"批鱼龙养起","yong":"蓝生（监生）之命"},{"name":"批桃浪进身","yong":"童生之命"},{"name":"批虎榜标名","yong":"生员（秀才）之命"},{"name":"批志合冲天","yong":"武举之命"},{"name":"批香拂桂林","yong":"有贵器者"},{"name":"批人间岳惊","yong":"异路成名"},{"name":"批富产祥麟","yong":"富命"},{"name":"批蚌产明珠","yong":"老来得子"},{"name":"批祥开后院","yong":"求子得子"},{"name":"批玉树流芳","yong":"遗腹子"}],"liuqin":[{"name":"父母双全","hua":"椿萱并茂（父如灵椿、母如萱草），双亲同享高寿，福禄绵长。"},{"name":"父母俱亡","hua":"椿萱早谢：双亲去得早，留下的子孙自会有一份出息。"},{"name":"母在父亡","hua":"灵椿雪压、萱草晚坚：父亲早逝，母亲独自守着家，一边纺线一边教子。"},{"name":"父在母亡","hua":"萱草先萎、椿树独高：母亲早逝，父亲还在，孩子少了那份细密的照应。"},{"name":"兄弟和睦","hua":"棠棣连枝、荆花同气：兄弟几个和乐同住，家声一起撑起来。"},{"name":"兄弟分飞","hua":"鸿雁分飞、荆树折枝：兄弟缘分薄，各自成家，中晚年聚少离多。"},{"name":"夫妇谐和","hua":"鸾凤和鸣、琴瑟谐和：得一个贤内助，子女也养得成行，白头相守。"},{"name":"难为妻子","hua":"琴瑟断弦可续、桂花先放遇风：头一段婚姻难到头，中途有变，后来还会有伴。"},{"name":"刑妻","hua":"炊臼无釜、镜破难圆：中年失妻或离异，多半在某一步运上应；家里那个主内的人走了。"}],"yun":[{"ju":"批八字行运造化诗","hua":"按初运、中运、晚运三段批：初运多述庇荫与辛苦，中运述财官发越，晚运述安享与寿元。"},{"ju":"讲谈批命鹧鸪天","hua":"以词牌句式作批语，一句一层：相貌、家世、婚姻、子女、行运、晚景。"},{"ju":"讲谈难为六亲诗句","hua":"专为六亲缘薄、刑克、离乱者备的句子，用时须看实际六亲宫位与喜忌，不可套用。"}],"mark":"活套原文属明清批命行业套语，含科举功名、男尊女卑等时代内容；现代只作结构与措辞参考。","shi":[{"sec":"批命活用总套","ju":"世际雍熙泰运开，玉麟应瑞降凡来。异时敏达成名早，首占春鳌榜上魁","hua":"总套起手：先许家世太平、儿孙出众，再说小时候就聪明、科举能占头名","yong":"批命开篇第一首，用在正文之前作引子；现代只取「先许家声、再叙本人」的次序"},{"sec":"批命活用总套","ju":"相貌堂堂荆璞玉，贤能卓立栋梁材。褆有恩沾福泽，雁鸿作队向云排","hua":"接着赞相貌气度：如未经雕琢的璞玉，才具可作栋梁；再写父母恩泽、兄弟成行","yong":"叙相貌与兄弟段"},{"sec":"批命活用总套","ju":"御沟红叶题诗早，凤友鸾交百岁谐","hua":"末写婚姻：红叶题诗的巧缘，夫妻如鸾凤和鸣到老","yong":"叙婚姻段收尾"},{"sec":"批命活用总套","ju":"丹桂燕山堪并秀，义方垂训乐成材。童蒙学而为政，恰如嫩菊傲霜开","hua":"第二首写家教：如窦燕山五子并秀，父母以义方教子；孩子读书早慧，如嫩菊耐霜","yong":"父母有教养、子女早慧之命"},{"sec":"批命活用总套","ju":"三四逢关须与保，只宜调理免伤怀","hua":"旧说三四岁有关煞，宜小心调养，不必忧","yong":"小儿关煞段，纯属旧说，现代只作提醒"},{"sec":"批命活用总套","ju":"豹贪玄雾隐南山，养就周身一点斑。敏达才华诚浩大，汪洋德量自洪宽","hua":"第三首写隐逸型：如豹隐南山，才华浩大、度量宽宏，不慕红尘，耕云钓月","yong":"志向清高、不求名利之命"},{"sec":"批命活用总套","ju":"萱花不幸经霜萎，椿树根深赋完。鱼水合欢分正副，琴瑟和乐咏关雎","hua":"母亲早逝、父亲健在；妻有正副之分，琴瑟和乐","yong":"母亡父在、有正妻偏房之命（旧制语）"},{"sec":"批命活用总套","ju":"桃李春寒花未结，若耶莲吐一枝蕃","hua":"子女如春寒桃李迟迟不结，后来才开出一枝","yong":"子息迟得"},{"sec":"批命活用总套","ju":"运限时今俱利坦，顺水清风挂锦帆。二七五五并三九，忽觉春风动考","hua":"行运顺利如顺水挂帆；到二七、五五、三九这些岁数上忽有变动（旧批以生数推年岁）","yong":"行运段：先顺后有一动"},{"sec":"批命活用总套","ju":"有福伤财而保己，免令月缺与花残","hua":"有福之人以破财免灾，破了财反保住了人身与家门","yong":"原书批语里很重要的一句：破财挡灾"},{"sec":"批命活用总套","ju":"峥嵘做出人头地，顺水行舟发不停。庭砌紫荆香郁郁，行边月桂笑欣欣","hua":"第四首写中晚年：出头、发财不停，兄弟和睦、子孙争气","yong":"中年以后发迹之命"},{"sec":"批命活用总套","ju":"天命交来前后地，马跳檀溪有一惊。幸赖五星多吉曜，惟凋树叶不伤根","hua":"五十岁前后有一惊，如刘备马跳檀溪，幸有吉星相护，只伤枝叶不动根本","yong":"中年一险；页面用时可换成「某年有一惊无险」"},{"sec":"批命活用总套","ju":"桑榆十载行佳运，福禄攸钟寿愈增。香山九老堪为伴，笑睹蟠桃几度新","hua":"晚年十年好运，福禄寿都增，如香山九老聚乐","yong":"晚运段"},{"sec":"讲谈批贵命杂用诗诀","ju":"龙逢凤沼辰居酉，三奇拱贵必超群。万里平途驰骏马，一江活水化鱼龙","hua":"三奇拱贵之格：如龙逢凤沼，前程万里，鱼化为龙","yong":"贵格起手句"},{"sec":"讲谈批贵命杂用诗诀","ju":"虎近端门威四海，巳寅生秀夺乾坤。名驹已出升平世，英物还生礼义人","hua":"巳寅生秀、威震四方；盛世出名驹，礼义之家出英物","yong":"贵格 + 家教"},{"sec":"讲谈批贵命杂用诗诀","ju":"局正格清台阁相，云龙风虎擢高科。笔下文章星斗灿，胸中志气动乾坤","hua":"格局清正者可为台阁之相；文章灿烂、志气撼人，科举高中","yong":"文贵、科第"},{"sec":"讲谈批贵命杂用诗诀","ju":"双门拱夹鸾台显，四柱逢生性出群。诗书自有渊源达，浴凤恩波四海春","hua":"两门拱夹主显贵；四柱得生者性超群，诗书有家学渊源","yong":"家学 + 贵格"},{"sec":"讲谈批贵命杂用诗诀","ju":"杀中包杀方为贵，龙居沧海早登云","hua":"杀中藏杀（杀有制有化）才为贵，如龙居沧海早登云路","yong":"七杀格成贵"},{"sec":"讲谈批贵命杂用诗诀","ju":"文章独步夸王粲，富贵双全比石崇。马骤天庭趋禁阙，雷霆德遇且超升","hua":"文才比王粲、富贵比石崇；马奔天庭直入宫阙，遇恩超升","yong":"文名与富并见"},{"sec":"讲谈批贵命杂用诗诀","ju":"玉阶献策三千丈，金榜题名第一班","hua":"殿前对策，金榜第一","yong":"科第之极"},{"sec":"讲谈批贵命杂用诗诀","ju":"金白水清秋必贵，丙丁入亥驾长虹","hua":"金白水清格，秋生必贵；丙丁入亥如驾长虹","yong":"金白水清 / 丙丁坐亥"},{"sec":"讲谈批贵命杂用诗诀","ju":"李杜文章无介意，萧曹案读足身荣","hua":"不必以李杜之文求名，走萧何曹参的案牍之路一样荣身","yong":"有文才而不以文名，宜吏途"},{"sec":"讲谈批贵命杂用诗诀","ju":"得从得化功名显，八位官星俊杰英","hua":"入从格、化格者功名显；官星多而成俊杰","yong":"从格 / 化格"},{"sec":"讲谈批贵命杂用诗诀","ju":"青标不是池中物，性格由来席上珍。三台辅命真堪美，月德扶身必显荣","hua":"非池中之物，性温如玉；三台辅命、月德扶身，必显荣","yong":"性格温雅而贵"},{"sec":"讲谈批贵命杂用诗诀","ju":"马化龙驹夸凤阙，扳龙附凤志冲宵。道合自扶伊鼎用，人贤拟在傅岩求","hua":"马化龙驹、攀龙附凤；才如伊尹傅说，终为辅相","yong":"依附贵人而成大用"},{"sec":"讲谈批贵命杂用诗诀","ju":"钧衡早镇三公府，骨相宜封万里侯","hua":"早年即登三公之位，骨相宜封侯","yong":"极贵之相（旧时夸张语）"},{"sec":"讲谈批贵命杂用诗诀","ju":"身近丹宸新衮绣，手调金鼎旧盐梅","hua":"身近皇帝、身着绣服，手调鼎鼐如宰相","yong":"近侍 / 宰辅"},{"sec":"讲谈批贵命杂用诗诀","ju":"水火既济名显达，寒谷春回锦绣勤","hua":"水火既济则名显；寒谷回春，勤而有成","yong":"水火调匀之命"},{"sec":"讲谈批贵命杂用诗诀","ju":"官露清高真贵特，财藏丰厚富荣昌","hua":"官星透出主清贵，财星藏库主丰厚","yong":"官露财藏"},{"sec":"讲谈批贵命杂用诗诀","ju":"厢囊陈钞多留积，仓廪豆粮足有余","hua":"仓箱有余，积储丰足","yong":"富命"},{"sec":"讲谈八字活套《珠玑集》","ju":"八字生来本自天，占魁真福尽朝年","hua":"天赋的福气，少年即占魁首","yong":"少年得志"},{"sec":"讲谈八字活套《珠玑集》","ju":"棱棱杀气冲牛斗，凛凛威风握将权","hua":"杀气冲斗牛，威风掌兵权","yong":"杀重用武"},{"sec":"讲谈八字活套《珠玑集》","ju":"八字生来气象鲜，管教平步上青天；出门车马多如簇，赫赫声名四海传","hua":"气象新鲜，平步青云；出门车马成群，声名远播","yong":"平步青云"},{"sec":"讲谈八字活套《珠玑集》","ju":"官居正品力争先，金刀铁马剑光悬","hua":"正品武职，金刀铁马","yong":"武贵"},{"sec":"讲谈八字活套《珠玑集》","ju":"当星得令重当先，能跨千里祖生鞭。蛮之邦清肃镇，四夷盘盗敢侵边","hua":"当令争先，如祖逖闻鸡起舞；镇守边方，外敌不敢犯","yong":"边镇武职"},{"sec":"讲谈八字活套《珠玑集》","ju":"堂堂杀印喜非常，此命天生价不双。读书决拟登黄甲，定作当朝一栋梁","hua":"杀印相生极贵，读书必登科甲，为朝廷栋梁","yong":"杀印格 + 科第"},{"sec":"讲谈八字活套《珠玑集》","ju":"人生伶俐且偻罗，性巧聪明志气多。异日读书终有路，管教及第早登科","hua":"人伶俐聪明、志气多，读书终有出路，早登科第","yong":"聪明早达"},{"sec":"讲谈八字活套《珠玑集》","ju":"去岁今年事未然，何如山下夜行船。刑刑并并添憔悴，保得人圆财未圆","hua":"近年事未成，如夜行船；刑并交加添憔悴，人团圆而财未圆","yong":"时运未通"},{"sec":"讲谈八字活套《珠玑集》","ju":"二十年前莫问妻，夜眠缩脚到鸡啼。只因命带孤辰杀，妻亦迟来子亦迟","hua":"二十岁前不必问婚事；命带孤辰，婚迟子迟","yong":"孤辰杀 → 婚迟"},{"sec":"讲谈八字活套《珠玑集》","ju":"且喜红鸾入命来，主添人口又招财。若无婚姻并喜事，更忧孝服入门来","hua":"红鸾入命主添丁进财；若无喜事，则忧孝服","yong":"红鸾年：非喜即丧"},{"sec":"讲谈八字活套《珠玑集》","ju":"罗计重逢百事凶，担棚带锁入牢中。虽然不受官刑打，也须病得不能通","hua":"罗睺计都重逢，百事凶，主牢狱或重病","yong":"罗计（旧批）：官非病灾"},{"sec":"讲谈八字活套《珠玑集》","ju":"冰清玉洁甚堪夸，荣夫益子会持家。虽然是个裙钗女，有志男儿不似他","hua":"女命冰清玉洁，旺夫益子会持家，胜过多有志气的男子","yong":"女命贤能"},{"sec":"批八字行运造化诗","ju":"从财从杀两般论，莫作寻常一例看。运至某方终发达，早年信步入金銮","hua":"入从财、从杀格的要另眼相看，不作常例；运一到位就发达，早年便入朝堂","yong":"从格行运批法"},{"sec":"批八字行运造化诗","ju":"金钟出冶方成器，业许终年渐渐成","hua":"如金钟出炉才成器，事业要慢慢做成","yong":"大器晚成"},{"sec":"批八字行运造化诗","ju":"三十年前连四九，跨马长安玩花柳。一朝身到凤凰台，独醉仙桃斟御酒","hua":"三十前后连四九之数，意气风发；一朝登上高位，独享恩荣","yong":"三十岁前后发迹"},{"sec":"批八字行运造化诗","ju":"四十年来事称怀，管教唾手取功名。空行万里恩光重，善牧黎民似水清","hua":"四十以后事事称心，功名唾手；为官牧民，清如水","yong":"四十岁后成名，宜亲民之职"},{"sec":"批八字行运造化诗","ju":"六六交来步步高，鲲鲸变化长波涛。一朝直上青云路，脱却单衣换紫袍","hua":"三十六以后步步走高，如鲲化为鹏，由布衣换紫袍","yong":"三十六岁后转运"},{"sec":"批八字行运造化诗","ju":"五五交来不等闲，龙麟凤羽任君攀。那时好展调羹手，定向皇家得意还","hua":"五五之数（旧批按生数推，或二十五或五十五）不寻常，可攀龙附凤、入朝得意","yong":"五五之数行运（岁数不固定）"},{"sec":"批八字行运造化诗","ju":"待到行年一并来，声名彰播凤凰台。腰悬金带趋金琐，官赐琼林乐御杯","hua":"行年到临，声名远播；腰金衣紫，受赐琼林宴","yong":"显贵之时"},{"sec":"批八字行运造化诗","ju":"六九数来连八八，利名场里享风光。燕山窦氏家声远，桂子庭前朵朵芳","hua":"六九至八八之数，名利双收；家声如窦燕山，子孙满庭","yong":"晚运全盛"},{"sec":"批八字行运造化诗","ju":"五旬七八遇官星，鹏鹦鹏程汉外风。龙虎榜中排姓字，管教垂手步蟾宫","hua":"五十七八遇官星，鹏程万里；榜上有名，垂手登第","yong":"五十末功名"},{"sec":"批八字行运造化诗","ju":"日月光华照世间，鸰原上舞翩翩。鸳鸯一对姻缘好，桂子森成戏彩栏","hua":"日月照临，兄弟和睦、夫妻和好、子女成行","yong":"六亲全美之命"},{"sec":"批八字行运造化诗","ju":"乾坤朗霁喜无云，鸿雁行中双共群。招得佳人才貌美，蟠桃一颗长精神","hua":"父母康宁、兄弟成群、娶得才貌之妻","yong":"六亲顺遂"},{"sec":"批八字行运造化诗","ju":"父母齐眉胜孟光，秋鸿作阵宿芦芳。牛郎织女姻缘好，丹桂花开朵朵香","hua":"父母齐眉、兄弟有序、夫妻和顺、子女争气","yong":"六亲全美"},{"sec":"批八字行运造化诗","ju":"斧头贯手命皆倾，棣萼连芳满路馨。美貌佳人方共老，琵琶拨出断肠声","hua":"命有凶煞（斧贯手），兄弟虽好而夫妻终断肠（丧妻）","yong":"兄弟有缘、妻缘有损"},{"sec":"批八字行运造化诗","ju":"双亲福寿久龟龄，鸿雁行中久失群。才貌佳人宜硬配，后园丹桂五枝荣","hua":"父母高寿，兄弟久散；妻要硬配才成，子女五人","yong":"父母寿、兄弟散、子多"},{"sec":"批八字行运造化诗","ju":"椿树风吹已福先，萱庭雨润正鲜妍。雁行品字方成阵，终久分飞各一天","hua":"父已亡、母健在；兄弟虽聚终必分飞","yong":"父亡母在、兄弟终散"},{"sec":"批八字行运造化诗","ju":"乾坤数定并悠长，造化成全福寿昌。坐使一门成后荫，故教丹桂满庭芳","hua":"父母寿长，家门有后荫，子孙满堂","yong":"家门兴旺"},{"sec":"批八字行运造化诗","ju":"双亲可惜早西归，鸿雁行中各自飞。硬命佳人方共老，后园丹桂雨霏霏","hua":"父母早亡、兄弟各自成家；妻须硬命才能到老，子女众多","yong":"父母早亡、子多"},{"sec":"批八字行运造化诗","ju":"乾坤早已被云迷，东岭孤松秀绝奇。结发姻缘重两两，栽花插柳假真儿","hua":"父母早不全，如东岭孤松；两度婚姻，有抱养之子","yong":"父母不全、重婚、过继"},{"sec":"批八字行运造化诗","ju":"椿萱俱已早遭霜，兄弟群中雪向阳。结发佳人金共石，丹桂枝兰末后香","hua":"父母俱亡、兄弟相依；妻情坚如金石，子女晚方显","yong":"父母俱亡、晚子"},{"sec":"批八字行运造化诗","ju":"乾坤云暗早沉西，萱草青青色更奇。鸿雁行中嫌伴少，声声嘹唳各东西","hua":"父母早逝，唯母一脉独青；兄弟人少且各散","yong":"父母早逝、兄弟少"},{"sec":"批八字行运造化诗","ju":"灵萱雪压已多年，萱草堂中福禄全。堪叹孔怀缘分浅，数中纵有也分烟","hua":"母在而有寿福；兄弟缘薄，纵有也分家","yong":"母在、兄弟分爨"},{"sec":"批八字行运造化诗","ju":"天高地厚两长年，鸿雁行数可齐全。鱼水夫妻谐白发，两枝丹桂在秋天","hua":"父母双全长寿、兄弟齐全、夫妻到老、子女二人","yong":"六亲全美"},{"sec":"批八字行运造化诗","ju":"日出东升月又西，玉昆金友不相宜。枕上鸳鸯同白发，后园丹桂五枝奇","hua":"兄弟不合（日出月西），夫妻到老，子女五人","yong":"兄弟疏、夫妻好、子多"},{"sec":"批八字行运造化诗","ju":"立身不必承先荫，玉隐石中金在沙。一日良工施大手，真金辉目玉无瑕","hua":"白手起家，如石中藏玉、沙里藏金，遇人赏识才显","yong":"白手发迹"},{"sec":"批八字行运造化诗","ju":"目下未成安稳地，荣华创业十分劳。逢羊过虎须通达，父子须同上九皋","hua":"眼下未稳，创业极劳；到未寅之年才通，父子同贵","yong":"先劳后成，未寅年通"},{"sec":"批八字行运造化诗","ju":"运令只许求安乐，回首桑榆泪满襟","hua":"行运只够求个安乐，晚年回首有憾","yong":"晚运平淡"},{"sec":"批八字行运造化诗","ju":"尚有好时在西北，眼前不必强追寻","hua":"好时在西北，眼前不必强求","yong":"西北方运"},{"sec":"批八字行运造化诗","ju":"时来合遇贵人发，某道荣身正起家","hua":"时来遇贵人提携，由某途起家","yong":"贵人提携"},{"sec":"批八字行运造化诗","ju":"中年运限风光在，伴雪经霜梅始开。得遇某时行其运，喜气直至五侯家","hua":"中年风光，如梅经霜而开；运到则喜气临门","yong":"中年发达"},{"sec":"批八字行运造化诗","ju":"运至时逢蛇共犬，冰消火炼也生光","hua":"运到巳戌之年，如冰消火炼而生光","yong":"巳戌年转机"},{"sec":"批八字行运造化诗","ju":"运至终须得大财，羊鸡某道出尘埃。若知某岁财源遂，一路滔滔快乐来","hua":"运终必得大财，未酉之年出尘埃；财源一顺便滔滔不绝","yong":"未酉年发财"},{"sec":"批八字行运造化诗","ju":"运至某方发达兴，中年胜似旧年成","hua":"运到某方发达，中年胜过早年","yong":"中年胜早年"},{"sec":"批八字行运造化诗","ju":"莫恨此人成败早，终须得奈破还成","hua":"不必恨成败来得早，破了还成","yong":"破而复成"},{"sec":"批八字行运造化诗","ju":"一重欣喜一重惊，借势因人自有成。莫叹少年荣辱事，梅花雪里香更清","hua":"喜惊相半，借他人之势而成；少年荣辱不必叹，梅在雪里香更清","yong":"靠人成事、晚节清"},{"sec":"批八字行运造化诗","ju":"何尤自小成冲破，及至中年破复成。有禄有财还晚景，无忧无虑乐升平","hua":"自小多冲破，中年破而复成，晚景有禄有财","yong":"少年破、晚年安"},{"sec":"批八字行运造化诗","ju":"少年生计未全成，某岁时来正显荣。自有高人轻借力，两重门户自光亨","hua":"少年未成，时来显荣；自有高人借力，两处门户都光亨","yong":"少年未成、中年成"},{"sec":"批八字行运造化诗","ju":"有心万里兴家业，历尽辛勤未见功。及至中年因贵发，时惟某运出朦胧","hua":"立志兴家，辛勤无成；中年因贵人而发，某运才出朦胧","yong":"中年因贵发"},{"sec":"批八字行运造化诗","ju":"晚来瞬息物更新，立志名高久夺身","hua":"晚来一变，物象更新，名高身显","yong":"晚运更新"},{"sec":"批八字行运造化诗","ju":"休嗟积岁与迍邅，运至中年有一凶。捱过某年交某运，如龙奋发出潭中","hua":"不必叹多年迍邅，中年有一凶；捱过某年交某运，如龙出潭","yong":"中年一关，过后腾达"},{"sec":"批八字行运造化诗","ju":"黄金白玉非身宝，守己安心有乐方。遇犬逢龙终发达，因人持却馨香","hua":"金玉非真宝，守己安心才乐；遇戌辰之年发达，因人而成","yong":"守成待时，戌辰年通"},{"sec":"批八字行运造化诗","ju":"凿石穿泉通巨海，秋深松桂长新花。西方通泰声名远，德业惟茂正起家","hua":"凿石引泉终通大海；秋深松桂开花，西方运通泰，德业起家","yong":"西方运、德业起家"},{"sec":"批八字行运造化诗","ju":"此命生来不遇时，花开雨打叶离枝。无情鸿雁分离散，有意鸳鸯各自飞","hua":"生不逢时，花被雨打；兄弟无情离散，夫妻有意也分飞","yong":"早运不遇、六亲离"},{"sec":"批八字行运造化诗","ju":"某岁运遇荣华禄，得失皆因分外求。动静本然天赋定，知音指绿向城新","hua":"某岁得荣华，得失都在分外之求；动静天赋已定，知音指引新程","yong":"运至得禄"},{"sec":"批八字行运造化诗","ju":"运逢某岁方生翼，遇马骑龙入凤城","hua":"运到某岁才生翼，遇午辰之年入京显达","yong":"午辰年腾达"},{"sec":"批八字行运造化诗","ju":"莫谓生平未称情，岂期枯木春始荣。知音总是秋江上，遇犬骑龙始见亨","hua":"不必说一生不称意，枯木也会逢春；遇戌辰之年才亨通","yong":"枯木逢春，戌辰年亨"},{"sec":"批八字行运造化诗","ju":"满院瑶桃尚未开，东方先放一枝梅。虽然傲雪凌霜久，终见阳和入户来","hua":"满院桃花未开，东方先放一枝梅；傲雪久，终见阳和","yong":"一枝先发、迟中有早"},{"sec":"批八字行运造化诗","ju":"财帛金珠满目前，绿窗朱户隐神仙。两重好运真为妙，积德修身感上天","hua":"财帛满前，朱门如神仙之居；两重好运，皆由积德修身","yong":"富而且积德"},{"sec":"批八字行运造化诗","ju":"迢迢前路未通津，革故重新始见成。某字运逢真个美，老来荣显慰平生","hua":"前路未通，革故更新才成；某运真美，老来荣显","yong":"改弦更张后成"},{"sec":"讲谈难为六亲诗句","ju":"六亲对面不相同，半是成孤半是空。鸿雁分飞秋塞外，鱼龙混杂碧波中","hua":"六亲虽在眼前却如不见，一半孤一半空；兄弟分飞，鱼龙混杂","yong":"六亲缘薄"},{"sec":"讲谈难为六亲诗句","ju":"秋空鸿雁潇湘远，一只孤飞转塞边","hua":"兄弟远隔，一只孤雁飞向塞外","yong":"兄弟孤远"},{"sec":"讲谈难为六亲诗句","ju":"顽金炼方成器，石上灵芝根不异","hua":"顽金要炼才成器，石上灵芝根性不凡","yong":"磨炼成器"},{"sec":"讲谈难为六亲诗句","ju":"风送雁飞深有序，秋深两两各分方。迢迢云路知何在，一在吴山一楚乡","hua":"兄弟有序而各分东西，一个吴一个楚","yong":"兄弟分居两地"},{"sec":"讲谈难为六亲诗句","ju":"一对鸳鸯有福全，分飞南北再重圆","hua":"夫妻有福，分而复合","yong":"离而复合"},{"sec":"讲谈难为六亲诗句","ju":"谁知雨骤风狂后，月缺花残两背盟","hua":"风雨之后月缺花残，两人背盟（离异）","yong":"离异"},{"sec":"讲谈难为六亲诗句","ju":"鸳鸯日暖始成双，雨骤风狂不久长。一鹭晚来同立处，柳阴深处桂花香","hua":"鸳鸯晚合，风雨一来不久长；后来另有归宿","yong":"晚合不久、后得良配"},{"sec":"讲谈难为六亲诗句","ju":"骤雨狂风打绿衣，一对鸳鸯各自飞。草塘鸥鸟纷纷盛，月朗星稀照钓矶","hua":"风雨打散鸳鸯，各自分飞；旁人反盛，己独清冷","yong":"夫妇离散"},{"sec":"讲谈难为六亲诗句","ju":"团团明月出云端，似有姮娥在广寒。保守全凭阴骘佑，春秋多在暮云间","hua":"如月中嫦娥独守清冷，全靠阴德护持，多在暮云之间","yong":"寡居清冷"},{"sec":"讲谈难为六亲诗句","ju":"墙外枝头花欲放，开时又虑雨和风。栽培须得阴功力，半有青黄半有红","hua":"子女将成又怕风雨；须阴德栽培，一半成一半折","yong":"子息有得有失"},{"sec":"讲谈难为六亲诗句","ju":"桂子只因花遇雨，蟠桃两颗半青黄。栽培当得阴功力，堪叹梅花更晚香","hua":"子女遇雨而折，只剩两三；须积阴德，梅花晚香","yong":"子息折损、晚年得子"},{"sec":"讲谈难为六亲诗句","ju":"连城白玉出蓝田，丹凤翔上碧天。蕴器终年成事业，立身切计事消然","hua":"子如玉出蓝田、凤翔碧天，器成业立","yong":"子息贵器"},{"sec":"讲谈难为六亲诗句","ju":"奇花并蒂后依稀，一雁东来一雁西。吴楚潇湘来往处，楚天空阔各分飞","hua":"兄弟并秀而后东西分飞，来往吴楚","yong":"兄弟并秀而散"},{"sec":"讲谈难为六亲诗句","ju":"闺中宝瑟尘多积，再被南方亦未清。鸥鹭满堂风雨恶，也疑惊散不同林","hua":"闺中琴瑟积尘（婚久不谐），南方再嫁也未清；满堂风雨，惊散不同林","yong":"婚不谐、再嫁未安"},{"sec":"讲谈难为六亲诗句","ju":"疏却相亲亲却疏，离南北往任君居。桑榆芝桂花荣茂，鹿向岩前福有余","hua":"亲者反疏，南北任居；晚年芝桂荣茂，福禄有余","yong":"六亲反疏、晚福"},{"sec":"讲谈难为六亲诗句","ju":"七九之年事不同，休说猪羊运不通。善世善人多福庆，林前一笑醉春风","hua":"七九之年（旧批按生数推）事有转机，莫说亥未运不通；善人多福","yong":"晚年转机"},{"sec":"讲谈难为六亲诗句","ju":"风边两雁过溪边，吴楚分飞各自然。毕有某年通大海，秋清万里好归源","hua":"兄弟各自分飞本出自然；某年终会通大海，秋清归源","yong":"兄弟各散、终有归处"},{"sec":"讲谈难为六亲诗句","ju":"成对鸳鸯游碧水，晚年一只绕清波。白云本是无心物，孤月清光照五湖","hua":"夫妻成对，晚年只剩一只；如孤月清光照五湖","yong":"晚年丧偶"},{"sec":"讲谈难为六亲诗句","ju":"遇犬逢猪身渐贵，逢龙见虎有惊忧。青山绿水开心处，明月清风兴自幽","hua":"遇戌亥之年渐贵，遇辰寅之年有惊忧；晚年山水自适","yong":"戌亥渐贵、辰寅有惊"},{"sec":"讲谈难为六亲诗句","ju":"借问百年身外事，若逢蛇犬送归程。山中猿鹤返为侣，明月清风识此情","hua":"若问身后归宿，巳戌之年为归程；归隐与猿鹤为侣","yong":"寿元之限（旧说）"},{"sec":"讲谈难为六亲诗句","ju":"孤军驻扎硬屯兵，力倦心疲战不成。此岁却如云掩月，六亲眷属火烧冰","hua":"如孤军硬撑，力倦无功；此年如云掩月，六亲如火烧冰（指望不上）","yong":"孤军奋战、六亲无靠"},{"sec":"讲谈难为六亲诗句","ju":"人事尽时天理顺，每向求安反见惊。若要称心遂意处，免随鸡走月重明","hua":"人事尽了天理才顺，越求安越见惊；要称心须待月重明","yong":"求安反惊、待时方遂"},{"sec":"讲谈难为六亲诗句","ju":"有意辰年龙在水，无心寅上虎归山。清风明月伴幽独，猿鹤相依不等闲","hua":"有意在辰年得水（龙在水），无心于寅年退隐（虎归山）；清风明月自守","yong":"辰年得志、寅年退隐"},{"sec":"讲谈难为六亲诗句","ju":"营求多利多成败，培种春花转寂寥。若问前程荣达事，夕阳影里采仙桃","hua":"经营多成败，春花转寂寥；问前程荣达，只在夕阳影里采仙桃（晚成）","yong":"经营起伏、晚成"},{"sec":"讲谈难为六亲诗句","ju":"运遇牛羊方始开，好骑牛背入秋山。西方一运花如锦，月照梅花影亦闲","hua":"遇丑未之运才开，西方一运如锦，月照梅花自在","yong":"丑未运通、西方如锦"},{"sec":"讲谈应命吉凶诗句","ju":"此命老来正壮强，养身不立利名场。轻财知命仁风顺，岁月优游夺霜","hua":"老来身体反壮，不争名利；轻财知命，仁风自顺，岁月优游","yong":"晚运康健、淡泊"},{"sec":"讲谈应命吉凶诗句","ju":"一叶熊罴积善家，发财事业盛奢华。就计成名当某运，拆鸳呼鸟落残霞","hua":"积善之家得贵子，发财盛华；某运成名，却有拆鸳之叹（婚变）","yong":"积善致富、婚有变"},{"sec":"讲谈应命吉凶诗句","ju":"此命推来福气多，性虽然艳绮罗。好女应知天产定，花容月貌赛姮娥","hua":"女命福气多，性艳丽，花容月貌","yong":"女命貌美福厚"},{"sec":"讲谈应命吉凶诗句","ju":"女造财官格局清，好福优游享太平。无荣无辱真贤慧，子贵夫荣应晚年","hua":"女命财官清，享太平；无荣无辱而贤慧，晚年子贵夫荣","yong":"女命财官清 → 晚福"},{"sec":"讲谈应命吉凶诗句","ju":"此是岩上一枯松，命中火性带刚强。真是财官凶化吉，孤标清节乐春风","hua":"如岩上枯松，火性刚强；财官化凶为吉，守节自乐","yong":"性刚守节"},{"sec":"讲谈应命吉凶诗句","ju":"此造重官煞印多，女性虽刚秉气和。贪生喜往东南位，贱买多绒赛绮罗","hua":"官杀印重，女命性刚而气和；喜东南，善经营","yong":"女命官印重、善经营"},{"sec":"讲谈应命吉凶诗句","ju":"克勤克俭性忠诚，夫明子秀自天然。之子好似莲花镜，命有三从四德贤","hua":"勤俭忠诚，夫明子秀；如莲花明镜，贤德","yong":"女命勤俭贤德"},{"sec":"讲谈应命吉凶诗句","ju":"下笔推排是某时，等闲八字本清奇。女中莫为无奇运，命好如荣纳福迟","hua":"八字清奇；女命不必愁无好运，命好只是纳福迟","yong":"女命福迟"},{"sec":"讲谈应命吉凶诗句","ju":"此造推来果是奇，心思才敏质清纯。不忮不求真贵特，成人成个杰中人","hua":"心思才敏、气质清纯，不忮不求，是杰中之杰","yong":"才敏清纯、杰出"},{"sec":"讲谈应命吉凶诗句","ju":"一笑能轻万户侯，命生值此果英豪。无辱无荣非俗子，用泽施仁礼义高","hua":"一笑轻万户侯，英豪之气；不慕荣辱而施仁守礼","yong":"豪气施仁"},{"sec":"讲谈应命吉凶诗句","ju":"天赐麟儿下九重，生成瑞气匆匆。短短之梯能步月，命好如龙入伴宫","hua":"天赐贵子，瑞气充盈；短梯也能步月，如龙入宫","yong":"贵子之命"},{"sec":"讲谈应命吉凶诗句","ju":"天赐聪明产善家，生逢此造实堪夸。命中准许趋金锁，短袖轻裘出众华","hua":"生于善家而聪明，可得近贵，衣着出众","yong":"聪明近贵"},{"sec":"讲谈应命吉凶诗句","ju":"好命如龙迥出尘，子成头角必峥嵘。难星又见用星制，养大英标步帝京","hua":"如龙出尘，子息出头；难星有制，长成后入京显达","yong":"子息出头"},{"sec":"讲谈应命吉凶诗句","ju":"此命推来性最华，子贵孙荣实可夸。倾城之璧成大用，家兴财富出兰芽","hua":"性华美，子贵孙荣；如和氏璧成大用，家兴财旺","yong":"子贵孙荣"},{"sec":"讲谈应命吉凶诗句","ju":"此时富贵命繁华，儿童值此锦中花。寿若风霜操干别，有才有业更兴家","hua":"小儿富贵之命，如锦中花；有才有业，兴家","yong":"小儿富贵（旧批）"},{"sec":"讲谈应命吉凶诗句","ju":"守自兰深出帐帷，亲休睹燕双飞。孤承夫福兴家业，命是人间女丈夫","hua":"深居守静，不羡双飞；独自承夫福、兴家业，女中丈夫","yong":"女命独立兴家"},{"sec":"讲谈应命吉凶诗句","ju":"孤梅好并一株松，独立森森独自荣。无骄无谄无灾咎，妻子迟招不犯重","hua":"如孤梅配松，独立自荣；不骄不谄无灾，妻迟娶而不重婚","yong":"孤高自立、婚迟"},{"sec":"讲谈应命吉凶诗句","ju":"此造推来果是奇，命许高扳步月梯。皆是五行天赋定，一个鸳鸯鸟堕飞","hua":"命奇可步月登高，皆是五行所定；只是鸳鸯一只堕飞（婚有损）","yong":"显达而婚有损"},{"sec":"讲谈应命吉凶诗句","ju":"老运推来更显扬，无间无阻必兴昌。结得好花并好子，果然夺得锦衣香","hua":"老运更显扬，无阻必兴；得好花好子，锦衣归香","yong":"老运显扬"},{"sec":"讲谈应命吉凶诗句","ju":"此命贤能胜孟光，女中君子世无双。克应某时其罕遇，夫妻和畅乐安康","hua":"女命贤能胜过孟光，夫妻和畅安康","yong":"女命贤能、夫妻和好"},{"sec":"讲谈批命鹧鸪天","ju":"杂气财官在月提，最宜冲破始为奇。忍耐方成中道好，春深莫怨吐花迟","hua":"杂气财官在月提，要冲破才奇；能忍耐，中道方好，春深不必怨花开迟","yong":"杂气财官格：库要开、运要冲"},{"sec":"讲谈批命鹧鸪天","ju":"贵造推排印绶明，财藏官露长精神。官印运来帮粟，闾里争先彩龙迎","hua":"印绶明而财藏官露，精神足；官印运一到，乡里争先迎接","yong":"印绶格：官印运发"},{"sec":"讲谈批命鹧鸪天","ju":"命里推排八字强，日干有气足财粮。子平理取伤官格，大运纵行到北方。才得显，福由彰","hua":"八字强、日干有气，作伤官格；行北方运才显，福由是彰","yong":"伤官格：北运显"},{"sec":"讲谈批命鹧鸪天","ju":"煞印棱棱格局成，明生杀露有威严。身强最行喜官运，主弱生扶掌大权","hua":"杀印成格，杀露有威；身强喜官运，身弱须生扶才掌权","yong":"杀印格：身强喜官"},{"sec":"讲谈批命鹧鸪天","ju":"此命偏官格最奇，产下之初正某时。官星不紊纯而贵，印旺扶元是福基","hua":"偏官格最奇；官星不混则纯贵，印旺扶身是福根","yong":"偏官格：纯而不混"},{"sec":"讲谈批命鹧鸪天","ju":"八字正官格局纯，才藏官露效雍容。伯仲庭前敦礼义，家道昌隆福禄钟","hua":"正官格纯，才藏官露而雍容；兄弟敦礼义，家道昌隆","yong":"正官格：家道昌"},{"sec":"论六格批命活套","ju":"正官之格喜清纯，不带冲伤不带刑。印旺资身为贵取，财多扶本富堪称","hua":"正官格批语分五段：一赞格局清纯、不逢冲刑；二叙家风诗书、父母兄弟；三叙财印运与功名；四叙某运有转折（防父丧一类）；五叙晚景子孙绕膝、寿数有定","yong":"正官格整段批语的骨架"},{"sec":"论六格批命活套","ju":"七杀当权蕴月支，惟宜身旺可胜之。官星不紊纯而贵，印旺扶元是福基","hua":"偏官格：先说杀在月支、须身旺；再说须纯而不混、印旺扶身；末写性刚勇敢、运势先潜后发、晚景福厚","yong":"七杀格整段骨架"},{"sec":"论六格批命活套","ju":"贵造清纯印绶逢，财藏官露是豪雄。润身富有千种粟，奚必登云步月宫","hua":"印绶格：印清而财藏官露，是豪雄之命；性温良恭俭，行运先平稳、后有一关、再逢佳境","yong":"印绶格整段骨架"},{"sec":"论六格批命活套","ju":"杀印棱棱格局清，日干秉令向春生。蛟龙岂是池中物，一遇风云即奋身","hua":"杀印格：杀印清而日干得令，如蛟龙非池中物；性雄硬量大，运到即起","yong":"杀印格整段骨架"},{"sec":"论六格批命活套","ju":"富造生于乔木家，正财之格实堪夸。比劫不来真空遇，日干兴旺享太华","hua":"正财格：先许家世、格局；再说比劫不来夺财；运程先财旺、中财后印、晚入官乡，末以高寿收","yong":"正财格整段骨架"},{"sec":"论六格批命活套","ju":"月令偏财一点清，又逢印绶与官星。主人抱负经纶业，似璞中含转世珍","hua":"偏财格：财清带印官，主有经纶之才；性喜交游、拘礼施仁；运程初运不比劫、中运印扶身健、晚景积财","yong":"偏财格整段骨架"},{"sec":"论六格批命活套","ju":"命里推排八字强，日干有气足财粮。子平理取伤官格，大运纵行到北方","hua":"伤官格：日干强、有财粮，作伤官格；行北方运才显；先叙才名、再叙婚姻，末写晚运","yong":"伤官格整段骨架"},{"sec":"论六格批命活套","ju":"杂气财官在月提，最宜冲破始为奇。忍耐方成中道好，春深莫怨吐花迟","hua":"杂气财官格：库要冲破才奇；须忍耐，中道方好；发达在晚期","yong":"杂气财官格整段骨架"},{"sec":"指明批贵命活套","ju":"批殿元显宦","hua":"状元批法：父母受封赠、兄弟有序、妻有正副、子接书香；初运荫下、二三运读书、三五运登第、某运升迁、末运寿八十二，收以「青松巢翡翠，一坏黄壤卧麒麟」","yong":"极贵（状元）"},{"sec":"指明批贵命活套","ju":"批宦相斯文二品之贵","hua":"二品文臣批法：五行清秀不杂、双亲皓首、妻正副、桂香；秋榜科甲、琼林宴、北阙拜官、父母褒封、乔迁；末运有谗谤归乡","yong":"二品文臣"},{"sec":"指明批贵命活套","ju":"批天资国器三品之贵","hua":"三品批法：父母宠渥、兄弟庆会、妻正副；初运未分、二运苦读、三运折桂探花、四五运郎官、六运大政、七运三品三台，八运终于任上","yong":"三品重臣"},{"sec":"指明批贵命活套","ju":"批及第登高进士等会","hua":"进士批法：星格奇异、文章官样；某运养才待时，再入官印之乡中科甲；礼部勤政、亲民如甘棠；因直谏被屈，再起为辅；晚运勇退归乡","yong":"进士出身"},{"sec":"指明批贵命活套","ju":"批月窟重光大夫等今","hua":"大夫批法：双亲恩庆、兄弟拂云、不再续娶、子联芳；初运读书、二运折桂、三运宪职（风霜之任）、四运礼乐兴、晚节乌纱南下","yong":"大夫（五品上）"},{"sec":"指明批贵命活套","ju":"批浪起春雷秀才等命","hua":"秀才批法：待时潜鳞、文华德器；某运如良玉不雕、某岁苦读精微；后园结异果（得子）；末写寿限「花落水流人不在」","yong":"秀才"},{"sec":"指明批贵命活套","ju":"批鱼龙养起蓝生等并用","hua":"监生批法：父亡母在、兄弟和睦、妻正副、子继旧业；守素遵度，某运苦读，献策观光，拜迪功郎，升郎官，任知县，牧民省刑薄敛","yong":"监生（入监读书）"},{"sec":"指明批贵命活套","ju":"批桃浪进身童生等命并用","hua":"童生批法：文质彬彬、习儒宗、性活泼；某运几年困于鸡窗，一旦标名虎榜；过目成诵、持身雍容；末以「龙虎成来金鼎满」收","yong":"童生"},{"sec":"指明批贵命活套","ju":"批虎榜标名生员等命并用","hua":"生员批法：兄弟联翩、妻贤举案、子绍书香；某运暂驻文航养才，再交某运跃过龙门；献三策、沾雨露、领春官、五马高封；末有谗谤、挂冠归菊","yong":"生员（秀才）"},{"sec":"指明批贵命活套","ju":"批志合冲天武举等会并用","hua":"武举批法：全用科举宴饮意象——琼林宴、月殿开、折桂、点桃腮；末以「矢心忠义」收，是武人忠义口气","yong":"武举"},{"sec":"指明批贵命活套","ju":"批香拂桂林有贵器者","hua":"贵器（得子）批法：松岳钟灵、充闾喜气；弄璋之诗、汤饼之宴；气壮食牛、才高附凤；积庆之家，先着蓝袍换绿袍","yong":"得贵子"},{"sec":"指明批贵命活套","ju":"批人间岳惊","hua":"凤雏批法：丹山产凤、一鸣百禽惊；丰姿颖异、气质清纯；初运杀重体弱，二八（十六岁）后鱼跃莲塘；后继以科名、官花县、遭谗归隐","yong":"幼慧早达"},{"sec":"指明批贵命活套","ju":"批富产祥麟富命","hua":"富命批法：积德豪门、瑞产祥麟；丰姿如荆山璞、资质如丽水金；父母恩重、兄弟联翩、早缔良姻、熊罴入梦（得子）；童限无星杀，八岁后有小惊，五六岁试短翎，后入芸窗、明伦堂、五经初试，某运下第不嗔，再逢坦道","yong":"富家之子"},{"sec":"指明批贵命活套","ju":"批蚌产明珠老来得子者用","hua":"老来得子批法：长庚焕彩、瑞气满室；飞熊入梦、老蚌产珠；世泽久远、福入桑榆（晚年）","yong":"老年得子"},{"sec":"指明批贵命活套","ju":"批祥开后院要生子用","hua":"求子得子批法：历世行仁积庆，侧室产名驹；成材承业、读父书；天姿削玉、体质藏珠","yong":"求子/侧室得子（旧制语）"},{"sec":"指明批贵命活套","ju":"批玉树流芳遗腹子用","hua":"遗腹子批法：以「玉树流芳」为喻，先赞父德，再说遗腹而生、克承先志、终能成立","yong":"遗腹子"},{"sec":"批六亲活套（父母兄弟夫妇）","ju":"彩衣庭下戏春风，真庆堂前娱晚荣。椿花堂上日烘烘，萱草庭前乐正浓","hua":"父母双全：以老莱子彩衣娱亲起，椿（父）萱（母）并茂，福禄绵绵","yong":"父母俱在"},{"sec":"批六亲活套（父母兄弟夫妇）","ju":"双亲太息早归西，久弃斑衣舞戏衣。椿萱俱值早秋霜，遗下庭前桂有芳","hua":"父母俱亡：双亲早逝，斑衣之乐久废；遗下子孙自有芳桂","yong":"父母俱亡"},{"sec":"批六亲活套（父母兄弟夫妇）","ju":"灵椿雪压已多年，萱草堂中福禄全。可怜严父早归西，慈母堂中福寿齐","hua":"母在父亡：灵椿被雪压（父亡），萱草晚节坚（母守节），断机教子","yong":"父亡母在"},{"sec":"批六亲活套（父母兄弟夫妇）","ju":"黯淡浮云迷皓月，一轮红日映桑榆。秋风肃杀摧萱草，椿树乔添岁月长","hua":"父在母亡：萱草先萎（母亡），椿树独高（父在），子失慈线","yong":"母亡父在"},{"sec":"批六亲活套（父母兄弟夫妇）","ju":"鹡鸰原上和声集，三五成群作队飞。棠棣川枝承雨露，共含瑞日养红颜","hua":"兄弟和睦：鹡鸰在原、棠棣连枝，三五成群、同气共居","yong":"兄弟和"},{"sec":"批六亲活套（父母兄弟夫妇）","ju":"一番风雨摧荆树，鸿雁分飞各自天。手足犹如冰见炭，弟兄恰似虎逢狼","hua":"兄弟分飞：荆树摧折、鸿雁各天；甚者如冰炭、如虎狼（兄弟反目）","yong":"兄弟散/不睦"},{"sec":"批六亲活套（父母兄弟夫妇）","ju":"鸳鸯一对好姻缘，桂子森成戏彩斓。内助得贤偕伉俪，承颜女子绍家声","hua":"夫妇谐和：鸳鸯好缘、贤内助、子女成行、家声有继","yong":"夫妻和"},{"sec":"批六亲活套（父母兄弟夫妇）","ju":"美貌佳人难共老，琵琶拨出断肠声。结发缘难并老，子如伯道数中真","hua":"难为妻子：佳人难共老，中道断肠；结发难偕老，子如邓伯道（无子）","yong":"婚难偕老、子息艰"},{"sec":"批六亲活套（父母兄弟夫妇）","ju":"炊臼梦回嗟寂寞，中间不见探头人。鼓盆休效庄生叹，弦断何年再续胶","hua":"刑妻：炊臼无釜（丧妻）、镜破难圆；某运之中刑起，堂前无主馈之人","yong":"丧妻/离异"}],"shi_note":"卷六活套逐首白话：共 174 条，按 sec 分组（批命活用总套、讲谈批贵命杂用诗诀、讲谈八字活套《珠玑集》、批八字行运造化诗、讲谈难为六亲诗句、讲谈应命吉凶诗句、讲谈批命鹧鸪天、论六格批命活套、指明批贵命活套、批六亲活套）。ju 为原句（摘二至四句），hua 为白话，yong 为适用场合。","ge_tao":{"正官格":{"ju":"正官之格喜清纯，不带冲伤不带刑。印旺资身为贵取，财多扶本富堪称","duan":["起手：八字里正官一位清纯，不带冲刑，走的是规矩与名分这一路","格局：官星要有身旺印绶来承，财来生官则名利两得；最怕伤官来损贵、官杀混杂","六亲：家风清白、父母有教养，兄弟守礼，婚姻多门当户对","行运：财印之运最得力，官星得地则名位进；伤官之运防口舌是非","收尾：一生以稳为主，晚景子孙守成"],"yong":"有官有印的正途"},"七杀格":{"ju":"七杀当权蕴月支，惟宜身旺可胜之。官星不紊纯而贵，印旺扶元是福基","duan":["起手：七杀当权在月支，这条路要有制有化才走得稳","格局：身旺能任杀则掌权，印来化杀则不伤身，食伤制杀则成器；最怕财来生杀又无制","六亲：性子刚烈，父母缘偏薄（杀重克身），兄弟也帮不上多少；婚配晚一点、找个性子硬的更合。","行运：制杀、化杀之运最得力；财杀并行之运防压力与伤病","收尾：撑得住就成贵格，撑不住就一生劳身"],"yong":"杀有制化、身能任杀"},"正财格":{"ju":"富造生于乔木家，正财之格实堪夸。比劫不来真空遇，日干兴旺享太华","duan":["起手：正财格是守成一路，财要身旺才任得起","格局：财喜欢食伤来生、官星来护；怕比劫来抢，也怕身弱扛不住。","六亲：家世以实业为根，父母勤俭；男命妻宫得力","行运：财旺、官旺之运名利双进；比劫之运防破财与合伙纠纷","收尾：稳中积富，晚景不忧吃穿"],"yong":"有财可守的富局"},"偏财格":{"ju":"月令偏财一点清，又逢印绶与官星。主人抱负经纶业，似璞中含转世珍","duan":["起手：偏财是流动之财、外来之财，靠机会与交际","格局：要身强、要官星护财、要食伤生财；怕比劫来分，也怕身弱守不住。","六亲：交游广、父缘较显（偏财为父）；婚姻易有变动或晚定","行运：财乡、官乡得力；比劫之乡防破耗","收尾：财来财去，能聚才成富"],"yong":"善经营者"},"正印格":{"ju":"贵造清纯印绶逢，财藏官露是豪雄。润身富有千种粟，奚必登云步月宫","duan":["起手：印绶主庇荫与学识，走的是文路、靠的是名分","格局：喜官杀生印、比劫帮身；最怕财旺破印","六亲：母缘厚（印为母），得长辈提携；性稳，婚姻多偏晚","行运：官印之运名利稳进；财运来时防因财失位","收尾：稳厚有荫，晚景安闲"],"yong":"靠名分与学问立身"},"偏印格":{"ju":"命里推排偏印明，财藏官露长精神","duan":["起手：偏印（枭神）主偏门之学、直觉与技艺，路走得窄而深","格局：要官杀来生、要自身有根；怕财把印冲了，也怕枭神把食夺了。","六亲：性子偏孤，亲缘淡；适合靠一门手艺立身，不适合挤在人群里。","行运：官杀生印之运得力；食神被夺之运防事阻","收尾：走专精一路，晚成一艺"],"yong":"技艺、玄学、专精之人"},"食神格":{"ju":"食神生旺最堪夸，食神生财福更加","duan":["起手：食神是温和输出，主口福、才艺与涵养","格局：要身旺、要有财（食神生财）；怕印来夺食。","六亲：心宽有格调，子女缘顺（食为子），父母妻子多和","行运：财乡最得力；印乡要防才艺被压","收尾：衣食不忧，晚景清闲"],"yong":"温和输出、衣食丰足"},"伤官格":{"ju":"此格伤官杀喜旺，只愁身旺尽伤官","duan":["起手：伤官是才气外露，聪明而带锋芒","格局：要伤得干净、要有财（伤官生财）、要有印（佩印）；最怕见官星。","六亲：聪明貌秀、言语直；婚姻里容易较真，旧说男命伤官克妻","行运：财运最顺；官运要防口舌、是非、官非","收尾：才气用对了成器，用错了伤人伤己"],"yong":"才气外露的人"},"建禄格":{"ju":"建禄庚辛旺在申，有官有印有财星。逆行辰巳荣财禄，北地须知富贵成","duan":["起手：月支正是日主的禄，身有根有力，是自立的底子","格局：身旺，要走财官食伤把力气泄出去；怕再来比劫印绶，越帮越堵。","六亲：早岁多劳，多自立门户；兄弟各有前程","行运：财官那几步能发起来；比劫那几步守着就好。","收尾：靠己不靠荫，中晚年自成"],"yong":"身有根、自立成家"},"月劫格":{"ju":"羊刃带伤官，驳杂事多端","duan":["起手：月支是羊刃，性刚、气盛、敢动","格局：要七杀来制刃、要偏财；怕伤官，也怕再来比劫。","六亲：性子烈，亲缘上多摩擦；婚配找个软的更合。","行运：杀运制刃则贵；刃旺无制之运防伤灾与争讼","收尾：有制则成将才，无制则多波折"],"yong":"刚烈之命，要在制"},"比劫格":{"ju":"比肩犯重，须防分财","duan":["起手：比劫成群，主自立、竞争与同辈缘分","格局：要官杀来管、要食伤来泄；怕再往上助旺。","六亲：兄弟朋友多，助力与拖累并存；婚姻防争","行运：官杀、食伤之运得力；比劫之运防分财","收尾：合伙的话，先把规矩立在前头；自己单干反而稳。"],"yong":"同辈缘分重、宜自立"},"从财格":{"ju":"从财从杀两般论，莫作寻常一例看","duan":["起手：日主无根无帮，局中财最旺，只能顺财走","格局：从财的，要财旺、要食伤生财、要官星护财；最怕日主忽然有根、比劫来帮——一不从，就散了。","六亲：多出身商贾或理财之家；婚姻常与财势相关","行运：财运顺遂；身旺之运要防破格","收尾：顺势则富，逆势则败"],"yong":"弃命从财，顺财为用"},"从杀格":{"ju":"弃命从杀论，杀旺反为权","duan":["起手：日主无根无帮，官杀成势，只能从杀","格局：要杀旺、要财来生杀；怕日主有根、印来生身——一不从，就悬了。","六亲：性沉毅，早年压力大、靠山少","行运：杀运、财运得力；帮身之运防病灾与是非","收尾：从得真则是贵格，假从则一生劳"],"yong":"弃命从杀，顺势为权"},"从儿格":{"ju":"弃命从儿，秀气流行","duan":["起手：日主无根，食伤成势，顺着秀气泄出去","格局：要有财（食伤生财）、要食伤旺；怕印来夺食，也怕日主忽然有根。","六亲：才艺出众，子息显（食伤为子）","行运：财乡、食伤乡顺；印乡破格","收尾：以才艺立家，靠输出吃饭"],"yong":"从儿格：以才艺为生"},"木专旺格":{"ju":"曲直生春月，庚辛干上逢。南离推富贵，坎地却犹凶","duan":["起手：木气聚成一局，日主仁厚有担当，适合文教、林园这一路。","格局：专旺是顺着一股气走，要水木火来生来帮；怕金（庚辛申酉）来破局。","六亲：一门之气偏聚，性偏而专；亲缘随气而聚散","行运：水木火之运助气成势；金（庚辛申酉）之运防破局","收尾：成局则气象可观，破局则一生偏枯"],"yong":"木专旺（一气成局）"},"火专旺格":{"ju":"炎上格中炎上名，丙丁得局气冲天","duan":["起手：火气聚成一局，日主气盛外向，适合出头露脸，不适合被压着。","格局：专旺是顺着一股气走，要木火土来生来帮；怕水（壬癸亥子）来破局。","六亲：一门之气偏聚，性偏而专；亲缘随气而聚散","行运：木火土之运助气成势；水（壬癸亥子）之运防破局","收尾：成局则气象可观，破局则一生偏枯"],"yong":"火专旺（一气成局）"},"土专旺格":{"ju":"稼穑格中稼穑名，戊己逢辰气自凝","duan":["起手：土气聚成一局，日主厚重能载，适合实业、地产这一路。","格局：专旺是顺着一股气走，要火土金来生来帮；怕木（甲乙寅卯）来破局。","六亲：一门之气偏聚，性偏而专；亲缘随气而聚散","行运：火土金之运助气成势；木（甲乙寅卯）之运防破局","收尾：成局则气象可观，破局则一生偏枯"],"yong":"土专旺（一气成局）"},"金专旺格":{"ju":"从革格中从革名，庚辛得局气锋棱","duan":["起手：金气聚成一局，日主锋锐果断，适合金属工艺、武职这一路。","格局：专旺是顺着一股气走，要土金水来生来帮；怕火（丙丁巳午）来破局。","六亲：一门之气偏聚，性偏而专；亲缘随气而聚散","行运：土金水之运助气成势；火（丙丁巳午）之运防破局","收尾：成局则气象可观，破局则一生偏枯"],"yong":"金专旺（一气成局）"},"水专旺格":{"ju":"润下格中润下名，壬癸逢申气自盈","duan":["起手：水气聚成一局，日主智谋深远，适合流动、商贸这一路。","格局：专旺是顺着一股气走，要金水木来生来帮；怕土（戊己辰戌丑未）来破局。","六亲：一门之气偏聚，性偏而专；亲缘随气而聚散","行运：金水木之运助气成势；土（戊己辰戌丑未）之运防破局","收尾：成局则气象可观，破局则一生偏枯"],"yong":"水专旺（一气成局）"},"化木格":{"ju":"丁壬合化木，化神得令便为真","duan":["起手：丁壬相合化木，木又当月令，日主本身没根，就从化神走","格局：化气看的是化出来的那股气，要水木来扶它；怕金来克它。","六亲：格局一化，六亲看化神那边，不从本气看","行运：助化神之运吉；克化神、争合妒合之运凶","收尾：化得真则如另一条命，化不真则两不相从、多波折"],"yong":"丁壬化木（化气格）"},"化火格":{"ju":"戊癸合化火，化神得令便为真","duan":["起手：戊癸相合化火，火又当月令，日主本身没根，就从化神走","格局：化气看的是化出来的那股气，要木火来扶它；怕水来克它。","六亲：格局一化，六亲看化神那边，不从本气看","行运：助化神之运吉；克化神、争合妒合之运凶","收尾：化得真则如另一条命，化不真则两不相从、多波折"],"yong":"戊癸化火（化气格）"},"化土格":{"ju":"甲己合化土，化神得令便为真","duan":["起手：甲己相合化土，土又当月令，日主本身没根，就从化神走","格局：化气看的是化出来的那股气，要火土来扶它；怕木来克它。","六亲：格局一化，六亲看化神那边，不从本气看","行运：助化神之运吉；克化神、争合妒合之运凶","收尾：化得真则如另一条命，化不真则两不相从、多波折"],"yong":"甲己化土（化气格）"},"化金格":{"ju":"乙庚合化金，化神得令便为真","duan":["起手：乙庚相合化金，金又当月令，日主本身没根，就从化神走","格局：化气看的是化出来的那股气，要土金来扶它；怕火来克它。","六亲：格局一化，六亲看化神那边，不从本气看","行运：助化神之运吉；克化神、争合妒合之运凶","收尾：化得真则如另一条命，化不真则两不相从、多波折"],"yong":"乙庚化金（化气格）"},"化水格":{"ju":"丙辛合化水，化神得令便为真","duan":["起手：丙辛相合化水，水又当月令，日主本身没根，就从化神走","格局：化气看的是化出来的那股气，要金水来扶它；怕土来克它。","六亲：格局一化，六亲看化神那边，不从本气看","行运：助化神之运吉；克化神、争合妒合之运凶","收尾：化得真则如另一条命，化不真则两不相从、多波折"],"yong":"丙辛化水（化气格）"}},"ge_tao_note":"按格局拼的整套批语：24 格，每格五段（起手／格局／六亲／行运／收尾），由 174 条活套句化出，句式仍是旧批的结构，话改成了白话。"},"reading_bazi/jiankang":{"note":"据《子平汇刊》本《渊海子平》卷三「论疾病」「论小儿」「论小儿关杀例」整理，病名为原书旧说，只作倾向参考，不下诊断。","gan_neifu":{"甲":"肝","乙":"胆","丙":"小肠","丁":"心","戊":"胃","己":"脾","庚":"大肠","辛":"肺","壬":"膀胱","癸":"肾"},"gan_waizhi":{"甲":"头","乙":"项","丙":"肩","丁":"心","戊":"胁","己":"腹","庚":"脐","辛":"股","壬":"胫","癸":"足"},"zhi_buwei":{"子":"疝气","丑":"肚腹","寅":"臂肢","卯":"目手","辰":"背胸","巳":"面齿","午":"心腹","未":"脾胸","申":"咳疾","酉":"肝肺","戌":"背肺","亥":"头肝"},"wuxing":{"木":{"ke":"金（庚辛申酉）","nei":"惊悸、虚怯、痨疾、呕血、头晕目眩、痰喘、头风脚气、左瘫右痪、口眼歪斜、风症、筋骨疼痛","wai":"皮肤干燥、眼目之疾、发须疏少、跌扑手足损伤","nv":"堕胎、血气不调","xiaoer":"急慢惊风、夜啼咳嗽","jing":"筋骨疼痛，盖因木被金伤"},"火":{"ke":"水（壬癸亥子）","nei":"颠哑、口心痛疼、急缓惊风、秃舌口咽哑、潮热心烦","wai":"眼暗失明、小肠肾气、疮毒脓血","nv":"干血淋漓","xiaoer":"痘疹、癣疮","jing":"眼暗目昏，多是火遭水克"},"土":{"ke":"木（甲乙寅卯）","nei":"膈食、翻胃、气蛊、蛊胀、泄泻、黄肿不能饮食、吃物拣择呕吐","wai":"左手口腹有疾、皮肤燥涩","nv":"","xiaoer":"疽病、脾黄","jing":"土虚乘木旺之乡，脾伤定论"},"金":{"ke":"火（丙丁巳午）","nei":"咳嗽喘吐、肠风痔漏、魑魅失魂、痨怯","wai":"皮肤枯燥、齆鼻、赤疽、痈背脓血","nv":"","xiaoer":"","jing":"金弱遇火炎之地，血疾无疑"},"水":{"ke":"土（戊己辰戌丑未）","nei":"遗精白浊、盗汗、虚损耳聋、伤寒感冒","wai":"牙痛、疝气、偏坠、腰痛、肾气淋沥","nv":"胎崩漏白带","xiaoer":"","jing":"下元冷疾，且缘水值土伤"}},"yao":"一五行太旺或不及都算病：看日主所属五行被哪一行克得重，克得多的重、克得少的轻。若本气旺而只逢一克，多半不显。","xiaoer":{"zong":"小儿命要身旺，喜印绶生扶，无财来克，则好养灾少；不要官杀、羊刃、伤官太旺。身旺也多灾，身弱则难养。忌早行运。","guan":"关杀取法：偏官为关，偏财为杀，按生数推年岁——水一、火二、木三、金四、土五。如甲日见庚杀，应四、九岁；丙见壬，一、六岁。","li":"财多主庶出或克父母；胎元不正、有胎衣包、仰生有惊等旧说只作参考。十五岁以后才谈得上分别贵贱。"}},"reading_bazi/liu_qin":{"version":"0.2","note":"白话版：只留判断与理由，不显示出处。","principle":"看六亲就两步：先看那颗「六亲星」，再看「六亲宫」。星对你有用，你就借得上它的力；是添乱的那一类，你就得替它受累。宫位也一样，不能只看星，也不能只看宫。","items":{"父":{"star":"偏财","palace":"月柱","judge":["偏财是父亲这颗星。它本身有生气、又有人来生它，父亲就撑得住，家里也能靠一靠。","这颗星要是气数走到尽头、被冲被刑，或者比劫来重重地克，跟父亲缘分就浅，容易分开，或者父亲身体多病。","有食伤来生这颗父星，而且它正好是命里用得上的，那父亲不光自己有福，你也能沾上光。"]},"母":{"star":"正印","palace":"月柱","judge":["正印是母亲这颗星。它有力、又没被财冲，母亲性子慈和，你也能得她的照顾。","这颗星被旺财硬克，或者气数走到尽头，母亲多半多病，母子缘分也薄。","印星太多、反倒成了累赘，母亲也操劳多病。印星要是好用，落在年是祖上，落在月是父母，落在时是子女的福气。"]},"妻":{"star":"男看正财，女看正官","palace":"日支","judge":["男命拿正财当妻、偏财当偏房；女命拿正官当夫、七杀当偏夫。这颗星跟日主贴得近、又是命里用得上的，就能得另一半的力。","日支被冲、落进空亡，或者被比劫来夺，婚姻就容易有波折。配偶宫是帮你的一路，就得内助；是添乱的一路，就受拖累。","财多身弱扛不住，轻的另一半性子强，重的会因为钱惹事。身旺、财也旺，日子就顺。"]},"兄弟姐妹":{"star":"比肩、劫财","palace":"月柱","judge":["身弱拿比劫来帮身，兄弟姐妹和睦，手足的力借得上。","身旺、财又轻，比劫还成了添乱的那一类，手足之间容易生分，甚至会为钱争。","比劫跟正财贴在一起，要防兄弟朋友分你的财。劫财合七杀，要是能把杀管住、或者留官取清，反倒不算坏事。"]},"子女":{"star":"男看官杀，女看食伤","palace":"时柱","judge":["子息星有力、有人帮、又是命里用得上的，子女孝顺，也能借上力。","子息星气数走到尽头，男命被伤官克、女命被印枭克，子女缘分就薄。","时柱落空亡、子息星又是添乱的那一类、还没人救，子女就难得。要是用印去制伤护身，或者用伤去制杀护身，子女这一块仍然能往好里走。"]}},"note2":"别拿一句「哪个宫带哪个神就哪个亲不好」来套，要看他这个神在命里是喜是忌，再和宫位一起看。"},"reading_bazi/nayin":{"note":"按纳音本义的白话解释（形象为主，不作吉凶断语）","items":{"海中金":"像藏在海底的金，要等空冲才现形；原文说它成器不借火力，靠的是那股灵秀之气。","炉中火":"炉膛里的火，热力集中、来得快；怕的是炉子漏了、柴断了，火就散。","大林木":"成片的林子，枝干舒展、能容人；怕被砍伐，也怕根下无水。","路旁土":"路边能长庄稼的土，实用、接地气；要靠水润、要防车马踩踏。","剑锋金":"开了刃的剑：要经百炼、红光透刃，还得有水来养，才不钝不折；锋芒太露也容易伤人。","山头火":"山顶上的火，亮得远、声势足；风一大就不好控。","涧下水":"山涧里的水，清而细、流得远；怕被土堵、怕断源。","城头土":"城墙上的土，厚实、能挡事；太干太硬就要水来和。","白蜡金":"白蜡一样的金，质细、怕磕碰；得养着，别硬碰硬。","杨柳木":"河边的柳，柔韧、会变通；根浅，怕水冲也怕干旱。","泉中水":"石缝里冒出的泉，源源不断、清冽；最怕淤塞。","屋上土":"屋顶的土，挡风遮雨、护着一家人；自己别再压上重物才好。","霹雳火":"雷火，来得突然、威力大；用在点子上是奇兵，滥用就伤。","松柏木":"松柏，耐寒、立得住；长得慢，但长得久。","长流水":"长流不断的水，有耐力、能走远路；怕的是只会流、不会蓄。","沙中金":"掺在沙里的金，要淘、要筛才见；成器慢，成了很实在。","山下火":"山脚下的火，温而不烈、照得近；适合贴身处事。","平地木":"平地上的树，容易长、也容易被伐；要有围有护。","壁上土":"墙上的土，规整、用来隔断；怕潮、怕裂缝。","金箔金":"打得很薄的金箔，好看、显贵气，但薄，经不起大力。","覆灯火":"灯罩里的火，光小而稳，照一室；要油、要罩，怕风吹。","天河水":"天上的水，雨露之恩，来得广、不落地；有润物之功，难独取。","大驿土":"大道上的土，往来通衢、经得起踩；适合做承载的一方。","钗钏金":"首饰上的金，精巧、贴身；适合细做，别拿去当刀剑使。","桑柘木":"养蚕的桑，实在、有用；年年被采，年年还长。","大溪水":"大溪的水，势大而急，走的是大道；怕拦、怕改道。","沙中土":"含沙的土，松而能渗；种东西要费力，胜在透气。","天上火":"太阳火，照得远、普施；自身太烈，要有水来中和。","石榴木":"石榴木长在金地、味带辛，性偏；别的木到午月就衰，它偏在午月最旺。","大海水":"大海，能容、能藏，也翻脸无常；要有堤、要有方向。"}},"reading_bazi/nvming":{"note":"据《子平汇刊》本《渊海子平》卷三女命诸篇（论妇人总诀、阴命赋、女命富贵贫贱篇、女命贵格、女命贱格、滚浪桃花、女命总断歌）整理。旧说多带时代偏见，只作传统断法参考，不当定论。","yao":"女命拿官星当夫、财星当福。先看夫星旺不旺，再看自身和子女。财旺能生官，丈夫就跟着得福。旧说喜欢清纯平和、不喜欢混杂——后面这半句带时代偏见，看的时候留个心。","zongjue":[{"dian":"官为夫","hua":"取正官为正夫、七杀为偏夫。官杀两样都露头，旧说于婚姻不利、容易反复；明里暗里夫星都聚着，就说人感情上定不下来。这是老一派的说法，只当一个倾向。"},{"dian":"财为福","hua":"财旺能生官，丈夫就沾光。女命的财不必太厚；财薄一点，反倒旺夫、对孩子也好。"},{"dian":"印食为贵","hua":"印绶和食神主名分和体面，是能被人称呼的那一路；印绶太旺，反而在子女这件事上容易卡。"},{"dian":"伤官","hua":"旧说「伤官见官」于婚姻不利，容易反复、人也劳碌。不过伤官重的人多半聪明、长得清爽。伤官配杀、又有财的，日子宽裕；没财的，就紧一些。"},{"dian":"杀多","hua":"七杀多，旧说夫缘就杂；官杀被合住，说是有旁人来争、婚配定不下来。这是旧时的口气，听听就好。"},{"dian":"身强弱","hua":"旧说女命身弱，性子纯、温柔、能伺候公婆、也帮得上丈夫；身强就压丈夫、脾气躁。其实这是老一套的框子——身弱身强各有各的病，没有哪一边就一定好。"},{"dian":"孤克","hua":"伤官、官星气数走尽，再赶上孤神寡宿、日时落空亡，旧说叫「孤克」；官杀露在天干、地支却没根、又没气，旧说归到偏房那一路。这些话带着旧时代的偏见，只当参考。"},{"dian":"天月二德","hua":"命里带天月二德，旧说生育上少出岔子。"},{"dian":"驿马咸池","hua":"旧说驿马再带贵人，最后还是漂泊；咸池就是桃花，主感情上不由己，再碰上驿马，人就容易跑远。旧书觉得女命该静不该动——这话按今天的眼光看，是对女性的额外限制，看个倾向就行。"},{"dian":"孤鸾","hua":"旧说甲寅、辛亥、丙午、戊午、壬子这几个日子，婚姻上容易落单；日时相冲，于夫、于子女都不算顺。这是旧歌诀的说法，不作定论。"},{"dian":"运","hua":"八字里官杀都没有，可运走到官杀财运上，夫星就落了地，不算孤；本来财官都有，偏偏走伤官劫财那一段，婚配就不太顺，往往要等这步运过去才成。"}],"yinming_fu":["看女命先看夫主盛衰，再论自身荣枯与子息强弱。","夫荣子旺，富贵荣华；子死夫衰，穷孤下贱。","有夫有子而贫寒，是自身落在衰乡；无夫无子而昌盛，是身居旺地。","贵人少者不富也昌；合贵神太多，非妓即尼。","四柱伤官而暗招财损，是淫贱之象。","招婿者夫显于门户之中；偏夫者夫旺于日时之上。","夫衰身旺，主廉洁；鬼旺身衰，必作孤寒之妇。"],"fu_gui_pin_jian":["先看官星：官带杀而贫贱，官得令而安荣。","伤官太重必妨夫，性也重。","倒食（偏印）重逢减福，再犯孤神更甚。","杀重须嫁贵室，合多定损贞名。","坐禄乘舆则稳厚；冲身动步则轻浮。","桃花滚浪，淫奔之耻不堪言。","日禄归时，贵重为人所敬。","天月二德坐本命又逢印绶，贵当两国之封。","时日羊刃不利夫宫，亦损平生性。","食神专旺则子有福；偏印窃身之盛则减。","阴日守中和则贞静；阳干支旺甚则经营夫婿。","欣逢正禄，怕犯咸池；清贵得长生之辅，杂浊以败气之归。","四柱败多，大忌冲身犯合，一生忙甚，非妓即为媒。","印坏与公姑相妒；食专得子嗣之宜。","官杀重逢须防淫乱；比劫姐妹透出便见争夫。","魁罡有灵便之机，日贵有安常之福。","官杀盛而无制伏，不为娼妓定作尼姑。"],"gui_ge":["正气官星","财官两旺","印绶天德","独杀有制","伤官生财","坐禄逢财","官星带合","日贵逢财","官贵逢官","官星坐禄","官星桃花","食神生旺","食神生财","杀化印绶","二德扶身","三奇合局","羊刃有制","拱禄拱贵","归禄逢财"],"jian_ge":["官杀混杂","官杀无制","杀星太重","伤官太重","贪财破印","比肩犯重","无官见合","无印见杀","伤官带杀","带合桃花","八字刑冲","财多身弱","羊刃冲刑","金神带刃","多官多合","倒插桃花","身旺无依","伤官见官","财官遇印","印绶遇劫"],"gunlang":["女命以官为夫或以杀为夫，只喜一位，多者克夫。","满盘官星为忌，满柱杀星反为福。","女命伤官不为贵，行伤官运克夫；伤官有制则身孤。","官星多者伤夫主贱；伤官带桃花为妓女命，或克子息。","若见贵人一位、或带荣神、或犯绝地，多主富贵贞节。","禄马相随、桃花带贵则贵；咸池遇马多淫，妨夫破家。","辰戌全则淫乱破家、伤夫克子；有辰无戌命孤，有戌多无辰初年劳碌。"],"zong_duan_ge":[{"ju":"择妇须沉静，夫星要强宫，身主要强甚","hua":"择妇看沉静；夫星要旺在强宫，日主自身也要够旺。"},{"ju":"官星若不合，夫主无所依","hua":"官星无合则夫主无依。"},{"ju":"合绝莫合贵","hua":"宁合绝地也不合贵神（合贵反不贵）。"},{"ju":"带禄日生旺，产死教人谤","hua":"日主带禄又生旺，旧说反主产厄。"},{"ju":"驿马带贵人，终久落风尘","hua":"驿马带贵人，终久落风尘。"},{"ju":"有辰休见戌，有戌休见辰；辰戌若相逢，多是淫破人","hua":"辰戌不宜并见，见则主淫破家。"},{"ju":"有杀不怕合，无杀却怕合","hua":"有七杀不怕合；无杀只怕合多。"},{"ju":"合神若是多，非妓亦讴歌","hua":"合神多，非妓即歌伎。"},{"ju":"贵人一座正，两三作宠定","hua":"贵人一位为正，两三则作宠妾。"},{"ju":"羊刃带伤官，驳杂事多端","hua":"羊刃带伤官，事多驳杂。"},{"ju":"满盘都是印，损子必须定","hua":"满盘印绶，必损子息。"},{"ju":"二德坐正财，富贵自然来","hua":"天月二德坐正财，富贵自然来。"},{"ju":"四柱带休囚，封赠福寿增","hua":"四柱带休囚，反主封赠福寿。"},{"ju":"金水若相逢，必招美丽容","hua":"金水相逢，主貌美。"},{"ju":"寅申巳亥全，孤淫口便便","hua":"寅申巳亥全，主孤淫口舌。"},{"ju":"子午逢卯酉，定是随人走","hua":"子午卯酉全见，主随人私奔。"},{"ju":"辰戌逢丑未，妇道之大忌","hua":"辰戌丑未全见，是妇道大忌。"},{"ju":"两贵一位杀，权家富贵说","hua":"两贵一位杀，主权贵之家。"},{"ju":"财官若藏库，冲破岂不富","hua":"财官藏库，得冲破则富。"},{"ju":"天干一字连，孤破祸绵绵","hua":"天干一字连（如甲甲乙甲乙），孤破祸连。"},{"ju":"地支连一字，两度成婚事","hua":"地支连一字，主两度成婚。"}],"mark":"这一段的旧说里有「淫贱」「克夫」「尼妓」这类话，那是旧时代对女性的价值判断，今天不该照搬。这里只留它看盘的路数，判断本身请只当倾向参考。"},"reading_bazi/rishi":{"note":"机器转写，非人工逐条翻译","items":{"甲日子时":{"general":"甲日子时：甲日甲子时，虽甲败在子，暗有癸水生气印缀，兼有官生其印，如果已土破印，月令有扶助，显贵。否则，秀","cases":{"甲子":"甲日子时：子已格，年月无庚辛申酉，丑午冲，离祖自立，显贵。如果年月都寅，遇到到申酉运，大","甲寅":"甲日子时：拱丑中辛，显贵。年月无庚辛申酉丑未，大显贵。再甲寅月，孤克，惟憎道可。亥子年月，","甲辰":"甲日子时：如果水位年月，水泛木浮，多主移根换；申月，杀星会印，都显贵。子月，行水木运，也","甲午":"甲日子时：時日亚冲，伤妻子，月通木气者显贵。纯子午年月，或亥未酉月，都显贵。","甲申":"甲日子时：甲胎遇到到印印化杀，显贵。重叠，子嗣离为。如果行束南方运，文武職居间。亥卯未辰","甲戌":"甲日子时：拱亥天门，会同帝阙，甲长生地也，不可以隔角。年月通申已酉丑金气，大显贵。戊"}},"甲日丑时":{"general":"甲日丑时：甲日乙丑时，辛金为官，已土为财，丑中暗己，被明乙劫，乙丑金神，如果年日時合成火局，得到制伏，","cases":{"甲子":"甲日丑时：連珠得到合妻贤子显贵。春月身旺，财帛破散。夏月甲衰，金神有制，显贵。秋生，近侍之","甲寅":"甲日丑时：春穷苦，秋显贵，冬富，夏火制金神，吉。","甲辰":"甲日丑时：多主富厚有财，通火气年月，显贵。","甲午":"甲日丑时：金神入火局，身弱体弱早亡。寅戊会火，是一木叠遇到到火位，不吉。如果單寅單戌，或申酉亥","甲申":"甲日丑时：带病普通。子月生，南方运，显贵。秋生化杀，天干透印绶，尤显贵。","甲戌":"甲日丑时：田連阡陌，贯朽粟陳，但未免先刑。寅年月，父子都。子月，西方运，金紫。"}},"甲日寅时":{"general":"甲日寅时：甲日丙寅时，甲木寅上健旺，丙为食神，寿星得到地，柱无壬癸克，通火木月气者显贵，怕见官星及申","cases":{"甲子":"甲日寅时：日禄居時，青云得到路，年月无庚辛金，显贵；通木火气極显贵。午月行束北方运，五六品","甲寅":"甲日寅时：年月无已酉辛丑字，是归禄格，位至一二品。纯木火带土，富显贵雙全，六卿之職。丙","甲辰":"甲日寅时：龙虎拱门，又龙吟虎啸，多主显贵，或一生近显贵，财源或得到或失去，名利既济未济。未、寅","甲午":"甲日寅时：身居地，多主平。如果通水月，木得到滋養，吉；火月寿天，天干比助无妨。","甲申":"甲日寅时：时日亚冲，聂伤妻子。如果年月日同，大显贵；已、亥二三品；辰、子年月，会水以杀化","甲戌":"甲日寅时：年月有土则富；有金反復。如有金，须生亥子印月方显贵，余月则否。"}},"甲日卯时":{"general":"甲日卯时：甲日丁卯时，伤官羊刃，甲用辛为官，丁字伤之，用已为财，卯中乙木劫之，多主为人狠。如果柱透辛，","cases":{"甲子":"甲日卯时：克刹吝，作事進退，不免刑伤妻子，或死他乡。生辰戌丑未月，显贵。卯月不利，柱有","甲寅":"甲日卯时：年月木火相停，通明之象，显贵。月令坐丑、未显贵。乙亥月，文章冠世，官至三品，干","甲辰":"甲日卯时：财帛满目，生計盈余，妻贤子孝，高命之。春生太旺无制，穷苦残病。丑、酉月显贵。","甲午":"甲日卯时：身坐地，不利刑。如果生秋冬，天。春夏富显贵。甲午月，大显贵，运宜束北方。","甲申":"甲日卯时：多主武職，风權显贵。酉月，火木运，中显贵。寅、午年月大显贵。","甲戌":"甲日卯时：遇到到亥月，有才学，显贵。羊刃最壤，造化须有制合方吉；身弱无不利，如果年月纯杀，甲"}},"甲日辰时":{"general":"甲日辰时：甲日戊辰时，天财坐库，时上偏财，遇到龙守库，多主为商买发财，田园广盛。八月带禄，财官都有，富","cases":{"甲子":"甲日辰时：多主移根换，改姓易宗，妻贤子孝，作高命。未月，行北方运，显贵。酉月，北方运，","甲寅":"甲日辰时：龙吟虎啸格，显贵。纯辰，中显贵。纯寅康寿。亥卯未三合，财旺身強，大显贵。酉丑申年","甲辰":"甲日辰时：刑冲发财，妻重子晚，雙親有克。酉月三四品显贵。丑月也显贵。地支纯辰，大显贵。","甲午":"甲日辰时：财多成败，早灰心。亥子丑卯午未年月大显贵。酉月也显贵。","甲申":"甲日辰时：多主孤，僧道清高。丑月富显贵。寅月尤显贵。甲戌日戊辰时，大富，年月扶合也显贵。寅亥"}},"甲日午时":{"general":"甲日午时：甲日庚午时，死地遇到到鬼，甲木死于午，午头见庚为鬼，不月令有扶助，无救助者，带病促。月遇到到丙寅，","cases":{"甲子":"甲日午时：时日相冲，爱伤妻子，普通。如果子午年月及寅戌月生，行西北方运，金紫风患。","甲寅":"甲日午时：春月有。夏月伤官伤盏，财源進退。申有權，酉反復。冬月伤妻子。子未年月杀助","甲辰":"甲日午时：田圍樂赏。寅月，行金运，风。","甲午":"甲日午时：破祖业发财，禄因财不得到善终。寅午戌年月，显贵。","甲申":"甲日午时：子辰年月会印。亥卯年月身旺，都显贵。寅戌会伤制杀，甲得到寄，也显贵，运喜金水。","甲戌":"甲日午时：生辰戌月，敦厚，不显贵则富。丑月行火土运，金紫风，寅月清显贵。"}},"甲日未时":{"general":"甲日未时：甲日辛未时，時显贵遇到到官，甲见辛为官，未有天乙显贵；已为财，未中已土得到气，如果通木气月，有寄者","cases":{"甲子":"甲日未时：辰戌丑未及已酉月，土金地方，文显贵达。","甲寅":"甲日未时：寅申月显贵。酉丑年月，大显贵。","甲辰":"甲日未时：辰戌丑未月富。已酉丑子年月显贵。","甲午":"甲日未时：春吉，夏不利，秋身弱任官禄，冬显贵。","甲申":"甲日未时：春吉，夏辛苦，秋达，冬根基别立显贵。子丑月大显贵。","甲戌":"甲日未时：先刑後显贵。寅卯酉年月显贵，子申年月，位至显贵。"}},"甲日申时":{"general":"甲日申时：甲日壬申时，甲木在申，申土壬水长生，庚金建禄，明暗鬼，甲旺化鬼为官，猎不免兑暴。如果生","cases":{"甲子":"甲日申时：申子辰亥月，水泛木漂，移根换，玉堂金马之显贵。水土运，不利。","甲寅":"甲日申时：旺中有失去。辰戌丑未月勾陳得到位；寅、午、戌月，偏官有制；秋月，行束南运，都显贵。","甲辰":"甲日申时：寅辰年月，文章显贵。透丙戊尤美。甲午日壬申时，申子辰月，改姓更宗，敦厚之命。","甲申":"甲日申时：寅月，身杀两停；卯月，以刃合杀，都显贵。子辰年月，以杀化印；已午火月，七杀有","甲戌":"甲日申时：辰戌丑未月，衣錦有成；亥月学堂；寅月建禄；都显贵。午酉月寿促，不然穷苦。"}},"甲日酉时":{"general":"甲日酉时：甲日癸酉时，胎生元命，甲木酉上受胎，为甲生气，明癸为印，暗辛为官，有已土破印，不显贵。酉为","cases":{"甲子":"甲日酉时：春生木旺；酉月官纯，显贵。如果混之以杀，或杀多，柱中全无火气，不利。","甲寅":"甲日酉时：春生，夏反復。秋性不定，多不利。冬普通。丑未月显贵。","甲辰":"甲日酉时：子戊年月，有财有官，显贵。","甲午":"甲日酉时：多主孤。生寅午戌月，行束北方郎官。","甲申":"甲日酉时：普通。通火气月，行南运，富显贵。申酉年月，多天。有水化金毒，只作官印，不作","甲戌":"甲日酉时：子戌年月，文章显贵。子午月，不显贵即富。"}},"甲日戌时":{"general":"甲日戌时：甲日甲戌时，甲用丙为食，辛为官，戌上食神入火局，辛有余气，身被火焚，为人好善，普通衣禄。","cases":{"甲子":"甲日戌时：春，夏暴，秋显贵，冬，移根换，柱见纯亥爽角，显贵终不利。辰戌丑未，离气财官，","甲寅":"甲日戌时：比肩爭禄，木气遭焚，四十後渐不如前。甲丙申子年月，大显贵。纯戌风，午月，行","甲辰":"甲日戌时：财源穩厚，多不利。春月金火运，官至六品。","甲午":"甲日戌时：春生，显贵人扶持。夏，背禄逐马。冬，印缓，吉。纯寅年月，近侍显贵。","甲申":"甲日戌时：爽酉官显贵，但身孤，发也不久。春生，木土运，显贵。","甲戌":"甲日戌时：背禄逐马，普通。秋生，官杀有气，显贵。辰戌丑未月，吉。卯月不利。如果丙寅、甲午年"}},"甲日亥时":{"general":"甲日亥时：甲日乙亥时，甲木亥上长生有旺，乙为刃，制克学堂，壬为倒食，亥上建禄。甲以金为官，戊已为财，","cases":{"甲子":"甲日亥时：成趣乾格，显贵。如生申月，杀旺合刃，權显贵。酉月正官，柱稍得到土助，大显贵。辰已魏","甲寅":"甲日亥时：辰戌丑未月，富。申酉月，显贵，冬，普通。如果寅亥月，高显贵。","甲辰":"甲日亥时：酉月正官，最显贵。辰戌丑未及寅亥年月，都吉。","甲午":"甲日亥时：卯月羊刃，刑骨肉，身弱不得到善终。春生，显贵为宰辅。申子戌午年月，行水火运，官","甲申":"甲日亥时：亥月，学问有成，显贵为风。申酉月，先穷苦後富。子月，行水火运，金紫。辰戌丑未，","甲戌":"甲日亥时：春冬生，富，土厚地方显贵。夏，力不聚财。秋普通。"}},"乙日子时":{"general":"乙日子时：乙日丙子时，六乙鼠显贵。乙用庚为官，死于子；见丙为伤，丙暗邀辛化杀为權，柱中不见庚辛，无丑","cases":{"乙丑":"乙日子时：身弱普通，无午穿冲，贤德温厚。申酉年月，风。寅子，显贵。怕丙寅、已未、甲","乙卯":"乙日子时：高。辰戌丑未亥年月，不见官星，显贵。","乙未":"乙日子时：平。如果子亥年月，大显贵，运同。怕已未月，刑伤，丙申月，身不完死；已丑月，破","乙酉":"乙日子时：显贵，身孤，反復起倒，月通水气，不见辛午也显贵。怕戊寅月，大不利；丁已月，破祖穷苦；","乙亥":"乙日子时：化青赤，多主福。生庚辰年月，富显贵。纯亥，成败。丑月，行南运郎官。已午西运，極"}},"乙日丑时":{"general":"乙日丑时：乙日丁丑时，食会财官，丁为食，庚为官，已为财，丑中有辛金合局，已土得到位，如有依靠者，显贵。","cases":{"乙丑":"乙日丑时：秋生有權；多主带病；夏吉，冬平；春旺，显贵。","乙卯":"乙日丑时：亥月，身旺见辛偏官，柱有丁制，风武職。","乙未":"乙日丑时：辰戌丑未月，富。春寿长，秋名利，夏穷苦苦，冬普通，申年月，武職三品。","乙酉":"乙日丑时：如果通木气有依靠者，显显贵。申丑年月也好，寅亥尤佳。","乙亥":"乙日丑时：亥月，性急有操持，妻贤子孝，官至六七品。午月长生，年月透官印，大显贵。"}},"乙日寅时":{"general":"","cases":{"乙卯":"乙日寅时：刑中发福。秋生显贵。酉年遇到辰戌丑未月，富。卯月建禄，午月印生，透官印，都吉。","乙未":"乙日寅时：春生有。秋显贵。夏普通，冬反復。辰戌且未，都吉。运同。","乙酉":"乙日寅时：春生富，夏平、秋显贵、寿促，冬吉。","乙亥":"乙日寅时：春吉，夏力，秋冬显贵。子丑年月，显贵至三品，有起有落，寿永。"}},"乙日卯时":{"general":"乙日卯时：乙日己卯时，禄入翩堂，乙木遇到到卯建禄，为人秀麗，通木火者显贵。见庚辛为伤禄破命，患目病。如果生","cases":{"乙未":"乙日卯时：年月不见庚辛金，显贵。秋生，看地厚薄，如生壬戌年月，三四品显贵。乙酉日己卯時秀，初","乙亥":"乙日卯时：生寅已月，不见庚辛，日禄归時格，显达清显贵。纯卯年月，高僧羽士。戌，特达聪明，"}},"乙日辰时":{"general":"乙日辰时：乙日庚辰时，妻贤子显贵。乙合庚化金，如果通申已酉丑月，为人秀麗，多主显贵，防目病。如不见化，以","cases":{"乙丑":"乙日辰时：破祖克父，身弱怕病，月令有扶助者，显贵。子申年月，天干透甲戊，合三奇，大显贵。","乙卯":"乙日辰时：富显贵。通火土年月，大显贵。","乙未":"乙日辰时：亥卯身，身旺；已申，官旺，天干透杀印，都显贵。丑酉纯杀，柱有火制，也吉。戌魏","乙酉":"乙日辰时：亥子年月，韩透戊癸，显贵。寅已午月，官杀有制，吉。纯酉化金，多主厚福。","乙亥":"乙日辰时：不显贵则富。如果年月癸戊一化，申卯两旺，已丑酉会金，行木土运，位至金紫。"}},"乙日午时":{"general":"乙日午时：乙日壬午时，印绶学堂，乙木长生在午，见壬为印，用丁为食，已爲财，午上丁已建旺，如果通水月气","cases":{"乙丑":"乙日午时：春夏多富显贵。秋冬官印，或纯杀透干，尤吉。","乙未":"乙日午时：寅卯身旺，亥子印旺，丑月财官印三奇，都多主显贵。申月正官，尤吉，如果庚午、丁亥","乙酉":"乙日午时：春吉。秋夏普通。柱纯乙酉，透庚合化，或见印助，大显贵。","乙亥":"乙日午时：春身旺，夏福厚，秋反復，冬吉。"}},"乙日未时":{"general":"","cases":{"乙丑":"乙日未时：不利刑孤，年月通土气，吉。","乙卯":"乙日未时：改祖离親，就妻为家。午未年月，显贵。春尤显贵。","乙未":"乙日未时：春，身旺刑伤。秋，官杀旺，科名有分。冬安穩。夏普通。","乙酉":"乙日未时：身坐杀，春，身旺，吉。夏，身弱杀衰，穷苦。秋，杀旺，身能徙化，显贵。冬平。辰戌","乙亥":"乙日未时：春木旺，刑伤妻子。申月官旺，显贵。酉杀旺，年月有火则吉。午未戌年月，一二品显贵。"}},"乙日申时":{"general":"乙日申时：乙日甲申时，官印生身，乙用庚为官，壬为印，申上庚旺壬生，身有寄，通金水月运者显贵；月令不扶，","cases":{"乙卯":"乙日申时：化显贵。月通水气无伤破者，显贵，不然，富。","乙未":"乙日申时：生未酉亥月，聪俊特达，官至二三品。丙丁寅午卯酉年月，伤食制杀，權显贵。","乙酉":"乙日申时：官杀混离，如果柱丁火制杀留官则吉。亥卯未酉年月，武職品；不久；行束南方运，","乙亥":"乙日申时：时落空亡，多主少子。秋生，官居六卿。亥卯年未月，都吉。"}},"乙日酉时":{"general":"乙日酉时：乙日乙酉时，身鬼旺，乙以辛为鬼，酉上辛旺乙。如果通已酉丑月，化金局者显贵。如用神坐木，身","cases":{"乙卯":"乙日酉时：月通金局者显贵。未寅年月，官至一二品。","乙未":"乙日酉时：拱显贵格，无刑破者显贵，有申填实则非。亥卯月，行西运，显贵。","乙酉":"乙日酉时：旺处自刑，年月火土重，多主。如果月令有扶助，透出印食，行火木运，大显贵。地支纯酉，","乙亥":"乙日酉时：春生，仁寿格，显贵。寅月，行金火运，大显贵。"}},"乙日戌时":{"general":"乙日戌时：乙日丙戌时，鬼臨身，乙用庚为官，见丙背禄，戌中有辛余气、丙丁库，食神制杀，如果柱透庚，伤","cases":{"乙丑":"乙日戌时：春身旺，吉。夏，伤官太重。秋，力辛苦。冬亥子，印绶带伤官，显贵。戌月，木","乙卯":"乙日戌时：寅卯月，运西运，六七品显贵。子月印缀；丑月气，刑出财官，都显贵。","乙未":"乙日戌时：旺处不利。卯午未戌年月，显贵。","乙酉":"乙日戌时：春身旺，冬印旺，大显贵。夏已午，秋酉戌，都显贵。也看天干如何？丁未、甲辰，生計","乙亥":"乙日戌时：血病。亥子卯未寅月，遇到显贵发福；天干透伤官生财，尤吉。枯木相遇到到局，遇到到春更生；"}},"乙日亥时":{"general":"乙日亥时：乙日丁亥时，死处遇到到生，乙木死，亥气壬水为生气印缀，乙用丁爲食，亥中丁坐无气，喜甲木生，","cases":{"乙卯":"乙日亥时：已酉丑月偏官，申月正官，都显贵。亥月，束南运，风。未月，三合木局，大显贵。","乙酉":"乙日亥时：月通金局，行水运，大显贵。通木气，发达。土气，意。","乙亥":"乙日亥时：有财自刑，寅卯身旺，天干透财者富；辰丑，行金火运，显贵。亥子申，官印雙清，更"}},"丙日子时":{"general":"丙日子时：丙日戊子时，官旺财生，丙用辛为财，癸为官，丙合辛，戊合癸，子中癸旺辛生，丙火无气。如果通火","cases":{"丙子":"丙日子时：寅已卯未月，木能生火，大显贵。冬月，丙火无气，体弱早亡。戌月，行火土运，五六品显贵。","丙寅":"丙日子时：生卯丑月，清显贵。寅戌，普通。夏月身旺，柱有水金方吉。子月正官，大显贵。怕癸已","丙辰":"丙日子时：丙辰为日德格，喜见官星。如果生戌月，身旺最宜，武显贵。寅月，行金水运，中显贵。申","丙午":"丙日子时：丙午为日刃格，要官杀制合。生辰戌丑未月，大富。亥卯未寅年月，大显贵，申已，文","丙申":"丙日子时：已午年月，行束北运，风患，子月，行木火运，三品。魏七品，酉亥，遇到显贵反贱。","丙戌":"丙日子时：春生，印绶最吉。夏，身太旺，普通。秋，财旺身弱，有寄则显贵。纯酉年月，文進"}},"丙日丑时":{"general":"丙日丑时：丙日己丑时，伤官背禄，傲物志高。丙用癸为官，魏中有癸余气，被明暗土，柱透癸为礼。如果见庚","cases":{"丙子":"丙日丑时：寅亥申辰年月，天干透财印食者显贵。","丙寅":"丙日丑时：普通，生乙酉月，正财格，有乙庚健旺者显贵。已丑年月，乾透官印者显贵。","丙午":"丙日丑时：春月，行火金运，官至極品。夏平，秋富，冬显贵，为妻子，午酉年月，五六品，此"}},"丙日寅时":{"general":"丙日寅时：丙日庚寅时，生气学堂，丙寅上长生，文章秀气；丙以庚辛为财，寅上庚丙旺。如果月令有扶助金局者财","cases":{"丙子":"丙日寅时：生子月，近显贵。癸酉月，行水木运，高显贵；火木运，五品以上显贵。未申、癸午年月，","丙辰":"丙日寅时：生寅午戌未年月，妻贤子孝，富显贵雙全。申子，行北运，大显贵。酉丑，富。","丙午":"丙日寅时：年月无壬癸子未已字，飛天禄马，显贵。已酉丑申，多主文学，不显贵即富。未月，伤官。","丙申":"丙日寅时：亥卯未、申子辰二局，官印雨旺，大显贵。已丑财局，吉。寅午戌火局，平。","丙戌":"丙日寅时：生亥子月，显贵。申酉年月，行北方运；寅午戌，行官鬼运，都大显贵。如果运臨死，"}},"丙日卯时":{"general":"丙日卯时：丙日辛卯时，财遇到到合，丙日卯上沐浴，见辛合神。如果身甚旺不得到化者，只是为人无禮就贪色欲，","cases":{"丙子":"丙日卯时：子卯相刑，伤妻害子。年月同，多主魁名，近侍之显贵。寅、午、丑、戌、天干地支都合","丙寅":"丙日卯时：无祖自立，有肢体病。寅卯未子月，显贵。余月平，运同。","丙辰":"丙日卯时：生寅戌月，天月二德，高。已月，行北方运，显贵。酉丑也显贵。亥卯未，大显贵。","丙午":"丙日卯时：年月中得到癸水官星去刃则吉。子月，伤克妻子，寅酉，性格刷強，不受擎，三四品","丙戌":"丙日卯时：伤妻害子，身旺不化者显贵。春，聪明好酒色。冬，行西运，富显贵。夏风。"}},"丙日辰时":{"general":"丙日辰时：丙日壬辰时，水火未济。丙见壬偏官，辰上壬水合局，火死无光。如果生春夏，身旺化鬼为官，行身","cases":{"丙子":"丙日辰时：辰戌丑未月，偏官有制，吉。亥卯年月，富显贵。寅午，行子运；子，行寅午运，都显贵。","丙寅":"丙日辰时：身杀雨旺，寅卯辰丑未年月，大显贵。已午戌年月也显贵。","丙辰":"丙日辰时：身孤有财，多主恶死。春生，行北运；夏，束运，都显贵。秋，南运，官至三品。","丙申":"丙日辰时：旺中。春平，夏福，秋富，冬寿促。如果申子辰木局，乾透印比助，大显贵，食制杀也","丙戌":"丙日辰时：不利。卯未年月，运行火土，官至三品，妻贤子孝。辰戌丑月，平穩。寅午子已年月，"}},"丙日午时":{"general":"丙日午时：丙日甲午时，丙火午上太旺，要见己合甲化土，火气伏晶，明照四方，如果不见土享福。生辰戌丑未","cases":{"丙子":"丙日午时：春生吉；夏无依，秋财旺，冬官显贵，少子晚成，火土运发达。","丙寅":"丙日午时：生辰戌丑未月，上伏火气，造化得到中显贵。午月，火太旺，不利。","丙辰":"丙日午时：寅卯印助，申酉印旺，已午身旺，亥子官旺，都吉。然以火土为重，无则福薄。未戌","丙午":"丙日午时：寅午戌月，作倒冲，二三品显贵。子月，南运，八九品显贵。寅月，南运，金紫显贵。午","丙申":"丙日午时：不见火土气者福薄。行金水运，显贵。","丙戌":"丙日午时：春生吉，夏孤克，秋吉，子少。寅午戌月，富显贵超群。神仙宰相。"}},"丙日未时":{"general":"丙日未时：丙日乙未时，生气印缀，丙见未为印库，如果通火气月，显贵；月令不扶，柱无财，不行财运，也作高命，","cases":{"丙子":"丙日未时：春，印缀穩厚。夏平穩，秋反復，冬显贵，运同。","丙寅":"丙日未时：生卯未月，印缀格，智慧丰厚，为妻子。寅已子辰年月，显贵。","丙辰":"丙日未时：春吉，夏平穩，秋碌，冬显贵。已午月，行西北运，六七品显贵。","丙午":"丙日未时：不显贵则富。午戌年月，職居风。申子辰，官星制刃；亥印未，印绶化刃，都吉。","丙申":"丙日未时：月令不扶火气，不见财星，作好命。年月子辰会官；亥卯会印，都显贵。","丙戌":"丙日未时：申子辰年月，近侍显贵。寅卯已年月，大显贵。"}},"丙日申时":{"general":"丙日申时：丙日丙申时，财旺身弱，丙遇到到庚为财，壬为鬼，申庚旺壬生，丙火无气，财须比肩分。如果月令不扶身旺","cases":{"丙子":"丙日申时：如果通火气及寅卯月再行身旺运，吉。年月纯金，命就财，也以吉。","丙寅":"丙日申时：时日对冲，聂伤妻子，通火气月，行身旺运，吉，亥月，手藝。丙辰日丙申時，寅月，","丙午":"丙日申时：多主血火厄，後大发。如果已月生，庚辛透露，财星格，武显贵。","丙戌":"丙日申时：柱无壬癸亥子酉字填实，作拱格，显贵。寅戌已午，身旺无依，僧道。"}},"丙日酉时":{"general":"","cases":{"丙子":"丙日酉时：春穩，夏显贵，秋平，冬吉。未申酉亥年月，大显贵。有魏会子，有辰会酉，都以显贵。","丙寅":"丙日酉时：卯亥未年月，韩透官杀者显贵。余月有藝，普通。","丙辰":"丙日酉时：寅午戌已年月，韩透杀印者显贵。申子会官，韩透印比者显贵。如年月火土，宜见财则吉。","丙午":"丙日酉时：生已午戌月，僧道命好；酉月显贵；亥子丑寅卯辰官印年月，大显贵。","丙申":"丙日酉时：通水木气月，行水木运显贵。已午，身旺。亥子，官旺。年月雨全者，大显贵。","丙戌":"丙日酉时：月通木气，行水运，显贵；通金气，行火运，金马玉堂，才名冠世。露庚藏戊，体弱早亡。"}},"丙日戌时":{"general":"丙日戌时：丙日戊戌时，寿永，名利不失去。寅亥卯未印及申酉戌已年月生，显贵。","cases":{"丙寅":"丙日戌时：翩堂食神，丙以戊为食神寿星，戊上丙火入库，戊土專位，如果通火气月及束南运，福","丙子":"丙日戌时：夏月，福寿雙全。春，木克土，食神被枭。寅月，丙戊都长生，最吉。有申庚制甲，","丙辰":"丙日戌时：午月，丙火有气，土厚地方，五六品显贵。亥月，金火运，风。","丙午":"丙日戌时：羊刃食神健旺，名利骤发，亥未辰戌年月，西方运，风。","丙申":"丙日戌时：亥月，束方运，显贵。寅午身旺，韩透财，吉。丑辰刑冲戌库，发于晚年。"}},"丙日亥时":{"general":"","cases":{"丙寅":"丙日亥时：夏生，化鬼为官，妻贤子孝，不显贵则富。寅卯辰已申丑年月，或午戌会局，天干更透","丙辰":"丙日亥时：日德格。寅月生，吉，辰月，为僧道多主富，平人孤克。戌月冲辰，已月冲亥，丙旺库，","丙午":"丙日亥时：武显贵。寅已午月生，妻重子晚，不显贵即富。秋冬，名利進退，酉午戌，大显贵。","丙申":"丙日亥时：春夏生，移根换，就妻改福。秋冬普通。酉月，行束南运，风。","丙戌":"丙日亥时：寅卯已午，木生火炎，妻伤子少，聪明富显贵；酉亥子丑，普通，束运也显贵。"}},"丁日子时":{"general":"丁日子时：丁日庚子时，身鬼旺，丁以庚为财，癸为鬼，子中有癸，丁火无气，不能助扶。如果通身旺月，有倚","cases":{"丁未":"丁日子时：辰戌丑未月，偏官有制。午月干強，显贵。余月有制伏，吉；戊子，文章秀。怕戊申","丁酉":"丁日子时：辰戌丑未月，刚明特达，显贵。辰已年月，显贵尊相府。怕甲寅月，破败恶死；癸已月，","丁亥":"丁日子时：五十後大旺。辰戌丑未月，吉。寅午年月，显贵。怕庚寅月，恶死；庚申月，身不全死；"}},"丁日丑时":{"general":"丁日丑时：丁日辛丑时，丑为财库，辛为妻财，已为食神，丑旺金局，暗己得到位，丁火无气，如果失去天時无依靠者，","cases":{"丁丑":"丁日丑时：申酉月，财格，财旺生官，显贵。午月，伤财身旺，多主官禄。纯子寅，武显贵三品。水月，","丁卯":"丁日丑时：辰已未年月，富显贵，妻子暹。寅卯印助，戌库身旺，刑。丑丁，得到依靠，大显贵。","丁未":"丁日丑时：时日冲，伤妻子。酉月，通水气，吉。运同。","丁酉":"丁日丑时：寅卯已午，身旺有托，多主文名高显贵，遇到非常。申酉戌，财旺之，最吉。亥子，官","丁亥":"丁日丑时：春印绶，吉，秋生，有火气也吉，夏太旺，不利。冬官杀旺，吉。未戌月，衢开丑库，"}},"丁日寅时":{"general":"丁日寅时：丁日壬寅时，身去徙官，丁壬化木，寅上健旺，如果水局之月，大显贵；通木月也显贵。如丁未月，行束方","cases":{"丁卯":"丁日寅时：显贵化吉。寅卯年月，行金水运，大显贵。亥子月，行西运，显贵。","丁未":"丁日寅时：恶死。春生印吉，夏，木火运，发福。秋富，冬显贵。酉戌年月，官至三品。亥卯寅戌，","丁酉":"丁日寅时：亥未寅卯申子年月，明富显贵，风極品。已午，宰相。辰月，行金水运；戌月，东","丁亥":"丁日寅时：日显贵格，配合壬寅，官印都全，文章显达。子月，大显贵，化气不利。"}},"丁日辰时":{"general":"丁日辰时：丁日甲辰时，印绶官库，甲为印，壬为官，辰中甲木印绶生身，官星合局，如果月令有扶助，有依靠者显贵，","cases":{"丁卯":"丁日辰时：辰戌丑未月，孤克，运通发财。丑月，南方运，显贵。卯月，金水运，近侍權显贵，不利","丁未":"丁日辰时：丑亥卯未月，印缀，官显贵。夏平。辰戌，显贵厚。酉午，金水运，大显贵。","丁亥":"丁日辰时：日显贵格，官禄得到位，必当达。申辰年月，大显贵。午月，束北运；辰月，北方运，都"}},"丁日午时":{"general":"丁日午时：丁日丙午时，青云得到路。丁火午上建禄，如果支无枭破，韩无癸刑，禄元纯粹，多主显贵。如支有子卯，干","cases":{"丁卯":"丁日午时：旺中有，卯字刑破白丁。已月。西北运，显贵；束南，品有。寅亥，武職二品。"}},"丁日未时":{"general":"丁日未时：丁日丁未时，火托木局，丁以甲为印绶，未为木库印绶之绑，如果柱不见财星，不行财运，月年通亥卯","cases":{"丁丑":"丁日未时：丑未刑冲，不得到善终。年月辰戌，四库全，显贵当品。申未，三品，法司淡薄清开。","丁卯":"丁日未时：刑中发。寅卯月，印缀，发财敦厚。辰戌申午，都吉。","丁未":"丁日未时：八專太旺，早克父母妻子，衣禄普通，为僧道吉。柱通金水木业金水运，衣禄安穩，","丁酉":"丁日未时：日显贵格。如果亥卯未寅月生，衣禄敦厚，寅月，金水运，金紫风。丁亥日丁未时，卯"}},"丁日申时":{"general":"丁日申时：丁日戊申时，身败背禄，丁以壬为官，申上见戊土伤克，如果年月干透，壬，见官为礼，有旺庚为财，","cases":{"丁丑":"丁日申时：秀显贵。未申年月，显贵；行束南运，大显贵。已月，西北运，六卿之職。","丁卯":"丁日申时：春，伤官用印；秋，伤官用财，都吉。夏，比肩；冬，伤官见官，普通。四季月，吉。","丁酉":"丁日申时：寅午戌丑辰未月生，伤官伤盘为奇，又日显贵格，多主登科第，运行金水，腰金衣紫。","丁亥":"丁日申时：日時相害，伤妻子。月令有扶助身旺者，显贵。年月戊戌、丁已，火土太重者目病。丁"}},"丁日酉时":{"general":"","cases":{"丁卯":"丁日酉时：时日亚冲，聂伤妻子，通火气吉。怕乙卯字。年月有亥未、已丑，但一字雨合，不以","丁亥":"丁日酉时：赛滞。如戊已丙丁年月，居近侍有權。卯甲乙寅，西北运，显贵。"}},"丁日戌时":{"general":"丁日戌时：丁日庚戌时，墓中遇到到，丁以庚辛为财，戊中有丙为败，不成其福。如果无救助，叠见癸水，多主伤目。","cases":{"丁丑":"丁日戌时：时日相刑，爱伤妻子。如果寅亥申酉年月，官至三品。午未子辰，行金木运也显贵。","丁卯":"丁日戌时：生亥未年月，三合会印，显贵。子月，杀印，吉。年月建禄，僧道，多主显贵。柱无救助，","丁未":"丁日戌时：多主刑。亥卯会印，申子辰会官，都多主文显贵。午月，建禄，有子冲，不利。如果年月用土生","丁酉":"丁日戌时：日显贵格，近显贵，业，有機谋。酉戌，六害，骨肉无情，秋月，五六品显贵。","丁亥":"丁日戌时：日显贵格。已酉丑年月，四五品显贵。寅卯亥，火金运，位至六卿。"}},"丁日亥时":{"general":"丁日亥时：丁日辛亥时，财官雙美，丁用壬为官，辛为财，甲为印，亥上有明辛为财，暗壬为官，生甲为印，如果","cases":{"丁丑":"丁日亥时：秋财旺，夏身旺，春印旺，显贵。冬，官杀太重，恐身弱不能勝任其福。","丁卯":"丁日亥时：时上财官印三奇，再得到年月印助财生，都多主大显贵。纯子，行木火运，官可六品，已酉","丁未":"丁日亥时：亥卯未寅辰午年月，韩透正印、正官者，聪明显贵；行西运，品。已丑月，风。","丁酉":"丁日亥时：显贵人捧印，显贵。子月，束方运，风患。柱有已丑会财，卯未会印，天干透财官印者，","丁亥":"丁日亥时：日显贵格，又三奇全，月令有扶助身旺者显贵。卯未三合印局，大显贵。"}},"戊日子时":{"general":"戊日子时：戊日壬子时，妻财都旺，戊以壬为妻财，子上壬水旺，戊土无气，生辰戌丑未月，不化者獲财。如果合","cases":{"戊子":"戊日子时：财星格。寅卯月，禄马朝元，显贵。酉亥丑年月，西北运，金紫风。怕乙卯年刑；","戊寅":"戊日子时：卯月，正官格，显贵。夏乖，秋少顺。丑酉年月，吉。怕已已月刑，已亥月不利刑。","戊辰":"戊日子时：春，财官旺、显贵。夏乖。秋少顺。冬财旺，行西南运，五六品显贵。怕庚辰月，自刑不利；","戊午":"戊日子时：時日亚冲，伤妻子。已午年月，风患。寅卯亥，六卿。申月，行木火运，侯伯。怕","戊戌":"戊日子时：寅已午年月，去财留印，三四品显贵。經云：能见羲忘利，取印舍财是也。子酉，五品"}},"戊日丑时":{"general":"戊日丑时：戊日癸丑时，戊以癸为妻财，丑中有癸余气财，癸旺，如果月令有扶助化为真火，为人明；如果通土气，","cases":{"戊子":"戊日丑时：戊月生，离气印绶，天干透丙丁字，不必格局，多主富显贵。如果年月午酉，干透庚乙，乙","戊寅":"戊日丑时：寅已午未戌月，化火吉。秋冬普通。","戊辰":"戊日丑时：寅已午未戌月，化火得到地，申子辰财局也吉。年月干支纯土，得到四库全者显贵。","戊午":"戊日丑时：寅戊未午年月，聪明特达威權。","戊申":"戊日丑时：辰戌丑未午月生，富显贵爱酒色。夏，束方运，显贵。秋冬，财旺生官，如果身弱，不天即","戊戌":"戊日丑时：夏生，东方运，显贵。辰戌丑未月，富显贵操，好花酒风流。化合南离局，财门日月开；"}},"戊日寅时":{"general":"戊日寅时：戊日甲寅时，身弱鬼旺，寅中甲建禄，丙生身，如通身旺月，有依靠有救助，化鬼为官，多主富显贵；反","cases":{"戊子":"戊日寅时：先破後发，显贵。未月生，干有制伏，显贵。午月无制，明近显贵。辰戌丑身旺，亥卯杀","戊寅":"戊日寅时：身旺，骨肉不同居。午月，刃印带杀；子月，正财杀，干透制；亥卯未，纯杀身柔，","戊辰":"戊日寅时：时上偏官，印绶带杀，柱有庚辛制伏者，显贵。辰戌丑未，身旺也显贵。","戊午":"戊日寅时：日羊刃，時偏官，以刃合杀，显贵。已酉丑月，刀筆人，制伏不宜太過；寅卯辰已戌","戊申":"戊日寅时：申酉，伤官带杀，土厚地方，显贵。魏卯年月，去杀留官，大显贵；要行金火运，位極人"}},"戊日卯时":{"general":"戊日卯时：戊日乙卯时，官強身弱，戊用乙为官，卯上乙旺戊死，如果无依靠，不月令有扶助，身弱化官为鬼，显贵","cases":{"戊子":"戊日卯时：时日相刑，伤妻害子，自成自立。年月再遇到，多主风。午酉，四正全，大显贵。","戊寅":"戊日卯时：亥子年月，妻贤子孝，显贵。卯辰纯，吉；寅已也吉。","戊辰":"戊日卯时：身孤，显贵。已卯年月，身強官旺，榮身显祖，子孝妻贤。","戊午":"戊日卯时：刃格，正官去刃爲福，子寅卯辰午未申亥年月，都多主显贵显。","戊申":"戊日卯时：中年破祖。春显贵。夏近显贵。秋孤苦。冬富显贵雙全。已月，木火运，五品上显贵。","戊戌":"戊日卯时：春官旺。夏，官印雙全，显贵显。秋平。冬显贵。戌丑年月，方面三品。戌月，行束方运，"}},"戊日辰时":{"general":"戊日辰时：戊日丙辰时，官藏财库，戊用壬癸为财，乙木为官，丙为倒食，辰上丙火无气，壬癸入库，乙有余气，","cases":{"戊子":"戊日辰时：春生近显贵。夏辛苦。秋，權高毒促。冬财，通火土，有依靠者显贵。","戊寅":"戊日辰时：龙吟虎啸，中年大显贵。子月，行北运，土厚地方，官至三品；束运，风。丑辰年月，","戊辰":"戊日辰时：克父大发，通身旺月，行束北运富；水木月，行身旺运，显贵。","戊午":"戊日辰时：亥卯年月，行束北运，富显贵。未丑，行西南运，风。"}},"戊日午时":{"general":"戊日午时：戊日戊午时，刃神重叠，戊以午为刃，性狠多剛，如见刑衡破害，刃神受制，月令有扶助者，为遗疆武職。","cases":{"戊子":"戊日午时：已寅戌月，风患。夏不熔，先刑後发，旺处多官。炎破祖。","戊寅":"戊日午时：戊月，三合火局，韩透癸化，得到天時地利者显贵。年月申子会水，寅午会火，有既济之","戊辰":"戊日午时：拱禄格，年月无寅已甲乙字，显贵。卯申，武職。酉丑亥，行南运，显贵。","戊午":"戊日午时：先刑後发，多不善终。寅已午戌年月，印缀，大显贵。纯午，武職威，名重藩。亥","戊申":"戊日午时：拱显贵格，年月遇到到寅，行南运，风患；遇到到午，显贵寿；戌文显贵。有未填实、已建禄相連一","戊戌":"戊日午时：大不利。卯午年月，官运，显贵。寅，印绶带杀，变不利爲吉。"}},"戊日未时":{"general":"","cases":{"戊寅":"戊日未时：先後易，显贵人提，不显贵即富。年月透甲制刃，地支午未身旺，杀刃雙，多主大显贵。","戊戌":"戊日未时：春，官旺，显贵。夏印安穩。秋平。冬孤苦。戌月，魁罡格，五六品显贵。须年月申子辰"}},"戊日申时":{"general":"戊日申时：戊日庚申时，戊以庚为食，壬癸为财，申上庚旺壬生，戊土有气，无丙火食破财，再无寅已刑冲，","cases":{"戊子":"戊日申时：如果生亥子月，也是合禄，显贵。","戊寅":"戊日申时：不利刑後发，如生寅月，作食禄制杀，显贵。","戊辰":"戊日申时：專食合禄，纯寅年月，二寅不怕一申冲，也显贵。","戊午":"戊日申时：未酉丑年月，柱无丙甲卯寅，入合禄格，行西北通，显贵；有甲丙又合神藏杀没，四柱","戊申":"戊日申时：身禄同案，富显贵雨全，子辰未酉年月，行西运，入合禄格，近上三品。年月丑戌，吉：","戊戌":"戊日申时：内，子月，也合禄格，文显贵三品。卯辰年月，大显贵。"}},"戊日酉时":{"general":"戊日酉时：戊日辛酉时，身败伤官，戊以乙为官，辛为伤官，酉上辛金旺，戊土沐浴，为人性傲行卑。年月透乙，","cases":{"戊子":"戊日酉时：已酉丑月，伤官伤，行财旺运，武職风。","戊寅":"戊日酉时：通土气月，行西北运，不显贵也富。","戊辰":"戊日酉时：丑未年月，干透财，多主显贵。如果癸已月，館学堂居提網，多主文学高科，寅申已亥年，","戊午":"戊日酉时：春夏普通。秋，伤官伤，權显贵寿促。冬，为妻子。","戊申":"戊日酉时：戌亥丑子年月，權显贵。","戊戌":"戊日酉时：辰戌丑未月，显贵。古人以水土败在酉，所以多无结果，或功名早退，或子息不成。觀"}},"戊日戌时":{"general":"","cases":{"戊子":"戊日戌时：酉申戌月，家财满目。辰、丑冲刑库开，都吉。","戊寅":"戊日戌时：寅午戌辰年月，金水运，大显贵。","戊辰":"戊日戌时：時日亚冲，伤妻子，如土厚地方，大显贵。卯月，火金运，中显贵。寅申戌丑，行西南","戊午":"戊日戌时：寅午戌月生，時火多，以印绶，未免孤克，先後易，不显贵即富。卯月，官星制","戊申":"戊日戌时：春显贵，夏平，秋富显贵，冬普通。","戊戌":"戊日戌时：秋富显贵。夏，西运；春，北运；冬，南运，都显贵。辰丑月，尤吉。"}},"戊日亥时":{"general":"戊日亥时：戊日癸亥时，戊合癸化火，火于亥，于水乡，不成其象，为人虚秀，多是九流藝術近显贵之人，多主","cases":{"戊子":"戊日亥时：年月不见戊字破格，显贵。申子年月，束南运；亥卯，南运，都显贵。已午未旺，大显贵。","戊寅":"戊日亥时：午未月生，化火会局，高命。春，官杀混，温衣禄。酉丑年月，三品京堂。","戊辰":"戊日亥时：秀。亥子月，财官格，不显贵则富。寅卯年月，显贵。夏生，教職。","戊午":"戊日亥时：显贵。寅已年月，土厚水秀地方，六七品显贵。卯未辰丑，都吉。","戊申":"戊日亥时：子未年月，无祖业，因妻导致富，不然移根换，穷苦就且。","戊戌":"戊日亥时：寅卯午已戌亥年月，天干透乙庚丁字，清要權显贵，宜火土运。"}},"己日子时":{"general":"己日子时：己日甲子时，明官暗财。已用甲为官，癸为财，辛为食，子为天乙显贵，子上有明甲暗癸，辛长生。身","cases":{"己酉":"己日子时：寅申午未丑年月，文显贵风。午月，束北运，品。怕庚寅年，破败恶死。己已月，"}},"己日丑时":{"general":"己日丑时：己日乙丑时，專财遇到到鬼，丑上有明乙为鬼，暗癸为财。如果有依靠通身旺者，显贵；通运也吉。如果鬼有助，","cases":{"己卯":"己日丑时：子申月，行金土运，侯伯。已酉丑戌年月，都吉。己已日乙丑时，寅卯月，偏官格。"}},"己日寅时":{"general":"己日寅时：己日丙寅时，官印生旺。已用甲为官，丙为印，寅上甲旺丙生。如果无破、通木局月气者，大显贵。喜","cases":{}},"己日卯时":{"general":"己日卯时：己日丁卯时，已以丁为印，乙为鬼，卯上明丁暗乙。如果月中无救助依靠者，虚秀不实，有成有。","cases":{"乙未":"己日卯时：不显贵则富；卯戊亥丑年月，吉。"}},"己日未时":{"general":"己日未时：己日辛未时，食神助官。已以辛为食，甲为官，未为官库，未上有明辛暗甲。如果有依靠月令有扶助，显贵。","cases":{}},"己日申时":{"general":"","cases":{"己卯":"己日申时：辰月，离气财官，早显贵。亥月、南方运，五、六品显贵。寅申年，三、二品显贵。"}},"己日酉时":{"general":"","cases":{"己酉":"己日酉时：偏财遇到食，多主。丑未子午都吉。酉月、内戚。如年月己酉全，犯破碎杀，多主一生"}},"庚日子时":{"general":"庚日子时：庚日丙子时，身鬼都衰弱。庚以癸为伤，丙为鬼。子上庚死、丙火无气、癸水健旺。如果身有依靠，吉；","cases":{"庚子":"庚日子时：显贵。年月再子，亚冲，午中丁爲官，已为印，人飛天禄马格；柱无财官填实，多主显贵；","庚寅":"庚日子时：春生，带财带杀，行金水运，金紫。夏，杀旺，大显贵。秋，身旺，须行南运，显贵。冬，","庚辰":"庚日子时：月通木火气，行西运，妙。乙已月，破败，刑。丁酉月，旺中刑，不利。己丑月，破，","庚午":"庚日子时：显贵。時日相冲，聂伤妻子，运喜西南，通火木月气，风三四品。秋生，丙火无气，","庚申":"庚日子时：申月，生土厚地方，显贵。辰未年月，行西运金，方吉。辛已月，不利刑。辛亥月，孤天。","庚戌":"庚日子时：春夏生。西南运；秋月、木火运，都显贵。怕乙已月，不利、破。乙亥月，官多，不利刑。"}},"庚日丑时":{"general":"庚日丑时：庚日丁丑时，金重火轻。庚以丁为官，以已为印，魏上丁火气轻，已土正位。如果通木火气月，官印遇到到","cases":{"庚子":"庚日丑时：春夏，显贵；秋普通；冬孤克。","庚寅":"庚日丑时：魁元。寅卯午未亥月，清秀高命。行午、未运，显贵。通火土年月，显贵。","庚辰":"庚日丑时：丑月，富就促。已，近侍，大显贵。通火旺土生月，显贵；不得到，运遇到也富，有名。","庚午":"庚日丑时：通土月气，显贵；不，也富，有名声。","庚申":"庚日丑时：丑月，金火运，極品。辰已午未戌月，官印雨旺，显贵。申、酉，身太旺，须行木火。","庚戌":"庚日丑时：春财旺；夏官旺；秋平淡；冬无力。"}},"庚日寅时":{"general":"庚日寅时：庚日戊寅时，火生金。庚以丙为鬼，戊为倒食。寅上有明戊、合癸化火，庚金气。如果月令不扶金旺月，","cases":{"庚子":"庚日寅时：寅午年月，登科达。申，三、四品显贵。丑月、金火运，公卿。","庚寅":"庚日寅时：月通火局或秋生，行身旺运，显贵。庚子月，自死。年见辛酉，体弱早亡残病。身弱见丙太","庚辰":"庚日寅时：春夏生，干透丙丁，运行身旺，显贵。","庚午":"庚日寅时：寅午戌月，金衰火旺，当带残病。纯寅，反多主極显贵。秋，金旺，多显贵，但怕時遇到亡劫，","庚申":"庚日寅时：時日亚冲，伤妻子。寅卯辰月、火金运。侯伯。春月、西南运，大显贵。寅月，显贵","庚戌":"庚日寅时：显贵。戌月，离气财官印绶，显贵。庚辰年，已卯月者，侯伯。"}},"庚日卯时":{"general":"","cases":{"庚子":"庚日卯时：子卯相刑，聂伤妻子，子年月，显贵。丑未，官至三品。一云破祖失去土，大显贵。","庚寅":"庚日卯时：亥卯月，财星格，早榮早退。午戌，三合官局，韩透金水，行西北运，吉。","庚辰":"庚日卯时：孤。年月通木气及有依靠者，显贵。","庚午":"庚日卯时：刑破。申子辰已酉丑，都行束南运，显贵。寅午戌亥卯未，须得到西北运为佳。","庚申":"庚日卯时：卯月，财星格，不显贵即富。丑已年月，翰林清显贵，官至亞卿。一云少穷苦，中年有小，","庚戌":"庚日卯时：少孤母，中年显贵。卯酉辰丑月，官至公卿。"}},"庚日辰时":{"general":"庚日辰时：庚日庚辰时，金水清白。六庚之中，庚戌庚辰为魁罡，怕见财官刑冲；不见，多主为人粗豪暴勇就显贵，","cases":{"庚子":"庚日辰时：申月生，井叉格。柱业运不见丙丁已午寅戌字，显贵。纯卯年月，位至公侯。","庚寅":"庚日辰时：龙虎拱门。年月通火土者，显贵。纯庚辰，王侯；不然，極不利。如果年月遇到木火，运再行，","庚辰":"庚日辰时：魁罡，年月不见财官亚戌字，显贵；衡破者富。申子年月作井叉，行西南运，吉。纯","庚午":"庚日辰时：自刑，金神入火乡。申月，行火木运，官可六品。","庚申":"庚日辰时：子、申年月入井叉。柱、运不遇到到丙丁已午字，显贵。纯庚申、庚辰，行西北束运，武","庚戌":"庚日辰时：魁罡，土厚地方，官高禄重。子月、西南运，显贵。寅辰年月，普通。"}},"庚日午时":{"general":"庚日午时：庚日壬午时，官印健旺。庚以丁为官，已为印，壬为食。午上壬食无气，丁已禄旺。通金土月气扶身","cases":{"庚子":"庚日午时：时日亚冲，聂伤妻子。通金气，显贵。火气，大显贵，但多聂禄。","庚寅":"庚日午时：辰戌丑未已申酉月，身旺，都显贵。寅午，火旺，运气再遇到，寿促；不然，残病。","庚辰":"庚日午时：食神旺，善飲食，有操持，发即死。","庚午":"庚日午时：寅午戌月、金柔火旺，畏缩残病。亥子午月、行木火运，显贵。","庚申":"庚日午时：禄马同乡，最吉。如午未年月，位至台阁。卯辰已，显贵。戌月、行火土运，清虚冷職。","庚戌":"庚日午时：卯月，正财，吉。未月，气财官，显贵。辰丑月同。壬庚会合臨午，无破无冲福自来；"}},"庚日未时":{"general":"庚日未时：庚日癸未时，印财库，庚以乙为财，未中入库，用丁为官，已为印，未中己丁有明癸制之。柱有己","cases":{"庚子":"庚日未时：年月无丁透露，有己土制伏癸水者，显贵。","庚寅":"庚日未时：显贵。辰戌丑未月，高。夏富。运同，已酉申月，身旺，大显贵。","庚辰":"庚日未时：魁罡日。辰中有土制癸。年月无丁；显贵。卯月，金水运，七品显贵。","庚午":"庚日未时：显贵。酉申已亥年月，總领兵戎，官至二品。先虚後实。","庚申":"庚日未时：酉月，武显贵，初年刹權。年月寅午戌、申子辰二局相参，显贵。","庚戌":"庚日未时：戌月、东方运，显贵。辰月卯年，大显贵。秋生最吉。夏，须行西北运。方吉。"}},"庚日申时":{"general":"庚日申时：庚日甲申时，日禄居时。庚金申上见禄，甲为偏财。柱中月令不扶丙火，已寅冲刑，多主显贵有普通。运同。","cases":{"庚子":"庚日申时：时犯日禄，见财星，柱无已寅丙，富显贵雙全。辰戌丑未土能生金，吉。寅午戌，普通。","庚寅":"庚日申时：寅、亥月，官至三品。","庚辰":"庚日申时：日魁罡，又归禄，都不喜财官、柱无寅午戌丙丁已字，显贵。","庚午":"庚日申时：显贵。通身旺月，无丙已寅午丁，伤破，显贵。","庚申":"庚日申时：显贵。无卯午未戌丙丁字，显贵。子丑月，金水运，文显贵。余见庚申、甲申，專禄归禄。","庚戌":"庚日申时：寅已午戌月，妻贤子孝，显贵。《神白經》运：金水带印，多主清聞之福。"}},"庚日酉时":{"general":"庚日酉时：庚日乙酉时，气化真金。庚以乙为财，辛爲刃，酉上财刃旺。如果化真金，柱中无火，金太剛则缺；","cases":{"庚子":"庚日酉时：多主富。月通火气，显贵：月令不扶，普通，运通也意。卯亥年月，帥间。一云破祖刑不利。","庚寅":"庚日酉时：刑。寅午戌吉。申子，兑暴。","庚辰":"庚日酉时：刑。寅卯午年等月，二品權显贵。戌亥大显贵。《神白經》云：化金，多主福厚。","庚午":"庚日酉时：刑，中显贵。寅午戌亥卯未二局，显贵。已，也吉。","庚申":"庚日酉时：真刑。寅午戌，大显贵。已酉丑，中显贵。申子辰，富。亥卯未，凋零，一云财吉。","庚戌":"庚日酉时：刑後发。寅午戌，官星明朗，显贵。亥卯未，富或五、六品显贵。已酉丑刃旺持，多主发"}},"庚日戌时":{"general":"庚日戌时：庚日丙戌时，金火持爭。庚以丙为鬼，丙火、戊土合局，金无气。如果通身旺印，卯月有救助者，显贵；","cases":{"庚子":"庚日戌时：春，偏官用财，吉。夏，杀旺身弱，兑暴。秋，身杀都旺。已酉丑月，西方运，腰金","庚寅":"庚日戌时：申子辰月，偏官有制，吉。秋生，身杀都旺，有禄權。纯午，孤穷苦无倚，不然残病。","庚辰":"庚日戌时：时日相冲，伤妻子。月通金水气，显贵。木火气重者，辛，体弱早亡或残病。","庚午":"庚日戌时：申酉亥魏、富，显贵三品。已午未申，透出壬字，艮坎乾方运，卿相有寿。","庚申":"庚日戌时：戌亥年月，东南运，显贵。申月，大显贵。","庚戌":"庚日戌时：辰戌丑未、印绶生助，吉。申子辰，偏官有制，显贵。月通金气，不透壬字，行北运，"}},"庚日亥时":{"general":"庚日亥时：庚日丁亥时，庚以甲为财，壬为食，丁为官。亥上丁火无气，壬旺甲生，庚金失去地，任财食。如果不","cases":{"庚子":"庚日亥时：显贵。申子辰月，伤官、碌。卯月、金火运、五六品显贵。","庚寅":"庚日亥时：平，初穷苦，中秀，末多主富旺。辰戌年月，显贵显。申酉亥卯已午年月，乾透乙已者，大","庚辰":"庚日亥时：纯未，达。已午，西北运，风慧、金紫。亥卯、金紫，有權。申月，建禄，最吉。","庚午":"庚日亥时：显贵。辰戌丑未月，土能生金，榮。申亥酉月，行木火运，極品。","庚申":"庚日亥时：秋生，南运，显贵；北运，普通。","庚戌":"庚日亥时：辰已午月，官杀混，也多主武显贵。丑月，西运，郎官。辰月，西北运，方面。"}},"辛日子时":{"general":"辛日子时：辛日戊子时，六朝阳。辛金子上长生学堂。辛以戊为印。癸为食，时上明戊暗癸，柱中不见丙丁午","cases":{"辛丑":"辛日子时：丑月，气财官，显贵。纯丑，儒職。纯辰、行西运，都患。酉月，束北运，显贵。怕庚","辛卯":"辛日子时：春生，寅穷苦、卯显贵。夏清显贵。秋羊刃，无益。冬富，丑月尤吉。辰戌未月，财官印缀、","辛未":"辛日子时：显贵。寅已午酉年月，火木运，显贵。亥子，翰苑。辰戌丑未，气财官印，都吉。怕庚","辛酉":"辛日子时：子酉月生，无丙丁火，不行南运，三、四品显贵。伤妻子；武職權重。《神白經》云：金","辛亥":"辛日子时：不显贵则富。亥月，无官，伤官伤，发福子少。春夏，亥子丑，木火运局，金紫风。"}},"辛日丑时":{"general":"","cases":{"辛丑":"辛日丑时：孤滞生。申酉月，金旺，运行火乡，疏通，刑伤妻子；为僧道，显贵。纯丑，西南运，","辛卯":"辛日丑时：寅卯亥未等月，财星格，南方运，显贵。辰戌丑未，印缀，南方运，吉。","辛未":"辛日丑时：寅卯未月，财星格。已午，官。","辛酉":"辛日丑时：破祖。已酉丑月，金多克木，俊俏有财，为妻子。寅午月，近侍，显贵。","辛亥":"辛日丑时：寅已午月，官星明朗，立計成象。卯未，财局，富显贵。未戌，冲，吉。申、子、辰月"}},"辛日寅时":{"general":"辛日寅时：辛日庚寅时，显贵人财官。辛以寅为天乙显贵，丙火为官，甲木为财，寅上丙、甲旺，如果通金木月气或通","cases":{"辛丑":"辛日寅时：春显贵；夏官旺；秋显达；冬吉。丑月、南运，风或武显贵。一云发即风病。年月酉、","辛卯":"辛日寅时：午未亥子，都显贵。寅卯申酉，六、七品显贵。","辛未":"辛日寅时：已未丑月，名標金標，妻贤子孝，晚年风病。寅卯午戌，都吉。","辛酉":"辛日寅时：显贵。春财聚；夏官禄成；秋身旺；亥子丑戌午酉等年月，都显贵。","辛亥":"辛日寅时：显贵，多主有暗病。韩透丙，发。午酉寅亥年月，南方运，显贵。"}},"辛日卯时":{"general":"辛日卯时：辛日辛卯时，比肩分财。辛以乙为财，卯上乙旺，遇到比分，损伤妻子。生秋冬，财官无气，普通。","cases":{"辛丑":"辛日卯时：春、夏生土厚地方，富显贵。秋，克妻刑子。冬、辛。寅已午月，近待，显贵。甲戌年","辛卯":"辛日卯时：寅午戌月，财官雙美，显贵。卯酉申辰年月，近侍，显贵；见官印财星，妙。一云先苦，","辛未":"辛日卯时：纯未、丁年月，大權显贵，不善终。寅已亥，纯吉。","辛酉":"辛日卯时：出身孤苦，中年獲福，末年封妻子，显贵。已月，官印遇到到天德，显贵当一品。丑月、木","辛亥":"辛日卯时：春夏，财官雙美，显贵。秋冬，背禄逐马、碌反復。亥，金水泄秀，多发高科。"}},"辛日辰时":{"general":"辛日辰时：辛日壬辰时，暗金沈水底。辛用丙为官，壬为伤官，辰水库，丙辛无气，壬水合局。如果年月透丙，是","cases":{"辛丑":"辛日辰时：春，财旺，妻贤子孝。夏，伤官见官，然也多富。秋吉。冬，孤克，多显贵。","辛卯":"辛日辰时：春、伤官生财。夏，行藏反復，或兑暴。午未也奇。秋，申酉身旺，得到火则吉。冬，","辛酉":"辛日辰时：春，富显贵雙全。夏好。秋身旺，显贵。冬，白丁；子月，辛生地，学堂，多主文学。年月","辛亥":"辛日辰时：显贵。春，财旺扶身。夏吉。秋身旺，好。冬，伤官伤，自立自成。卯未年月，显贵。"}},"辛日午时":{"general":"辛日午时：辛日甲午时，鬼旺身弱。辛用丁为鬼，已为倒食，甲为财。甲午木死则神无气，丁已健旺，见午为","cases":{"辛丑":"辛日午时：未申年月，四柱有利害，虽富寿天。通金，虽显贵不永。","辛未":"辛日午时：申子辰，偏官有制，吉。丑戌，方面。未月。显贵。","辛酉":"辛日午时：春，财旺；夏，官显贵，都吉。秋，身強，富不永，冬，普通。","辛亥":"辛日午时：亥子年月，金水》亟秀，文学堪。辰戌丑未、气财官，显贵。"}},"辛日未时":{"general":"辛日未时：辛日乙未时，天财入库。辛以乙为财，未上入库；已为倒食，丁为正鬼；未上有暗丁，已被明乙制伏，","cases":{"辛卯":"辛日未时：亥卯未月，财盛生官，吉。","辛未":"辛日未时：寅卯未年月，财旺生官，名高禄重。通火气，行西运；通金气，行南，都吉。","辛酉":"辛日未时：月通火气，行束运，显贵。辰戌丑未，最吉。亥卯，显贵显不久。秋生，身太旺，财官无","辛亥":"辛日未时：亥卯未月，财星格。吉。秋冬，孤。辰、丑，近侍三品。"}},"辛日申时":{"general":"辛日申时：辛日丙申时，丙辛化水，申上长生。如果月通已酉丑金气者，精神秀麗，文章聚福。通火气旺、有依靠","cases":{"辛丑":"辛日申时：化显贵。少年赛刹，中显贵显。亥月，作化气看。吉。寅午戊已未月，官星有气；春，财","辛卯":"辛日申时：化显贵。寅已午未戌酉亥月，官星明朗，山明水秀，登科榮显贵。通士气，也显贵。一云少","辛未":"辛日申时：因显贵人门下得到富。春，清显贵。夏，普通。秋，富。冬，大显贵促。《神白經》云：金水","辛酉":"辛日申时：寅已午戌月，官旺，榮显贵。神白經云：水化多主显贵。","辛亥":"辛日申时：发福，防孤克带病。通金气，多主人秀麗福厚。通水气，大显贵。"}},"辛日酉时":{"general":"辛日酉时：辛日丁酉时，火金持爭。辛金酉上健旺，见丁为正鬼；酉上丁长生，破禄，不成其福，反復成。身","cases":{"辛丑":"辛日酉时：高平穩。酉月、土木运，方面。戌亥子已未年月，大显贵。","辛卯":"辛日酉时：時日冲。月通金气，不透丙丁，南方运，显贵。","辛未":"辛日酉时：不显贵则富。月通金气，无丙丁字，行南运，显贵。","辛酉":"辛日酉时：年月通金气，吉。丑月，西方运，风。寅午戌，显贵。","辛亥":"辛日酉时：显贵。丑寅卯酉年月；近待、金紫。"}},"辛日戌时":{"general":"辛日戌时：辛日戊戌时，禄同印堂同居。辛以戌为禄堂，戌上有明戊为印绶；以丙、丁为官，戌上戊土正位，丙、","cases":{"辛丑":"辛日戌时：刑害。辰戌丑未，印绶，行南运，大显贵。寅已，正官，显贵。子午卯酉，武職风。","辛卯":"辛日戌时：刑害，餮。亥，卯月，木火运，五、六品显贵。","辛未":"辛日戌时：兑恶狠暴，聂伤妻子。寅已午戌丑月，显贵。申子辰亥，金水》亟秀，尤显贵。一云克父","辛酉":"辛日戌时：不利刑。已酉丑辰戌未年月，魁元，卿、尹之命。","辛亥":"辛日戌时：兑狠、機谋奸猾，計较。一云不利後发。"}},"辛日亥时":{"general":"","cases":{"辛丑":"辛日亥时：辰戌丑未及寅卯月生，作飛天禄马，显贵。未月，金水运，金紫方面。","辛卯":"辛日亥时：寅卯亥未月，财旺生官，终身有。已酉丁年月，显贵。","辛未":"辛日亥时：显贵。亥卯未寅月，金能克木，为财盛生官，名利显贵，已午年月，富显贵。秋生，透丙，","辛酉":"辛日亥时：辰戌丑未、气财官，吉。纯亥，冲已中丙火为官，显贵。"}},"壬日子时":{"general":"壬日子时：壬日庚子时，刃旺身強。壬以庚为倒食，癸为羊刃，时上明庚癸旺，如果通火土月气，制伏庚癸，大显贵；","cases":{"壬子":"壬日子时：辰戌丑未月，气财官；已申酉丑，印缀，居土厚分野，都显贵。寅月，金水运，近侍","壬寅":"壬日子时：显贵就刑。辰戌丑未月，离气财官；已申酉月，印缀，都显贵。怕乙已月受刑，丁酉月大","壬辰":"壬日子时：如果寅午月生，财星旺；辰戌丑未，官旺，都吉。纯辰，透庚壬，作壬龙背格，大显贵。","壬午":"壬日子时：時日亚冲，女多男少。丑未月，行南运，富显贵。余年月，觀显贵命可见。怕甲午月自","壬申":"壬日子时：穷苦、刑。未月，气财官，行财旺运显贵，先後易。辰，会水太旺，须行火土运，","壬戌":"壬日子时：天。丑月金火运，辰未财官格，都显贵。寅酉，行西北运，显贵。申子辰，行束南运，極"}},"壬日丑时":{"general":"壬日丑时：壬日辛丑时，官印得到位。壬以已为官，辛为印，上金局，暗已得到位，如果月令有扶助，为人清秀，禄显贵安","cases":{"壬子":"壬日丑时：已酉丑月，印缀，多受父母。申月，火土运，近侍有權。辰戌丑未，有官有印，丰","壬寅":"壬日丑时：丑月，气印绶高。辰已，杀強无制伏，财官身弱，辛苦。","壬辰":"壬日丑时：辰戌丑未，气财官印缀，都吉。春平，夏财禄，秋吉，中有不利。冬身旺，须行南运","壬午":"壬日丑时：禄马同乡，显贵。夏吉。秋，财官印全，也显贵。","壬申":"壬日丑时：寅卯亥未年月，進士风，官至二品，终有起倒。辰戌，富足。申酉，享用自然，行","壬戌":"壬日丑时：辰月，衡开财官，显贵。丑戌，也吉。柱有乙癸卯字，普通。"}},"壬日寅时":{"general":"壬日寅时：壬日壬寅时，水火既济。壬用丙为财，甲为食，寅上丙生甲旺，壬水无气，如果通水局，有依靠，都显贵，","cases":{"壬子":"壬日寅时：纯子，年月无午衡破，入飛天格，富显贵。寅卯已申酉戌亥年月，都显贵。","壬寅":"壬日寅时：壬趣艮格，土厚地方，山明水秀，腰金衣紫。已亥年月，武職三品，富厚纯篱。寅年","壬辰":"壬日寅时：纯辰，壬骑龙背格，干头无丙丁戊己，运行比肩，大显贵。纯寅大富。卯戌月，木金运，","壬午":"壬日寅时：少年多病厄。壬午，禄马同乡。辰寅年月，二品显贵。申酉，高尚，如果通木火，才名冠","壬申":"壬日寅时：已酉丑月，武職三品。辛卯、戊月，也显贵。子寅，大显贵。一云穷苦就发，也不久。","壬戌":"壬日寅时：已月，偏官格，名標金榜，身坐玉堂。纯子，三品，寅卯，行北运，风。又，六壬"}},"壬日卯时":{"general":"壬日卯时：壬日癸卯时，身死刃生。壬以癸为刃，卯为暗乙，就伤官鬼。卯上癸生乙旺壬死，月令不扶身旺月气，无","cases":{"壬子":"壬日卯时：子卯相刑，聂伤妻子，显贵人提，财帛盈余，敦厚之命。","壬寅":"壬日卯时：背财禄，或兴或。子年月，显贵。已月，财官虽刑，也显贵。辰戌丑未，官杀制刃，","壬辰":"壬日卯时：通身旺月，见土金破刃，行财运，显贵。","壬午":"壬日卯时：壬居午位，禄马同乡，又遇上卯时，显贵榮达。已午年月，武職风。","壬申":"壬日卯时：亥卯未寅月，伤官伤盏，妻贤子孝，土厚显贵命。纯辰，医萄。子月水木，显贵。","壬戌":"壬日卯时：甲癸午酉年月，文显贵。申，普通，金火运，显贵。"}},"壬日辰时":{"general":"壬日辰时：壬日甲辰时，也为壬龙背。壬以甲为食神，辰上壬水合局，甲有生气，食神旺相，月令有扶助者富显贵福","cases":{"壬子":"壬日辰时：纯子年月，飛天禄马，无破，六卿。已酉，大显贵。亥，也显贵。","壬寅":"壬日辰时：已月偏官格，不冲不破，显贵。午，正官，显贵。辰卯局全，束方，少年登科，榮显贵。","壬辰":"壬日辰时：辰月生，壬龙背，大显贵。寅月，不显贵即富。戌月，气财官，衡开辰库，高命。子","壬午":"壬日辰时：水火炎。寅辰年月，翰苑宿儒，或居祭酒。纯子，风。卯寅，富厚。辰子，儒職。","壬申":"壬日辰时：水火炎，丑寅年月，文行武權。纯子，金火运，方面。","壬戌":"壬日辰时：寅申酉月，行南运，显贵戚。亥卯未申子辰已午年月，都吉。"}},"壬日午时":{"general":"壬日午时：壬日丙午时，禄马三奇。壬以已为官，丙丁为财，午上丁已是禄马，壬水受胎，有依靠，通金水月气，","cases":{"壬子":"壬日午时：公直撑持，孤高就显贵。年月子午，字重，水火既济，品。","壬寅":"壬日午时：寅午戌月，财星格，但嫌身弱，宜僧道，吉。秋生，印缀。冬，身旺，行金火运，金","壬辰":"壬日午时：寅午戌月，财旺，大显贵。","壬午":"壬日午时：冬日身旺，吉。夏，财多身弱，丑日近侍，显贵。寅午，金土运，獨弱強，命就财，","壬申":"壬日午时：通金水月气，显贵；月令不扶，命就财，多主富，不然，極穷苦苦。","壬戌":"壬日午时：寅月，三合财局，命相，富。秋，身有托，显贵。冬也吉。"}},"壬日未时":{"general":"壬日未时：壬日丁未时，夫妻化，壬合丁，未上同木局，显贵。如果月通木局，有依靠者发财，月令不扶，但有资助，","cases":{"壬子":"壬日未时：月通木气，显贵；通金气，富，通火土气，富显贵；两全月令不扶，行火土运，也吉。","壬寅":"壬日未时：丁壬化木，亥卯未，寅月，显贵。","壬辰":"壬日未时：辰月生，壬龙背局，显贵。寅月，妻重子榮。三合水局，身旺无倚，多穷苦克妻。","壬午":"壬日未时：春平，夏富，秋显贵，冬吉。已午年月，位至王候。未月，束运，显贵。子月，正印、三","壬申":"壬日未时：大富。已午年月，或透戊己，富显贵雙全。","壬戌":"壬日未时：日德，封妻子，中年又損妻子。亥子申酉月，显贵。已午，不显贵即富。辰月天，月德"}},"壬日申时":{"general":"壬日申时：壬日戊申时，水土混澜。壬以戊为鬼，庚为印，申上庚金健旺，壬水长生，戊土偏官，身鬼都強，为","cases":{"壬子":"壬日申时：羊刃带杀，显贵人提。已午年月，近侍有。","壬寅":"壬日申时：时日相冲，身孤为僧道，吉。如寅午戊或纯辰年月，也显贵。","壬辰":"壬日申时：戌月生，早登科甲，官至方面。寅卯丑申子午等年月，显贵，武職一品。","壬午":"壬日申时：偏官偏印。亥卯未寅月，威權。子丑月，木火运，翰林清显贵。戌月，行束南运，高品。","壬申":"壬日申时：壬水长生，居申，杀旺身強，更生亥卯未月，偏官有制，吉。","壬戌":"壬日申时：破滞多赛。纯酉，巨富。如果月令不扶身旺月，行杀旺乡，不吉。有甲制也可。戊己土重，"}},"壬日酉时":{"general":"","cases":{"壬子":"壬日酉时：春平，夏吉，秋常，冬旺。如卯月生，好花酒。","壬寅":"壬日酉时：大富显贵，喜通水气，行官运，显贵。但好花酒，风流人物。","壬辰":"壬日酉时：高，月同日，壬龙背，大显贵。已月，行束北运，显贵。","壬午":"壬日酉时：禄马同乡，先後易。魏寅月，行金水运，武職二品。","壬申":"壬日酉时：官印臨门，局中无衡破，禄马雙全，不显贵即富。戊月生，束南方运，腰金衣紫。","壬戌":"壬日酉时：亥寅子月，行财官运，显贵非常。纯亥，文显贵。"}},"壬日戌时":{"general":"壬日戌时：壬日庚戌时，枭臨财库，壬以丙丁为财，库于戌，庚为倒食，戊偏官，如果通火木月气，有依靠者，显贵；","cases":{"壬子":"壬日戌时：名利進退，庚辛年月，显贵。辰魏，刑冲；酉月，破害，财库得到用；已午，财官旺，都","壬寅":"壬日戌时：刑妻克子。如果春生，平，夏、冬，吉。辰丑未月，显贵。","壬辰":"壬日戌时：夏月，不富则显贵，春平，秋穩，冬辛勤苦，或为僧道，有财破刑。","壬午":"壬日戌时：禄马同乡，壬自坐禄，有庚辛制甲乙为显贵。辰戌丑未年月，吉。申月学堂，文显贵大。","壬申":"壬日戌时：通火木月气，富显贵；月令不扶，行通运，也好。丑戌年月，大显贵。","壬戌":"壬日戌时：不利妻，多主被妻妾害，反覆成败。纯戌，显贵。寅丑，武職。申月，长生学堂，修文多"}},"壬日亥时":{"general":"壬日亥时：壬日辛亥时，日禄居時，无克破，有依靠，柱中不见财官，富显贵达；行束运，大显贵；如果通气，减福；","cases":{"壬子":"壬日亥时：多主父母不得到善终，後发不富。亥卯年月，文章進身，大显贵。","壬寅":"壬日亥时：中发。未月，气财官，敦厚，中年显贵，五十後终。亥月，东南运，方面。","壬辰":"壬日亥时：秀显贵、惡死，午月，乾头无己土，青云得到路，如果有甲合，为去官留杀，三四品显贵。酉","壬午":"壬日亥时：平。魏月，风。寅月，禄马同乡，行金水运，方面。戌月，束北运，四五品。丑午，","壬申":"壬日亥时：显贵。辰戌丑未，气财官，吉。年月干无已土，入日禄格，酉月申卯年，行束北运，","壬戌":"壬日亥时：少年富显贵。亥申已戌年月，一二品显贵。纯戌，水火运，金紫。"}},"癸日子时":{"general":"","cases":{"癸丑":"癸日子时：午寅、乙丑，已丑年月，文職四五品，通身旺木气月，无戊已午已字，显贵。未，风","癸卯":"癸日子时：時日相刑，伤妻克子，近显贵；无已土，威權。如果亥已都全，進士烏府。年月寅，伤","癸未":"癸日子时：申酉月，显贵。戌亥，大富显贵。寅卯，孤。辰已，不利。怕壬申月，身不全，不利；庚辰月，","癸酉":"癸日子时：行藏進退，少子为妻家。怕丙寅月，不全死；乙已月，大破不利死；丁酉月，自缢","癸亥":"癸日子时：显贵。亥月生，飛天禄马，登科甲第，大显贵。又癸禄居子，壬禄居亥，日時互换，三四"}},"癸日丑时":{"general":"","cases":{"癸丑":"癸日丑时：丑已中丙戊为财官，如果生丑寅申子酉三合年月，多主妻贤于孝，榮显贵特达；火土运不利；","癸卯":"癸日丑时：日显贵格，身孤克，多主显贵。丑寅辰年月，韩支无戊己已午卯字，品。","癸未":"癸日丑时：子丑寅年月，显贵，中年富。卯月，行金水运，品。辰戌，四库全，大显贵。","癸酉":"癸日丑时：福德秀气格，学问源，行藏進退，为妻家。","癸亥":"癸日丑时：拱禄格，怕衡破、填实，柱无子已午未字，大显贵。寅午戌月，南方运，六七品。"}},"癸日寅时":{"general":"癸日寅时：癸日甲寅时，刑合财官，癸以丙为财，戊为官，寅刑出已中丙戊为财官，如果柱无官杀及刑衡破害損格，","cases":{"癸丑":"癸日寅时：本显贵，丑中有辛金，减其分数。纯水年月，官至一品。秋生印缀，也显贵。辰月，行束","癸卯":"癸日寅时：亥卯未月，至显贵。寅卯年月，刑合格，侯伯。寅亥，四品。寅月，西运，金紫。丑戌","癸未":"癸日寅时：多主秀实，中年显贵。如果生已未已已年月，武显贵。","癸酉":"癸日寅时：金神格。寅午戌月，结火局，显贵特达，官至二三品。怕丑年，不显贵。已未亥子年月，","癸亥":"癸日寅时：子丑未申月，進士，运行金水，风。卯戊年月，地支六合，显贵。"}},"癸日卯时":{"general":"癸日卯时：癸日乙卯时，食神乾旺。癸以乙为学堂食神，卯上癸水长生，乙坐禄，柱中无已破辛，午酉刑冲，","cases":{"癸丑":"癸日卯时：辰丑月，高显贵。一云：少中年显贵。","癸卯":"癸日卯时：。生寅卯月，伤官格，言富显贵。未戌年月，技藝近显贵。辰丑，吉。已、丙子，","癸未":"癸日卯时：寅亥卯未月，伤官伤，剛普通。辰戌申子月，显贵。","癸酉":"癸日卯时：申子辰月，显贵。寅午戌，中。亥卯未，平。已酉丑，富。","癸亥":"癸日卯时：辰己月，风惠。"}},"癸日辰时":{"general":"癸日辰时：癸日丙辰时，身坐官库，癸用戊已为官，辰上土墓为官库，见丙为财，辰为水局，丙火无气，癸水合","cases":{"癸丑":"癸日辰时：平。辰戌丑未月，财官有气，显贵。","癸卯":"癸日辰时：孤獨离为椿萱，有财帛，显贵，人钦敬。卯亥年月，日显贵格。午戌，九品至五品。寅月，","癸未":"癸日辰时：高。寅卯未月，普通。辰戌丑月，吉，已月，财官都旺，显贵。","癸酉":"癸日辰时：孤，显贵。已酉丑月，显贵。寅卯，不吉。子午，富。戌月，大显贵。","癸亥":"癸日辰时：柱无甲木破损官库，显贵，运南。"}},"癸日午时":{"general":"癸日午时：癸日戊午时，化气成火局，癸合戊化火，午上帝旺，合局就显贵，身旺不化癸水，地方之气引到南方，","cases":{"癸丑":"癸日午时：财厚，南运多主显贵寿促，束运吉。","癸卯":"癸日午时：申子辰亥月，身旺不化，普通。卯戌月，显贵。","癸未":"癸日午时：寅午戌，化火合局，显贵。","癸酉":"癸日午时：多主伤妻家财，有始无终，子年子显贵就无禄，行南运，好。","癸亥":"癸日午时：显贵，未月，束方运；金月有制，都显贵。"}},"癸日未时":{"general":"","cases":{"癸丑":"癸日未时：高。年月都丑，穷苦薄。辰戌丑未，土旺，多主目病、穷苦。通金木水气，显贵。午月，东","癸卯":"癸日未时：子已未年月，二品。已寅字，刑六親。","癸未":"癸日未时：高。春偏官有制，吉。夏，普通。秋、冬身旺，申月行木运，显显贵。已辰年，六卿。","癸酉":"癸日未时：寅已申酉丑戌年月，显贵。"}},"癸日申时":{"general":"癸日申时：癸日庚申时，作專印合禄。癸以戊为正官，庚为正印，申上庚旺戊生，以申合已中戊丙，癸日得到财官，","cases":{"癸丑":"癸日申时：辰戌丑未年月，文章冠世，官至三品。子月坐禄，也吉。","癸卯":"癸日申时：卯月作合禄格，西北运，显贵，金紫。申月，束北运，风惠。庚辰、庚戌年月，正官格，","癸未":"癸日申时：柱有甲寅，乙卯，已舆甲合，乙舆庚合，妻贤子孝，榮华在後。酉申年月，三四品。","癸酉":"癸日申时：卯酉戊寅年月，显贵。申酉，火木运，大显贵。","癸亥":"癸日申时：性平身孤。卯未月，学，显贵命。申，也显贵。子申，近侍有權。"}},"癸日酉时":{"general":"癸日酉时：癸日辛酉时，明暗枭神。癸见辛为倒食，酉上辛建旺，癸失去地，如果无依靠救助者，遇到显贵生涯；有依靠","cases":{"癸丑":"癸日酉时：秋月，印绶格，行官杀运，吉。冬，福禄雙全。子寅年月，干头无戊已字，显贵。","癸卯":"癸日酉时：日显贵格，辰戌丑未月，显贵。子卯年月，大显贵。已午，也显贵。又云不利妻子。","癸未":"癸日酉时：春穷苦，夏先後易，秋吉，冬显贵。","癸酉":"癸日酉时：申酉月，印绶多，能守祖，破妻家。子已午月，韩透庚辛，禄显贵印缀都全，显贵不可言。","癸亥":"癸日酉时：戊月，行东南运，金紫；束北，风惠。子月建禄，年遇到财官，大显贵。"}},"癸日戌时":{"general":"癸日戌时：癸日壬戌时，水火既济，癸用丙丁为财，戊土为官，戊舆癸合旺，为人智谋，月令有扶助有依靠者显贵；不","cases":{"癸丑":"癸日戌时：刑，亥月，土厚地方上显贵。辰申年月，南方运，状元。五月，南运，都。如果春秋生，","癸卯":"癸日戌时：日显贵格，寅已年月，韩透戊丁财官就旺，大显贵有權。卯辰丑午子等年月，文显贵。酉戌，","癸未":"癸日戌时：刑。已月生，三四品。子庚年月，近侍显贵。癸酉日壬戌時，亥子月，才智高显贵，妻贤","癸亥":"癸日戌时：春生，伤官见官，夏财旺，秋、冬吉，名利有成。戌辰月，行亥子运，显贵。子月，行"}},"癸日亥时":{"general":"癸日亥时：癸日癸亥时，禄马飛天格，癸水亥健旺，癸用戊为官，丙为财，亥中丙戊都，癸无财官，亥去冲","cases":{"癸丑":"癸日亥时：作拱禄格。已酉丑生，福德秀气。午月普通。卯酉月，行南运，金紫风惠，但为。","癸卯":"癸日亥时：平，日显贵格。寅卯月，伤官，行金水运，风。辰戌魏未月，官旺。纯卯，三品显贵。","癸未":"癸日亥时：身下坐财官。辰戌丑未月，行束北运，显贵。秋月，束运，七八品显贵；干透正印、正官，","癸酉":"癸日亥时：辰戌丑未月，生涯遂意。酉月，行束北运，八九品显贵。申月，东方运，五品。","癸亥":"癸日亥时：性飘逸，中年大富。冬月生，飛天禄马，无戊已子字填实惹绊，显贵；不然，孤克"}}}},"reading_bazi/rishi_cases_plain":{"note":"甲日细则的逐条白话改写（第一批 64 条）。只改说法，不改断语方向。","items":{"甲日子时":{"甲子":"甲子日甲子时：年月不见庚辛申酉，也没有丑午来冲，离祖自立反而能贵；年月都是寅，再走到申酉运就要当心。","甲寅":"甲寅日甲子时：暗拱丑里的辛为官，显贵；年月不见庚辛申酉丑未，更贵。甲寅月生则孤克，做僧道反而合适。","甲辰":"甲辰日甲子时：水多木浮的月份，多半离乡改名；申月杀星会印，贵；子月走水木运，也贵。","甲午":"甲午日甲子时：日和时相冲，伤妻子；通木气月则贵。纯子午年月，或亥未酉月，都贵。","甲申":"甲申日甲子时：胎地遇印、印能化杀，显贵；杀太重则子息缘薄。走东南运，可做文武官职。","甲戌":"甲戌日甲子时：拱亥为天门、会帝阙，是甲的长生地，不算隔角。年月通申巳酉丑金气，大贵。"},"甲日丑时":{"甲子":"甲子日乙丑时：连珠合财，妻贤子贵；春月身旺财易散，夏月有制则贵，秋生近侍之贵。","甲寅":"甲寅日乙丑时：春生贫穷，秋生贵，冬生富，夏月火能制金也吉。","甲辰":"甲辰日乙丑时：多半富厚有财；通火气年月，显贵。","甲午":"甲午日乙丑时：金神入火局，身弱多病；寅戌会火更不利。单见寅或戌，或见申酉亥，反而好些。","甲申":"甲申日乙丑时：带病平常；子月生走南方运则贵，秋月化杀、天干透印绶更贵。","甲戌":"甲戌日乙丑时：田产连片、仓里陈粮，只是先有刑伤；寅年月父子都贵，子月走西方运至金紫。"},"甲日寅时":{"甲子":"甲子日丙寅时：日禄归时，青云得路；年月无庚辛金则贵，通木火气极贵。午月走东北方运，可至五六品。","甲寅":"甲寅日丙寅时：年月不见巳酉辛丑，是归禄格，位至一二品；纯木火带土，富贵双全，可至六卿。","甲辰":"甲辰日丙寅时：龙虎拱门、龙吟虎啸，多主显贵或有显贵提携；财源时得时失，名利半济。","甲午":"甲午日丙寅时：身坐死地，多半平常；通水月木得滋养则吉，火月寿短，天干有比劫帮身无妨。","甲申":"甲申日丙寅时：日时相冲，伤妻子；年月日同气则大贵，巳亥二三品，辰子年月以杀化印。","甲戌":"甲戌日丙寅时：年月有土则富，见金反复；见金要生亥子印月才贵，别的月份不然。"},"甲日卯时":{"甲子":"甲子日丁卯时：克剥吝啬、做事进退，不免刑伤妻子或客死他乡；生辰戌丑未月则贵，卯月不利。","甲寅":"甲寅日丁卯时：年月木火相停，成「通明」之象，显贵；月令丑未也贵。乙亥月文章冠世、官至三品。","甲辰":"甲辰日丁卯时：财帛满目、生计有余，妻贤子孝，是高命；春生太旺无制，反而贫病。丑酉月贵。","甲午":"甲午日丁卯时：身坐死地、怕刑冲；秋冬生不利，春夏富贵。甲午月大贵，运喜东北。","甲申":"甲申日丁卯时：多主武职、掌权显贵；酉月走火木运中贵，寅午年月大贵。","甲戌":"甲戌日丁卯时：遇亥月有才学、显贵；羊刃最怕冲坏，要有制合才好；身弱反而无妨，纯杀年月另论。"},"甲日辰时":{"甲子":"甲子日戊辰时：多半离乡改姓，妻贤子孝，可作高命；未月走北方运贵，酉月走北方运亦贵。","甲寅":"甲寅日戊辰时：龙吟虎啸格，显贵；纯辰中贵，纯寅康寿，亥卯未三合财旺身强则大贵。","甲辰":"甲辰日戊辰时：刑冲反而发财，妻晚子迟、与父母有克；酉月三四品，丑月也贵，地支纯辰大贵。","甲午":"甲午日戊辰时：财多而成败反复，容易早灰心；亥子丑卯午未年月大贵，酉月也贵。","甲申":"甲申日戊辰时：多主孤独，做僧道反而清高；丑月富贵，寅月更贵。甲戌日戊辰时大富，年月扶合也贵。","甲戌":"甲戌日戊辰时：田产广、仓粮陈，只是先有刑伤；寅年月父子都贵，子月西方运至金紫。"},"甲日午时":{"甲子":"甲子日庚午时：日时相冲，伤妻子，只算平常；子午年月或寅戌月生，走西北方运，可得金紫之位。","甲寅":"甲寅日庚午时：春月有成；夏月伤官伤尽、财源进退；申月有权，酉月反复；冬月伤妻；子未年月杀来助。","甲辰":"甲辰日庚午时：田园之乐；寅月走金运则劳碌。","甲午":"甲午日庚午时：破祖业后发财，禄因财来却难善终；寅午戌年月显贵。","甲申":"甲申日庚午时：子辰年月会印，亥卯年月身旺，都显贵；寅戌月会伤制杀、甲有托，也贵，运喜金水。","甲戌":"甲戌日庚午时：生辰戌月敦厚，不贵则富；丑月走火土运至金紫，寅月清贵。"},"甲日未时":{"甲子":"甲子日辛未时：辰戌丑未及巳酉月，土金成方，文章显达。","甲寅":"甲寅日辛未时：寅申月显贵；酉丑年月大贵。","甲辰":"甲辰日辛未时：辰戌丑未月富；巳酉丑子年月显贵。","甲午":"甲午日辛未时：春吉、夏不利、秋身弱任官禄、冬显贵。","甲申":"甲申日辛未时：春吉、夏辛苦、秋显达、冬另立根基而贵；子丑月大贵。","甲戌":"甲戌日辛未时：先受刑后得贵；寅卯酉年月贵，子申年月位至显贵。"},"甲日申时":{"甲子":"甲子日壬申时：申子辰亥月水多木漂，主离乡改名，仍是玉堂金马之贵；走水土运不利。","甲寅":"甲寅日壬申时：旺中带失；辰戌丑未月官星到位，寅午戌月偏官有制，秋月走东南运，都贵。","甲辰":"甲辰日壬申时：寅辰年月文章显贵，透丙戊更好；甲午日壬申时、申子辰月，改姓更宗，是敦厚之命。","甲申":"甲申日壬申时：寅月身杀两停，卯月以刃合杀，都贵；子辰年月以杀化印，巳午火月七杀有制。","甲戌":"甲戌日壬申时：辰戌丑未月衣锦有成，亥月学堂，寅月建禄，都显贵；午酉月寿短，不然劳苦。"},"甲日酉时":{"甲子":"甲子日癸酉时：春生木旺；酉月官星纯则贵；若混七杀或多杀、柱中全无火气，则不利。","甲寅":"甲寅日癸酉时：春生平常，夏生反复，秋生性不定多不利，冬生平常；丑未月显贵。","甲辰":"甲辰日癸酉时：子戌年月有财有官，显贵。","甲午":"甲午日癸酉时：多主孤独；寅午戌月生，走东北方运可做郎官。","甲申":"甲申日癸酉时：平常；通火气月走南方运则富贵，申酉年月多夭折；有水化金毒，只作官印看。","甲戌":"甲戌日癸酉时：子戌年月文章显贵；子午月不贵也富。"},"甲日戌时":{"甲子":"甲子日甲戌时：春夏生暴发，秋生显贵，冬生离乡改名；柱见纯亥爽角，贵也终不利；辰戌丑未月另看。","甲寅":"甲寅日甲戌时：比肩争禄、木气遭焚，四十岁后渐渐不如从前；甲丙申子年月大贵。","甲辰":"甲辰日甲戌时：财源稳厚，但多不利；春月走金火运，官至六品。","甲午":"甲午日甲戌时：春生有贵人扶持；夏生背禄逐马；冬生印绶吉；纯寅年月近侍之贵。","甲申":"甲申日甲戌时：酉月官星显贵，但身孤、发不久；春生走木土运则贵。","甲戌":"甲戌日甲戌时：背禄逐马，只算平常；秋生官杀有气则贵；辰戌丑未月吉，卯月不利。"},"甲日亥时":{"甲子":"甲子日乙亥时：成趋乾格，显贵；申月杀旺合刃则有权，酉月正官、有土来助则大贵。","甲寅":"甲寅日乙亥时：辰戌丑未月富，申酉月贵，冬生平常；寅亥月生更高。","甲辰":"甲辰日乙亥时：酉月正官最贵；辰戌丑未及寅亥年月，都吉。","甲午":"甲午日乙亥时：卯月羊刃刑骨肉，身弱难善终；春生可至宰辅；申子戌午年月走水火运，官位可期。","甲申":"甲申日乙亥时：亥月学问有成、以风宪显贵；申酉月先贫后富；子月走水火运至金紫。","甲戌":"甲戌日乙亥时：春冬生富，土厚地方显贵；夏生力不聚财；秋生平常。"},"乙日子时":{"乙丑":"乙丑日丙子时：身弱只算平常；没有午来穿冲，人贤德温厚。申酉年月有风宪之象，寅子年月显贵；怕丙寅、己未、甲子月。","乙卯":"乙卯日丙子时：命格偏高；辰戌丑未亥年月、又不见官星，显贵。","乙未":"乙未日丙子时：平常；子亥年月大贵，运同论。怕己未月刑伤、丙申月身不全、己丑月破败。","乙酉":"乙酉日丙子时：显贵但身孤、反复起倒；月通水气、不见辛午也贵。怕戊寅月大不利、丁巳月破祖穷苦。","乙亥":"乙亥日丙子时：化青赤，多半有福；庚辰年月富而贵。纯亥成败不一，丑月走南运可为郎官，巳午酉运极旺。"},"乙日丑时":{"乙丑":"乙丑日丁丑时：秋生有权，多带病；夏吉、冬平、春旺则贵。","乙卯":"乙卯日丁丑时：亥月身旺、见辛为偏官，柱中有丁制住，可做武职。","乙未":"乙未日丁丑时：辰戌丑未月富；春寿长、秋名利、夏辛苦、冬平常；申年月武职三品。","乙酉":"乙酉日丁丑时：通木气、有人托底则贵；申丑年月也好，寅亥更佳。","乙亥":"乙亥日丁丑时：亥月性急有操持，妻贤子孝，官至六七品；午月长生，年月透官印则大贵。"},"乙日寅时":{"乙卯":"乙卯日戊寅时：刑中发福；秋生显贵；酉年遇辰戌丑未月则富；卯月建禄、午月印生，透官印都吉。","乙未":"乙未日戊寅时：春生有成；秋贵、夏平常、冬反复；辰戌丑未月都吉，运同论。","乙酉":"乙酉日戊寅时：春生富，夏平，秋贵但寿促，冬吉。","乙亥":"乙亥日戊寅时：春吉，夏费力，秋冬显贵；子丑年月可至三品，有起有落，寿长。"},"乙日卯时":{"乙未":"乙未日己卯时：年月不见庚辛金则贵；秋生看地气厚薄，壬戌年月可至三四品。乙酉日己卯时秀气，初年平常。","乙亥":"乙亥日己卯时：寅巳月生、不见庚辛，是日禄归时格，清贵显达；纯卯年月宜僧道；戌月聪明特达。"},"乙日辰时":{"乙丑":"乙丑日庚辰时：破祖克父、身弱多病，月令有帮则贵；子申年月、天干透甲戊成三奇，大贵。","乙卯":"乙卯日庚辰时：富贵；通火土年月，大贵。","乙未":"乙未日庚辰时：亥卯月身旺、巳申月官旺，天干透杀印都贵；丑酉纯杀、柱中有火制，也吉。","乙酉":"乙酉日庚辰时：亥子年月、干透戊癸则贵；寅巳午月官杀有制则吉；纯酉化金，多主厚福。","乙亥":"乙亥日庚辰时：不贵则富；年月癸戊一化、申卯两旺、巳丑酉会金，走木土运可至金紫。"},"乙日午时":{"乙丑":"乙丑日壬午时：春夏多富贵；秋冬见官印，或纯杀透干，更吉。","乙未":"乙未日壬午时：寅卯月身旺、亥子月印旺、丑月财官印三奇，多主显贵；申月正官尤吉。","乙酉":"乙酉日壬午时：春吉，夏秋平常；柱中纯乙酉、透庚合化，或得印助，大贵。","乙亥":"乙亥日壬午时：春身旺、夏福厚、秋反复、冬吉。"},"乙日未时":{"乙丑":"乙丑日癸未时：不利刑伤孤独；年月通土气则吉。","乙卯":"乙卯日癸未时：改祖离亲、就妻成家；午未年月显贵，春生更贵。","乙未":"乙未日癸未时：春生身旺有刑伤；秋官杀旺、可取科名；冬安稳；夏平常。","乙酉":"乙酉日癸未时：身坐杀；春身旺吉，夏身弱杀衰穷苦，秋杀旺而身能化则贵，冬平；辰戌月另论。","乙亥":"乙亥日癸未时：春木旺、刑伤妻子；申月官旺则贵，酉月杀旺要年月有火才吉；午未戌年月可至一二品。"},"乙日申时":{"乙卯":"乙卯日甲申时：合化则贵；月通水气、无伤破则贵，不然只是富。","乙未":"乙未日甲申时：未酉亥月生，聪俊特达，官至二三品；丙丁寅午卯酉年月，伤食制杀、有权而贵。","乙酉":"乙酉日甲申时：官杀混杂；柱中有丁火制杀留官则吉；亥卯未酉年月做武职，但不长久，走东南方运更好。","乙亥":"乙亥日甲申时：时柱落空亡，多主少子；秋生官至六卿；亥卯未年月都吉。"},"乙日酉时":{"乙卯":"乙卯日乙酉时：月通金局则贵；未寅年月官至一二品。","乙未":"乙未日乙酉时：拱贵格，无刑破则贵，见申填实就不算；亥卯月走西运，显贵。","乙酉":"乙酉日乙酉时：旺处自刑；年月火土重则多病。月令有帮、透出印食，走火木运，大贵；地支纯酉另论。","乙亥":"乙亥日乙酉时：春生是仁寿格，显贵；寅月走金火运，大贵。"},"乙日戌时":{"乙丑":"乙丑日丙戌时：春身旺吉；夏伤官太重；秋费力辛苦；冬亥子月印绶带伤官则贵；戌月另看。","乙卯":"乙卯日丙戌时：寅卯月生、走西运可至六七品；子月印绶、丑月刑出财官，都显贵。","乙未":"乙未日丙戌时：旺处不利；卯午未戌年月显贵。","乙酉":"乙酉日丙戌时：春身旺、冬印旺，大贵；夏巳午、秋酉戌，都显贵；还要看天干配合。","乙亥":"乙亥日丙戌时：主血病；亥子卯未寅月遇贵发福；天干透伤官生财更吉；枯木逢春更生。"},"乙日亥时":{"乙卯":"乙卯日丁亥时：巳酉丑月偏官、申月正官，都显贵；亥月走东南运有风宪之象；未月三合木局，大贵。","乙酉":"乙酉日丁亥时：月通金局、走水运大贵；通木气则发达；通土气则滞。","乙亥":"乙亥日丁亥时：有财自刑；寅卯月身旺、天干透财则富；辰丑月走金火运显贵；亥子申月官印双清更好。"},"丙日子时":{"丙子":"丙子日戊子时：寅巳卯未月木能生火，大贵；冬月丙火没气，体弱早亡；戌月走火土运，可至五六品。","丙寅":"丙寅日戊子时：卯丑月清贵，寅戌月平常；夏月身旺、柱里有水金才吉；子月正官，大贵。怕癸巳月。","丙辰":"丙辰日戊子时：日德格，喜见官星；戌月身旺最宜，可作武贵；寅月走金水运中贵。","丙午":"丙午日戊子时：日刃格，要有官杀制合；辰戌丑未月大富；亥卯未寅年月大贵，申巳月另看。","丙申":"丙申日戊子时：巳午年月走东北运有风宪之象；子月走木火运可至三品；酉亥月遇贵反贱。","丙戌":"丙戌日戊子时：春生印绶最吉；夏身太旺只算平常；秋财旺身弱、有托则贵；纯酉年月文进之贵。"},"丙日丑时":{"丙子":"丙子日己丑时：寅亥申辰年月，天干透财印食的，显贵。","丙寅":"丙寅日己丑时：平常；乙酉月生是正财格，乙庚健旺则贵；巳丑年月干透官印则贵。","丙午":"丙午日己丑时：春月走火金运，官至极品；夏平、秋富、冬贵；午酉年月可至五六品。"},"丙日寅时":{"丙子":"丙子日庚寅时：子月生近贵；癸酉月走水木运则贵，火木运五品以上；未申、癸午年月另看。","丙辰":"丙辰日庚寅时：寅午戌未年月，妻贤子孝、富贵双全；申子月走北运大贵；酉丑月富。","丙午":"丙午日庚寅时：年月不见壬癸子未巳，是飞天禄马，显贵；巳酉丑申多主文学，不贵则富；未月伤官。","丙申":"丙申日庚寅时：亥卯未、申子辰两局齐备，官印两旺，大贵；巳丑财局吉；寅午戌火局平常。","丙戌":"丙戌日庚寅时：亥子月生则贵；申酉年月走北运、寅午戌走官鬼运，都大贵；运临死地则减。"},"丙日卯时":{"丙子":"丙子日辛卯时：子卯相刑，伤妻害子；年月同气多主魁名、近侍之贵；寅午丑戌月干支相合另看。","丙寅":"丙寅日辛卯时：离祖自立，带肢体之病；寅卯未子月显贵，其余月份平常，运同论。","丙辰":"丙辰日辛卯时：寅戌月生有天月二德，格高；巳月走北运则贵，酉丑也贵；亥卯未大贵。","丙午":"丙午日辛卯时：年月里得癸水官星把刃制住则吉；子月伤克妻子；寅酉月性刚不受制，可至三四品。","丙戌":"丙戌日辛卯时：伤妻害子，身旺不化则贵；春生聪明好酒色；冬生走西运富贵；夏月劳碌。"},"丙日辰时":{"丙子":"丙子日壬辰时：辰戌丑未月偏官有制则吉；亥卯年月富贵；寅午月走子运、子月走寅午运，都贵。","丙寅":"丙寅日壬辰时：身杀两旺，寅卯辰丑未年月大贵；巳午戌年月也贵。","丙辰":"丙辰日壬辰时：身孤有财，多主不得善终；春生走北运、夏生走东运都贵，秋生走南运可至三品。","丙申":"丙申日壬辰时：旺中有失；春平、夏福、秋富、冬寿促；申子辰成木局、干透印比则大贵，食神制杀也贵。","丙戌":"丙戌日壬辰时：不利；卯未年月走火土运可至三品，妻贤子孝；辰戌丑月平稳；寅午子巳月另看。"},"丙日午时":{"丙子":"丙子日甲午时：春吉；夏无依靠；秋财旺；冬官贵，子少晚成；走火土运发达。","丙寅":"丙寅日甲午时：辰戌丑未月能压住火气，中贵；午月火太旺，不利。","丙辰":"丙辰日甲午时：寅卯印助、申酉印旺、巳午身旺、亥子官旺，都吉；但要以火土为重，缺了福薄。","丙午":"丙午日甲午时：寅午戌月作倒冲，可至二三品；子月走南运八九品，寅月走南运至金紫。","丙申":"丙申日甲午时：不见火土气的人福薄；走金水运则贵。","丙戌":"丙戌日甲午时：春吉、夏孤克、秋吉但子少；寅午戌月富贵超群，古称「神仙宰相」。"},"丙日未时":{"丙子":"丙子日乙未时：春印绶稳厚；夏平稳；秋反复；冬显贵，运同论。","丙寅":"丙寅日乙未时：卯未月印绶格，智慧丰厚，主为妻子；寅巳子辰年月显贵。","丙辰":"丙辰日乙未时：春吉、夏平稳、秋劳碌、冬显贵；巳午月走西北运可至六七品。","丙午":"丙午日乙未时：不贵则富；午戌年月可居风宪；申子辰月官星制刃、亥未月印绶化刃，都吉。","丙申":"丙申日乙未时：月令不帮火气、又不见财星，反是好命；子辰会官、亥卯会印，都贵。","丙戌":"丙戌日乙未时：申子辰年月近侍之贵；寅卯巳年月大贵。"},"丙日申时":{"丙子":"丙子日丙申时：通火气、寅卯月再走身旺运则吉；年月纯金、弃命就财，也吉。","丙寅":"丙寅日丙申时：日时对冲，伤妻子；通火气月走身旺运则吉；亥月偏手艺；丙辰日丙申时、寅月另论。","丙午":"丙午日丙申时：多主血光火厄，之后大发；巳月生、庚辛透出成财格，可作武贵。","丙戌":"丙戌日丙申时：柱中无壬癸亥子酉填实，可作拱格，显贵；寅戌巳午月身旺无依，宜僧道。"},"丙日酉时":{"丙子":"丙子日丁酉时：春稳、夏贵、秋平、冬吉；未申酉亥年月大贵；有合子、合酉的也贵。","丙寅":"丙寅日丁酉时：卯亥未年月、干透官杀则贵；其余月份只算有手艺、平常。","丙辰":"丙辰日丁酉时：寅午戌巳年月、干透杀印则贵；申子会官、干透印比则贵；年月火土重，宜见财。","丙午":"丙午日丁酉时：巳午戌月生做僧道命好；酉月贵；亥子丑寅卯辰官印年月大贵。","丙申":"丙申日丁酉时：通水木气、走水木运则贵；巳午月身旺，亥子月官旺，两全则大贵。","丙戌":"丙戌日丁酉时：月通木气走水运则贵；通金气走火运，金马玉堂、才名冠世；露庚藏戊，体弱早亡。"},"丙日戌时":{"丙寅":"丙寅日戊戌时：食神坐库，丙以戊为食神寿星；通火气月、走东南运则有福。","丙子":"丙子日戊戌时：夏月福寿双全；春月木克土、食神被枭；寅月丙戊都长生，最吉；申庚制甲。","丙辰":"丙辰日戊戌时：午月丙火有气、土厚地方，可至五六品；亥月走金火运有风宪之象。","丙午":"丙午日戊戌时：羊刃与食神都旺，名利骤发；亥未辰戌年月走西方运，风宪。","丙申":"丙申日戊戌时：亥月走东运则贵；寅午月身旺、干透财吉；丑辰刑冲戌库，晚发。"},"丙日亥时":{"丙寅":"丙寅日己亥时：夏生化鬼为官，妻贤子孝，不贵则富；寅卯辰巳申丑年月、或午戌会局，天干再透用神更佳。","丙辰":"丙辰日己亥时：日德格；寅月吉；辰月做僧道多富、常人孤克；戌月冲辰、巳月冲亥，丙旺入库存。","丙午":"丙午日己亥时：武贵；寅巳午月生妻重子晚，不贵即富；秋冬名利进退；酉午戌月大贵。","丙申":"丙申日己亥时：春夏生离乡改名、就妻改福；秋冬平常；酉月走东南运有风宪。","丙戌":"丙戌日己亥时：寅卯巳午月木生火炎，妻伤子少，人聪明而富贵；酉亥子丑月平常，走东运也贵。"},"丁日子时":{"丁未":"丁未日庚子时：辰戌丑未月偏官有制；午月干强则贵；其余月份有制伏就吉；戊子月文章秀。怕戊申月。","丁酉":"丁酉日庚子时：辰戌丑未月刚明特达、显贵；辰巳年月可至相府；怕甲寅月破败、癸巳月不利。","丁亥":"丁亥日庚子时：五十岁后大旺；辰戌丑未月吉，寅午年月显贵；怕庚寅月恶死、庚申月身不全。"},"丁日丑时":{"丁丑":"丁丑日辛丑时：申酉月财格，财旺生官则贵；午月伤财身旺，多主官禄；纯子寅月武贵三品。","丁卯":"丁卯日辛丑时：辰巳未年月富贵、妻子显达；寅卯印助、戌库身旺，但有刑；丑月丁得依靠，大贵。","丁未":"丁未日辛丑时：日时相冲，伤妻子；酉月通水气则吉，运同论。","丁酉":"丁酉日辛丑时：寅卯巳午月身旺有托，多主文名高、遇非常之贵；申酉戌月财旺，最吉；亥子月官旺。","丁亥":"丁亥日辛丑时：春印绶吉，秋生有火气也吉；夏太旺不利；冬官杀旺则吉；未戌月冲开丑库。"},"丁日寅时":{"丁卯":"丁卯日壬寅时：化吉则贵；寅卯年月走金水运，大贵；亥子月走西运，显贵。","丁未":"丁未日壬寅时：主恶死；春生印吉，夏走木火运发福，秋富，冬贵；酉戌年月官至三品。","丁酉":"丁酉日壬寅时：亥未寅卯申子年月，明富显贵、可至极品；巳午月宰相；辰月走金水运。","丁亥":"丁亥日壬寅时：日贵格，配壬寅则官印俱全、文章显达；子月大贵，化气不利。"},"丁日辰时":{"丁卯":"丁卯日甲辰时：辰戌丑未月孤克，运通则发财；丑月走南运显贵；卯月走金水运近侍有权。","丁未":"丁未日甲辰时：丑亥卯未月印绶、官星显贵；夏平；辰戌月显贵厚；酉午月走金水运大贵。","丁亥":"丁亥日甲辰时：日贵格、官禄到位，必有发达；申辰年月大贵；午月走东北运、辰月走北运都贵。"},"丁日午时":{"丁卯":"丁卯日丙午时：旺中带滞，卯字刑破则成白丁；巳月走西北运显贵，东南运有名无实；寅亥月武职二品。"},"丁日未时":{"丁丑":"丁丑日丁未时：丑未刑冲，难得善终；年月辰戌四库全则贵；申未月三品，法司清要。","丁卯":"丁卯日丁未时：刑中发福；寅卯月印绶、发财敦厚；辰戌申午月都吉。","丁未":"丁未日丁未时：八专太旺，早克父母妻子，衣食平常，做僧道反而吉；通金水木、走金水运则安稳。","丁酉":"丁酉日丁未时：日贵格；亥卯未寅月生衣食敦厚；寅月走金水运至金紫；丁亥日丁未时另论。"},"丁日申时":{"丁丑":"丁丑日戊申时：秀而贵；未申年月显贵，走东南运大贵；巳月走西北运可至六卿。","丁卯":"丁卯日戊申时：春伤官用印、秋伤官用财，都吉；夏比肩，冬伤官见官只算平常；四季月吉。","丁酉":"丁酉日戊申时：寅午戌丑辰未月生，伤官伤尽为奇，又是日贵格，多主登科第；走金水运至腰金衣紫。","丁亥":"丁亥日戊申时：日时相害、伤妻子；月令有帮身旺则贵；年月戊戌、丁巳火土太重，主眼病。"},"丁日酉时":{"丁卯":"丁卯日己酉时：日时相冲，伤妻子；通火气则吉；怕乙卯；年月亥未、巳丑有一字相合则不以冲论。","丁亥":"丁亥日己酉时：滞塞；如戊己丙丁年月，可在近侍而有职；卯甲乙寅月走西北运则贵。"},"丁日戌时":{"丁丑":"丁丑日庚戌时：日时相刑，伤妻子；寅亥申酉年月可至三品；午未子辰月走金木运也贵。","丁卯":"丁卯日庚戌时：亥未年月三合会印则贵；子月杀印吉；年月建禄者宜僧道、也多显贵；柱无救助则平。","丁未":"丁未日庚戌时：多主刑；亥卯会印、申子辰会官，多主文贵；午月建禄但子来冲，不利；年月用土生扶另论。","丁酉":"丁酉日庚戌时：日贵格，近贵有谋略；酉戌六害骨肉无情；秋月可至五六品。","丁亥":"丁亥日庚戌时：日贵格；巳酉丑年月可至四五品；寅卯亥月走火金运，位至六卿。"},"丁日亥时":{"丁丑":"丁丑日辛亥时：秋财旺、夏身旺、春印旺，都贵；冬官杀太重，怕身弱担不起福。","丁卯":"丁卯日辛亥时：时上财官印三奇，再有年月印助财生，多主大贵；纯子月走木火运可至六品。","丁未":"丁未日辛亥时：亥卯未寅辰午年月、干透正印正官，聪明显贵；走西运有名位；巳丑月有风宪之象。","丁酉":"丁酉日辛亥时：贵人捧印，显贵；子月走东运有风患；柱有巳丑会财、卯未会印、干透财官印者更贵。","丁亥":"丁亥日辛亥时：日贵格又三奇全，月令有帮身旺则贵；卯未三合印局大贵。"},"戊日子时":{"戊子":"戊子日壬子时：财星格；寅卯月禄马朝元则贵；酉亥丑年月走西北运至金紫；怕乙卯年刑。","戊寅":"戊寅日壬子时：卯月正官格，显贵；夏不利、秋略顺；丑酉年月吉；怕己巳月刑、己亥月不利。","戊辰":"戊辰日壬子时：春财官旺则贵；夏不利；秋略顺；冬财旺，走西南运可至五六品；怕庚辰月自刑。","戊午":"戊午日壬子时：日时相冲，伤妻子；巳午年月有风宪之象；寅卯亥月可至六卿；申月走木火运可至侯伯。","戊戌":"戊戌日壬子时：寅巳午年月去财留印，可至三四品；子酉月五品。古语说「见义忘利，取印舍财」就是这个。"},"戊日丑时":{"戊子":"戊子日癸丑时：戌月生离气印绶、天干透丙丁，不必论格，多主富贵；午酉年月、干透庚乙另看。","戊寅":"戊寅日癸丑时：寅巳午未戌月化火则吉；秋冬平常。","戊辰":"戊辰日癸丑时：寅巳午未戌月化火得地，申子辰财局也吉；年月干支纯土、四库全则贵。","戊午":"戊午日癸丑时：寅戌未午年月，聪明特达、有权。","戊申":"戊申日癸丑时：辰戌丑未午月生，富贵但好酒色；夏走东运则贵；秋冬财旺生官，身弱则不利。","戊戌":"戊戌日癸丑时：夏生走东运则贵；辰戌丑未月富贵有操守，也风流好酒；化火局则财门大开。"},"戊日寅时":{"戊子":"戊子日甲寅时：先破后发则贵；未月干有制伏则贵；午月无制只近贵；辰戌丑月身旺、亥卯月杀旺。","戊寅":"戊寅日甲寅时：身旺但骨肉不同居；午月刃印带杀、子月正财带杀而干透制；亥卯未纯杀则身柔。","戊辰":"戊辰日甲寅时：时上偏官、印绶带杀，柱有庚辛制伏则贵；辰戌丑未月身旺也贵。","戊午":"戊午日甲寅时：日坐羊刃、时上偏官，以刃合杀则贵；巳酉丑月是刀笔吏，制伏不宜太过。","戊申":"戊申日甲寅时：申酉月伤官带杀、土厚地方则贵；卯月去杀留官大贵，宜走金火运，位极人臣。"},"戊日卯时":{"戊子":"戊子日乙卯时：日时相刑，伤妻害子，自成自立；年月再遇多主风宪；午酉四正全则大贵。","戊寅":"戊寅日乙卯时：亥子年月妻贤子孝、显贵；纯卯辰吉，寅巳也吉。","戊辰":"戊辰日乙卯时：身孤而贵；巳卯年月身强官旺，荣身显祖，子孝妻贤。","戊午":"戊午日乙卯时：羊刃格，正官把刃制住反为福；子寅卯辰午未申亥年月多主显贵。","戊申":"戊申日乙卯时：中年破祖；春贵、夏近贵、秋孤苦、冬富贵双全；巳月走木火运可至五品以上。","戊戌":"戊戌日乙卯时：春官旺；夏官印双全则贵；秋平；冬贵；戌丑年月可至方面三品。"},"戊日辰时":{"戊子":"戊子日丙辰时：春生近贵；夏辛苦；秋权高但寿促；冬财旺，通火土、有托则贵。","戊寅":"戊寅日丙辰时：龙吟虎啸，中年大贵；子月走北运、土厚地方可至三品；走东运有风宪。","戊辰":"戊辰日丙辰时：克父却大发；通身旺月走东北运则富；水木月走身旺运则贵。","戊午":"戊午日丙辰时：亥卯年月走东北运，富贵；未丑月走西南运有风宪。"},"戊日午时":{"戊子":"戊子日戊午时：巳寅戌月有风患；夏月火不熔金，先刑后发，旺处多官；火炎则破祖。","戊寅":"戊寅日戊午时：戌月三合火局、干透癸化，得天时地利则贵；申子会水、寅午会火而有既济之象。","戊辰":"戊辰日戊午时：拱禄格，年月无寅巳甲乙则贵；卯申月武职；酉丑亥月走南运则贵。","戊午":"戊午日戊午时：先刑后发，多不善终；寅巳午戌月印绶，大贵；纯午月武职威名，镇守一方。","戊申":"戊申日戊午时：拱贵格；年月见寅走南运有风宪；见午则贵而寿；戌月文贵；有未填实另论。","戊戌":"戊戌日戊午时：大不利；卯午年月走官运则贵；寅月印绶带杀，变不利为吉。"},"戊日未时":{"戊寅":"戊寅日己未时：先后易变，有贵人提携，不贵即富；年月透甲制刃、午未身旺、杀刃两全，多主大贵。","戊戌":"戊戌日己未时：春官旺则贵；夏印绶安稳；秋平；冬孤苦；戌月是魁罡格，可至五六品。"},"戊日申时":{"戊子":"戊子日庚申时：亥子月生也是合禄格，显贵。","戊寅":"戊寅日庚申时：不利，刑后发；寅月生可作食禄制杀，显贵。","戊辰":"戊辰日庚申时：专食合禄；纯寅年月两寅不怕一申冲，也贵。","戊午":"戊午日庚申时：未酉丑年月、柱中无丙甲卯寅，入合禄格，走西北运则贵；有甲丙则合神藏、杀没。","戊申":"戊申日庚申时：身禄同宫，富贵双全；子辰未酉年月走西运，入合禄格，近三品；丑戌年月吉。","戊戌":"戊戌日庚申时：子月也合禄格，文贵三品；卯辰年月大贵。"},"戊日酉时":{"戊子":"戊子日辛酉时：巳酉丑月伤官伤尽，走财运则武职风宪。","戊寅":"戊寅日辛酉时：通土气月走西北运，不贵也富。","戊辰":"戊辰日辛酉时：丑未年月干透财，多主显贵；癸巳月作馆学之贵，多主文学高科。","戊午":"戊午日辛酉时：春夏平常；秋伤官伤尽、有权但寿促；冬主为妻子操劳。","戊申":"戊申日辛酉时：戌亥丑子年月，有权而贵。","戊戌":"戊戌日辛酉时：辰戌丑未月显贵；古人说水土败在酉，所以多无结果、或功名早退、或子息不成。"},"戊日戌时":{"戊子":"戊子日壬戌时：酉申戌月家财满目；辰丑月冲开财库，都吉。","戊寅":"戊寅日壬戌时：寅午戌辰年月走金水运，大贵。","戊辰":"戊辰日壬戌时：日时相冲伤妻子；土厚地方大贵；卯月走火金运中贵；寅申戌丑月走西南运。","戊午":"戊午日壬戌时：寅午戌月生、时上火多，以印绶论，难免孤克、先后易变，不贵即富；卯月官星来制。","戊申":"戊申日壬戌时：春贵、夏平、秋富贵、冬平常。","戊戌":"戊戌日壬戌时：秋富贵；夏走西运、春走北运、冬走南运，都贵；辰丑月更吉。"},"戊日亥时":{"戊子":"戊子日癸亥时：年月不见戊来破格则贵；申子年月走东南运、亥卯月走南运都贵；巳午未月旺则大贵。","戊寅":"戊寅日癸亥时：午未月生化火会局，是高命；春官杀混杂、衣食温饱；酉丑年月可至三品京堂。","戊辰":"戊辰日癸亥时：秀气；亥子月财官格，不贵则富；寅卯年月贵；夏生只做教职。","戊午":"戊午日癸亥时：显贵；寅巳年月、土厚水秀之地，可至六七品；卯未辰丑月都吉。","戊申":"戊申日癸亥时：子未年月无祖业，因妻得富，不然离乡改名、清苦度日。","戊戌":"戊戌日癸亥时：寅卯午巳戌亥年月，天干透乙庚丁，清要有权而贵，宜走火土运。"},"己日子时":{"己酉":"己酉日甲子时：寅申午未丑年月，文章显贵有风宪之象；午月走东北运有名位；怕庚寅年破败、己巳月不利。"},"己日丑时":{"己卯":"己卯日乙丑时：子申月走金土运，可至侯伯；巳酉丑戌年月都吉；己巳日乙丑时、寅卯月为偏官格。"},"己日卯时":{"乙未":"己未日丁卯时：不贵则富；卯戌亥丑年月都吉。"},"己日申时":{"己卯":"己卯日壬申时：辰月离气财官，早贵；亥月走南运可至五六品；寅申年可至二品。"},"己日酉时":{"己酉":"己酉日癸酉时：偏财遇食神，多有所成；丑未子午月都吉；酉月主内戚；年月己酉全则犯破碎，一生多波折。"},"庚日子时":{"庚子":"庚子日丙子时：显贵；年月再逢子、与午相冲，午中丁为官、巳为印，成飞天禄马格；柱中不见财官填实则贵。","庚寅":"庚寅日丙子时：春生带财带杀，走金水运可至金紫；夏杀旺大贵；秋身旺须走南运才贵；冬另看。","庚辰":"庚辰日丙子时：月通木火气走西运最佳；乙巳月破败有刑，丁酉月旺中有刑不利，己丑月破。","庚午":"庚午日丙子时：显贵但日时相冲、伤妻子；运喜西南，通火木月气可有风宪三四品；秋生丙火无气。","庚申":"庚申日丙子时：申月生、土厚地方则贵；辰未年月走西运方吉；辛巳月不利有刑，辛亥月孤克。","庚戌":"庚戌日丙子时：春夏生走西南运、秋走木火运，都贵；怕乙巳月破败、乙亥月官多不利。"},"庚日丑时":{"庚子":"庚子日丁丑时：春夏贵，秋平常，冬孤克。","庚寅":"庚寅日丁丑时：寅卯午未亥月，清秀高命；走午未运则贵；通火土年月也贵。","庚辰":"庚辰日丁丑时：丑月富但寿促；巳月近侍大贵；通火旺土生之月则贵，运上遇到也有名。","庚午":"庚午日丁丑时：通土月气则贵，不通也富、有名声。","庚申":"庚申日丁丑时：丑月走金火运可至极品；辰巳午未戌月官印两旺则贵；申酉月身太旺，要行木火。","庚戌":"庚戌日丁丑时：春财旺、夏官旺、秋平淡、冬无力。"},"庚日寅时":{"庚子":"庚子日戊寅时：寅午年月可登科；申月三四品；丑月走金火运至公卿。","庚寅":"庚寅日戊寅时：月通火局或秋生、走身旺运则贵；庚子月自死；年见辛酉则体弱多病；身弱见丙火另看。","庚辰":"庚辰日戊寅时：春夏生、干透丙丁、走身旺运则贵。","庚午":"庚午日戊寅时：寅午戌月金衰火旺，多带残疾；纯寅反倒极贵；秋金旺多贵，但怕时上见亡神劫煞。","庚申":"庚申日戊寅时：日时相冲伤妻子；寅卯辰月走火金运可至侯伯；春月走西南运大贵。","庚戌":"庚戌日戊寅时：显贵；戌月离气财官印绶齐全则贵；庚辰年己卯月可至侯伯。"},"庚日卯时":{"庚子":"庚子日己卯时：子卯相刑、伤妻子；子年月则贵，丑未月可至三品；另说破祖失土反而大贵。","庚寅":"庚寅日己卯时：亥卯月财星格，早荣早退；午戌月三合官局、干透金水，走西北运则吉。","庚辰":"庚辰日己卯时：孤；年月通木气、有托则贵。","庚午":"庚午日己卯时：刑破；申子辰巳酉丑月都宜走东南运，显贵；寅午戌亥卯未月宜走西北运。","庚申":"庚申日己卯时：卯月财星格，不贵即富；丑巳年月为翰林清贵，官至亚卿；也有说少年辛苦、中年小成。","庚戌":"庚戌日己卯时：少孤母，中年显贵；卯酉辰丑月可至公卿。"},"庚日辰时":{"庚子":"庚子日庚辰时：申月生是井叉格；柱与运都不见丙丁巳午寅戌，则贵；纯卯年月可至公侯。","庚寅":"庚寅日庚辰时：龙虎拱门；年月通火土则贵；纯庚辰可至王侯，不然极不利；年月遇木火再行运另看。","庚辰":"庚辰日庚辰时：魁罡，年月不见财官与戌则贵，有冲破则富；申子月作井叉，走西南运吉。","庚午":"庚午日庚辰时：自刑，金神入火乡；申月走火木运可至六品。","庚申":"庚申日庚辰时：子申年月入井叉；柱与运不见丙丁巳午则贵；纯庚申庚辰走西北东运，可作武职。","庚戌":"庚戌日庚辰时：魁罡、土厚地方，官高禄重；子月走西南运则贵；寅辰年月平常。"},"庚日午时":{"庚子":"庚子日壬午时：日时相冲伤妻子；通金气则贵，火气重则大贵但禄多耗。","庚寅":"庚寅日壬午时：辰戌丑未巳申酉月身旺，都贵；寅午月火旺，运上再遇则寿促，不然残病。","庚辰":"庚辰日壬午时：食神旺、口福好、有操持，但一发即止。","庚午":"庚午日壬午时：寅午戌月金柔火旺，多畏缩残病；亥子午月走木火运则贵。","庚申":"庚申日壬午时：禄马同乡，最吉；午未年月可至台阁，卯辰巳月显贵；戌月走火土运只做清闲冷职。","庚戌":"庚戌日壬午时：卯月正财则吉；未月离气财官则贵，辰丑月同论；壬庚会合临午，无破无冲自然有福。"},"庚日未时":{"庚子":"庚子日癸未时：年月不透丁、又有己土制住癸水，则贵。","庚寅":"庚寅日癸未时：显贵；辰戌丑未月格高；夏富；巳酉申月身旺，大贵。","庚辰":"庚辰日癸未时：魁罡日，辰中有土制癸；年月不见丁则贵；卯月走金水运可至七品。","庚午":"庚午日癸未时：显贵；酉申巳亥年月可统领兵戎、官至二品，先虚后实。","庚申":"庚申日癸未时：酉月武贵，初年掌权；寅午戌与申子辰两局相参则贵。","庚戌":"庚戌日癸未时：戌月走东运则贵；辰月卯年大贵；秋生最吉；夏生须走西北运方吉。"},"庚日申时":{"庚子":"庚子日甲申时：时犯日禄、又见财星，柱中无己寅丙则富贵双全；辰戌丑未土能生金则吉；寅午戌月平常。","庚寅":"庚寅日甲申时：寅亥月可至三品。","庚辰":"庚辰日甲申时：日坐魁罡又归禄，不喜财官；柱中无寅午戌丙丁巳则贵。","庚午":"庚午日甲申时：显贵；通身旺月、无丙巳寅午丁来伤破则贵。","庚申":"庚申日甲申时：显贵；无卯午未戌丙丁则贵；子丑月走金水运为文贵；与庚申、甲申专禄归禄同论。","庚戌":"庚戌日甲申时：寅巳午戌月妻贤子孝、显贵；古书说金水带印，多主清闲之福。"},"庚日酉时":{"庚子":"庚子日乙酉时：多主富；月通火气则贵，月令不帮则平常、运通则好；卯亥年月可做帅臣；另说破祖有刑。","庚寅":"庚寅日乙酉时：有刑；寅午戌月吉，申子月刚暴。","庚辰":"庚辰日乙酉时：有刑；寅卯午年月可至二品有权，戌亥月大贵；古书说化金多主福厚。","庚午":"庚午日乙酉时：有刑但中贵；寅午戌与亥卯未两局则贵；巳月也吉。","庚申":"庚申日乙酉时：真刑；寅午戌月大贵，巳酉丑月中贵，申子辰月富，亥卯未月凋零。","庚戌":"庚戌日乙酉时：刑后发；寅午戌月官星明朗则贵，亥卯未月富或五六品，巳酉丑月刃旺则多发。"},"庚日戌时":{"庚子":"庚子日丙戌时：春偏官用财则吉；夏杀旺身弱主刚暴；秋身杀两旺；巳酉丑月走西方运至腰金。","庚寅":"庚寅日丙戌时：申子辰月偏官有制则吉；秋生身杀两旺、有禄有权；纯午月孤苦无依，不然残病。","庚辰":"庚辰日丙戌时：日时相冲伤妻子；月通金水气则贵；木火气重则多病或残。","庚午":"庚午日丙戌时：申酉亥月富而贵，可至三品；巳午未申月透壬，走艮坎乾方运，可做卿相、有寿。","庚申":"庚申日丙戌时：戌亥年月走东南运则贵；申月大贵。","庚戌":"庚戌日丙戌时：辰戌丑未月印绶生助则吉；申子辰月偏官有制则贵；月通金气不透壬、走北运另看。"},"庚日亥时":{"庚子":"庚子日丁亥时：显贵；申子辰月伤官主劳碌；卯月走金火运可至五六品。","庚寅":"庚寅日丁亥时：平常，早年清苦、中年转秀、晚年多富；辰戌年月显贵；申酉亥卯巳午年月、干透乙己者大贵。","庚辰":"庚辰日丁亥时：纯未月显达；巳午月走西北运有风宪、可至金紫；亥卯月有权；申月建禄最吉。","庚午":"庚午日丁亥时：显贵；辰戌丑未月土能生金则荣；申亥酉月走木火运可至极品。","庚申":"庚申日丁亥时：秋生走南运则贵，北运平常。","庚戌":"庚戌日丁亥时：辰巳午月官杀混杂，也主武贵；丑月走西运为郎官；辰月走西北运可至方面。"},"辛日子时":{"辛丑":"辛丑日戊子时：丑月离气财官则贵；纯丑为儒职；纯辰走西运有风患；酉月走东北运则贵；怕庚月。","辛卯":"辛卯日戊子时：春生寅月穷苦、卯月则贵；夏清贵；秋羊刃无益；冬富、丑月尤吉；辰戌未月财官印俱全。","辛未":"辛未日戊子时：显贵；寅巳午酉年月走火木运则贵；亥子月入翰苑；辰戌丑未月离气财官印，都吉。","辛酉":"辛酉日戊子时：子酉月生、没有丙丁火、也不走南运，可至三四品；伤妻子、掌武职。古书说金水相涵。","辛亥":"辛亥日戊子时：不贵则富；亥月无官、伤官伤尽反而发福但子少；春夏生、亥子丑月走木火运有风宪之象。"},"辛日丑时":{"辛丑":"辛丑日己丑时：孤滞；申酉月金旺，走火乡能疏通，但刑伤妻子；做僧道反显贵；纯丑月走西南运。","辛卯":"辛卯日己丑时：寅卯亥未月财星格，走南运则贵；辰戌丑未月印绶，走南运吉。","辛未":"辛未日己丑时：寅卯未月财星格；巳午月官星得地。","辛酉":"辛酉日己丑时：破祖；巳酉丑月金多克木，人俊俏有钱但为妻子操劳；寅午月近侍之贵。","辛亥":"辛亥日己丑时：寅巳午月官星明朗、立计成象；卯未月财局则富贵；未戌月有冲反吉；申子辰月另论。"},"辛日寅时":{"辛丑":"辛丑日庚寅时：春贵、夏官旺、秋显达、冬吉；丑月走南运有风宪或武贵；另说发即风病。","辛卯":"辛卯日庚寅时：午未亥子月都贵；寅卯申酉月可至六七品。","辛未":"辛未日庚寅时：巳未丑月名标金榜、妻贤子孝，晚年有风病；寅卯午戌月都吉。","辛酉":"辛酉日庚寅时：显贵；春财聚、夏官禄成、秋身旺；亥子丑戌午酉年月都贵。","辛亥":"辛亥日庚寅时：显贵但多暗病；干透丙火则发；午酉寅亥年月走南运则贵。"},"辛日卯时":{"辛丑":"辛丑日辛卯时：春夏生、土厚地方富贵；秋克妻刑子；冬平常；寅巳午月近侍之贵。","辛卯":"辛卯日辛卯时：寅午戌月财官双美则贵；卯酉申辰年月近侍之贵；见官印财星更好；另说先苦后甜。","辛未":"辛未日辛卯时：纯未、丁年月，大权在握但不善终；寅巳亥月纯吉。","辛酉":"辛酉日辛卯时：出身孤苦、中年得福、晚年克妻而贵；巳月官印遇天德，贵当一品；丑月走木运。","辛亥":"辛亥日辛卯时：春夏财官双美则贵；秋冬背禄逐马、劳碌反复；亥月金水泄秀，多出高科之人。"},"辛日辰时":{"辛丑":"辛丑日壬辰时：春财旺、妻贤子孝；夏伤官见官，但也多富；秋吉；冬孤克、多显贵。","辛卯":"辛卯日壬辰时：春伤官生财；夏进退反复或刚暴；午未月也奇；秋申酉身旺，见火则吉。","辛酉":"辛酉日壬辰时：春富贵双全；夏好；秋身旺则贵；冬只作白丁；子月辛金生地、入学堂，多主文学。","辛亥":"辛亥日壬辰时：显贵；春财旺扶身；夏吉；秋身旺好；冬伤官伤尽、自立自成；卯未年月则贵。"},"辛日午时":{"辛丑":"辛丑日甲午时：未申年月四柱有利害，虽富但寿短；通金气则贵但不长久。","辛未":"辛未日甲午时：申子辰月偏官有制则吉；丑戌月可至方面；未月显贵。","辛酉":"辛酉日甲午时：春财旺、夏官贵，都吉；秋身强而富不长久；冬平常。","辛亥":"辛亥日甲午时：亥子月金水相涵、堪作文学之才；辰戌丑未月离气财官则贵。"},"辛日未时":{"辛卯":"辛卯日乙未时：亥卯未月财盛生官，吉。","辛未":"辛未日乙未时：寅卯未年月财旺生官，名高禄重；通火气宜走西运，通金气宜走南运，都吉。","辛酉":"辛酉日乙未时：月通火气走东运则贵；辰戌丑未月最吉；亥卯月贵但不长久；秋生身太旺、财官无气。","辛亥":"辛亥日乙未时：亥卯未月财星格则吉；秋冬孤；辰丑月近侍三品。"},"辛日申时":{"辛丑":"辛丑日丙申时：化气则贵；少年滞碍、中年显贵；亥月作化气看则吉；寅午戌巳未月官星有气。","辛卯":"辛卯日丙申时：化气则贵；寅巳午未戌酉亥月官星明朗、山明水秀，可登科；通土气也贵。","辛未":"辛未日丙申时：因贵人门下得富；春清贵、夏平常、秋富、冬大贵但寿促。","辛酉":"辛酉日丙申时：寅巳午戌月官旺则贵；古书说水化多主显贵。","辛亥":"辛亥日丙申时：发福但防孤克带病；通金气人秀丽福厚；通水气则大贵。"},"辛日酉时":{"辛丑":"辛丑日丁酉时：格高而稳；酉月走土木运可至方面；戌亥子巳未年月大贵。","辛卯":"辛卯日丁酉时：日时相冲；月通金气、不透丙丁，走南运则贵。","辛未":"辛未日丁酉时：不贵则富；月通金气、无丙丁，走南运则贵。","辛酉":"辛酉日丁酉时：年月通金气则吉；丑月走西运有风宪之象；寅午戌月显贵。","辛亥":"辛亥日丁酉时：显贵；丑寅卯酉年月近侍之贵、可至金紫。"},"辛日戌时":{"辛丑":"辛丑日戊戌时：有刑害；辰戌丑未月印绶，走南运大贵；寅巳月正官则贵；子午卯酉月武职风宪。","辛卯":"辛卯日戊戌时：刑害、贪食；卯月走木火运可至五六品。","辛未":"辛未日戊戌时：刚恶狠暴、伤妻子；寅巳午戌丑月显贵；申子辰亥月金水相涵，更贵；另说克父。","辛酉":"辛酉日戊戌时：不利有刑；巳酉丑辰戌未年月可为魁元、卿尹之命。","辛亥":"辛亥日戊戌时：刚狠、有机谋而近奸诈；另说不利，后发。"},"辛日亥时":{"辛丑":"辛丑日己亥时：辰戌丑未及寅卯月生，作飞天禄马，显贵；未月走金水运至金紫方面。","辛卯":"辛卯日己亥时：寅卯亥未月财旺生官，终身有靠；巳酉丁年月显贵。","辛未":"辛未日己亥时：显贵；亥卯未寅月金能克木、财盛生官，名利双全；巳午年月富贵；秋生透丙另论。","辛酉":"辛酉日己亥时：辰戌丑未月离气财官则吉；纯亥月冲巳中丙火为官，显贵。"},"壬日子时":{"壬子":"壬子日庚子时：辰戌丑未月离气财官；巳申酉丑月印绶，住土厚之地都贵；寅月走金水运可近侍。","壬寅":"壬寅日庚子时：显贵但带刑；辰戌丑未月离气财官、巳申酉月印绶，都贵；怕乙巳月受刑、丁酉月大不利。","壬辰":"壬辰日庚子时：寅午月生财星旺、辰戌丑未月官旺，都吉；纯辰透庚壬成壬骑龙背格，大贵。","壬午":"壬午日庚子时：日时相冲，女多男少；丑未月走南运富贵；怕甲午月自刑。","壬申":"壬申日庚子时：清苦有刑；未月离气财官，走财运显贵但先后易变；辰月会水太旺，须走火土运。","壬戌":"壬戌日庚子时：丑月走金火运、辰未月财官格，都贵；寅酉月走西北运则贵；申子辰月走东南运极贵。"},"壬日丑时":{"壬子":"壬子日辛丑时：巳酉丑月印绶，多得父母之力；申月走火土运近侍有权；辰戌丑未月官印俱全、丰厚。","壬寅":"壬寅日辛丑时：丑月离气印绶格高；辰巳月杀强无制、财官身弱，辛苦。","壬辰":"壬辰日辛丑时：辰戌丑未月离气财官印绶，都吉；春平、夏财禄、秋吉中带不利；冬身旺须走南运。","壬午":"壬午日辛丑时：禄马同乡，显贵；夏吉；秋财官印全，也贵。","壬申":"壬申日辛丑时：寅卯亥未年月有进士之风、官至二品，但有起倒；辰戌月富足；申酉月享用自然。","壬戌":"壬戌日辛丑时：辰月冲开财官则贵；丑戌月也吉；柱有乙癸卯则平常。"},"壬日寅时":{"壬子":"壬子日壬寅时：纯子月、年月无午冲破，入飞天格，富贵；寅卯巳申酉戌亥年月都贵。","壬寅":"壬寅日壬寅时：壬趋艮格，土厚地方、山明水秀，可至腰金衣紫；巳亥年月武职三品、富厚。","壬辰":"壬辰日壬寅时：纯辰是壬骑龙背格，干头无丙丁戊己、运走比肩，大贵；纯寅大富；卯戌月走木金运。","壬午":"壬午日壬寅时：少年多病；壬午日禄马同乡；辰寅年月可至二品；申酉月清高，通木火则才名冠世。","壬申":"壬申日壬寅时：巳酉丑月武职三品；辛卯、戊月也贵；子寅月大贵；另说先贫后发但不长久。","壬戌":"壬戌日壬寅时：巳月偏官格，名标金榜、身坐玉堂；纯子月三品；寅卯月走北运有风宪之象。"},"壬日卯时":{"壬子":"壬子日癸卯时：子卯相刑、伤妻子，但有贵人提携，财帛有余，是敦厚之命。","壬寅":"壬寅日癸卯时：背财禄，时兴时败；子年月则贵；巳月财官虽刑也贵；辰戌丑未月官杀制刃。","壬辰":"壬辰日癸卯时：通身旺月、见土金破刃，走财运则贵。","壬午":"壬午日癸卯时：壬坐午为禄马同乡，又逢卯时，显贵荣达；巳午年月可作武职风宪。","壬申":"壬申日癸卯时：亥卯未寅月伤官伤尽，妻贤子孝、土厚则贵；纯辰月宜医卜；子月水木相生则贵。","壬戌":"壬戌日癸卯时：甲癸午酉年月文贵；申月平常，走金火运则贵。"},"壬日辰时":{"壬子":"壬子日甲辰时：纯子年月飞天禄马、无破，可至六卿；巳酉月大贵；亥月也贵。","壬寅":"壬寅日甲辰时：巳月偏官格、不冲不破则贵；午月正官则贵；辰卯月成局、走东方运，少年登科。","壬辰":"壬辰日甲辰时：辰月生是壬骑龙背，大贵；寅月不贵即富；戌月离气财官、冲开辰库，是高命。","壬午":"壬午日甲辰时：水火相炎；寅辰年月可作翰苑宿儒；纯子月有风宪之象；卯寅月富厚；辰子月儒职。","壬申":"壬申日甲辰时：水火相炎；丑寅年月文行武权；纯子月走金火运可至方面。","壬戌":"壬戌日甲辰时：寅申酉月走南运可至贵戚；亥卯未、申子辰、巳午年月都吉。"},"壬日午时":{"壬子":"壬子日丙午时：为人公直、孤高而贵；年月子午对冲则水火既济，有名位。","壬寅":"壬寅日丙午时：寅午戌月财星格，但嫌身弱，宜僧道则吉；秋生印绶；冬身旺走金火运至金紫。","壬辰":"壬辰日丙午时：寅午戌月财旺，大贵。","壬午":"壬午日丙午时：冬身旺则吉；夏财多身弱；丑日近侍之贵；寅午月走金土运，命就财则富。","壬申":"壬申日丙午时：通金水月气则贵；月令不帮则弃命就财，多主富，不然极贫。","壬戌":"壬戌日丙午时：寅月三合财局，富贵；秋身有托则贵；冬也吉。"},"壬日未时":{"壬子":"壬子日丁未时：月通木气则贵、通金气则富、通火土气则富贵；月令不帮但走火土运也吉。","壬寅":"壬寅日丁未时：丁壬化木；亥卯未、寅月生则贵。","壬辰":"壬辰日丁未时：辰月生是壬骑龙背局则贵；寅月妻重子荣；三合水局则身旺无依，多清苦克妻。","壬午":"壬午日丁未时：春平、夏富、秋贵、冬吉；巳午年月可至王侯；未月走东运则贵；子月正印。","壬申":"壬申日丁未时：大富；巳午年月或透戊己，富贵双全。","壬戌":"壬戌日丁未时：日德，早年克妻、中年又损妻；亥子申酉月则贵；巳午月不贵即富；辰月有天月德。"},"壬日申时":{"壬子":"壬子日戊申时：羊刃带杀，有贵人提携；巳午年月近侍有职。","壬寅":"壬寅日戊申时：日时相冲，身孤宜僧道则吉；寅午戌或纯辰年月也贵。","壬辰":"壬辰日戊申时：戌月生早登科甲、官至方面；寅卯丑申子午年月显贵，可作武职一品。","壬午":"壬午日戊申时：偏官偏印；亥卯未寅月有权；子丑月走木火运为翰林清贵；戌月走东南运至高位。","壬申":"壬申日戊申时：壬水长生于申，杀旺身强；生亥卯未月偏官有制则吉。","壬戌":"壬戌日戊申时：破滞多烦；纯酉月巨富；身旺月走杀旺之乡不利，有甲木制杀也可；戊己土重另看。"},"壬日酉时":{"壬子":"壬子日己酉时：春平、夏吉、秋平常、冬旺；卯月生好酒色。","壬寅":"壬寅日己酉时：大富大贵，喜通水气、走官运则贵；但好酒色、是风流人物。","壬辰":"壬辰日己酉时：格高，月日同气为壬骑龙背，大贵；巳月走东北运则贵。","壬午":"壬午日己酉时：禄马同乡，先后易变；寅月走金水运可作武职二品。","壬申":"壬申日己酉时：官印临门、局中无冲破，禄马双全，不贵即富；戌月走东南运至腰金衣紫。","壬戌":"壬戌日己酉时：亥寅子月走财官运，贵不可言；纯亥月文贵。"},"壬日戌时":{"壬子":"壬子日庚戌时：名利进退；庚辛年月则贵；辰戌月有刑冲；酉月有破害，财库得用则发；巳午月财官旺。","壬寅":"壬寅日庚戌时：刑妻克子；春生平常，夏冬吉；辰丑未月显贵。","壬辰":"壬辰日庚戌时：夏月不富即贵；春平、秋稳、冬辛苦，或做僧道、有财破之刑。","壬午":"壬午日庚戌时：禄马同乡、壬自坐禄，有庚辛制住甲乙则贵；辰戌丑未年月吉；申月学堂，文贵而大。","壬申":"壬申日庚戌时：通火木月气则富贵；月令不帮但运通也好；丑戌年月大贵。","壬戌":"壬戌日庚戌时：不利妻、多被妻妾所害，反复成败；纯戌月显贵；寅丑月武职；申月长生学堂，修文有成。"},"壬日亥时":{"壬子":"壬子日辛亥时：多主父母不得善终，后发但不算富；亥卯年月以文章进身，大贵。","壬寅":"壬寅日辛亥时：中年发；未月离气财官，敦厚、中年显贵、五十后收局；亥月走东南运可至方面。","壬辰":"壬辰日辛亥时：秀而贵，但防恶死；午月干头无己土，青云得路；有甲合则去官留杀，可至三四品。","壬午":"壬午日辛亥时：平常；辰月有风宪之象；寅月禄马同乡、走金水运至方面；戌月走东北运四五品；丑午月另看。","壬申":"壬申日辛亥时：显贵；辰戌丑未月离气财官则吉；年月干无己土，入日禄格；酉月申卯年走东北运。","壬戌":"壬戌日辛亥时：少年富贵；亥申巳戌年月可至一二品；纯戌月走水火运至金紫。"},"癸日子时":{"癸丑":"癸丑日壬子时：巳丑年月可作文职四五品；通身旺木气月、不见戊己午巳则贵；未月有风宪之象。","癸卯":"癸卯日壬子时：日时相刑、伤妻克子，但近贵；无己土则有威权；亥巳齐全可中进士、入乌府。","癸未":"癸未日壬子时：申酉月贵；戌亥月大富大贵；寅卯月孤；辰巳月不利；怕壬申月身不全、庚辰月不利。","癸酉":"癸酉日壬子时：进退不定、子少、为妻家操劳；怕丙寅月不全、乙巳月大破、丁酉月自缢。","癸亥":"癸亥日壬子时：显贵；亥月生是飞天禄马，登科甲第、大贵；癸禄在子、壬禄在亥，日时互换，可至三四品。"},"癸日丑时":{"癸丑":"癸丑日癸丑时：丑巳中丙戊为财官；生丑寅申子酉三合年月，多主妻贤子孝、荣贵特达；火土运不利。","癸卯":"癸卯日癸丑时：日贵格、身孤克，但多显贵；丑寅辰年月、干支无戊己巳午卯，有名位。","癸未":"癸未日癸丑时：子丑寅年月显贵、中年富；卯月走金水运有名位；辰戌月四库全则大贵。","癸酉":"癸酉日癸丑时：福德秀气格，有学问，进退为妻家所牵。","癸亥":"癸亥日癸丑时：拱禄格，怕冲破填实；柱无子巳午未则大贵；寅午戌月走南运可至六七品。"},"癸日寅时":{"癸丑":"癸丑日甲寅时：本可显贵，丑中有辛金减分；纯水年月可至一品；秋生印绶也贵；辰月走东运。","癸卯":"癸卯日甲寅时：亥卯未月极贵；寅卯年月为刑合格，可至侯伯；寅亥月四品；寅月走西运至金紫。","癸未":"癸未日甲寅时：多主秀实、中年显贵；巳未巳巳年月可作武贵。","癸酉":"癸酉日甲寅时：金神格；寅午戌月结火局，贵而特达、官至二三品；怕丑年不贵。","癸亥":"癸亥日甲寅时：子丑未申月中进士、走金水运有风宪；卯戌年月地支六合则贵。"},"癸日卯时":{"癸丑":"癸丑日乙卯时：辰丑月格高显贵；也有人说少年、中年显贵。","癸卯":"癸卯日乙卯时：寅卯月伤官格，主富贵；未戌年月靠技艺近贵；辰丑月吉。","癸未":"癸未日乙卯时：寅亥卯未月伤官伤尽只算刚强平常；辰戌申子月显贵。","癸酉":"癸酉日乙卯时：申子辰月贵；寅午戌月中等；亥卯未月平；巳酉丑月富。","癸亥":"癸亥日乙卯时：辰巳月有风宪之象。"},"癸日辰时":{"癸丑":"癸丑日丙辰时：平常；辰戌丑未月财官有气则贵。","癸卯":"癸卯日丙辰时：孤独离乡，但有财帛、显贵受人敬；卯亥年月为日贵格；午戌月可至九品至五品。","癸未":"癸未日丙辰时：格高；寅卯未月平常；辰戌丑月吉；巳月财官都旺则贵。","癸酉":"癸酉日丙辰时：孤而贵；巳酉丑月显贵；寅卯月不吉；子午月富；戌月大贵。","癸亥":"癸亥日丙辰时：柱中无甲木破损官库则贵，运宜南方。"},"癸日午时":{"癸丑":"癸丑日戊午时：财厚，走南运多主显贵但寿短；东运吉。","癸卯":"癸卯日戊午时：申子辰亥月身旺不化，只算平常；卯戌月显贵。","癸未":"癸未日戊午时：寅午戌月化火合局，显贵。","癸酉":"癸酉日戊午时：多主伤妻耗财，有始无终；子年月显贵但无禄，走南运较好。","癸亥":"癸亥日戊午时：显贵；未月走东运、金月有制，都贵。"},"癸日未时":{"癸丑":"癸丑日己未时：格高；年月都丑则贫薄；辰戌丑未月土旺，多主眼病、清苦；通金木水气则贵。","癸卯":"癸卯日己未时：子巳未年月可至二品；见巳寅字则刑六亲。","癸未":"癸未日己未时：格高；春月偏官有制则吉；夏平常；秋冬身旺；申月走木运显贵；巳辰年可至六卿。","癸酉":"癸酉日己未时：寅巳申酉丑戌年月显贵。"},"癸日申时":{"癸丑":"癸丑日庚申时：辰戌丑未年月文章冠世、官至三品；子月坐禄也吉。","癸卯":"癸卯日庚申时：卯月为合禄格，走西北运至金紫；申月走东北运有风宪；庚辰庚戌年月为正官格。","癸未":"癸未日庚申时：柱有甲寅乙卯，巳与甲合、乙与庚合，妻贤子孝、荣华在后；酉申年月可至三四品。","癸酉":"癸酉日庚申时：卯酉戊寅年月显贵；申酉月走火木运大贵。","癸亥":"癸亥日庚申时：性平身孤；卯未月有学问、显贵；申月也贵；子申月近侍有权。"},"癸日酉时":{"癸丑":"癸丑日辛酉时：秋月印绶格走官杀运则吉；冬福禄双全；子寅年月干头无戊己则贵。","癸卯":"癸卯日辛酉时：日贵格；辰戌丑未月贵；子卯年月大贵；巳午月也贵；另说不利妻子。","癸未":"癸未日辛酉时：春清苦、夏先后易、秋吉、冬贵。","癸酉":"癸酉日辛酉时：申酉月印绶多，能守祖业但破妻家；子巳午月干透庚辛、禄贵印绶俱全，贵不可言。","癸亥":"癸亥日辛酉时：戌月走东南运至金紫，东北运有风宪；子月建禄，年遇财官大贵。"},"癸日戌时":{"癸丑":"癸丑日壬戌时：有刑；亥月、土厚地方上贵；辰申年月走南运可中状元；春秋生另论。","癸卯":"癸卯日壬戌时：日贵格；寅巳年月干透戊丁、财官旺则大贵有权；卯辰丑午子年月文贵。","癸未":"癸未日壬戌时：有刑；巳月生可至三四品；子庚年月近侍之贵；癸酉日壬戌时、亥子月才智高、妻贤。","癸亥":"癸亥日壬戌时：春伤官见官；夏财旺；秋冬吉、名利有成；戌辰月走亥子运则贵。"},"癸日亥时":{"癸丑":"癸丑日癸亥时：作拱禄格；巳酉丑生为福德秀气；午月平常；卯酉月走南运至金紫有风宪。","癸卯":"癸卯日癸亥时：平常，日贵格；寅卯月伤官、走金水运有风宪；辰戌丑未月官旺；纯卯月三品。","癸未":"癸未日癸亥时：身坐财官；辰戌丑未月走东北运则贵；秋月走东运七八品；干透正印正官更好。","癸酉":"癸酉日癸亥时：辰戌丑未月生涯顺遂；酉月走东北运八九品；申月走东运五品。","癸亥":"癸亥日癸亥时：性飘逸，中年大富；冬月生是飞天禄马，没有戊己子填实牵绊则贵，否则孤克。"}}},"reading_bazi/rishi_plain":{"note":"日时断总论的白话改写：按原句意思压成一句，只留结论与条件，不改断语方向。","items":{"甲日子时":"甲日甲子时：子水暗生印、官又生印，月令有人帮就显贵；没人帮则聪明好看却落不到实处。","甲日丑时":"甲日乙丑时：官财都被比劫夺，若年日时合成火局把劫制住，反而能成。","甲日寅时":"甲日丙寅时：食神得地、自身健旺，柱里不见壬癸来克、又通火木月气，显贵；怕见官星和申来冲。","甲日卯时":"甲日丁卯时：伤官配羊刃，伤了官、夺了财，人偏狠；柱里透辛把伤制住才好。","甲日辰时":"甲日戊辰时：时上偏财坐库，多半靠做生意发财、田产丰厚；八月生财官都全，更富。","甲日午时":"甲日庚午时：午是甲的死地，又见庚为鬼，没救应的人多半带疾、寿促；月令帮身才有转机。","甲日未时":"甲日辛未时：官星坐天乙、财也有气，通木气月、有人托底就显贵。","甲日申时":"甲日壬申时：申是壬的长生、庚的禄，鬼旺；自身也旺的话能把鬼化成官，只是脾气免不了刚暴。","甲日酉时":"甲日癸酉时：胎地，明有癸印、暗藏辛官，己土来破印就不显贵。","甲日戌时":"甲日甲戌时：食神入了火局，自身被火烤，人多好善，衣食只算普通。","甲日亥时":"甲日乙亥时：亥上长生、又有乙刃和壬枭，官财都藏在里，要看月令给不给力。","乙日子时":"乙日丙子时：六乙鼠贵格，暗里邀来辛官，柱中不见庚辛、又没有丑午来搅，就贵。","乙日丑时":"乙日丁丑时：食神会合财官，丑里辛金成局，有人托底就显贵。","乙日卯时":"乙日己卯时：卯为建禄，人长得秀气，通木火月气显贵；见庚辛伤禄，容易犯目疾。","乙日辰时":"乙日庚辰时：乙庚化金，通金月就贵、但要防眼病；化不成就按官星论，妻子贤能。","乙日午时":"乙日壬午时：印绶坐学堂，午月见壬为印、丁为食，通水月气显贵。","乙日申时":"乙日甲申时：官印生身，通金水月运显贵；月令不帮忙就平常。","乙日酉时":"乙日乙酉时：身与鬼都旺，通金月化成金局就贵；用神落在木上则身强。","乙日戌时":"乙日丙戌时：丙把官背掉、戌中食神制杀，柱里透庚就成了伤官见官。","乙日亥时":"乙日丁亥时：死处逢生，得壬水印来生，喜甲木帮身。","丙日子时":"丙日戊子时：官旺财也生，可丙火没气；通火月帮身就贵，不通就贫。","丙日丑时":"丙日己丑时：伤官背禄、心高气傲，柱里透癸还能成器；见庚辛则走财路。","丙日寅时":"丙日庚寅时：寅为长生、文章秀气，通金局则财旺。","丙日卯时":"丙日辛卯时：辛财来合，身太旺又不化，人多无礼、贪色。","丙日辰时":"丙日壬辰时：水火未济，火在辰上失了光；春夏天身旺，能把鬼化成官。","丙日午时":"丙日甲午时：火太旺，要有己土把甲化开、把火气收住；生在土月反而有福。","丙日未时":"丙日乙未时：未是印库，通火月显贵；月令不帮、又没财，也算高命。","丙日申时":"丙日丙申时：财旺身弱，要兄弟来分担；月令帮身有力才贵。","丙日戌时":"丙日戊戌时：寿长、名利不失；寅亥卯未或申酉戌月生，显贵。","丁日子时":"丁日庚子时：财鬼都旺而丁火无气，通身旺月、有人托底就贵。","丁日丑时":"丁日辛丑时：丑是财库、辛是妻财，丁火无气，失了天时又没依靠，财来得快去得也快。","丁日寅时":"丁日壬寅时：丁壬化木、寅上健旺，水局月大贵，木月也贵。","丁日辰时":"丁日甲辰时：印绶坐官库，月令有帮、有人托底就显贵。","丁日午时":"丁日丙午时：建禄青云，支里无枭破、干上无癸来刑，禄元纯粹就贵。","丁日未时":"丁日丁未时：未是木库印绶，柱里不见财、不走财运，反成高格。","丁日申时":"丁日戊申时：官被戊土伤克，年月透壬才算见官有礼，有庚作财更好。","丁日戌时":"丁日庚戌时：墓中见财，福不成；再叠癸水克身，容易伤眼睛。","丁日亥时":"丁日辛亥时：财官双美，明辛暗壬、又生甲印，通金水就贵。","戊日子时":"戊日壬子时：妻财旺而自身弱，生在土月不化才得财。","戊日丑时":"戊日癸丑时：癸财藏在丑里，月令帮身把土化实，人聪明；通土气则富。","戊日寅时":"戊日甲寅时：身弱鬼旺，通身旺月把鬼化成官，主富贵；反过来就受制。","戊日卯时":"戊日乙卯时：官强身弱，没人帮就把官看成鬼，显贵也辛苦。","戊日辰时":"戊日丙辰时：官藏在财库里，辰中壬癸入库、乙木有余气。","戊日午时":"戊日戊午时：羊刃重叠、性子刚狠，见刑冲破害把刃制住，可做武职。","戊日申时":"戊日庚申时：食神生财，别让丙火破了财，也别再见寅巳刑冲。","戊日酉时":"戊日辛酉时：伤官旺、身败，人性傲；年月透乙则官星受伤。","戊日亥时":"戊日癸亥时：戊癸想化火，可亥是水乡化不成，人显得虚秀，多走九流技艺的路。","己日子时":"己日甲子时：明官暗财，子又是天乙，身有托就贵。","己日丑时":"己日乙丑时：专财逢鬼，身旺有托就显贵，鬼再得助就麻烦。","己日寅时":"己日丙寅时：官印生旺，无破、通木局月气，大贵。","己日卯时":"己日丁卯时：印透出来、鬼藏在卯里，月令没救应就虚秀不实。","己日未时":"己日辛未时：食神助官，未是官库，有托、月令帮忙就贵。","庚日子时":"庚日丙子时：身与鬼都弱，子水伤官旺，自身有托则吉。","庚日丑时":"庚日丁丑时：金重火轻，通木火月气，官印才相滋。","庚日寅时":"庚日戊寅时：寅里戊土合癸化火来克身，月令不帮金旺就劳碌。","庚日辰时":"庚日庚辰时：金水清白，但魁罡怕财官刑冲；不冲则以粗豪勇武显贵。","庚日午时":"庚日壬午时：官印健旺，通金土月气帮身就贵。","庚日未时":"庚日癸未时：印与财库同宫，癸水能制丁火。","庚日申时":"庚日甲申时：日禄落到时上，月令不帮丙火、又没刑冲，贵而平常。","庚日酉时":"庚日乙酉时：财与刃都旺，柱里无火，金太刚就容易折。","庚日戌时":"庚日丙戌时：金火相争，通身旺印绶、有救应才贵。","庚日亥时":"庚日丁亥时：财食都旺而自身失地，要看有没有托来任财食。","辛日子时":"辛日戊子时：六阴朝阳，柱里不见丙丁午，就贵。","辛日寅时":"辛日庚寅时：寅是天乙，丙为官、甲为财，通金木月气就贵。","辛日卯时":"辛日辛卯时：比肩分财，秋冬财官无气，只算平常。","辛日辰时":"辛日壬辰时：暗金沉到水底，年月透丙才算官星显露。","辛日午时":"辛日甲午时：鬼旺身弱，午是丁己旺地。","辛日未时":"辛日乙未时：天财入库，暗丁被明乙制住，财能留住。","辛日申时":"辛日丙申时：丙辛化水、申上长生，通金局则精神秀丽、文章聚福。","辛日酉时":"辛日丁酉时：火金相争，丁破禄，福不成、反复。","辛日戌时":"辛日戊戌时：禄堂与印同居，土太旺就会把火的光晦掉。","壬日子时":"壬日庚子时：刃旺身强，通火土月把庚癸制住，大贵。","壬日丑时":"壬日辛丑时：官印得位，月令有帮就清秀、禄位安稳。","壬日寅时":"壬日壬寅时：水火既济，通水局、有托的人皆贵。","壬日卯时":"壬日癸卯时：自身临死地、刃又生，卯中伤官旺，月令不帮就难成。","壬日辰时":"壬日甲辰时：壬骑龙背，食神旺相，月令有帮就富贵福厚。","壬日午时":"壬日丙午时：禄马三奇，通金水月气就贵。","壬日未时":"壬日丁未时：丁壬化木，通木局、有托就贵，月令不帮但有资助也能发财。","壬日申时":"壬日戊申时：水土混澜，身鬼都强，好坏看有没有制伏。","壬日戌时":"壬日庚戌时：枭神临财库，通火木月气、有托就贵。","壬日亥时":"壬日辛亥时：日禄居时，没克破、有托，柱中不见财官也富；走东运大贵。","癸日寅时":"癸日甲寅时：寅刑出巳中丙戊为财官，柱里没有官杀刑冲就有格。","癸日卯时":"癸日乙卯时：食神旺、学堂吉，无己破辛、无午酉刑冲则秀。","癸日辰时":"癸日丙辰时：身坐官库，见丙为财，辰又是水局。","癸日午时":"癸日戊午时：戊癸化火、午为帝旺，身旺不化就要往南方引气。","癸日申时":"癸日庚申时：专印合禄，申里合出巳中戊丙为财官。","癸日酉时":"癸日辛酉时：明暗都是枭神，没有救应就劳碌。","癸日戌时":"癸日壬戌时：水火既济，月令有帮有托就贵。","癸日亥时":"癸日癸亥时：禄马飞天格，亥里藏丙戊，癸本身无财官，要靠冲巳去取。"}},"reading_bazi/shensha":{"note":"白话版：查法 + 主什么。神煞只作参考，不单独断吉凶。","items":{"羊刃":"日主走到帝旺的那一支（甲卯、丙午、戊午、庚酉、壬子，阴干取对应）。主性急、有冲劲，刃被冲或再走刃运要留意。","空亡":"按日柱所在的旬查，旬里缺的两个地支就是空亡。落在哪一柱，那柱所主的事容易虚、不落实。","驿马":"三合局所冲的那一支（寅午戌见申、申子辰见寅、巳酉丑见亥、亥卯未见巳）。主走动、迁移、外出发展。","天乙贵人":"甲戊庚见丑未、乙己见子申、丙丁见亥酉、壬癸见卯巳、辛见午寅。主遇事有人帮、有贵人缘。","华盖":"三合局的墓库支（寅午戌见戌、申子辰见辰、巳酉丑见丑、亥卯未见未）。主偏静、有艺文或宗教缘，也容易独处。","咸池（桃花）":"三合局的沐浴支（寅午戌见卯、申子辰见酉、巳酉丑见午、亥卯未见子）。主人缘、异性缘好，也主感情事多。","孤辰寡宿":"按年支三会分组取：亥子丑见寅为孤、见戌为寡；寅卯辰见巳、丑；巳午未见申、辰；申酉戌见亥、未。主亲缘偏淡、喜独处。","魁罡":"日柱为庚辰、庚戌、壬辰、戊戌四日。主性刚、决断强，最好有东西管着。","天德":"按月份查天干或地支（如正月见丁、二月见申之类）。主逢凶有解、心性厚。","月德":"按月份查（寅午戌见丙、申子辰见壬、巳酉丑见庚、亥卯未见甲）。主温和、少灾。","劫煞":"三合局所绝之地（寅午戌见亥、申子辰见巳、巳酉丑见寅、亥卯未见申）。主突发之耗、竞争。","亡神":"三合局所临官之地（寅午戌见巳、申子辰见亥、巳酉丑见申、亥卯未见寅）。主思虑多、易有暗耗。"}},"reading_bazi/tiaohou_table":{"note":"《穷通宝鉴》调候用神表（十干配十二月），据《命运的求索》表7.1–7.11 转录；用神为天干。","table":{"甲":{"正月":["丙","癸"],"二月":["庚","丙","丁","戊","己"],"三月":["庚","丁","壬"],"四月":["癸","丁","庚"],"五月":["癸","丁","庚"],"六月":["癸","丁","庚"],"七月":["庚","丁","丙"],"八月":["庚","丁","丙"],"九月":["庚","甲","丁","壬","癸"],"十月":["庚","丁","丙","戊"],"十一月":["丁","庚","丙"],"十二月":["丁","庚","丙"]},"乙":{"正月":["丙","癸"],"二月":["丙","癸"],"三月":["癸","丙","戊"],"四月":["癸"],"五月":["癸","丙"],"六月":["癸","丙"],"七月":["丙","癸","己"],"八月":["癸","丙","丁"],"九月":["癸","辛"],"十月":["丙","戊"],"十一月":["丙"],"十二月":["丙"]},"丙":{"正月":["壬","庚"],"二月":["壬","己"],"三月":["壬","甲"],"四月":["壬","庚","癸"],"五月":["壬","庚"],"六月":["壬","庚"],"七月":["壬","戊"],"八月":["壬","癸"],"九月":["甲","壬"],"十月":["甲","戊","庚","壬"],"十一月":["壬","戊","己"],"十二月":["壬","甲"]},"丁":{"正月":["甲","庚"],"二月":["庚","甲"],"三月":["甲","庚"],"四月":["甲","庚"],"五月":["壬","庚","癸"],"六月":["甲","壬","庚"],"七月":["甲","庚","丙","戊"],"八月":["甲","庚","丙","戊"],"九月":["甲","戊","庚"],"十月":["甲","庚"],"十一月":["甲","庚"],"十二月":["甲","庚"]},"戊":{"正月":["丙","甲","癸"],"二月":["丙","甲","癸"],"三月":["甲","丙","癸"],"四月":["甲","丙","癸"],"五月":["壬","甲","丙"],"六月":["癸","丙","甲"],"七月":["丙","癸","甲"],"八月":["丙","癸"],"九月":["甲","丙","癸"],"十月":["甲","丙"],"十一月":["丙","甲"],"十二月":["丙","甲"]},"己":{"正月":["丙","庚","甲"],"二月":["甲","癸","丙"],"三月":["丙","癸","甲"],"四月":["癸","丙"],"五月":["癸","丙"],"六月":["癸","丙"],"七月":["丙","癸"],"八月":["丙","癸"],"九月":["甲","丙","癸"],"十月":["丙","甲","戊"],"十一月":["丙","甲","戊"],"十二月":["丙","甲","戊"]},"庚":{"正月":["戊","甲","壬","丙","丁"],"二月":["丁","甲","庚","丙"],"三月":["甲","丁","壬","癸"],"四月":["壬","戊","丙","丁"],"五月":["壬","癸"],"六月":["丁","甲"],"七月":["丁","甲"],"八月":["丁","甲","丙"],"九月":["甲","壬"],"十月":["丁","丙"],"十一月":["丁","甲","丙"],"十二月":["丙","甲","丁"]},"辛":{"正月":["己","壬","庚"],"二月":["壬","甲"],"三月":["壬","甲"],"四月":["壬","癸","甲"],"五月":["壬","己","癸"],"六月":["壬","庚","甲"],"七月":["壬","甲","戊"],"八月":["壬","甲"],"九月":["壬","甲"],"十月":["壬","丙"],"十一月":["丙","戊","壬","甲"],"十二月":["丙","壬","戊","己"]},"壬":{"正月":["庚","丙","戊"],"二月":["戊","辛","庚"],"三月":["甲","庚"],"四月":["庚","辛","壬","癸"],"五月":["癸","庚","辛"],"六月":["辛","甲"],"七月":["戊","丁"],"八月":["甲","庚"],"九月":["甲","丙"],"十月":["戊","丙","庚"],"十一月":["戊","丙"],"十二月":["丙","丁","甲"]},"癸":{"正月":["辛","丙"],"二月":["庚","辛"],"三月":["丙","辛","甲"],"四月":["辛"],"五月":["庚","辛","壬","癸"],"六月":["庚","辛","壬","癸"],"七月":["丁"],"八月":["辛","丙"],"九月":["辛","甲","壬","癸"],"十月":["庚","辛","戊","丁"],"十一月":["丙","辛"],"十二月":["丙","丁"]}}},"reading_bazi/wuxing":{"version":"0.1","note":"白话版：据《三命通会》卷一「论五行生成」「五行生克」「总纳音」「论天干」「论地支」「人元司事」等篇提炼，只留结论，不标出处。","items":[{"key":"shengcheng","title":"五行生成","body":"水一、火二、木三、金四、土五，这五个数不是随手排的：水在北方子位，子是一阳初生，所以水是一；火在南方午位，午是二阴初生，所以火是二；木在东方，东属阳，三又是奇数，所以木是三；金在西方，西属阴，四又是偶数，所以金是四；土在西南长夏，五是奇数，所以土是五。\n\n生成的时候，水六、火七、木八、金九，土则常以五为用，不必到十。万物靠这套数生成，不能逃出这个范围。"},{"key":"shengke","title":"五行相生相克","body":"木在东方、主春天：木是阳气一动、顶开地面长出来的。水往东流来生木，木往上长、根往下扎，这是它本来的样子。\n\n火在南方、主夏天：火是化、是毁，阳气在上、阴气在下，烧得旺就能把万物化开。钻木取火，火由木生；但火没有固定的形体，它的根还在木。\n\n金在西方、主秋天：金是禁，阴气开始收敛万物的时候。金子从沙里淘、从土里出，生于土又与土分开。\n\n水在北方、主冬天：水是藏，万物都藏在里面。\n\n土在中央、寄旺四季：金木水火都要靠土才能成，所以五行里土的分量特殊。"},{"key":"nayin","title":"纳音为什么从金起","body":"六十甲子的纳音，用的是六十律旋相为宫的办法，跟《易经》的纳甲同一路数：乾纳甲、坤纳癸，从乾开始到坤结束。\n\n纳音先从金起、最后到土，因为五行里只有金做成器物会响，声音最明显。\n\n具体排法是「同类娶妻、隔八生子」，是律吕相生的路子。所以纳音讲的不是五行本身，而是五行被「敲响」时的音。"},{"key":"ganzhi","title":"天干地支与藏干","body":"天干叫「天元」，管的是禄；地支叫「地元」，管的是身；地支里藏着的天干叫「人元」，也就是司事的那位，算命时就是月令所取的用神所在。\n\n一个月里藏着的天干并不是平均分：比如正月建寅，寅里先是艮土用事五天，再是丙火长生五天，剩下二十天由甲木当值。所以看月令，要看这一段里到底是谁在管事。"},{"key":"dun","title":"月柱和时柱怎么推","body":"月柱用五虎遁：甲己之年丙作首，乙庚之岁戊为头，丙辛之岁寻庚上，丁壬壬位顺行流，戊癸之年甲寅起。\n\n时柱用五鼠遁：甲己还加甲，乙庚丙作初，丙辛从戊起，丁壬庚子居，戊癸何方发，壬子是真途。\n\n说白了就是：年干定月干，日干定时干，顺着十二个月、十二个时辰往下排。"}]},"reading_bazi/xingqing":{"note":"据《子平汇刊》本《渊海子平》卷三「论性情」、卷四「十干体象」「十二支体象」整理，诗诀保留原句，白话为改写。","yao":"看性情，先看日干（你本身），再看月支（你落的时节）；四柱之间别互相打架。五行一多就杂，人的格局就不清。日干弱的，遇事容易往后缩、怕羞；日干强的，又容易自以为是、话说得大。","gan":{"甲":{"xiang":"参天大树、栋梁之材","xing":"性仁厚正直，肯担事，喜欢往上长、往外撑","xi":"底下有土把根扎住，再有金来修枝打杈，才成得了栋梁。","ji":"火太多，木头被烧成灰；水太多，根泡得漂起来。","poem":"甲木天干作首排，原无枝叶与根荄；欲存天地千年久，直向泥沙万丈埋。斫就栋梁金得用，化成灰炭火为灾。","yuan":"甲木枝干分刚柔，春生忌再扶，遇火有文明之象"},"乙":{"xiang":"藤萝花草、蔓生之木","xing":"性柔顺随人，根浅却韧，靠依附攀缘成事","xi":"喜欢向阳的地方，有水滋润，再有点木来作伴。","ji":"怕阴湿。水多了根漂，金多了被砍折；往南火太炎、往西土太重，都容易受伤。","poem":"乙木根荄种得深，只宜阳地不宜阴；漂浮最怕多逢水，刻斫何当苦用金。南去火炎灾不浅，西行土重祸犹侵。","yuan":"卯木为有根荄，宜阳地不宜阴，叠旺则成其林"},"丙":{"xiang":"太阳之火","xing":"性光明正大、热情外放，心直口快，爱显扬","xi":"有壬水映着，光才显得出来；再加木来生火。","ji":"其实不怕水来克。真正怕的是木太多、长成林子把光遮了；再就是火太旺，烧得干。","poem":"丙火明明一太阳，原从正大立纲常；洪光不独窥千里，巨焰犹能遍八荒。江湖宛水安能克，惟怕成林木作殃。","yuan":"丙火太阳之象，忌生扶喜剥削，水不合则火不能克，惟忌木盛则蔽之"},"丁":{"xiang":"灯烛之火","xing":"性内敛细腻，心思密，耐得住，也记仇","xi":"时候对了，灯烛之火也炼得动金；再拿干柴（木）把火引起来。","ji":"时候不对，连一寸金都熔不动；木是湿的，点不着；太阳（丙）一出来，灯烛的光就被夺了。","poem":"丁火其形一烛灯，太阳相见夺光明；得时能化千金铁，失令难熔一寸金。虽少干柴犹可引，纵多湿木不能生。","yuan":"丁日未支得时，忌失令，虽未能生湿木，难发真光"},"戊":{"xiang":"城墙堤岸之土","xing":"性厚重稳当，能扛事、能挡风浪，也容易固执","xi":"底下根基厚——有火来生、有土来帮——才立得稳；东南方向顺手。","ji":"根基薄了，金一来就把土气泄走；水一大，堤就崩；木疏得太狠，土也空了。","poem":"戊土城墙堤岸同，镇江河海要根重；柱中带合形还壮，日下乘虚势必崩。力薄不胜金漏泄，功成安用木疏通。","yuan":"戊土禄厚，喜逢巳寅生合，水盛则崩"},"己":{"xiang":"田园之土","xing":"性温和能容，能屈能伸，善于周旋养人","xi":"火土凑成一局最好；时候对了，才载得住东西。","ji":"水金旺的地方，自身就弱；时候不对，连剑戟都埋不住。印太旺、合又多，再碰上刑冲，总归不合适。","poem":"己土田园属四维，坤深能为万物基；水金旺处身还弱，火土功成局最奇。失令岂能埋剑戟，得时方可用鎡基。","yuan":"己土阴土，应合去，忌失时，善生旺又喜刑冲"},"庚":{"xiang":"顽铁生金","xing":"性刚直果断，讲义气，不服软、不肯拐弯","xi":"得用火反复锻打才成器。夏天生的往东南走，还得再炼；秋天生的往西北走，本身就带光芒。","ji":"水多的地方像淬冷了会生锈；土太重把金埋了；木太旺，金去砍它反倒自己受损。","poem":"庚金顽钝性偏刚，火制功成怕水乡；夏产东南过锻炼，秋生西北亦光芒。水深反见他相克，木旺能令我自伤。","yuan":"庚金顽铁，忌生扶，喜剥削，怕土重及木多"},"辛":{"xiang":"珠玉之金","xing":"性清高灵秀，爱美讲体面，心思细、要面子","xi":"最喜欢天气和暖、水又清；湿土能生金，也合它的性子。","ji":"用不着猛火去炼。木多火旺的时候，往西北走比较稳；水冷金寒，得有丙丁火来暖一暖；自己坐禄有根了，就不必再靠厚土。","poem":"辛金珠玉性通灵，最爱阳和沙水清；成就不劳炎火煅，资扶偏爱湿泥生。木多火旺宜西北，水冷金寒要丙丁。","yuan":"辛金温润，喜生扶忌剥削，喜见土水逢之，喜行西北"},"壬":{"xiang":"江河大海之水","xing":"性聪慧量大，能容能变，格局要大才安","xi":"有土作堤才不泛滥；火土能成财官。长生在申、归禄在亥，这两个位置是它的根。","ji":"干支上水太多就漂了；火土太重又把源头烤干。身强却没有财禄，往西北走，早年多半不顺。","poem":"壬水汪洋并百川，漫流天下总无边；干支多聚成漂荡，火土重逢涸本源。养性结胎须未午，长生归禄属乾坤。","yuan":"壬水有根之水，忌生扶喜剥削，无土则漫流"},"癸":{"xiang":"雨露之水，通亥子则成江河","xing":"性内敏善谋，心思深，不轻易外露","xi":"要有人生扶，还得有根（亥子）；八字里有财官也不嫌多。","ji":"最怕被克泄得太狠；一点土都没有，就散得没形。申子辰凑齐反而是上格，寅午戌齐了也算中和。","poem":"癸水应非雨露么，根通亥子即江河；柱无坤坎身还弱，局有财官不尚多。申子辰全成上格，寅午戌备要中和。","yuan":"癸乃润泽之水，通亥子则成江海，喜生扶忌剥削，喜合忌克冲"}},"zhi":{"子":{"xiang":"溪涧汪洋之水，一阳初生","xing":"性灵动多智，机敏，外柔内主意多","xi":"跟申、辰合成局，水就成了江海；有丑土作堤，才收得住。","ji":"被午一冲就定不下来；跟卯相刑还算有情。水太旺、没人管，就漂了。","poem":"月支子水占魁名，溪涧汪洋不尽清；天道阳回行土旺，人间水暖寄金生。若逢午破应无定，纵遇卯刑还有情。"},"丑":{"xiang":"隆冬湿土，二阳回转","xing":"性耐忍含蓄，能存能藏，慢热","xi":"土暖了才生万物；日时上水木多的，往东南走合适。","ji":"怕冰霜太重。跟戌未刑冲，反倒把库打开有了用；金寒的时候就深藏不动。","poem":"隆冬丑土怯冰霜，谁识天时转二阳；暖土诚能生万物，寒金难道只深藏。"},"寅":{"xiang":"三阳之木，气聚火生","xing":"性向上有冲劲，敢开头，脾气来得快","xi":"跟午戌合成火局；跟巳、申相合，能带来贵人；跟卯未合，是成家的格局。","ji":"申来冲，把月令和禄都冲破了；火本来多，再往南方走就太燥。","poem":"艮宫之木建于春，气聚三阳火在寅；志合蛇猴三贵客，类同卯未一家人。超凡入圣惟逢午，破禄伤提独虑申。"},"卯":{"xiang":"仲春正旺之木，繁华","xing":"性温润有风致，重情面，易受外物影响","xi":"跟亥未三合成林，再有人来生扶。","ji":"最怕庚辛和申酉一层层叠上来；亥子壬癸水太重也不行；走到酉运容易受伤。","poem":"卯木繁华秉气深，仲春难道不嫌金；庚辛叠见愁申酉，亥子重来忌癸壬。祸见六冲应落业，喜逢三合便成林。"},"辰":{"xiang":"三月湿土，水木之库","xing":"性沉稳有涵养，善藏事，转得快","xi":"这个库得冲一下才开，像拿钥匙开门；开了走水木就顺。","ji":"冲得太狠，门就破了；水木本来就重，再走西北运，这点厚土存不住。","poem":"辰当三月水泥温，长养堪培万木根；虽是甲衰乙余气，纵然壬墓癸还魂。直须一钥能开库，若遇三冲即破门。"},"巳":{"xiang":"初夏火旺之地，六阳","xing":"性热烈能干，行动快，场面大","xi":"东南是生发之地；时候对了，戊土跟着母（火）走，也有禄。","ji":"庚金这时候不当令，只能靠印来生；巳亥一冲就有伤，寅来刑巳反倒没什么；往西北走气就衰了。","poem":"巳当初夏火增光，造化流行正六阳；失令庚金生赖母，得时戊土禄随娘。三刑传送翻无害，一撞登明便有伤。"},"午":{"xiang":"炎炎之火，六阳一阴生","xing":"性外放大方，热得快也散得快","xi":"跟寅戌合成火局；东南正是它最强的地方。","ji":"最怕子来冲——用火的人一冲就散；申子一齐来，就是硬碰硬地克。","poem":"午月炎炎火正升，六阳气续一阴生；申子齐来能战克，戌寅同见越光明。东南正是身强地，西北休囚已丧形。"},"未":{"xiang":"六月阴深，火渐衰，木之库","xing":"性内敛持重，藏得住心事","xi":"带点刑冲，库才开；天冷的时候，得有丙丁火来暖。","ji":"一点火都没有还走金水，就吃亏；旁边没有亥卯，这个局就变不动。","poem":"未月阴深火渐衰，藏官藏印不藏财；近无亥卯形难变，远带刑冲库亦开。无火怕行金水去，多寒偏爱丙丁来。"},"申":{"xiang":"月建之金，金刚健，水土长生","xing":"性爽利果断，能扛也能伤人","xi":"有巳午的炉火来炼，才成剑戟；跟子辰成局，锋芒就出来了。","ji":"土太重会把金埋了，这是真吃亏；木多要是没水，金最后还能赢。","poem":"申金刚健月支逢，水土长生在此宫；巳午炉中成剑戟，子辰局里得光锋。木多无水终能胜，土重埋金却有凶。"},"酉":{"xiang":"八月辛金旺地，金白水清","xing":"性清亮爱洁，讲究，容不得含糊","xi":"有水润着；三合成局，就坚利得很。","ji":"火多了发愁，往寅卯东方走不利；木旺的时候往南走、见丙丁反倒好；西北其实跟它是有情的。","poem":"八月从魁已得名，羡他金白水流清；火多东去愁寅卯，木旺南行怕丙丁。"},"戌":{"xiang":"九月刚土，火土之库","xing":"性刚硬守信，讲义气，护短","xi":"有火来炼才成器；辰来一冲，能生出雨露；跟寅相合，文章就活了。","ji":"这地方旧称天罗，容易让人迷糊；火命的人碰上容易受伤；木太旺就克土。","poem":"九月河魁性最刚，发云于此物收藏；洪炉巨火能成就，钝铁顽金赖主张。海窟冲龙生雨露，山头合虎动文章。"},"亥":{"xiang":"登明之位，水旺之地，六阴","xing":"性深沉多思，藏锋，慢热但有后劲","xi":"有午（胜光）和土来管着；往东北、东南这些和暖的方向走。","ji":"碰不上申（传送），水就浪得没边；金一多，水更泛滥。","poem":"登明之位水源深，雨雪生寒值六阴；必待胜光方用土，不逢传送浪多金。"}},"wuxing":{"木":{"xing":"仁","ti":"清秀体长，面色青白","guo":"过了头，人容易折、脾气偏硬；不够的时候，少了那点仁厚，心里容易生妒。"},"火":{"xing":"礼","ti":"面上尖下圆，印堂窄，鼻露窍；精神闪烁，言语急，坐则摇膝，面色或青赤","guo":"过了头，机灵会滑向讨好，性子急、胡子发赤；不够的时候，人黄瘦，心术容易偏，事情有头没尾。"},"土":{"xing":"信","ti":"背圆腰阔，鼻大口方，眉目清秀，面如墙壁，色黄","guo":"过了头，老实到有点笨、认死理；不够的时候，脸色总像有心事，鼻梁低、脸偏，声音重而浊。"},"金":{"xing":"义","ti":"骨肉相应，方面白色，眉高眼深，高鼻耳仰，声音清响","guo":"过了头，勇是够的，却少了仁，好斗又贪；不够的时候，想得多、下不了决心，手也紧。"},"水":{"xing":"智","ti":"志足多谋，机关深远，文学聪明","guo":"过了头，心思活络到有点滑、人也飘；不够的时候，胆子小、没什么主意，身形偏瘦小。"}}},"reading_bazi/yun_notes":{"version":"0.2","note":"白话版：只留判断与理由，不显示出处。","dayun":{"principle":"大运是从月令顺逆推出来的，一步管十年，干支一起看。看运只讲喜忌：走到喜用的地方就顺，走到忌神的地方就别扭。","judge":["命里身旺，走克、泄、耗的运顺手；身弱，走生扶的运顺手。","运和命局合出三合三会：合出来是你用得上的，帮力就大；合出来是添乱的，事情就容易堵。","运干和运支要分开看，各自跟命局、流年发生生克合冲。本版按干支各半算，是个近似。"]},"liunian":{"principle":"流年是那年管事的主角，吉凶还是按喜忌定：冲掉忌神是好事，冲掉喜用就麻烦。","judge":["流年干支是你用得上的，这一年就顺；是添乱的，事情就容易卡。","日柱或大运跟流年天克地冲，叫「征太岁」，这一年一定动；动的是好是坏，看冲掉的是哪一边。","岁运相生、或者跟命里用得上的那一头相合，是好事；岁运并临、伏吟反吟又不见可用的，多半反反复复。","岁运跟命局合成化气：化出来是能用的就顺，是添乱的就滞。"]},"special":{"cong":{"name":"从格","rule":"日主没根、没人帮、连印都没有，满盘偏在一边，只好顺着走：从杀、从财、从儿。从的越旺越好，日主越弱越好。","ji":"最怕日主突然有根，从不成，反而出祸。"},"zhuanwang":{"name":"专旺格","rule":"日主自己成一气（成三合或三会），气势纯，越旺越好，喜欢生它、帮它。","ji":"怕走克破的运，也怕杂神破局。"},"hua":{"name":"化气格","rule":"日主和旁边的天干合化成另一种五行，化出来的那股气又正好当令，就是真化；不当令就是假化。","ji":"怕争合、妒合，也怕克化神的东西；化神喜旺怕衰。"}},"commentary_note":"看命以用神和全局配合为准，不拿神煞断生死。"},"reading_qimen/daily_qimen_copy":{"note":"日家奇门今日一句：休门方位 + 太乙星方位。零术语、少用「你」、≤35 字。","door_actions":{"休门":"歇口气、慢慢谈","生门":"谈事求财","开门":"见人办事","景门":"递文书","伤门":"带点锋的事","杜门":"躲一躲","死门":"了结旧事","惊门":"放消息"},"star_phrases":{"太乙":"求财谋事都顺当","青龙":"觅利有喜","太阴":"暗处有财","天乙":"宜会客饮宴","天符":"宜静不宜动","摄提":"少与人争","轩辕":"出门多留神","招摇":"凡事让一让","咸池":"防口舌官非"},"variants":["今日{dir}方顺，{action}。","今日{dir}有吉，{action}。","太乙在{taiyi_dir}方，{phrase}。"]},"reading_qimen/doors":{"开门":{"jixiong":"吉","wx":"金","gist":"开是打开、公开、走正门的意思。事情摆在明面上办，名正言顺，就顺着它。","yong":"适合见官、面谈、开业、上任、搬家、考试报名这类「走正规流程」的事。","ji":"不适合偷偷摸摸、走偏门的打算——开门最讲名分，阴私的事反而容易被摊开。","gong":"落在乾、兑宫最舒展；落艮宫像金埋在土里施展不开；落离宫被火克着，硬碰容易受伤。"},"休门":{"jixiong":"吉","wx":"水","gist":"休是休整、和解、慢慢来。不争不抢，靠关系和耐心把事办成。","yong":"适合求人调停、谈和、退一步的谈判、休息养病、收账讲情面。","ji":"不适合赶进度、强攻硬上——休门要的是缓，急事用它容易误时。","gong":"落在震、坎宫顺；落坤、艮宫被土克，落在巽宫像水进了洼地施展不开。"},"生门":{"jixiong":"大吉","wx":"土","gist":"生是生长、生财、有活路。万物在这一格有生机，是整张盘里最好的一扇门之一。","yong":"适合求财、谈生意、找工作、动土盖房、种养买卖，尤其跟土地、房子、实业沾边的事。","ji":"唯独不适合丧葬吊唁——生门忌死气，喜事别和丧事混着办。","gong":"落在乾、兑、艮宫旺；落坎宫反着劲儿，落震宫被克，硬来容易伤本钱。"},"伤门":{"jixiong":"凶","wx":"木","gist":"伤是消耗、磨擦、费力气。门开着，但走过去要掉层皮。","yong":"反倒适合讨债、抓捕、竞争博弈这类需要「带点锋」的事。","ji":"不适合出行、谈判、结婚搬家这些求顺的事——动辄有磕碰，劳而无功。","gong":"落在震、巽宫旺；落坤宫入墓、落艮宫被迫，更凶。"},"杜门":{"jixiong":"小凶","wx":"木","gist":"杜是堵住、关起来、不出声。这一格适合藏，不适合露。","yong":"适合躲避、隐匿、闭关做事、堵漏洞，也适合闭门把一样东西做扎实。","ji":"不适合求人办事、见面沟通——杜门关着，路是断的，越问越僵。","gong":"落在乾宫反着劲、落兑宫被克，藏不住；落坎宫反而有人帮你接着。"},"景门":{"jixiong":"次吉","wx":"火","gist":"景是光亮、场面、文书。热闹好看，但光鲜是给别人看的，里子未必厚。","yong":"适合递交文书、投稿、考试笔试、宴请、见场面上的事。","ji":"不适合求实利、谋大事——景门主虚火，也常带着口舌是非，白纸黑字的事反而容易惹纠纷。","gong":"落离、坤、艮宫可以；落乾、兑宫被迫，场面撑不住；落坎宫反着劲。"},"死门":{"jixiong":"凶","wx":"土","gist":"死是停住、结束、没有回旋。这一格的事，宜收不宜开。","yong":"只有吊唁、了结旧事、清账封账、下决心做个了断，才适合走这扇门。","ji":"不适合开张、结婚、动土、求医问药——新事撞上死门，多半起不来。","gong":"落乾、兑宫反而旺（凶门旺，凶得更明白），要格外留心。"},"惊门":{"jixiong":"凶","wx":"金","gist":"惊是虚惊、口舌、人心不稳。事情里有杂音，先别当真，也别对吵。","yong":"适合设疑、佯动、谈判时虚晃一枪这类需要「造声势」的场合。","ji":"不适合签约、定事、见重要的人——惊门里消息多半有水分，容易惊而不实。","gong":"落兑、乾、坎宫旺；落震、巽宫死气一点，落离宫被火克着反而稍安。"}},"reading_qimen/dunfa":{"天遁":{"level":"吉","text":"开、休、生三吉门，天盘丙奇加地盘丁奇，或临九地、太阴，为天遁。可以遁迹隐形，乘天德月德等吉神，百事皆吉。"},"地遁":{"level":"吉","text":"开、休、生三吉门合乙奇，临地盘六合、九地、太阴，为地遁。得日精所护，宜筑造起造、葬埋藏匿，百事皆吉。"},"人遁":{"level":"吉","text":"开、休、生三吉门合三奇临六合，或生门三奇临太阴、生门乙奇临九地，为人遁。宜和合人事，求财喜、谋望遂心。"},"风遁":{"level":"吉","text":"开、休、生合乙奇，临六辛落巽宫，为风遁。此方宜祭风，行兵利火攻。"},"云遁":{"level":"吉","text":"开、休、生合乙奇临六辛宫，或生门天芮临坤、三吉门合辛临乙，为云遁。冬宜祈雪，夏宜求雨。"},"龙遁":{"level":"吉","text":"开、休、生合天心星、六壬于坎宫，为龙遁。此方祈雨必应，水战必胜。"},"虎遁":{"level":"吉","text":"开门合庚临兑宫，或休门乙奇加辛于艮、生门辛加乙于艮，为虎遁。宜祭风、镇邪、安宅，利为客。"},"神遁":{"level":"吉","text":"开门乙奇合天心、天禽星临九天于乾宫，为神遁。此方宜祭祀祈祷，神必暗助。"},"鬼遁":{"level":"吉","text":"休门天辅辛临丁奇，或生门太阴、九地临丁奇，为鬼遁。宜探路侦贼、用间谋，宅中有异宜书符镇之。"},"真诈":{"level":"吉","text":"开、休、生三吉门合三奇，临地盘太阴宫，为真诈。宜施恩隐遁、祈祷求位，吉。"},"重诈":{"level":"吉","text":"开、休、生三吉门合三奇，临地盘六合宫，为重诈。宜收降添兵、纳财袭爵、拜印绶，吉。"},"休诈":{"level":"吉","text":"开、休、生三吉门合三奇，临地盘九地宫，为休诈。宜合药祈福、禳灾祭祀、施恩隐遁，大吉。"},"天假":{"level":"吉","text":"景门合乙丙丁三奇，临地盘九天宫，为天假。宜陈述事务、谒贵求官，大吉。"},"地假":{"level":"吉","text":"杜门合丁己癸，临九地、太阴或六合宫，为地假。宜潜藏埋伏、躲避灾难。"},"人假":{"level":"吉","text":"惊门合六合或六壬，临地盘九天宫，为人假。宜捕捉逃亡，若太白荧惑入己必获。"},"神假":{"level":"吉","text":"伤门合丁己癸，临地盘九地宫，为神假。宜埋葬伏藏，人不能知。"},"鬼假":{"level":"吉","text":"死门合丁己癸，临地盘九地宫，为鬼假。宜超亡荐度。"}},"reading_qimen/kekying":{"戊戊":{"name":"伏吟","level":"平","text":"天盘戊加地盘戊，谓之伏吟，凡事闭塞，宜静守不宜动。"},"戊乙":{"name":"青龙合灵","level":"平","text":"戊加乙为青龙合灵，门吉则事吉，门凶则事凶，吉凶以门为准。"},"戊丙":{"name":"青龙返首","level":"吉","text":"戊加丙为青龙返首，动作大利，但若逢墓迫击刑，则吉事变凶。"},"戊丁":{"name":"青龙耀明","level":"吉","text":"戊加丁为青龙耀明，谒贵求名吉利；若值墓迫，反招是非。"},"戊己":{"name":"贵人入狱","level":"凶","text":"戊加己为贵人入狱，公私皆不利，宜守不宜求。"},"戊庚":{"name":"值符飞宫","level":"凶","text":"戊加庚为值符飞宫，吉事不吉，凶事更凶。"},"戊辛":{"name":"青龙折足","level":"凶","text":"戊加辛为青龙折足，吉门生助尚可谋为；逢凶门招灾失财，防足疾。"},"戊壬":{"name":"青龙入天牢","level":"凶","text":"戊加壬为青龙入天牢，阴事阳事都不利，宜避锋芒。"},"戊癸":{"name":"青龙华盖","level":"吉","text":"戊加癸为青龙华盖，吉格者招福，若门凶则多乖舛。"},"乙戊":{"name":"利阴害阳","level":"凶","text":"乙加戊为利阴害阳，门逢凶迫则财破人伤。"},"乙乙":{"name":"日奇伏吟","level":"平","text":"乙加乙为日奇伏吟，不宜谒贵求名，只可安分守身。"},"乙丙":{"name":"奇仪顺遂","level":"吉","text":"乙加丙为奇仪顺遂，遇吉星可迁官进职；遇凶星则夫妻离别。"},"乙丁":{"name":"奇仪相佐","level":"吉","text":"乙加丁为奇仪相佐，传送文书吉利，百事可为。"},"乙己":{"name":"日奇入雾","level":"平","text":"乙加己为日奇入雾，前程不明；得凶门必凶，得二吉门为地遁。"},"乙庚":{"name":"日奇被刑","level":"凶","text":"乙加庚为日奇被刑，争讼败产，夫妻各怀私心。"},"乙辛":{"name":"青龙逃走","level":"凶","text":"乙加辛为青龙逃走，奴仆拐带，六畜皆伤，防破财。"},"乙壬":{"name":"日奇入地","level":"凶","text":"乙加壬为日奇入地，尊卑悖乱，官讼是非。"},"乙癸":{"name":"华盖逢星官","level":"吉","text":"乙加癸为华盖逢星官，宜遁迹修道、隐匿藏形，躲灾避难为吉。"},"丙戊":{"name":"飞鸟跌穴","level":"吉","text":"丙加戊为飞鸟跌穴，谋为百事洞明，进财进喜。"},"丙乙":{"name":"日月并明","level":"吉","text":"丙加乙为日月并行，公谋私为皆吉。"},"丙丙":{"name":"月奇悖师","level":"凶","text":"丙加丙为月奇悖师，文书逼迫，破耗遗失。"},"丙丁":{"name":"月奇朱雀","level":"吉","text":"丙加丁为月奇朱雀，贵人文书吉利，常人平静；得三奇门为天遁。"},"丙己":{"name":"大悖入刑","level":"凶","text":"丙加己为大悖入刑，囚人刑杖，文书不行；得吉门吉，凶门转凶。"},"丙庚":{"name":"荧入太白","level":"凶","text":"丙加庚为荧入太白，门户破败，盗贼耗失，宜守不宜攻。"},"丙辛":{"name":"谋事就成","level":"吉","text":"丙加辛为谋事就成，病人遇之不凶，事可谋成。"},"丙壬":{"name":"火入天罗","level":"凶","text":"丙加壬为火入天罗，为客不利，是非颇多。"},"丙癸":{"name":"华盖悖师","level":"凶","text":"丙加癸为华盖悖师，阴人害事，灾祸颇生。"},"丁戊":{"name":"青龙转光","level":"吉","text":"丁加戊为青龙转光，官人升迁，常人威昌。"},"丁乙":{"name":"人遁吉格","level":"吉","text":"丁加乙为人遁吉格，贵人加官进爵，常人婚姻财喜。"},"丁丙":{"name":"星随月转","level":"吉","text":"丁加丙为星随月转，贵人越级高升，常人乐中生悲。"},"丁丁":{"name":"奇入太阴","level":"吉","text":"丁加丁为奇入太阴，文书即至，喜事遂心。"},"丁己":{"name":"火入勾陈","level":"凶","text":"丁加己为火入勾陈，奸私仇冤，事因女人而起。"},"丁庚":{"name":"年月日时格","level":"平","text":"丁加庚为年月日时格，文书阻隔，行人必归。"},"丁辛":{"name":"朱雀入狱","level":"平","text":"丁加辛为朱雀入狱，罪人释囚，官人失位。"},"丁壬":{"name":"五神互合","level":"吉","text":"丁加壬为五神互合，贵人恩诏，讼狱公平。"},"丁癸":{"name":"朱雀投江","level":"凶","text":"丁加癸为朱雀投江，文书口舌，音信沉溺。"},"己戊":{"name":"犬遇青龙","level":"平","text":"己加戊为犬遇青龙，门吉谋望遂意，门凶枉费心机。"},"己乙":{"name":"墓神不明","level":"平","text":"己加乙为墓神不明，宜遁迹隐形，逃走为利。"},"己丙":{"name":"火悖地户","level":"凶","text":"己加丙为火悖地户，阳人冤冤相害，阴人淫污。"},"己丁":{"name":"朱雀入墓","level":"平","text":"己加丁为朱雀入墓，文状词讼，先曲后直。"},"己己":{"name":"地户逢鬼","level":"凶","text":"己加己为地户逢鬼，病者必死，百事不遂。"},"己庚":{"name":"刑格返名","level":"凶","text":"己加庚为刑格返名，词讼先动者不利，阴星有谋害之情。"},"己辛":{"name":"游魂入墓","level":"凶","text":"己加辛为游魂入墓，大人鬼魅，小人作祟。"},"己壬":{"name":"地网高张","level":"凶","text":"己加壬为地网高张，狡童佚女，奸情伤杀。"},"己癸":{"name":"地刑玄武","level":"凶","text":"己加癸为地刑玄武，男女疾病垂危，词讼有牢狱之灾。"},"庚戊":{"name":"太白天乙伏宫","level":"凶","text":"庚加戊为太白天乙伏宫，百事不可谋，为凶。"},"庚乙":{"name":"太白蓬星","level":"平","text":"庚加乙为太白蓬星，退吉进凶，宜守不宜攻。"},"庚丙":{"name":"太白入荧","level":"凶","text":"庚加丙为太白入荧，贼必来，为客进利，为主破财。"},"庚丁":{"name":"亭亭之格","level":"平","text":"庚加丁为亭亭之格，因私情起官司，门吉有救。"},"庚己":{"name":"刑格","level":"凶","text":"庚加己为刑格，官司受重刑，最不宜行。"},"庚庚":{"name":"太白同宫","level":"凶","text":"庚加庚为太白同宫，官灾横祸，兄弟雷攻。"},"庚辛":{"name":"白虎干格","level":"凶","text":"庚加辛为白虎干格，远行车折马死，出行防意外。"},"庚壬":{"name":"上格","level":"凶","text":"庚加壬为上格，远行迷失道路，音信难通。"},"庚癸":{"name":"大格","level":"凶","text":"庚加癸为大格，行人至官司止，生产母子俱伤，大凶。"},"辛戊":{"name":"困龙被伤","level":"凶","text":"辛加戊为困龙被伤，官司破败，宜屈抑守分，妄动有祸殃。"},"辛乙":{"name":"白虎猖狂","level":"凶","text":"辛加乙为白虎猖狂，人亡家败，远行多殃，车船俱伤。"},"辛丙":{"name":"干合悖师","level":"凶","text":"辛加丙为干合悖师，荧惑出现，占事必因财致讼。"},"辛丁":{"name":"狱神得奇","level":"吉","text":"辛加丁为狱神得奇，经商获倍利，囚人逢赦。"},"辛己":{"name":"入狱自刑","level":"凶","text":"辛加己为入狱自刑，奴仆背主，讼诉难伸。"},"辛庚":{"name":"白虎出力","level":"凶","text":"辛加庚为白虎出力，刀刃相接，主客相残，逊让稍可。"},"辛辛":{"name":"伏吟天庭","level":"凶","text":"辛加辛为伏吟天庭，公废私就，讼狱自罹罪名。"},"辛壬":{"name":"凶蛇入狱","level":"凶","text":"辛加壬为凶蛇入狱，两男争女，先动失理。"},"辛癸":{"name":"天牢华盖","level":"凶","text":"辛加癸为天牢华盖，日月失明，误入天网，诸事乖张。"},"壬戊":{"name":"小蛇化龙","level":"吉","text":"壬加戊为小蛇化龙，男人发达，女产婴童。"},"壬乙":{"name":"小蛇日奇","level":"吉","text":"壬加乙为小蛇日奇，女子柔顺，男子嗟叹，占孕生男。"},"壬丙":{"name":"水蛇入火","level":"凶","text":"壬加丙为水蛇入火，官灾刑禁，络绎不绝。"},"壬丁":{"name":"干合蛇刑","level":"平","text":"壬加丁为干合蛇刑，文书牵连，男吉女凶。"},"壬己":{"name":"凶蛇入墓","level":"凶","text":"壬加己为凶蛇入墓，大祸将至，顺守斯吉，词讼理曲。"},"壬庚":{"name":"太白擒蛇","level":"吉","text":"壬加庚为太白擒蛇，刑狱公平，立剖邪正。"},"壬辛":{"name":"螣蛇相缠","level":"凶","text":"壬加辛为螣蛇相缠，纵得吉门亦不能安，谋望被人欺瞒。"},"壬壬":{"name":"蛇入地罗","level":"平","text":"壬加壬为蛇入地罗，外入缠绕，内事烦琐，吉门吉星可免蹉跎。"},"壬癸":{"name":"幼女奸淫","level":"凶","text":"壬加癸为幼女奸淫，家有丑声，门吉星凶反祸。"},"癸戊":{"name":"天乙会合","level":"吉","text":"癸加戊为天乙会合，财喜婚姻，吉人相助；门凶迫制反祸官非。"},"癸乙":{"name":"华盖逢星","level":"吉","text":"癸加乙为华盖逢星，贵人禄位，常人平安。"},"癸丙":{"name":"华盖悖师","level":"平","text":"癸加丙为华盖悖师，贵贱逢之，命好者喜事临门。"},"癸丁":{"name":"螣蛇夭矫","level":"凶","text":"癸加丁为螣蛇夭矫，文书官司，火焚莫逃。"},"癸己":{"name":"华盖地户","level":"平","text":"癸加己为华盖地户，音信皆阻，躲灾避难为吉。"},"癸庚":{"name":"太白入网","level":"平","text":"癸加庚为太白入网，以暴争讼，力平方平。"},"癸辛":{"name":"网盖天牢","level":"凶","text":"癸加辛为网盖天牢，占讼占病，死罪难逃。"},"癸壬":{"name":"复见螣蛇","level":"凶","text":"癸加壬为复见螣蛇，嫁娶重婚，无子不保年华。"},"癸癸":{"name":"天网四张","level":"凶","text":"癸加癸为天网四张，行人失伴，病讼皆伤。"}},"reading_qimen/shens":{"值符":{"gist":"八神之首，像盖了章的公函——它到的地方，权威、贵人、正经门路都在。","shun":"用它办正事、见官长、求贵人，事半功倍。","ni":"最忌和庚金硬碰（太白格），权威被冲撞，好事打折。"},"腾蛇":{"gist":"虚而不实的一条蛇。它照到的地方，消息多半有假、事情反复、心里发慌。","shun":"适合演戏、造势、谈判时放烟幕。","ni":"不适合定合同、听信传言——腾蛇底下的事，先当故事听。"},"太阴":{"gist":"暗中相助的力量。像一位不出面的女眷，帮你也在暗处帮。","shun":"适合私下沟通、密谈、暗访、女人出面调停。","ni":"主谋划可以，主决断不行——太阴拖得越久越难摊牌。"},"六合":{"gist":"和合之神。合作、婚姻、中间人、说媒搭桥，全归它管。","shun":"谈判、签约、结亲、找人搭伙，六合照应的事容易谈成。","ni":"六合被冲克时，合伙容易生内隙、口头约定容易翻脸。"},"白虎":{"gist":"最硬的一股煞气。它到的地方，主伤、主刀兵、主刚猛冲突。","shun":"适合比硬碰硬的场合：执法、竞标、下狠心断舍离。","ni":"远行、见官、动手术都避开它落的方向；白虎压用神，先退一步再谈。"},"玄武":{"gist":"暗昧之神。它照到的地方，多半有隐瞒、有水分、有人在背后做小动作。","shun":"适合暗中布局、隐蔽行事。","ni":"不适合信口头承诺、放贷托付——玄武之下，防偷防骗防小人。"},"九地":{"gist":"稳如老地的神。它照应的事，安、静、藏、慢。","shun":"适合屯守、积蓄、蛰伏等待，把根扎深。","ni":"不利快速推进——九地里的路，走一步算一步，急不来。"},"九天":{"gist":"高飞之神。它照到的地方，志在高远、声在外、宜动不宜静。","shun":"适合远行、外派、发布、造大声势，也适合搏一把大局。","ni":"九天被克时，好高骛远、雷声大雨点小，宣传别做过头。"}},"reading_qimen/stars":{"天蓬":{"wx":"水","jixiong":"大凶","alias":"贪狼、文昌","gist":"胆子大、路子野的一颗星。顺的时候敢闯敢干、财路大开；失了时运，就是酒色破财、招贼惹祸的旧账。","wang":"旺相时适合开创、闯新局面，也主聪明外露；衰死时防水患、防盗、防烂桃花。"},"天芮":{"wx":"土","jixiong":"大凶","alias":"巨门、病符","gist":"一张盘里的病星。它落在哪一宫，哪一宫的事就容易缠夹不清、拖成慢性的毛病。","wang":"旺相时反主肯钻研、适合学东西拜师傅；衰死时防身体拖沓、小人背后使绊。落宫常提示需要「先治病再办事」。"},"天冲":{"wx":"木","jixiong":"小吉","alias":"禄存、蚩尤","gist":"一股往前冲的劲。适合在动中求财、雷厉风行；但劲是双刃，冲过头就是车祸、官非、兄弟反目。","wang":"旺相时做事快、机会抓得住；衰死时宜静不宜动，越折腾越亏。"},"天辅":{"wx":"木","jixiong":"大吉","alias":"文曲","gist":"文运之星。考试、文书、读书、面试、见文化人，都归它管。","wang":"旺相时文职升迁、金榜题名、好文章；衰死时体弱多思、犹豫不决。"},"天禽":{"wx":"土","jixiong":"吉","alias":"廉贞","gist":"居中宫的星，像一位不出门的老掌柜，四时皆旺。它当值符时，见官、谋事、嫁娶、买卖都平顺。","wang":"得它照应的事，讲一个「正」字——正路走通了，百事都宜。"},"天心":{"wx":"金","jixiong":"吉","alias":"武曲","gist":"掌印之星，主领导、医治、解决问题的手腕。","wang":"旺相时升职掌权、看病遇到好大夫、麻烦事有人出面摆平；衰死时防头痛胸痛、职场是非。"},"天柱":{"wx":"金","jixiong":"小凶","alias":"破军、盗贼星","gist":"破坏之星。它到的地方，宜守不宜攻，藏起来最安全。","wang":"旺相时适合退守、屯粮自固、以退为进；衰死时防口舌官司、喉肺之疾、东西破损。"},"天任":{"wx":"土","jixiong":"吉","alias":"左辅","gist":"任是担起来的意思。主富足安稳、置产兴业，像一位肯扛事的兄长。","wang":"旺相时置业买宅、百事皆宜；衰死时做事阻滞、筋骨腰背容易劳损。"},"天英":{"wx":"火","jixiong":"小凶","alias":"右弼","gist":"性子最烈的一颗星。旺时声名远播、场面漂亮；衰时性急易怒、防火灾血光。","wang":"旺相时适合婚庆饮宴、发表文书；衰死时防心脑眼疾、脾气坏事。"}}};
